import React, { useState, useRef, useCallback } from 'react';
import { ArrowLeft, LogOut, BookOpen, Users } from 'lucide-react';
import { extractRulesFromCharacter } from './utils/templateImporter';
import { RulesData } from '../types/rules';
import AdminCreationEditor from './components/AdminCreationEditor';
import AdminAttributesEditor from './components/AdminAttributesEditor';
import AdminSkillsEditor from './components/AdminSkillsEditor';
import AdminCostsEditor from './components/AdminCostsEditor';
import AdminCountersEditor from './components/AdminCountersEditor';
import AdminBackgroundsEditor from './components/AdminBackgroundsEditor';
import ImportResultModal from './components/ImportResultModal';
import ChangelogModal from '../components/ChangelogModal';
import DeploymentMonitor from './components/DeploymentMonitor';
import ImportWizardModal from './components/import-wizard/ImportWizardModal';
import AdminTraitLibrary from './components/libraries/AdminTraitLibrary';
import AdminSkillLibrary from './components/libraries/AdminSkillLibrary';
import AdminSpecializationLibrary from './components/libraries/AdminSpecializationLibrary';
import AdminBackgroundLibrary from './components/libraries/AdminBackgroundLibrary';
import AdminCounterLibrary from './components/libraries/AdminCounterLibrary';
import DeployToGithubModal from './components/DeployModal';
import AdminDashboard from './components/AdminDashboard';
import CampaignCharactersView from './components/CampaignCharactersView';
import ConfirmationModal from '../components/ui/ConfirmationModal';
import LoginScreen from './components/LoginScreen';
import GlobalPlayersView from './components/GlobalPlayersView';
import { ErrorService } from '../services/ErrorService';
import UnauthorizedScreen from './components/UnauthorizedScreen';
import { useAdminAuth } from './hooks/useAdminAuth';
import { useAdminRulesHandler } from './hooks/useAdminRulesHandler';
import AdminHeader from './components/AdminHeader';
import { CampaignService } from '../services/CampaignService';

const AdminApp: React.FC = () => {
    const { session, isAdmin, logout } = useAdminAuth();
    const {
        rules,
        currentSettingId,
        currentSettingName,
        globalUsage,
        isSaving,
        saveFeedback,
        setSaveFeedback,
        hasUnsavedChanges,
        handleSelectSetting,
        handleUpdateRules,
        refreshRules,
        handleSaveToCloud,
        handleExport,
        clearRules
    } = useAdminRulesHandler();

    const [viewMode, setViewMode] = useState<'dashboard' | 'editor' | 'players'>('dashboard');
    const [activeTab, setActiveTab] = useState<'general' | 'attributes' | 'skills' | 'costs' | 'libraries' | 'players'>('general');
    const [activeLibraryTab, setActiveLibraryTab] = useState<'traits' | 'skills' | 'specializations' | 'backgrounds' | 'counters'>('traits');

    const [showDeployModal, setShowDeployModal] = useState(false);
    const [showImportResult, setShowImportResult] = useState(false);
    const [importReport, setImportReport] = useState<{ success: string[], warnings: string[] } | null>(null);
    const [showChangelog, setShowChangelog] = useState(false);
    const [wizardOpen, setWizardOpen] = useState(false);
    const [candidateRules, setCandidateRules] = useState<RulesData | null>(null);

    const [confirmState, setConfirmState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
        type: 'danger' | 'warning' | 'info' | 'success';
    }>({ isOpen: false, title: "", message: "", onConfirm: () => { }, type: 'info' });

    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleBackToDashboard = useCallback(() => {
        if (hasUnsavedChanges) {
            setConfirmState({
                isOpen: true,
                title: "Modifications non sauvegardées",
                message: "Vous avez des modifications en attente qui seront perdues si vous quittez. Confirmer ?",
                type: 'warning',
                onConfirm: () => {
                    setViewMode('dashboard');
                    clearRules();
                    setConfirmState(prev => ({ ...prev, isOpen: false }));
                }
            });
            return;
        }
        setViewMode('dashboard');
        clearRules();
    }, [hasUnsavedChanges, clearRules]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file || !rules) return;

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const json = JSON.parse(e.target?.result as string);
                const { rules: extractedCandidate } = extractRulesFromCharacter(json, rules);
                setCandidateRules(extractedCandidate);
                setWizardOpen(true);
            } catch (error) {
                ErrorService.handleError(error, { context: 'AdminApp.importFile', userMessage: "Erreur lors de la lecture du fichier." });
            }
        };
        reader.readAsText(file);
        event.target.value = '';
    };

    if (!session) return <LoginScreen />;
    if (!isAdmin) return <UnauthorizedScreen session={session} />;

    if (viewMode === 'dashboard') {
        return (
            <AdminDashboard
                onSelectSetting={(id, name, rules) => { handleSelectSetting(id, name, rules); setViewMode('editor'); }}
                onViewPlayers={() => setViewMode('players')}
                onLogout={logout}
            />
        );
    }

    if (viewMode === 'players') {
        return (
            <div className="min-h-screen bg-gray-50 p-8">
                <div className="max-w-7xl mx-auto">
                    <div className="flex justify-between items-center mb-6">
                        <button
                            onClick={() => setViewMode('dashboard')}
                            className="flex items-center gap-2 text-slate-600 hover:text-slate-900 font-bold transition-colors"
                            aria-label="Retour au Tableau de Bord"
                        >
                            <ArrowLeft size={20} /> Retour au Tableau de Bord
                        </button>
                        <button
                            onClick={logout}
                            className="flex items-center gap-2 bg-[#5c4d41] hover:bg-[#8b2e2e] text-white px-4 py-2 rounded-md font-bold transition-all shadow-md group"
                            aria-label="Se déconnecter"
                        >
                            <LogOut size={18} className="group-hover:rotate-12 transition-transform" /> Déconnexion
                        </button>
                    </div>
                    <GlobalPlayersView />
                </div>
            </div>
        );
    }

    if (!rules) {
        return (
            <div className="flex items-center justify-center h-screen bg-gray-100 text-red-600">
                <div className="text-center">
                    <h1 className="text-2xl font-bold">Chargement...</h1>
                    <p>Initialisation de l'éditeur...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-mystic-stone text-stone-200 font-sans pb-20 transition-colors duration-500">
            <AdminHeader
                currentSettingName={currentSettingName}
                hasUnsavedChanges={hasUnsavedChanges}
                isSaving={isSaving}
                onBack={handleBackToDashboard}
                onSave={handleSaveToCloud}
                onImport={() => fileInputRef.current?.click()}
                onExport={handleExport}
                onPublish={() => setShowDeployModal(true)}
                onLogout={logout}
                onShowChangelog={() => setShowChangelog(true)}
                onCheckSchema={() => currentSettingId && CampaignService.checkSchema?.(currentSettingId)}
            />

            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept=".json" />

            <nav className="bg-mystic-deep/90 border-b border-stone-800 mt-0 sticky top-[72px] z-40 backdrop-blur-md shadow-lg">
                <div className="max-w-7xl mx-auto flex">
                    {([
                        { id: 'general', label: 'Général & Création' },
                        { id: 'attributes', label: 'Attributs' },
                        { id: 'skills', label: 'Compétences' },
                        { id: 'costs', label: 'Coûts & Limites' },
                        { id: 'libraries', label: <div className="flex items-center justify-center gap-2"><BookOpen size={16} /> Bibliothèques</div> },
                        { id: 'players', label: <div className="flex items-center justify-center gap-2"><Users size={16} /> Joueurs</div> }
                    ] as const).map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`flex-1 py-4 text-center font-bold uppercase tracking-widest text-xs border-b-2 transition-all ${activeTab === tab.id ? 'border-amber-gold text-amber-gold bg-amber-900/10' : 'border-transparent text-stone-500 hover:text-stone-300 hover:bg-stone-800'}`}
                        >
                            {tab.label}
                        </button>
                    ))}
                </div>
            </nav>

            <main className={`mx-auto p-6 transition-all duration-300 ${activeTab === 'skills' ? 'max-w-[1600px]' : 'max-w-7xl'}`}>
                {activeTab === 'general' && (
                    <div className="bg-mystic-surface p-8 rounded-sm shadow-glass border border-stone-700/50 animate-in fade-in slide-in-from-bottom-4">
                        <h2 className="text-2xl font-serif font-bold mb-6 text-amber-gold border-b border-stone-700 pb-2 flex items-center gap-2">
                            Configuration Générale
                        </h2>
                        <AdminCreationEditor rules={rules} onUpdate={handleUpdateRules} />
                    </div>
                )}
                {activeTab === 'attributes' && <AdminAttributesEditor rules={rules} onUpdate={handleUpdateRules} />}
                {activeTab === 'skills' && <AdminSkillsEditor rules={rules} onUpdate={handleUpdateRules} />}
                {activeTab === 'costs' && <AdminCostsEditor rules={rules} onUpdate={handleUpdateRules} />}
                {activeTab === 'libraries' && (
                    <div className="animate-in fade-in slide-in-from-bottom-4">
                        <div className="flex gap-2 mb-6 bg-mystic-surface p-2 rounded-sm shadow-md border border-stone-700 w-fit mx-auto overflow-x-auto">
                            {['traits', 'skills', 'backgrounds', 'counters', 'specializations'].map((lt) => (
                                <button
                                    key={lt}
                                    onClick={() => setActiveLibraryTab(lt as typeof activeLibraryTab)}
                                    className={`px-6 py-2 rounded-sm font-bold text-xs uppercase tracking-wider transition-all whitespace-nowrap ${activeLibraryTab === lt ? 'bg-amber-gold text-stone-900 shadow-glow-gold' : 'text-stone-500 hover:text-stone-300 hover:bg-stone-800'}`}
                                >
                                    {lt.charAt(0).toUpperCase() + lt.slice(1)}
                                </button>
                            ))}
                        </div>
                        {activeLibraryTab === 'traits' && <AdminTraitLibrary rules={rules} onUpdate={handleUpdateRules} globalUsage={globalUsage} />}
                        {activeLibraryTab === 'skills' && <AdminSkillLibrary rules={rules} onUpdate={handleUpdateRules} globalUsage={globalUsage} />}
                        {activeLibraryTab === 'backgrounds' && <AdminBackgroundLibrary rules={rules} onUpdate={handleUpdateRules} globalUsage={globalUsage} />}
                        {activeLibraryTab === 'counters' && <AdminCounterLibrary rules={rules} onUpdate={handleUpdateRules} globalUsage={globalUsage} />}
                        {activeLibraryTab === 'specializations' && <AdminSpecializationLibrary rules={rules} onUpdate={handleUpdateRules} globalUsage={globalUsage} />}
                    </div>
                )}
                {activeTab === 'players' && currentSettingId && <CampaignCharactersView settingId={currentSettingId} onRefreshRules={refreshRules} />}
            </main>

            <ImportResultModal isOpen={showImportResult} onClose={() => setShowImportResult(false)} report={importReport} />
            <ChangelogModal isOpen={showChangelog} onClose={() => setShowChangelog(false)} />

            {wizardOpen && candidateRules && rules && (
                <ImportWizardModal
                    isOpen={wizardOpen}
                    onClose={() => { setWizardOpen(false); setCandidateRules(null); }}
                    currentRules={rules}
                    candidateRules={candidateRules}
                    onConfirm={(merged: RulesData) => {
                        handleUpdateRules(merged);
                        setWizardOpen(false);
                        setCandidateRules(null);
                        setImportReport({ success: ["Fusion effectuée avec succès"], warnings: [] });
                        setShowImportResult(true);
                    }}
                />
            )}

            {saveFeedback && (
                <ConfirmationModal
                    isOpen={saveFeedback.isOpen}
                    onClose={() => setSaveFeedback(null)}
                    onConfirm={() => setSaveFeedback(null)}
                    title={saveFeedback.success ? "Sauvegarde Réussie" : "Erreur de Sauvegarde"}
                    message={saveFeedback.message}
                    type={saveFeedback.success ? 'success' : 'danger'}
                    confirmLabel="OK"
                    cancelLabel=""
                />
            )}

            <ConfirmationModal
                isOpen={confirmState.isOpen}
                onClose={() => setConfirmState(prev => ({ ...prev, isOpen: false }))}
                onConfirm={confirmState.onConfirm}
                title={confirmState.title}
                message={confirmState.message}
                type={confirmState.type}
            />
            <DeploymentMonitor />
        </div>
    );
};

export default AdminApp;

import React from 'react';
import { RulesData } from '../../types/rules';
import { Coins, Zap, BarChart3, TrendingUp, Info } from 'lucide-react';
import { RuleCalculationsService } from '../../services/RuleCalculationsService';
import { MotionFade } from '../../components/ui/motion/MotionFade';
import { MotionCard } from '../../components/ui/motion/MotionCard';

interface AdminCostsEditorProps {
    rules: RulesData;
    onUpdate: (newRules: RulesData) => void;
}

const AdminCostsEditor: React.FC<AdminCostsEditorProps> = ({ rules, onUpdate }) => {
    // const costs = rules.configurations.xpCosts;
    // const creationConfig = rules.configurations.creation;

    // Calculs de preview
    // const exampleRank = 3;
    // const exampleTriangular = RuleCalculationsService.triangular(exampleRank);

    const updateCategoryCost = (id: string, factor: number, type: 'linear' | 'triangular') => {
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                skillCategories: rules.definitions.skillCategories.map(cat =>
                    cat.id === id ? { ...cat, costConfig: { factor, type } } : cat
                )
            }
        });
    };

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            <MotionFade delay={0.1}>
                <MotionCard className="p-8" hoverEffect="glow">
                    <h3 className="font-bold text-stone-300 text-lg mb-6 flex items-center gap-2 border-b border-stone-700/50 pb-2 px-2 font-serif tracking-wide">
                        <Coins size={20} className="text-amber-500" /> Économie des Compétences
                    </h3>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="border-b border-stone-800 italic text-stone-500 text-[10px] uppercase tracking-widest">
                                    <th className="pb-3 px-2 font-bold">Catégorie</th>
                                    <th className="pb-3 px-2 font-bold">Behavior</th>
                                    <th className="pb-3 px-4 font-bold text-center">Formule</th>
                                    <th className="pb-3 px-2 font-bold text-right w-32">Multiplicateur</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-stone-800/30">
                                {rules.definitions.skillCategories.map((cat, index) => (
                                    <MotionFade key={cat.id} delay={0.2 + (index * 0.05)} usePresence={false} tag="tr" className="hover:bg-stone-800/30 transition-colors group">
                                        <td className="py-4 px-2">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-sm bg-stone-950 flex items-center justify-center text-stone-600 group-hover:bg-amber-950/30 group-hover:text-amber-500 transition-colors border border-stone-800 group-hover:border-amber-500/30">
                                                    <Zap size={14} />
                                                </div>
                                                <div>
                                                    <div className="text-sm font-bold text-stone-300 font-serif tracking-wide">{cat.label}</div>
                                                    <div className="text-[10px] text-stone-500 font-mono tracking-tighter uppercase">{cat.id}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="py-4 px-2">
                                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-sm border ${cat.behavior === 'Compétence' ? 'bg-emerald-950/30 text-emerald-500 border-emerald-900/50' :
                                                cat.behavior === 'Arrière-plan' ? 'bg-amber-950/30 text-amber-500 border-amber-900/50' :
                                                    cat.behavior === 'Secondaire' ? 'bg-indigo-950/30 text-indigo-400 border-indigo-900/50' :
                                                        'bg-stone-800 text-stone-400 border-stone-700'
                                                }`}>
                                                {cat.behavior}
                                            </span>
                                        </td>
                                        <td className="py-4 px-4">
                                            <div className="flex items-center justify-center gap-1">
                                                <div className="inline-flex bg-stone-950 p-1 rounded-sm gap-1 border border-stone-800">
                                                    <button
                                                        onClick={() => updateCategoryCost(cat.id, cat.costConfig.factor, 'triangular')}
                                                        className={`px-3 py-1 rounded-sm text-[10px] font-bold transition-all flex items-center gap-1 ${cat.costConfig.type === 'triangular'
                                                            ? 'bg-stone-800 text-amber-500 shadow-sm ring-1 ring-amber-500/50'
                                                            : 'text-stone-600 hover:text-stone-400'
                                                            }`}
                                                        title="Somme triangulaire (1+2+3...)"
                                                    >
                                                        <BarChart3 size={12} /> Triangulaire
                                                    </button>
                                                    <button
                                                        onClick={() => updateCategoryCost(cat.id, cat.costConfig.factor, 'linear')}
                                                        className={`px-3 py-1 rounded-sm text-[10px] font-bold transition-all flex items-center gap-1 ${cat.costConfig.type === 'linear'
                                                            ? 'bg-stone-800 text-emerald-500 shadow-sm ring-1 ring-emerald-500/50'
                                                            : 'text-stone-600 hover:text-stone-400'
                                                            }`}
                                                        title="Progression par palier fixe"
                                                    >
                                                        <TrendingUp size={12} /> Linéaire
                                                    </button>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="py-4 px-2 text-right">
                                            <div className="flex items-center justify-end gap-2">
                                                <span className="text-xs text-stone-600 font-bold">x</span>
                                                <input
                                                    type="number"
                                                    step="0.1"
                                                    value={cat.costConfig.factor}
                                                    onChange={(e) => updateCategoryCost(cat.id, parseFloat(e.target.value) || 0, cat.costConfig.type)}
                                                    className="w-16 p-2 border border-stone-700 rounded-sm text-center font-bold text-sm bg-stone-950 text-stone-300 focus:bg-stone-900 focus:ring-1 focus:ring-amber-500/50 focus:border-amber-500 outline-none transition-all placeholder-stone-700"
                                                />
                                            </div>
                                        </td>
                                    </MotionFade>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    <div className="mt-6 bg-stone-950/50 p-4 rounded-sm border border-dashed border-stone-800 text-xs text-stone-500 italic flex gap-3 items-center">
                        <Info size={16} className="text-stone-600 shrink-0" />
                        <div>
                            Le coût total d'un élément est calculé ainsi : [Valeur de Base] × [Multiplicateur].
                            <br />
                            Par exemple, Rang 3 en Triangulaire (1+2+3=6) avec un multiplicateur de x3 coûte 18 XP.
                        </div>
                    </div>
                </MotionCard>
            </MotionFade>
        </div>
    );
};

export default AdminCostsEditor;

import React from 'react';
import { CampaignService } from '../../services/CampaignService';
import { RulesData } from '../../types/rules';
import { Loader2, Scroll } from 'lucide-react';
import ConfirmationModal from '../../components/ui/ConfirmationModal';
import DuplicateSettingModal from './DuplicateSettingModal';
import { MotionFade } from '../../components/ui/motion/MotionFade';
import { ErrorService } from '../../services/ErrorService';
import { useDashboardActions } from '../hooks/useDashboardActions';
import { DashboardHeader } from './dashboard/DashboardHeader';
import { DashboardCreateBanner } from './dashboard/DashboardCreateBanner';
import { CampaignCard } from './dashboard/CampaignCard';

interface AdminDashboardProps {
    onSelectSetting: (id: string, name: string, rules: RulesData) => void;
    onViewPlayers: () => void;
    onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onSelectSetting, onViewPlayers, onLogout }) => {
    const {
        settings,
        isLoading,
        isCreating,
        newName,
        setNewName,
        settingToDelete,
        setSettingToDelete,
        settingToDuplicate,
        setSettingToDuplicate,
        showArchived,
        setShowArchived,
        handleCreate,
        handleDelete,
        handleToggleVisibility,
        handleToggleArchive,
        confirmDuplicate
    } = useDashboardActions();

    const handleSelect = async (id: string) => {
        try {
            const rules = await CampaignService.loadSetting(id);
            const settingName = settings.find(s => s.id === id)?.name || "Campagne";

            if (rules) {
                onSelectSetting(id, settingName, rules);
            }
        } catch (error) {
            ErrorService.handleError(error, {
                context: 'AdminDashboard.handleSelect',
                userMessage: 'Erreur lors du chargement de la campagne.'
            });
        }
    };

    const filteredSettings = settings.filter(s => showArchived || !s.is_archived);

    return (
        <div className="flex flex-col min-h-screen bg-stone-950 p-8 w-full transition-colors duration-500 relative overflow-hidden">
            {/* Background Texture Effect */}
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/dark-leather.png')] opacity-20 pointer-events-none" />
            <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-stone-900 to-transparent pointer-events-none" />

            <div className="max-w-6xl mx-auto w-full relative z-10">
                <DashboardHeader
                    showArchived={showArchived}
                    setShowArchived={setShowArchived}
                    onViewPlayers={onViewPlayers}
                    onLogout={onLogout}
                />

                <MotionFade delay={0.2}>
                    <p className="text-stone-400 mb-8 italic font-serif text-lg tracking-wide border-l-2 border-amber-800/50 pl-4 max-w-2xl">
                        "Gérez vos chroniques, vos règles et le destin de vos investigateurs dans l'ombre."
                    </p>
                </MotionFade>

                <DashboardCreateBanner
                    newName={newName}
                    setNewName={setNewName}
                    handleCreate={handleCreate}
                    isCreating={isCreating}
                />

                {/* List */}
                {
                    isLoading && settings.length === 0 ? (
                        <div className="flex justify-center py-32">
                            <Loader2 size={64} className="animate-spin text-amber-900/40" />
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {filteredSettings.length === 0 && !isLoading && (
                                <MotionFade className="col-span-full text-center py-20 text-stone-600 italic font-serif text-xl border-2 border-dashed border-stone-800/50 rounded-xl bg-stone-900/20 backdrop-blur-sm">
                                    Le vide s'étend devant vous... <br /> Commencez par inscrire une nouvelle légende.
                                </MotionFade>
                            )}

                            {filteredSettings.map((setting, index) => (
                                <CampaignCard
                                    key={setting.id}
                                    setting={setting}
                                    index={index}
                                    onSelect={handleSelect}
                                    onToggleVisibility={handleToggleVisibility}
                                    onToggleArchive={handleToggleArchive}
                                    onDuplicate={(id, name) => setSettingToDuplicate({ id, name })}
                                    onDelete={(id) => setSettingToDelete(id)}
                                />
                            ))}
                        </div>
                    )
                }

                <ConfirmationModal
                    isOpen={!!settingToDelete}
                    onClose={() => setSettingToDelete(null)}
                    onConfirm={handleDelete}
                    title="Dissoudre la Chronique ?"
                    message="Attention : Cette action est irréversible. L'histoire, les règles et les destins liés à cette chronique seront perdus à jamais dans le néant."
                    confirmLabel="Dissoudre"
                    type="danger"
                    scheme="mystic"
                />

                <DuplicateSettingModal
                    isOpen={!!settingToDuplicate}
                    onClose={() => setSettingToDuplicate(null)}
                    oldName={settingToDuplicate?.name || ''}
                    onConfirm={confirmDuplicate}
                />
            </div>
        </div>
    );
};

export default AdminDashboard;

/**
 * GlobalPlayersView
 * 
 * Admin view to list ALL synchronized characters across all campaigns.
 * Useful for finding "orphaned" characters or tracking player activity globally.
 */

import React, { useState, useEffect } from 'react';
import { Users, Search, Eye, Trash2, Calendar, Shield, Info, AlertCircle } from 'lucide-react';
import { CharacterSyncService, SyncedCharacterSummary, SyncedCharacter } from '../../services/CharacterSyncService';
import CharacterReadOnlyView from './CharacterReadOnlyView';
import { GameSettingSummary, CampaignService } from '../../services/CampaignService';
import ConfirmationModal from '../../components/ui/ConfirmationModal';
import { logger } from '../../utils/logger';
import { ErrorService } from '../../services/ErrorService';
import { Loader2 } from 'lucide-react';

const GlobalPlayersView: React.FC = () => {
    const [characters, setCharacters] = useState<SyncedCharacterSummary[]>([]);
    const [campaigns, setCampaigns] = useState<GameSettingSummary[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCharacter, setSelectedCharacter] = useState<SyncedCharacter | null>(null);
    const [filterOrphans, setFilterOrphans] = useState(false);
    const [characterToDelete, setCharacterToDelete] = useState<string | null>(null);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const [charData, campaignData] = await Promise.all([
                CharacterSyncService.getAllCharacters(),
                CampaignService.listPublicSettings()
            ]);
            setCharacters(charData);
            setCampaigns(campaignData);
        } catch (error) {
            ErrorService.handleError(error, {
                context: 'GlobalPlayersView.loadData',
                userMessage: "Échec du chargement de la base de données joueurs."
            });
        } finally {
            setIsLoading(false);
        }
    };

    const getCampaignName = (settingId: string | null) => {
        if (!settingId) return <span className="text-amber-600 font-bold flex items-center gap-1"><AlertCircle size={14} /> Orphelin</span>;
        const campaign = campaigns.find(c => c.id === settingId);
        return campaign ? campaign.name : <span className="text-stone-400 italic">Inconnue</span>;
    };

    const formatSize = (bytes: number | undefined) => {
        if (bytes === undefined) return '-';
        if (bytes < 1024) return `${bytes} o`;
        if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} ko`;
        return `${(bytes / (1024 * 1024)).toFixed(1)} Mo`;
    };

    const handleViewDetails = async (id: string) => {
        try {
            const fullChar = await CharacterSyncService.getCharacterById(id);
            if (fullChar) {
                setSelectedCharacter(fullChar);
            }
        } catch (error) {
            ErrorService.handleError(error, {
                context: 'GlobalPlayersView.handleViewDetails',
                userMessage: "Impossible d'afficher les détails du personnage."
            });
        }
    };

    const handleDelete = (id: string) => {
        setCharacterToDelete(id);
    };

    const confirmDelete = async () => {
        if (!characterToDelete) return;
        try {
            const success = await CharacterSyncService.deleteCharacter(characterToDelete);
            if (success) {
                setCharacters(prev => prev.filter(c => c.id !== characterToDelete));
            }
        } catch (error) {
            ErrorService.handleError(error, {
                context: 'GlobalPlayersView.confirmDelete',
                userMessage: "Échec de la suppression."
            });
        } finally {
            setCharacterToDelete(null);
        }
    };

    const filteredCharacters = characters.filter(char => {
        const matchesSearch =
            char.character_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            char.player_name.toLowerCase().includes(searchTerm.toLowerCase());

        const matchesOrphan = filterOrphans ? !char.setting_id : true;

        return matchesSearch && matchesOrphan;
    });

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-3">
                        <Users className="text-indigo-600" />
                        Master List des Joueurs
                    </h2>
                    <p className="text-slate-500 text-sm">Vue globale de tous les personnages synchronisés sur le cloud.</p>
                </div>

                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-grow md:w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input
                            type="text"
                            placeholder="Rechercher personnage ou joueur..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                        />
                    </div>

                    <button
                        onClick={() => setFilterOrphans(!filterOrphans)}
                        className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${filterOrphans
                            ? 'bg-amber-100 text-amber-700 border border-amber-200'
                            : 'bg-slate-100 text-slate-600 border border-slate-200 hover:bg-slate-200'
                            }`}
                        title="Afficher uniquement les personnages dont la campagne a été supprimée"
                    >
                        <AlertCircle size={18} />
                        Orphelins
                    </button>

                    <button
                        onClick={loadData}
                        className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition-colors"
                        title="Rafraîchir"
                    >
                        <Calendar size={20} />
                    </button>
                </div>
            </div>

            {isLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-white rounded-xl border border-slate-200 shadow-sm">
                    <Loader2 className="animate-spin mb-4 text-indigo-600" size={40} />
                    <p>Chargement de la base de données joueurs...</p>
                </div>
            ) : filteredCharacters.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-white rounded-xl border border-slate-200 shadow-sm">
                    <Users className="mb-4 opacity-20" size={64} />
                    <p className="text-lg font-medium">Aucun personnage trouvé</p>
                    <p className="text-sm">Essayez d'ajuster vos filtres ou de réinitialiser la recherche.</p>
                </div>
            ) : (
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-xs font-bold uppercase tracking-wider">
                                <th className="px-6 py-4">Personnage</th>
                                <th className="px-6 py-4">Joueur</th>
                                <th className="px-6 py-4">Campagne</th>
                                <th className="px-6 py-4">Dernière Sync</th>
                                <th className="px-6 py-4 text-center">Taille</th>
                                <th className="px-6 py-4 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {filteredCharacters.map((char) => (
                                <tr key={char.id} className="hover:bg-slate-50/80 transition-colors text-sm">
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-800 flex items-center gap-2">
                                            <Shield size={16} className="text-indigo-500" />
                                            {char.character_name}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-500">
                                                {char.player_name.charAt(0).toUpperCase()}
                                            </div>
                                            <span className="text-slate-600 font-medium">{char.player_name}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="text-slate-600">
                                            {getCampaignName(char.setting_id)}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-slate-500">
                                        <div className="flex items-center gap-1.5">
                                            <Calendar size={14} className="text-slate-400" />
                                            {new Date(char.last_synced).toLocaleString('fr-FR', {
                                                day: '2-digit', month: '2-digit', year: 'numeric',
                                                hour: '2-digit', minute: '2-digit'
                                            })}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <div className="text-stone-500 font-mono text-xs">
                                            {formatSize(char.data_size)}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button
                                                onClick={() => handleViewDetails(char.id)}
                                                className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                                                title="Voir la fiche détaillée"
                                            >
                                                <Eye size={18} />
                                            </button>
                                            <button
                                                onClick={() => handleDelete(char.id)}
                                                className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                                                title="Supprimer la synchronisation"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Read-Only Modal View */}
            {selectedCharacter && (
                <CharacterReadOnlyView
                    character={selectedCharacter}
                    onClose={() => setSelectedCharacter(null)}
                />
            )}

            <ConfirmationModal
                isOpen={!!characterToDelete}
                onClose={() => setCharacterToDelete(null)}
                onConfirm={confirmDelete}
                title="Supprimer la synchronisation ?"
                message="Attention : Cette action supprimera définitivement la fiche du cloud. Le joueur pourra toujours synchroniser sa fiche à nouveau s'il le souhaite."
                confirmLabel="Supprimer"
                type="danger"
            />
        </div>
    );
};

export default GlobalPlayersView;

import React from 'react';
import { Loader2 } from 'lucide-react';
import { GameSettingSummary } from '../../../services/CampaignService';

interface CampaignSelectorProps {
    settings: GameSettingSummary[];
    onSelect: (id: string) => void;
}

export const CampaignSelector: React.FC<CampaignSelectorProps> = ({ settings, onSelect }) => {
    return (
        <div className="flex-grow flex flex-col p-6 overflow-hidden">
            <div className="mb-4">
                <h3 className="text-lg font-bold text-slate-800">Choisir une campagne cible</h3>
                <p className="text-sm text-slate-500">Ce personnage est un "orphelin" (sans campagne). Veuillez sélectionner la campagne où importer ses caractéristiques.</p>
            </div>

            <div className="flex-grow overflow-y-auto space-y-2 pr-2">
                {settings.length === 0 ? (
                    <div className="text-center py-10 text-slate-400">
                        <Loader2 className="animate-spin mx-auto mb-2" />
                        Chargement des campagnes...
                    </div>
                ) : (
                    settings.map((s: any) => (
                        <button
                            key={s.id}
                            onClick={() => onSelect(s.id)}
