import { useState, useEffect } from 'react';
import { RulesData } from '../../types/rules';
import { AttributePreset } from '../../types/system';
import { AttributeService } from '../../services/AttributeService';
import { DEFAULT_ATTRIBUTES, getDefaultSecondaryAttrs } from '../../data/defaults/attributes';

export const useAttributeEditor = (rules: RulesData, onUpdate: (newRules: RulesData) => void) => {
    const definitions = rules.definitions;
    const attributesMap = definitions.attributes || {};
    const secondaryMap = definitions.secondaryAttributes || {};
    const labelsMap = definitions.labels || {};

    // Standard order for sorting categories
    const STANDARD_ORDER = ['pave_attributs_1', 'pave_attributs_2', 'pave_attributs_3', 'pave_attributs_4', 'pave_attributs_5'];

    const categories = Object.keys(attributesMap).sort((a, b) => {
        const indexA = STANDARD_ORDER.indexOf(a);
        const indexB = STANDARD_ORDER.indexOf(b);
        if (indexA !== -1 && indexB !== -1) return indexA - indexB;
        if (indexA !== -1) return -1;
        if (indexB !== -1) return 1;
        return a.localeCompare(b);
    });

    // --- CONFIRMATION STATE ---
    const [confirmState, setConfirmState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
        type: 'danger' | 'warning' | 'info' | 'success';
    }>({
        isOpen: false,
        title: "",
        message: "",
        onConfirm: () => { },
        type: 'info'
    });

    const closeConfirm = () => {
        setConfirmState(prev => ({ ...prev, isOpen: false }));
    };

    const requestConfirm = (title: string, message: string, onConfirm: () => void, type: 'danger' | 'warning' | 'info' = 'warning') => {
        setConfirmState({ isOpen: true, title, message, onConfirm, type });
    };

    // --- PRESETS STATE ---
    const [showPresetConfirm, setShowPresetConfirm] = useState(false);
    const [pendingPreset, setPendingPreset] = useState<any>(null);
    const [dbPresets, setDbPresets] = useState<AttributePreset[]>([]);
    const [isLoadingPresets, setIsLoadingPresets] = useState(true);

    useEffect(() => {
        loadDBPresets();
    }, []);

    const loadDBPresets = async () => {
        setIsLoadingPresets(true);
        const data = await AttributeService.listAttributePresets();
        if (data) setDbPresets(data);
        setIsLoadingPresets(false);
    };

    // --- PRESETS ---
    const requestPresetLoad = (preset: any) => {
        if (preset.structure && !preset.structure[0].secondaryAttrs && preset.structure[0].attrs) {
            preset.structure = preset.structure.map((cat: any) => ({
                ...cat,
                secondaryAttrs: []
            }));
        }
        setPendingPreset(preset);
        setShowPresetConfirm(true);
    };

    const handleSaveCurrentAsPreset = async (name: string, desc: string) => {
        const structure = categories.map(cat => ({
            id: cat,
            label: labelsMap[cat] || cat,
            attrs: [...attributesMap[cat]],
            secondaryAttrs: rules.configurations.global.secondaryAttributes ? [...(secondaryMap[cat] || [])] : []
        }));

        const isSecondaryActive = !!rules.configurations.global.secondaryAttributes;
        const success = await AttributeService.saveAttributePreset(name, desc, structure, isSecondaryActive);
        if (success) {
            loadDBPresets();
        }
    };

    const handleDeletePreset = (id: string) => {
        requestConfirm(
            "Supprimer le Préréglage ?",
            "Cette action est irréversible.",
            async () => {
                const success = await AttributeService.deleteAttributePreset(id);
                if (success) loadDBPresets();
            },
            'danger'
        );
    };

    const handleUpdatePreset = async (id: string, name: string, description: string) => {
        const success = await AttributeService.updateAttributePreset(id, { name, description });
        if (success) loadDBPresets();
        return success;
    };

    const executePresetLoad = () => {
        if (!pendingPreset) return;

        const newAttributes: Record<string, string[]> = {};
        const newLabels: Record<string, string> = { ...labelsMap };
        const newSecondary: Record<string, string[]> = { ...secondaryMap };
        const hasSecondaryInPreset = pendingPreset.has_secondary || pendingPreset.hasSecondary || false;

        pendingPreset.structure.forEach((cat: any) => {
            newAttributes[cat.id] = [...cat.attrs];
            newLabels[cat.id] = cat.label;
            if (cat.secondaryAttrs) {
                newSecondary[cat.id] = [...cat.secondaryAttrs];
            }
        });

        onUpdate({
            ...rules,
            configurations: {
                ...rules.configurations,
                global: {
                    ...rules.configurations.global,
                    secondaryAttributes: hasSecondaryInPreset
                }
            },
            definitions: {
                ...rules.definitions,
                attributes: newAttributes,
                secondaryAttributes: newSecondary,
                labels: newLabels
            }
        });

        setShowPresetConfirm(false);
        setPendingPreset(null);
    };

    // --- MANAGE CATEGORIES ---
    const addCategory = () => {
        const count = categories.length;
        let nextId = `pave_attributs_${count + 1}`;
        if (categories.includes(nextId)) {
            nextId = `pave_attributs_${count + 1}_${Math.random().toString(36).substr(2, 3)}`;
        }

        const firstCatId = categories[0];
        const attributeCount = firstCatId ? (attributesMap[firstCatId]?.length || 0) : 4;

        let defaults = DEFAULT_ATTRIBUTES[nextId] || [];
        if (defaults.length < attributeCount) {
            const extra = Array(attributeCount - defaults.length).fill(0).map((_, i) => `Attribut ${defaults.length + i + 1}`);
            defaults = [...defaults, ...extra];
        } else if (defaults.length > attributeCount) {
            defaults = defaults.slice(0, attributeCount);
        }

        if (defaults.length === 0) {
            defaults = Array(attributeCount).fill(0).map((_, i) => `Attribut ${i + 1}`);
        }

        const isSecondaryActive = !!rules.configurations.global.secondaryAttributes;
        const newSecondaryMap = { ...secondaryMap };
        if (isSecondaryActive) {
            const label = nextId.charAt(0).toUpperCase() + nextId.slice(1);
            newSecondaryMap[nextId] = getDefaultSecondaryAttrs(label, nextId);
        }

        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                attributes: {
                    ...attributesMap,
                    [nextId]: defaults
                },
                secondaryAttributes: newSecondaryMap,
                labels: {
                    ...labelsMap,
                    [nextId]: nextId.charAt(0).toUpperCase() + nextId.slice(1)
                }
            }
        });
    };

    const removeCategory = (categoryId: string) => {
        if (categories.length <= 1) return;
        requestConfirm(
            `Supprimer le pavé "${labelsMap[categoryId] || categoryId}" ?`,
            "Toutes les données associées seront perdues.",
            () => {
                const newAttributes = { ...attributesMap };
                delete newAttributes[categoryId];
                const newSecondary = { ...secondaryMap };
                delete newSecondary[categoryId];
                const newLabels = { ...labelsMap };
                delete newLabels[categoryId];

                onUpdate({
                    ...rules,
                    definitions: {
                        ...rules.definitions,
                        attributes: newAttributes,
                        secondaryAttributes: newSecondary,
                        labels: newLabels
                    }
                });
            },
            'danger'
        );
    };

    // ... (rest of functions like toggleSecondaryGlobal, etc. remain unchanged but need to be included in replacement if I'm replacing a block.
    // Wait, the block I'm replacing is from line 43 to 324? No, that's too big and risky for "ReplacementChunk" if I can avoid it.
    // I should use ReplaceFileContent with a smaller chunk or multiple chunks?
    // The previous tool was ReplaceFileContent.
    // I will replace the logic for `removeCategory` and `handleDeletePreset` specifically, and add the state at the top.
    // But `removeCategory` is at 165, `handleDeletePreset` at 69.
    // I'll try to replace the whole return statement and the state definition first?
    // No, I need to replace the specific functions. I'll use multi_replace? No, I'll use `replace_file_content` but I have to be careful.
    // Actually, I can replace the whole file content starting from line 25 where states are defined.
    // It's cleaner to use `replace_file_content` for the whole Hook body if I'm changing state AND functions.
    // But I must include `toggleSecondaryGlobal` etc.
    // I will use `replace_file_content` from line 26 to the end.

    const toggleSecondaryGlobal = () => {
        const isActive = !!rules.configurations.global.secondaryAttributes;
        const newActive = !isActive;
        const newSecondary = { ...secondaryMap };
        if (newActive) {
            Object.keys(attributesMap).forEach(cat => {
                const label = labelsMap[cat] || cat;
                const defaultSec = getDefaultSecondaryAttrs(label, cat);
                if (!newSecondary[cat] || newSecondary[cat].length !== 2 ||
                    (newSecondary[cat][0] === "" && newSecondary[cat][1] === "")) {
                    const existing = newSecondary[cat] || [];
                    newSecondary[cat] = [
                        existing[0] || defaultSec[0],
                        existing[1] || defaultSec[1]
                    ];
                }
            });
        }

        onUpdate({
            ...rules,
            configurations: {
                ...rules.configurations,
                global: {
                    ...rules.configurations.global,
                    secondaryAttributes: newActive
                }
            },
            definitions: {
                ...rules.definitions,
                secondaryAttributes: newSecondary
            }
        });
    };

    const updateSecondaryItemName = (category: string, index: number, newName: string) => {
        const newSecondary = { ...secondaryMap };
        if (!newSecondary[category]) newSecondary[category] = ["", ""];
        newSecondary[category][index] = newName;
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                secondaryAttributes: newSecondary
            }
        });
    };

    const updateLabel = (category: string, newLabel: string) => {
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                labels: {
                    ...labelsMap,
                    [category]: newLabel
                }
            }
        });
    };

    const addAttribute = () => {
        const newAttributesMap = { ...attributesMap };
        const count = attributesMap[categories[0]]?.length || 0;
        const newName = `Attribut ${count + 1}`;
        Object.keys(newAttributesMap).forEach(cat => {
            newAttributesMap[cat] = [...newAttributesMap[cat], newName];
        });
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                attributes: newAttributesMap
            }
        });
    };

    const removeAttribute = (index: number) => {
        const newAttributesMap = { ...attributesMap };
        const count = attributesMap[categories[0]]?.length || 0;
        if (count <= 1) return;

        // ADDING CONFIRM HERE TOO as it's a destructive action often
        requestConfirm(
            "Supprimer l'attribut ?",
            "Cet attribut sera retiré de tous les pavés.",
            () => {
                Object.keys(newAttributesMap).forEach(cat => {
                    const newList = [...newAttributesMap[cat]];
                    newList.splice(index, 1);
                    newAttributesMap[cat] = newList;
                });
                onUpdate({
                    ...rules,
                    definitions: {
                        ...rules.definitions,
                        attributes: newAttributesMap
                    }
                });
            },
            'danger'
        );
    };

    const updateItemName = (category: string, index: number, newName: string) => {
        const newAttributesMap = { ...attributesMap };
        newAttributesMap[category][index] = newName;
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                attributes: newAttributesMap
            }
        });
    };

    return {
        categories,
        attributesMap,
        secondaryMap,
        labelsMap,
        states: {
            showPresetConfirm,
            setShowPresetConfirm,
            pendingPreset,
            setPendingPreset,
            dbPresets,
            isLoadingPresets,
            // New state
            confirmState,
            closeConfirm
        },
        actions: {
            addCategory,
            removeCategory,
            updateLabel,
            addAttribute,
            removeAttribute,
            updateItemName,
            toggleSecondaryGlobal,
            updateSecondaryItemName,
            requestPresetLoad,
            executePresetLoad,
            handleSaveCurrentAsPreset,
            handleDeletePreset,
            handleUpdatePreset
        }
    };
};

import { useState, useEffect, useCallback } from 'react';
import { SyncedCharacter } from '../../services/CharacterSyncService';
import { CampaignService, GameSettingSummary } from '../../services/CampaignService';
import { RulesData } from '../../types/rules';
import { DotEntry } from '../../types';
import { logger } from '../../utils/logger';

export type TabType = 'traits' | 'skills' | 'specializations' | 'backgrounds' | 'counters';

export interface ImportCandidate<T> {
    name: string;
    data: T;
    isSelected: boolean;
    isDuplicate: boolean;
    isVariable?: boolean;
}

export function useLibraryImport(
    character: SyncedCharacter,
    onSuccess?: () => void,
    onClose?: () => void
) {
    const [targetSettingId, setTargetSettingId] = useState<string | null>(character.setting_id || null);
    const [settings, setSettings] = useState<GameSettingSummary[]>([]);
    const [rules, setRules] = useState<RulesData | null>(null);
    const [activeTab, setActiveTab] = useState<TabType>('traits');
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [importDestination, setImportDestination] = useState<'campaign' | 'global'>('campaign');

    const [traitCandidates, setTraitCandidates] = useState<ImportCandidate<any>[]>([]);
    const [skillCandidates, setSkillCandidates] = useState<ImportCandidate<any>[]>([]);
    const [specCandidates, setSpecCandidates] = useState<ImportCandidate<any>[]>([]);
    const [backgroundCandidates, setBackgroundCandidates] = useState<ImportCandidate<any>[]>([]);
    const [counterCandidates, setCounterCandidates] = useState<ImportCandidate<any>[]>([]);

    useEffect(() => {
        if (!targetSettingId) {
            CampaignService.listSettings().then(data => {
                if (data) setSettings(data);
            });
        }
    }, [targetSettingId]);

    const analyzeData = useCallback(async () => {
        if (!targetSettingId) return;
        setIsLoading(true);

        try {
            const currentRules = await CampaignService.loadSetting(targetSettingId);
            if (!currentRules) return;
            setRules(currentRules);

            const charData = typeof character.data === 'string'
                ? JSON.parse(character.data)
                : character.data;

            // Traits
            const traits = (charData.traits || []).map((t: any) => ({
                name: t.name,
                data: t,
                isSelected: true,
                isDuplicate: (currentRules.libraries?.traits || []).some((l: any) => l.name === t.name),
                isVariable: t.isVariable
            }));
            setTraitCandidates(traits);

            // Skills
            const skills: ImportCandidate<any>[] = [];
            const skillsMap = charData.skills || {};
            Object.keys(skillsMap).forEach(catId => {
                const list = skillsMap[catId] || [];
                list.forEach((s: DotEntry) => {
                    if (s.name && s.name !== "Nouvelle Compétence") {
                        skills.push({
                            name: s.name,
                            data: { ...s, defaultCategory: catId },
                            isSelected: true,
                            isDuplicate: (currentRules.libraries?.skills || []).some((l: any) => l.name === s.name),
                            isVariable: (s as any).isVariable
                        });
                    }
                });
            });
            setSkillCandidates(skills);

            // Specs
            const specs: ImportCandidate<any>[] = [];
            Object.keys(skillsMap).forEach(catId => {
                const list = skillsMap[catId] || [];
                list.forEach((s: DotEntry) => {
                    if ((s as any).specializations) {
                        (s as any).specializations.forEach((spec: any) => {
                            if (spec.name) {
                                specs.push({
                                    name: spec.name,
                                    data: spec,
                                    isSelected: true,
                                    isDuplicate: false,
                                    isVariable: false
                                });
                            }
                        });
                    }
                });
            });
            setSpecCandidates(specs);

            // Backgrounds
            const backgrounds = (charData.backgrounds || []).map((b: any) => ({
                name: b.name,
                data: b,
                isSelected: true,
                isDuplicate: (currentRules.libraries?.backgrounds || []).some((l: any) => l.name === b.name),
                isVariable: false
            }));
            setBackgroundCandidates(backgrounds);

            // Counters
            const countersFlat: ImportCandidate<any>[] = [];
            const countersData = charData.counters || {};

            // Handle record structure
            Object.keys(countersData).forEach(key => {
                const item = countersData[key];
                if (Array.isArray(item)) {
                    item.forEach(c => {
                        if (c.name) {
                            countersFlat.push({
                                name: c.name,
                                data: c,
                                isSelected: true,
                                isDuplicate: (currentRules.libraries?.counters || []).some((l: any) => l.name === c.name),
                                isVariable: false
                            });
                        }
                    });
                } else if (item && item.name) {
                    countersFlat.push({
                        name: item.name,
                        data: item,
                        isSelected: true,
                        isDuplicate: (currentRules.libraries?.counters || []).some((l: any) => l.name === item.name),
                        isVariable: false
                    });
                }
            });
            setCounterCandidates(countersFlat);

        } catch (err) {
            logger.error("Failed to analyze character data for import", err);
        } finally {
            setIsLoading(false);
        }
    }, [targetSettingId, character]);

    useEffect(() => {
        analyzeData();
    }, [analyzeData]);

    const handleTabChange = (tab: TabType) => setActiveTab(tab);

    const toggleCandidateSelection = (type: TabType, index: number) => {
        const updater = (prev: ImportCandidate<any>[]) => {
            const next = [...prev];
            next[index] = { ...next[index], isSelected: !next[index].isSelected };
            return next;
        };

        if (type === 'traits') setTraitCandidates(updater);
        if (type === 'skills') setSkillCandidates(updater);
        if (type === 'specializations') setSpecCandidates(updater);
        if (type === 'backgrounds') setBackgroundCandidates(updater);
        if (type === 'counters') setCounterCandidates(updater);
    };

    const handleImport = async () => {
        if (!targetSettingId || !rules) return;
        setIsSaving(true);

        try {
            const updatedRules = JSON.parse(JSON.stringify(rules));
            if (!updatedRules.libraries) updatedRules.libraries = {};

            // Traits
            const selectedTraits = traitCandidates.filter(c => c.isSelected && !c.isDuplicate);
            if (selectedTraits.length > 0) {
                const newTraits = selectedTraits.map(c => ({
                    id: crypto.randomUUID(),
                    name: c.name,
                    description: c.data.description || "",
                    type: c.data.type || "avantage",
                    cost: String(c.data.cost || "0")
                }));
                updatedRules.libraries.traits = [...(updatedRules.libraries.traits || []), ...newTraits];
            }

            // Skills
            const selectedSkills = skillCandidates.filter(c => c.isSelected && !c.isDuplicate);
            if (selectedSkills.length > 0) {
                const newSkills = selectedSkills.map(c => ({
                    id: crypto.randomUUID(),
                    name: c.name,
                    description: "",
                    defaultCategory: c.data.defaultCategory || "competences",
                    isVariable: !!c.isVariable
                }));
                updatedRules.libraries.skills = [...(updatedRules.libraries.skills || []), ...newSkills];
            }

            // Backgrounds
            const selectedBackgrounds = backgroundCandidates.filter(c => c.isSelected && !c.isDuplicate);
            if (selectedBackgrounds.length > 0) {
                const newBackgrounds = selectedBackgrounds.map(c => ({
                    id: crypto.randomUUID(),
                    name: c.name,
                    description: c.data.description || ""
                }));
                updatedRules.libraries.backgrounds = [...(updatedRules.libraries.backgrounds || []), ...newBackgrounds];
            }

            // Counters
            const selectedCounters = counterCandidates.filter(c => c.isSelected && !c.isDuplicate);
            if (selectedCounters.length > 0) {
                const newCounters = selectedCounters.map(c => ({
                    id: crypto.randomUUID(),
                    name: c.name,
                    description: "",
                    defaultValue: c.data.defaultValue || 0,
                    maxValue: c.data.maxValue || 10,
                    xpCost: 0
                }));
                updatedRules.libraries.counters = [...(updatedRules.libraries.counters || []), ...newCounters];
            }

            // Save
            await CampaignService.saveSetting(targetSettingId, updatedRules);

            if (onSuccess) onSuccess();
            if (onClose) onClose();

        } catch (err) {
            logger.error("Import failed", err);
        } finally {
            setIsSaving(false);
        }
    };

    const getSelectedCount = () => {
        return traitCandidates.filter(c => c.isSelected).length +
            skillCandidates.filter(c => c.isSelected).length +
            specCandidates.filter(c => c.isSelected).length +
            backgroundCandidates.filter(c => c.isSelected).length +
            counterCandidates.filter(c => c.isSelected).length;
    };

    return {
        targetSettingId,
        setTargetSettingId,
        settings,
        activeTab,
        handleTabChange,
        isLoading,
        isSaving,
        importDestination,
        updateImportDestination: (dest: 'campaign' | 'global') => setImportDestination(dest),
        traitCandidates,
        skillCandidates,
        specCandidates,
        backgroundCandidates,
        counterCandidates,
        toggleCandidateSelection,
        handleImport,
        getSelectedCount
    };
}

import { useState } from 'react';
import { RulesData, SkillCategoryConfig, SkillBehavior } from '../../types/rules';
import { LibrarySkillEntry, DotEntry } from '../../types';

export function useSkillEditorActions(rules: RulesData, onUpdate: (newRules: RulesData) => void) {
    const [syncSuccess, setSyncSuccess] = useState<string | null>(null);

    const ensureSkillInLibrary = (skillName: string, category: string, currentRules: RulesData): RulesData | null => {
        if (!skillName || skillName.trim() === "" || skillName === "Nouvelle Compétence") return null;

        const lib = currentRules.libraries?.skills || [];
        const exists = lib.some(s => s.name.trim().toLowerCase() === skillName.trim().toLowerCase());

        if (!exists) {
            const newEntry: LibrarySkillEntry = {
                id: crypto.randomUUID(),
                name: skillName.trim(),
                description: "",
                defaultCategory: category,
                isVariable: false
            };
            const newLib = [...lib, newEntry].sort((a, b) => a.name.localeCompare(b.name));

            return {
                ...currentRules,
                libraries: {
                    ...currentRules.libraries,
                    skills: newLib
                }
            };
        }
        return null;
    };

    const handleSyncAll = () => {
        let currentRules = { ...rules };
        let addedCount = 0;
        const skillsMap = rules.definitions.skills || {};
        const skillCategories = rules.definitions.skillCategories || [];

        skillCategories.forEach(cat => {
            const skills = skillsMap[cat.id] || [];
            skills.forEach(skillName => {
                const updated = ensureSkillInLibrary(skillName, cat.id, currentRules);
                if (updated) {
                    currentRules = updated;
                    addedCount++;
                }
            });
        });

        if (addedCount > 0) {
            onUpdate(currentRules);
            setSyncSuccess(`${addedCount} compétence(s) ajoutée(s) à la bibliothèque.`);
            setTimeout(() => setSyncSuccess(null), 3000);
        } else {
            setSyncSuccess("Bibliothèque déjà à jour.");
            setTimeout(() => setSyncSuccess(null), 3000);
        }
    };

    const updateSkillList = (category: string, newList: string[]) => {
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                skills: {
                    ...rules.definitions.skills,
                    [category]: newList
                }
            }
        });
    };

    const updateLabel = (category: string, newLabel: string) => {
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                skillCategories: rules.definitions.skillCategories.map(cat =>
                    cat.id === category ? { ...cat, label: newLabel } : cat
                )
            }
        });
    };

    const updateCategoryMetadata = (category: string, updates: Partial<SkillCategoryConfig>) => {
        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                skillCategories: rules.definitions.skillCategories.map(cat =>
                    cat.id === category ? { ...cat, ...updates } : cat
                )
            }
        });
    };

    const updateBehavior = (category: string, behavior: SkillBehavior) => {
        let factor = 1;
        let type: 'linear' | 'triangular' = 'triangular';

        if (behavior === 'Secondaire') {
            factor = 0.5;
            type = 'triangular';
        } else if (behavior === 'Arrière-plan' || behavior === 'Compteur') {
            factor = 1;
            type = 'linear';
        }

        onUpdate({
            ...rules,
            definitions: {
                ...rules.definitions,
                skillCategories: rules.definitions.skillCategories.map(cat =>
                    cat.id === category
                        ? {
                            ...cat,
                            behavior,
                            costConfig: { factor, type }
                        }
                        : cat
                )
            }
        });
    };

    const addSkill = (category: string, isSpacer = false) => {
        const skillsMap = rules.definitions.skills || {};
        const currentList = skillsMap[category] || [];
        updateSkillList(category, [...currentList, isSpacer ? "" : "Nouvelle Compétence"]);
    };

    const removeSkill = (category: string, index: number) => {
        const skillsMap = rules.definitions.skills || {};
        const currentList = skillsMap[category] || [];
        const newList = [...currentList];
        newList.splice(index, 1);
        updateSkillList(category, newList);
    };

    const updateSkillName = (category: string, index: number, newName: string) => {
        const skillsMap = rules.definitions.skills || {};
        const currentList = skillsMap[category] || [];
        const newList = [...currentList];
        newList[index] = newName;
        updateSkillList(category, newList);
    };

    const handleSkillBlur = (category: string, skillName: string) => {
        const updatedRules = ensureSkillInLibrary(skillName, category, rules);
        if (updatedRules) {
            onUpdate(updatedRules);
        }
    };

    return {
        syncSuccess,
        handleSyncAll,
        updateLabel,
        updateBehavior,
        updateCategoryMetadata,
        updateSkillName,
        addSkill,
        removeSkill,
        handleSkillBlur,
        updateSkillList
    };
}

import { RulesData } from '../../types/rules';
import { LibraryEntry, LibrarySkillEntry, LibrarySpecializationEntry } from '../../types/system';

export interface DiffReport {
    hasChanges: boolean;
    details: {
        general: string[];
        attributes: string[];
        skills: string[];
        backgrounds: string[];
        counters: string[];
        libraries: {
            traits: { new: number, conflict: number, identical: number };
            skills: { new: number, conflict: number, identical: number };
            specializations: { new: number, conflict: number, identical: number };
            backgrounds: { new: number, conflict: number, identical: number };
            counters: { new: number, conflict: number, identical: number };
        };
    };
}

export interface ImportOptions {
    sections: {
        general: boolean; // Config creation, xp, theme
        attributes: boolean; // Definitions
        skills: boolean; // Definitions
        backgrounds: boolean; // Definitions
        counters: boolean; // Definitions
        libraries: boolean; // Content
    };
    libraryStrategy: 'ignore' | 'overwrite' | 'copy';
}

const isDifferent = (a: any, b: any) => JSON.stringify(a) !== JSON.stringify(b);

export const calculateDiff = (current: RulesData, candidate: RulesData): DiffReport => {
    const report: DiffReport = {
        hasChanges: false,
        details: {
            general: [],
            attributes: [],
            skills: [],
            backgrounds: [],
            counters: [],
            libraries: {
                traits: { new: 0, conflict: 0, identical: 0 },
                skills: { new: 0, conflict: 0, identical: 0 },
                specializations: { new: 0, conflict: 0, identical: 0 },
                backgrounds: { new: 0, conflict: 0, identical: 0 },
                counters: { new: 0, conflict: 0, identical: 0 }
            }
        }
    };

    // 1. General Config
    if (isDifferent(current.configurations.creation, candidate.configurations.creation)) {
        report.details.general.push("Configuration de création modifiée");
    }
    if (isDifferent(current.configurations.xpCosts, candidate.configurations.xpCosts)) {
        report.details.general.push("Coûts XP modifiés");
    }


    // 2. Attributes
    const attrKeys = new Set([...Object.keys(current.definitions.attributes), ...Object.keys(candidate.definitions.attributes)]);
    attrKeys.forEach(k => {
        if (isDifferent(current.definitions.attributes[k], candidate.definitions.attributes[k])) {
            report.details.attributes.push(`Pavé "${k}" modifié`);
        }
    });

    // 3. Skills
    const skillKeys = new Set([...Object.keys(current.definitions.skills), ...Object.keys(candidate.definitions.skills)]);
    skillKeys.forEach(k => {
        if (isDifferent(current.definitions.skills[k], candidate.definitions.skills[k])) {
            report.details.skills.push(`Catégorie "${k}" modifiée`);
        }
    });

    // 4. Libraries Analysis
    const analyzeLib = <T extends { id: string }>(curr: T[], cand: T[]) => {
        const stats = { new: 0, conflict: 0, identical: 0 };
        const currMap = new Map(curr.map(i => [i.id, i]));

        cand.forEach(item => {
            if (!currMap.has(item.id)) {
                stats.new++;
            } else {
                if (isDifferent(currMap.get(item.id), item)) {
                    stats.conflict++;
                } else {
                    stats.identical++;
                }
            }
        });
        return stats;
    };

    if (candidate.libraries?.traits) {
        report.details.libraries.traits = analyzeLib(current.libraries?.traits || [], candidate.libraries.traits);
    }
    if (candidate.libraries?.skills) {
        report.details.libraries.skills = analyzeLib(current.libraries?.skills || [], candidate.libraries.skills);
    }

    // Calculate Global Change Flag
    report.hasChanges =
        report.details.general.length > 0 ||
        report.details.attributes.length > 0 ||
        report.details.skills.length > 0 ||
        report.details.libraries.traits.new > 0 ||
        report.details.libraries.traits.conflict > 0;
    // ... (add others)

    return report;
};

export const mergeRules = (current: RulesData, candidate: RulesData, options: ImportOptions): RulesData => {
    // Deep clone current to start
    const result: RulesData = JSON.parse(JSON.stringify(current));

    if (options.sections.general) {
        result.configurations.creation = candidate.configurations.creation;
        result.configurations.xpCosts = candidate.configurations.xpCosts;

        // Also card config if present? Assuming included in general
        result.configurations.cards = candidate.configurations.cards;
    }

    if (options.sections.attributes) {
        result.definitions.attributes = candidate.definitions.attributes;
        result.definitions.secondaryAttributes = candidate.definitions.secondaryAttributes;
        result.configurations.global.secondaryAttributes = candidate.configurations.global.secondaryAttributes;
        result.configurations.global.maxAttributeScore = candidate.configurations.global.maxAttributeScore;
    }

    if (options.sections.skills) {
        result.definitions.skills = candidate.definitions.skills;
        result.definitions.labels = candidate.definitions.labels; // Labels usually go with skills definitions
    }

    if (options.sections.backgrounds) {
        result.definitions.backgrounds = candidate.definitions.backgrounds;
    }

    if (options.sections.counters) {
        result.definitions.counters = candidate.definitions.counters;
    }

    // Library Merge Logic
    if (options.sections.libraries) {
        // Ensure library buckets exist
        if (!result.libraries) result.libraries = { traits: [], skills: [], specializations: [], backgrounds: [], counters: [] };

        const mergeLibList = <T extends { id: string }>(curr: T[], cand: T[]) => {
            const map = new Map(curr.map(i => [i.id, i]));

            cand.forEach(item => {
                if (!map.has(item.id)) {
                    // New item
                    map.set(item.id, item);
                } else {
                    // Conflict
                    if (options.libraryStrategy === 'overwrite') {
                        map.set(item.id, item);
                    } else if (options.libraryStrategy === 'copy') {
                        // Create copy with new ID
                        const copy = { ...item, id: crypto.randomUUID() };
                        map.set(copy.id, copy);
                    }
                    // if 'ignore', do nothing
                }
            });
            return Array.from(map.values());
        };

        if (candidate.libraries?.traits) {
            result.libraries.traits = mergeLibList(current.libraries?.traits || [], candidate.libraries.traits);
        }
        if (candidate.libraries?.skills) {
            result.libraries.skills = mergeLibList(current.libraries?.skills || [], candidate.libraries.skills);
        }
    }

    return result;
};

import { RulesData } from '../../types/rules';
import { INITIAL_DATA } from '../../data/initialState';
import { logger } from '../../utils/logger';
import { DotEntry, AttributeEntry } from '../../types';

declare global {
    interface Window {
        EXTERNAL_RULES?: RulesData;
    }
}

/**
 * Generates a default RulesData object based on the Application's hardcoded Initial State.
 * This serves as a fallback when no external rules.js is loaded (e.g. first deployment).
 */
export const generateDefaultRules = (): RulesData => {
    const data = INITIAL_DATA;

    // Helper to extract names
    const extractNames = (list: (DotEntry | AttributeEntry)[] | undefined): string[] => {
        if (!Array.isArray(list)) return [];
        return list.map(item => item.name || "");
    };

    // Construct Definitions
    const skillDefs: Record<string, string[]> = {};
    if (data.skills) {
        Object.keys(data.skills).forEach(key => {
            skillDefs[key] = extractNames(data.skills[key]);
        });
    }

    const attrDefs: Record<string, string[]> = {};
    if (data.attributes) {
        Object.keys(data.attributes).forEach(key => {
            attrDefs[key] = extractNames(data.attributes[key]);
        });
    }

    const secAttrDefs: Record<string, string[]> = {};
    if (data.secondaryAttributes) {
        Object.keys(data.secondaryAttributes).forEach(key => {
            secAttrDefs[key] = extractNames(data.secondaryAttributes[key]);
        });
    }

    const counterDefs: Record<string, any> = {};
    if (data.counters) {
        Object.keys(data.counters).forEach(key => {
            if (key === 'custom') return;
            const c = (data.counters as Record<string, any>)[key];
            if (c && !Array.isArray(c)) {
                counterDefs[key] = {
                    id: key,
                    name: c.name,
                    max: c.max, // Initial State max
                    xpCost: 5 // Default assumption
                };
            }
        });
    }

    const backgroundDefs = data.skills.arrieres_plans
        ? extractNames(data.skills.arrieres_plans).filter(n => n.trim() !== "")
        : [];

    return {
        settingId: "standard-rules",
        settingName: "Règles Standard",
        version: "2.12.55",
        configurations: {
            creation: data.creationConfig,

            xpCosts: {
                attributeFactor: 6,
                skillFactor: 1,
                specializationFactor: 0
            },
            cards: {
                ...data.creationConfig.cardConfig,
                ranks: ['Valet', 'Dame', 'Roi'],
                counts: ['Un', 'Deux', 'Trois', 'Quatre'],
                maxLabel: 'Quatre Rois (Max)'
            },
            global: {
                maxAttributeScore: 5,
                maxSkillScore: 5,
                secondaryAttributes: data.secondaryAttributesActive
            }
        },
        definitions: {
            attributes: attrDefs,
            secondaryAttributes: secAttrDefs,
            skills: skillDefs,
            skillCategories: [
                { id: 'Col_Comp_1', label: 'Talents', behavior: 'Compétence', allowSpecializations: true, costConfig: { factor: 1, type: 'triangular' } },
                { id: 'Col_Comp_2', label: 'Compétences', behavior: 'Compétence', allowSpecializations: true, costConfig: { factor: 1, type: 'triangular' } },
                { id: 'Col_Comp_3', label: 'Compétences (Suite)', behavior: 'Compétence', allowSpecializations: true, costConfig: { factor: 1, type: 'triangular' } },
                { id: 'Col_Comp_4', label: 'Connaissances', behavior: 'Compétence', allowSpecializations: true, costConfig: { factor: 1, type: 'triangular' } },
                { id: 'Col_Comp_5', label: 'Autres Compétences', behavior: 'Compétence', allowSpecializations: true, costConfig: { factor: 1, type: 'triangular' } },
                { id: 'Col_Comp_6', label: 'Compétences Secondaires', behavior: 'Secondaire', allowSpecializations: false, costConfig: { factor: 0.5, type: 'triangular' } },
                { id: 'Col_Comp_7', label: 'Autres', behavior: 'Secondaire', allowSpecializations: false, costConfig: { factor: 0.5, type: 'triangular' } },
                { id: 'Col_Comp_8', label: 'Arrières Plans', behavior: 'Arrière-plan', allowSpecializations: false, costConfig: { factor: 1, type: 'linear' } },
                { id: 'Col_Comp_9', label: 'Compteurs', behavior: 'Compteur', allowSpecializations: false, costConfig: { factor: 1, type: 'linear' } }
            ],
            backgrounds: backgroundDefs,
            counters: counterDefs,
            labels: {
                // Default Labels mapped to IDs
                talents: "Talents",
                competences: "Compétences",
                competences_col_2: "Compétences (Suite)",
                connaissances: "Connaissances",
                competences2: "Compétences Secondaires",
                autres_competences: "Autres Compétences",
                autres: "Autres"
            }
        },
        libraries: {
            traits: data.library || [],
            skills: data.skillLibrary || [],
            specializations: data.specializationLibrary || [],
            backgrounds: [],
            counters: []
        }
    };
};

export const loadRules = (): RulesData => {
    if (window.EXTERNAL_RULES) {
        return window.EXTERNAL_RULES;
    }

    logger.warn("rules.js not found. Loading fallback rules from Initial State.");
    return generateDefaultRules();
};

import { CharacterSheetData, DotEntry, AttributeEntry } from '../../types';
import { RulesData } from '../../types/rules';

/**
 * Tries to detect if the JSON is a Full Backup or a Direct Sheet Export
 * and returns the CharacterSheetData if found.
 */
const normalizeInput = (json: any): CharacterSheetData | null => {
    if (!json || typeof json !== 'object') return null;

    // 1. Direct CharacterSheetData
    if (json.header && json.attributes && json.skills) {
        return json as CharacterSheetData;
    }

    // 2. Full Backup Wrapper (legacy or specific export)
    if (json.data && typeof json.data === 'object' && json.data.header && json.data.attributes) {
        return json.data as CharacterSheetData;
    }

    // 3. "System" or "Template" export from ExportPanel
    if (json.creationConfig && json.skills) {
        return json as CharacterSheetData;
    }

    return null;
};

/**
 * Extracts configuration and definitions from a Character Sheet
 * to update the Admin Rules.
 */
export const extractRulesFromCharacter = (
    inputJson: unknown,
    currentRules: RulesData
): { rules: RulesData; report: { success: string[]; warnings: string[] } } => {
    const sheet = normalizeInput(inputJson);
    const warnings: string[] = [];
    const success: string[] = [];

    if (!sheet) {
        throw new Error("Format de fichier non reconnu. Veuillez importer un JSON de Personnage ou de Template (Système).");
    }

    const newRules: RulesData = JSON.parse(JSON.stringify(currentRules));

    // Ensure libraries structure exists
    if (!newRules.libraries) {
        newRules.libraries = {
            traits: [],
            skills: [],
            specializations: [],
            backgrounds: [],
            counters: []
        };
    }

    // 1. Import Creation Config
    if (sheet.creationConfig) {
        newRules.configurations.creation = {
            ...newRules.configurations.creation,
            ...sheet.creationConfig,
            // Deep merge rank slots if present
            rankSlots: sheet.creationConfig.rankSlots || newRules.configurations.creation.rankSlots
        };
        success.push("Configuration de Création (Points, Mode)");
    } else {
        warnings.push("Configuration de Création manquante (ignoré).");
    }

    // 2. Import XP Costs
    if (sheet.xpCosts) {
        newRules.configurations.xpCosts = {
            ...newRules.configurations.xpCosts,
            ...sheet.xpCosts
        };
        success.push("Configuration des Coûts XP (Multiplicateurs)");
    } else {
        // Fallback: If not present in sheet (old version), keep current rules
        warnings.push("Coûts XP (Multiplicateurs) manquants dans le fichier (ignoré).");
    }


    // 4. Import Attributes Definitions
    if (sheet.attributes) {
        const newAttrs: Record<string, string[]> = {};
        Object.keys(sheet.attributes).forEach(cat => {
            const list = sheet.attributes[cat];
            if (Array.isArray(list)) {
                newAttrs[cat] = list.map((a: AttributeEntry) => a.name);
            }
        });

        // Also Secondary Attributes if active
        if (sheet.secondaryAttributesActive && sheet.secondaryAttributes) {
            const newSecAttrs: Record<string, string[]> = {};
            Object.keys(sheet.secondaryAttributes).forEach(cat => {
                const list = sheet.secondaryAttributes[cat];
                if (Array.isArray(list)) {
                    newSecAttrs[cat] = list.map((a: AttributeEntry) => a.name);
                }
            });
            newRules.definitions.secondaryAttributes = newSecAttrs;

            // Sync with Global Config Flag
            newRules.configurations.global.secondaryAttributes = true;

            success.push("Définitions des Attributs (Primaires et Secondaires)");
        } else {
            // Ensure flag is false if not active
            newRules.configurations.global.secondaryAttributes = false;
            success.push("Définitions des Attributs (Primaires)");
        }

        newRules.definitions.attributes = newAttrs;
    }

    // 5. Import Skills Definitions
    if (sheet.skills) {
        const newSkills: Record<string, string[]> = {};
        Object.keys(sheet.skills).forEach(cat => {
            const list = (sheet.skills as Record<string, DotEntry[]>)[cat];
            if (Array.isArray(list)) {
                newSkills[cat] = list
                    .map((s: DotEntry) => s.name ? s.name : "") // Keep name or empty string for spacer
                    .filter((name: string) => name !== undefined && name !== null); // Only filter real nulls
            }
        });
        newRules.definitions.skills = newSkills;
        success.push(`Définitions des Compétences (${Object.keys(newSkills).length} catégories)`);
    }

    // 6. Import Backgrounds (Arrières-Plans)
    if (sheet.skills && (sheet.skills as Record<string, DotEntry[]>).arrieres_plans) {
        const bgList = (sheet.skills as Record<string, DotEntry[]>).arrieres_plans
            .filter((s: DotEntry) => s.name && s.name.trim() !== "")
            .map((s: DotEntry) => s.name);

        newRules.definitions.backgrounds = bgList;
        success.push(`Définitions Arrière-Plans (${bgList.length} items)`);
    }

    // 7. Import Counters (Best Effort)
    if (sheet.counters) {
        const rulesCounters: Record<string, any> = {};
        Object.keys(sheet.counters).forEach(key => {
            if (key === 'custom') return;
            const c = (sheet.counters as Record<string, any>)[key];
            if (c && !Array.isArray(c)) {
                rulesCounters[key] = {
                    id: key,
                    name: c.name || key,
                    max: c.value || 10, // On sheet, value is the Max dots
                    xpCost: 5 // Default if unknown
                };
            }
        });

        // If we are updating rules, we might want to keep existing config if keys match?
        // But here we are overwriting.
        newRules.definitions.counters = rulesCounters;
        success.push(`Définitions Compteurs (${Object.keys(rulesCounters).length} items detected)`);
    }

    // Import Background Cost config
    if (sheet.creationConfig && sheet.creationConfig.backgroundCost !== undefined) {
        newRules.configurations.creation.backgroundCost = sheet.creationConfig.backgroundCost;
    }


    // 8. Import Libraries (Traits & Skills)
    // We treat the sheet's library/skillLibrary as candidates
    if (sheet.library && Array.isArray(sheet.library)) {
        newRules.libraries.traits = sheet.library;
        success.push(`Bibliothèque de Traits (${sheet.library.length} items)`);
    }

    if (sheet.skillLibrary && Array.isArray(sheet.skillLibrary)) {
        newRules.libraries.skills = sheet.skillLibrary;
        success.push(`Réserve de Compétences (${sheet.skillLibrary.length} items)`);
    }

    if (sheet.specializationLibrary && Array.isArray(sheet.specializationLibrary)) {
        newRules.libraries.specializations = sheet.specializationLibrary;
        success.push(`Bibliothèque de Spécialisations (${sheet.specializationLibrary.length} items)`);
    }

    return { rules: newRules, report: { success, warnings } };
};

