    <div className={`w-full px-6 pb-20 mx-auto relative flex transition-all duration-300 ${!showAdvancedTabs ? 'max-w-[1100px]' : 'max-w-[1600px]'}`}>
      {/* --- LEFT COLUMN: Main Content --- */}
      <div className={`flex-grow transition-all duration-300 ${(activeTab === 'skills' || activeTab === 'specializations') ? 'mr-80' : ''}`}>


        {/* Expert Mode Warning Banner */}
        {isOnlineMode && expertMode && (
          <div className="sticky top-14 z-50 mb-2 flex justify-center no-print">
            <div className="flex items-center gap-3 bg-amber-100 border border-amber-300 text-amber-800 px-4 py-2 rounded-full shadow-md text-xs font-bold animate-in fade-in slide-in-from-top-2 duration-200">
              <AlertTriangle size={16} />
              <span>Mode Expert activé — Les modifications peuvent causer des conflits avec les règles de la campagne</span>
              <button
                onClick={disableExpertMode}
                className="ml-2 px-2 py-1 bg-amber-200 hover:bg-amber-300 rounded text-[10px] uppercase tracking-wide"
              >
                Désactiver
              </button>
            </div>
          </div>
        )}

        {/* Header Navigation */}
        <div className="sticky top-14 z-40 mb-8 flex justify-center no-print pointer-events-none" style={{ top: isOnlineMode && expertMode ? '4.5rem' : '3.5rem' }}>
          <div className="pointer-events-auto flex gap-2 bg-[#fdfbf7]/90 backdrop-blur-sm p-1.5 rounded-full shadow-xl border border-[#bfae85]/30 items-center animate-in fade-in slide-in-from-top-4 duration-300 flex-wrap justify-center">

            {/* Advanced tabs - only shown if !isOnlineMode OR expertMode */}
            {showAdvancedTabs && (
              <>
                <button onClick={() => setActiveTab('attributes')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'attributes' ? 'bg-[#8b2e2e] text-white shadow-md ring-2 ring-[#8b2e2e]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}><LayoutGrid size={16} /> Attributs</button>
                <button onClick={() => setActiveTab('skills')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'skills' ? 'bg-[#8b2e2e] text-white shadow-md ring-2 ring-[#8b2e2e]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}><List size={16} /> Compétences</button>
                <button onClick={() => setActiveTab('specializations')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'specializations' ? 'bg-[#8b2e2e] text-white shadow-md ring-2 ring-[#8b2e2e]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}><Tag size={16} /> Spécialisations</button>
                <button onClick={() => setActiveTab('creation')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'creation' ? 'bg-[#8b2e2e] text-white shadow-md ring-2 ring-[#8b2e2e]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}><UserPlus size={16} /> Paramètres</button>
                <button onClick={() => setActiveTab('suggestions')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'suggestions' ? 'bg-[#8b2e2e] text-white shadow-md ring-2 ring-[#8b2e2e]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}>
                  <Lightbulb size={16} /> Suggestions {localData.suggestions && localData.suggestions.length > 0 ? `(${localData.suggestions.length})` : ''}
                </button>
              </>
            )}

            {/* Réglages Avancés button - only shown in Online mode when Expert is OFF */}
            {isOnlineMode && !expertMode && (
              <button
                onClick={() => setShowExpertWarning(true)}
                className="px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all text-amber-700 bg-amber-100/50 hover:bg-amber-200/70 border border-amber-300/50"
              >
                <Lock size={16} /> Réglages Avancés
              </button>
            )}

            {/* Cloud tab - always visible if syncId exists */}
            {localData.syncInfo?.syncId && (
              <button onClick={() => setActiveTab('cloud')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'cloud' ? 'bg-[#2d5a27] text-white shadow-md ring-2 ring-[#2d5a27]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}><UploadCloud size={16} /> Cloud</button>
            )}

            {/* Bibliothèque tab - always visible */}
            <button onClick={() => setActiveTab('library')} className={`px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'library' ? 'bg-[#8b2e2e] text-white shadow-md ring-2 ring-[#8b2e2e]/20' : 'text-[#5c4d41] hover:bg-[#bfae85]/10'}`}><BookOpen size={16} /> Bibliothèque</button>
          </div>
        </div>

        <div className="flex justify-between items-center p-6 border-y border-[#bfae85]/30 bg-[#fdfbf7]/50 backdrop-blur-sm mb-8 rounded-sm">
          <ThematicButton
            variant="danger"
            onClick={() => setShowResetConfirm(true)}
            leftIcon={<AlertTriangle size={18} />}
          >
            Réinitialiser
          </ThematicButton>

          <div className="flex gap-4">
            <ThematicButton
              variant="secondary"
              onClick={onClose}
            >
              Fermer
            </ThematicButton>

            <ThematicButton
              variant="primary"
              onClick={handleSave}
              disabled={!isDirty}
              leftIcon={<Save size={18} />}
            >
              {isDirty ? 'Enregistrer' : 'À jour'}
            </ThematicButton>
          </div>
        </div>

        <div className="space-y-8 min-h-[400px]">
          {activeTab === 'attributes' && (
            <AttributesEditor
              data={localData}
              onUpdate={handleLocalUpdate}
              onAddLog={onAddLog}
            />
          )}

          {activeTab === 'skills' && (
            <SkillsEditor
              data={localData}
              onUpdate={handleLocalUpdate}
              onAddLog={onAddLog}
              draggedItem={draggedItem}
              setDraggedItem={setDraggedItem}
            />
          )}

          {activeTab === 'specializations' && (
            <SpecializationsEditor
              data={localData}
              onUpdate={handleLocalUpdate}
              onAddLog={onAddLog}
            />
          )}

          {activeTab === 'creation' && (
            <CreationConfigEditor
              data={localData}
              onUpdate={handleLocalUpdate}
              onAddLog={onAddLog}
            />
          )}

          {activeTab === 'suggestions' && (
            <AdminSuggestions
              data={localData}
              onUpdate={handleLocalUpdate}
              onAddLog={onAddLog}
            />
          )}

          {activeTab === 'library' && (
            <div className="h-[calc(100vh-250px)] min-h-[600px] border border-[#bfae85]/30 rounded-sm overflow-hidden shadow-sm">
              <LibraryView data={localData} onUpdate={handleLocalUpdate} />
            </div>
          )}

          {activeTab === 'cloud' && (
            <div className="max-w-2xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
              <div className="bg-white p-8 rounded-sm border border-[#bfae85]/30 shadow-sm relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-5 rotate-12"><UploadCloud size={120} /></div>

                <h3 className="text-2xl font-serif font-bold text-[#2c241b] mb-6 flex items-center gap-3">
                  <div className="p-2 bg-indigo-50 text-indigo-700 rounded-sm"><RefreshCw size={24} /></div>
                  Paramètres Cloud
                </h3>

                <div className="space-y-6">
                  <div className="flex items-center justify-between p-4 bg-stone-50 border border-stone-200 rounded-sm hover:border-indigo-300 transition-colors">
                    <div className="flex-grow">
                      <div className="font-bold text-[#4a3b32]">Synchronisation Automatique</div>
                      <p className="text-xs text-stone-500 mt-1 max-w-md">
                        Sauvegarde automatiquement votre fiche personnage sur le serveur après chaque modification importante (délai de 10 secondes).
                      </p>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer ml-4">
                      <input
                        type="checkbox"
                        className="sr-only peer"
                        checked={localData.syncInfo?.isAutoSyncEnabled || false}
                        onChange={(e) => handleLocalUpdate({
                          ...localData,
                          syncInfo: {
                            ...localData.syncInfo!,
                            isAutoSyncEnabled: e.target.checked
                          }
                        })}
                      />
                      <div className="w-14 h-7 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[4px] after:left-[4px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-6 after:transition-all peer-checked:bg-indigo-600"></div>
                    </label>
                  </div>

                  <StorageMonitor />

                  <div className="p-4 border border-[#bfae85]/30 rounded-sm bg-[#fdfbf7]">
                    <h4 className="text-xs font-bold text-[#8b2e2e] uppercase tracking-widest mb-3 border-b border-[#bfae85]/20 pb-2">Informations de Synchronisation</h4>
                    <div className="grid grid-cols-2 gap-4 text-xs">
                      <div>
                        <span className="text-stone-500">ID Unique :</span>
                        <div className="font-mono mt-1 text-[#4a3b32] truncate bg-stone-100 p-1 rounded" title={localData.syncInfo?.syncId}>{localData.syncInfo?.syncId}</div>
                      </div>
                      <div>
                        <span className="text-stone-500">Campagne :</span>
                        <div className="font-bold mt-1 text-[#4a3b32]">{localData.syncInfo?.settingName}</div>
                      </div>
                      <div>
                        <span className="text-stone-500">Joueur :</span>
                        <div className="font-bold mt-1 text-[#4a3b32]">{localData.header.player}</div>
                      </div>
                      <div>
                        <span className="text-stone-500">Dernière Sauvegarde :</span>
                        <div className="font-bold mt-1 text-[#4a3b32]">
                          {localData.syncInfo?.lastSynced ? new Date(localData.syncInfo.lastSynced).toLocaleString('fr-FR') : 'Jamais'}
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 p-3 bg-amber-50 border border-amber-200 text-amber-800 rounded-sm text-xs">
                    <AlertTriangle size={18} className="shrink-0" />
                    <p>La synchronisation manuelle reste disponible à tout moment via le bouton Sync de la barre de navigation.</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* --- RIGHT COLUMN: Library Sidebar (Only in Skills Tab) --- */}
      {activeTab === 'skills' && (
        <LibrarySidebar
          data={localData}
          onUpdate={handleLocalUpdate}
          onAddLog={onAddLog}
          draggedItem={draggedItem}
          setDraggedItem={setDraggedItem}
        />
      )}

      {activeTab === 'specializations' && (
        <SpecializationLibrarySidebar
          data={localData}
          onUpdate={handleLocalUpdate}
          onAddLog={onAddLog}
        />
      )}

      {activeTab === 'suggestions' && (
        <div className="hidden lg:block w-80 shrink-0 ml-6 bg-white border border-[#bfae85]/30 rounded-sm p-4 h-fit sticky top-24">
          <div className="text-xs text-stone-500 italic text-center">
            Les suggestions validées modifient immédiatement les règles chargées en mémoire. Pensez à exporter vos règles ensuite.
          </div>
        </div>
      )}

      {/* Reset Confirmation Modal */}
      {showResetConfirm && (
        <ThematicModal
          isOpen={showResetConfirm}
          onClose={() => setShowResetConfirm(false)}
          title="Réinitialisation Complète"
          icon={<AlertCircle size={24} className="text-[#8b2e2e]" />}
          size="md"
          footer={
            <>
              <button onClick={() => setShowResetConfirm(false)} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
              <button onClick={performReset} className="px-6 py-2 bg-[#8b2e2e] text-white rounded-sm font-bold shadow-md hover:bg-[#6a2424]">
                Confirmer la purge
              </button>
            </>
          }
        >
          <div className="flex flex-col items-center text-center space-y-4 py-4">
            <div className="w-16 h-16 bg-[#8b2e2e]/10 text-[#8b2e2e] rounded-full flex items-center justify-center shadow-inner">
              <RefreshCw size={32} />
            </div>
            <div className="space-y-2">
              <p className="text-sm text-[#5c4d41] leading-relaxed">
                Êtes-vous sûr de vouloir réinitialiser toute la fiche aux valeurs par défaut ?
              </p>
              <div className="bg-red-50/50 border border-red-200/50 p-3 rounded-sm">
                <p className="text-[11px] font-bold text-[#8b2e2e] uppercase tracking-wider">Attention : Perte de données</p>
                <p className="text-[10px] text-red-800/70 mt-1 italic">
                  Toutes les données actuelles et la structure personnalisée seront définitivement perdues.
                </p>
              </div>
            </div>
          </div>
        </ThematicModal>
      )}

      {/* Expert Mode Warning Modal */}
      <ExpertModeWarningModal
        isOpen={showExpertWarning}
        onClose={() => setShowExpertWarning(false)}
        onConfirm={() => {
          enableExpertMode();
          setShowExpertWarning(false);
        }}
      />
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect } from 'react';
import { UploadCloud, AlertTriangle, CheckCircle, RefreshCw } from 'lucide-react';
import ThematicModal from './ui/ThematicModal';
import { CharacterSyncService } from '../services/CharacterSyncService';
import { CharacterSheetData } from '../types/character';
import { GameSettingSummary, CampaignService } from '../services/CampaignService';
import { useRules } from '../context/RulesContext';
import { ErrorService } from '../services/ErrorService';

interface SyncModalProps {
    isOpen: boolean;
    onClose: () => void;
    characterData: CharacterSheetData;
    onSyncComplete: (syncInfo: CharacterSheetData['syncInfo']) => void;
}

type SyncStatus = 'idle' | 'loading' | 'success' | 'error';

const SyncModal: React.FC<SyncModalProps> = ({
    isOpen,
    onClose,
    characterData,
    onSyncComplete
}) => {
    const { isOnlineMode, rules } = useRules();
    const [campaigns, setCampaigns] = useState<GameSettingSummary[]>([]);
    const [selectedCampaign, setSelectedCampaign] = useState<string>('');
    const [playerName, setPlayerName] = useState<string>('');
    const [characterName, setCharacterName] = useState<string>('');
    const [status, setStatus] = useState<SyncStatus>('idle');
    const [errorMessage, setErrorMessage] = useState<string>('');
    const [isLoadingCampaigns, setIsLoadingCampaigns] = useState(false);
    const [isAutoSync, setIsAutoSync] = useState(false);

    // Pre-fill from existing syncInfo or header
    useEffect(() => {
        if (isOpen) {
            // Priority 1: Current Rules (if online)
            if (isOnlineMode && rules?.settingId) {
                setSelectedCampaign(rules.settingId);
            }
            // Priority 2: Existing sync info (if not online or as fallback)
            else if (characterData.syncInfo) {
                setSelectedCampaign(characterData.syncInfo?.settingId || '');
            }

            // Pre-fill names from header
            setPlayerName(characterData.header?.player || '');
            setCharacterName(characterData.header?.name || '');
            setIsAutoSync(characterData.syncInfo?.isAutoSyncEnabled || false);
            setStatus('idle');
            setErrorMessage('');
        }
    }, [isOpen, characterData, isOnlineMode, rules]);

    // Load public campaigns
    useEffect(() => {
        if (isOpen && campaigns.length === 0) {
            loadCampaigns();
        }
    }, [isOpen]);

    const loadCampaigns = async () => {
        setIsLoadingCampaigns(true);
        try {
            const publicSettings = await CampaignService.listPublicSettings();
            setCampaigns(publicSettings);
            // Auto-select first campaign if none selected
            if (publicSettings.length > 0 && !selectedCampaign) {
                setSelectedCampaign(publicSettings[0].id);
            }
        } catch (e) {
            ErrorService.handleError(e, { context: 'SyncModal.loadCampaigns', userMessage: 'Impossible de charger la liste des campagnes.' });
        } finally {
            setIsLoadingCampaigns(false);
        }
    };

    const handleSync = async () => {
        if (!selectedCampaign || !playerName.trim() || !characterName.trim()) {
            setErrorMessage('Veuillez remplir tous les champs');
            return;
        }

        setStatus('loading');
        setErrorMessage('');

        const result = await CharacterSyncService.syncCharacter(
            selectedCampaign,
            playerName.trim(),
            characterName.trim(),
            characterData
        );

        if (result.success && result.syncId) {
            setStatus('success');
            const campaignData = campaigns.find(c => c.id === selectedCampaign);

            // Notify parent with new sync info
            onSyncComplete({
                syncId: result.syncId,
                settingId: selectedCampaign,
                settingName: campaignData?.name || 'Campagne',
                lastSynced: Date.now(),
                isAutoSyncEnabled: isAutoSync
            });

            // Close after short delay to show success
            setTimeout(() => {
                onClose();
            }, 1500);
        } else {
            setStatus('error');
            setErrorMessage(result.error || 'Échec de la synchronisation');
        }
    };

    const canSync = selectedCampaign && playerName.trim() && characterName.trim() && status !== 'loading';

    return (
        <ThematicModal
            isOpen={isOpen}
            onClose={onClose}
            title="Synchroniser avec le MJ"
            icon={<UploadCloud size={28} />}
            size="sm"
            footer={
                <div className="flex gap-3 w-full justify-end">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-[#5c4d41] hover:bg-[#bfae85]/20 rounded-md transition-colors"
                    >
                        Annuler
                    </button>
                    <button
                        onClick={handleSync}
                        disabled={!canSync}
                        className={`px-6 py-2 rounded-md font-bold flex items-center gap-2 transition-all ${canSync
                            ? 'bg-[#2d5a27] hover:bg-[#3d7a37] text-white'
                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                            }`}
                    >
                        {status === 'loading' ? (
                            <>
                                <span className="animate-spin">⏳</span>
                                <span className="ml-2">Synchronisation...</span>
                            </>
                        ) : status === 'success' ? (
                            <>
                                <CheckCircle size={18} />
                                <span className="ml-2">Synchronisé !</span>
                            </>
                        ) : (
                            <>
                                <UploadCloud size={18} />
                                <span className="ml-2">Synchroniser</span>
                            </>
                        )}
                    </button>
                </div>
            }
        >
            <div className="space-y-5">
                {/* Info Banner */}
                <div className="bg-blue-50 border border-blue-200 rounded-md p-3 text-sm text-blue-800">
                    <p>
                        Cette action enverra une copie de votre fiche au MJ de la campagne sélectionnée.
                        Vos données locales ne seront pas modifiées.
                    </p>
                </div>

                {/* Campaign Selector */}
                <div>
                    <div className="flex justify-between items-center mb-1.5">
                        <label className="block text-sm font-bold text-[#4a3b32]">
                            Campagne
                        </label>
                        {isOnlineMode && (
                            <span className="text-[10px] bg-amber-100 text-amber-700 font-bold px-2 py-0.5 rounded border border-amber-200 uppercase flex items-center gap-1">
                                <span className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></span>
                                Verrouillé sur session active
                            </span>
                        )}
                    </div>
                    {isLoadingCampaigns ? (
                        <div className="text-gray-500 text-sm">Chargement des campagnes...</div>
                    ) : campaigns.length === 0 ? (
                        <div className="text-amber-600 text-sm flex items-center gap-2">
                            <AlertTriangle size={16} />
                            Aucune campagne publique disponible
                        </div>
                    ) : (
                        <select
                            value={selectedCampaign}
                            onChange={(e) => setSelectedCampaign(e.target.value)}
                            disabled={isOnlineMode}
                            className={`w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e] ${isOnlineMode ? 'opacity-70 bg-stone-50 cursor-not-allowed' : ''}`}
                        >
                            {campaigns.map(campaign => (
                                <option key={campaign.id} value={campaign.id}>
                                    {campaign.name} (v{campaign.version})
                                </option>
                            ))}
                        </select>
                    )}
                    {isOnlineMode && (
                        <p className="mt-1.5 text-[11px] text-stone-500 italic">
                            Les règles appliquées dépendent de cette campagne. Vous ne pouvez pas synchroniser sur une autre source sans recharger l'application.
                        </p>
                    )}
                </div>

                {/* Player Name */}
                <div>
                    <label className="block text-sm font-bold text-[#4a3b32] mb-1.5">
                        Nom du Joueur
                    </label>
                    <input
                        type="text"
                        value={playerName}
                        onChange={(e) => setPlayerName(e.target.value)}
                        placeholder="Votre nom"
                        className="w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e]"
                    />
                </div>

                {/* Character Name */}
                <div>
                    <label className="block text-sm font-bold text-[#4a3b32] mb-1.5">
                        Nom du Personnage
                    </label>
                    <input
                        type="text"
                        value={characterName}
                        onChange={(e) => setCharacterName(e.target.value)}
                        placeholder="Nom du personnage"
                        className="w-full px-3 py-2 border border-[#bfae85] rounded-md bg-white text-[#2c241b] focus:outline-none focus:ring-2 focus:ring-[#8b2e2e]"
                    />
                </div>

                {/* Auto-sync Toggle */}
                <div className="flex items-center justify-between p-3 bg-indigo-50 border border-indigo-100 rounded-md">
                    <div>
                        <div className="text-sm font-bold text-indigo-900 flex items-center gap-2">
                            <RefreshCw size={14} className={isAutoSync ? "animate-spin-slow" : ""} />
                            Synchronisation automatique
                        </div>
                        <p className="text-[11px] text-indigo-700 mt-0.5">
                            Sauvegarde vers le cloud après chaque modification (délai 10s).
                        </p>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                        <input
                            type="checkbox"
                            className="sr-only peer"
                            checked={isAutoSync}
                            onChange={(e) => setIsAutoSync(e.target.checked)}
                        />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                    </label>
                </div>

                {/* Error Message */}
                {errorMessage && (
                    <div className="bg-red-50 border border-red-300 rounded-md p-3 text-sm text-red-700 flex items-center gap-2">
                        <AlertTriangle size={16} />
                        {errorMessage}
                    </div>
                )}

                {/* Success Message */}
                {status === 'success' && (
                    <div className="bg-green-50 border border-green-300 rounded-md p-3 text-sm text-green-700 flex items-center gap-2">
                        <CheckCircle size={16} />
                        Fiche synchronisée avec succès !
                    </div>
                )}

                {/* Existing Sync Info */}
                {characterData.syncInfo && (
                    <div className="text-xs text-gray-500 border-t border-[#bfae85]/30 pt-3 mt-3">
                        Dernière sync : {new Date(characterData.syncInfo.lastSynced || Date.now()).toLocaleString('fr-FR')}
                        <br />
                        Campagne : {characterData.syncInfo.settingName}
                    </div>
                )}
            </div>
        </ThematicModal>
    );
};

export default SyncModal;

import React, { useState } from 'react';
import { CharacterSheetData, LibraryEntry } from '../types';
import { Search, Plus, BookOpen, Filter, Coins, Layers, ArrowDownAZ, ArrowUpAZ, Download, RefreshCw, X } from 'lucide-react';
import TraitCard from './trait-library/TraitCard';
import TraitForm from './trait-library/TraitForm';
import TraitImportModal from './trait-library/TraitImportModal';
import TraitVariantPicker from './trait-library/TraitVariantPicker';
import ConfirmationModal from './ui/ConfirmationModal';
import { useTraitLibrary, SortOption, SortOrder } from '../hooks/useTraitLibrary';
import { useTraitSelection } from '../hooks/useTraitSelection';
import { useTraitActions } from '../hooks/useTraitActions';

interface TraitLibraryProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onSelect?: (entry: LibraryEntry) => void;
    onMultiSelect?: (instances: { entry: LibraryEntry; variant?: string }[]) => void;
    isEditable?: boolean;
    defaultFilter?: 'all' | 'avantage' | 'desavantage';
}

const TraitLibrary: React.FC<TraitLibraryProps> = ({ data, onUpdate, onSelect, onMultiSelect, isEditable = true, defaultFilter = 'all' }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [filterType, setFilterType] = useState<'all' | 'avantage' | 'desavantage'>(defaultFilter);
    const [selectedTags, setSelectedTags] = useState<string[]>([]);
    const [sortBy, setSortBy] = useState<SortOption>('name');
    const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

    const { processedList, hybridList, allAvailableTags } = useTraitLibrary(
        data, searchTerm, filterType, selectedTags, sortBy, sortOrder
    );

    const {
        selection,
        variantPicker,
        setVariantPicker,
        toggleSelection,
        addInstanceWithVariant,
        removeInstance,
        handleConfirmMultiSelect
    } = useTraitSelection(onMultiSelect);

    const {
        isModalOpen,
        setIsModalOpen,
        editForm,
        setEditForm,
        tagInput,
        setTagInput,
        error,
        showDeleteConfirm,
        setShowDeleteConfirm,
        showOfficialUpdateConfirm,
        setShowOfficialUpdateConfirm,
        updateResult,
        setUpdateResult,
        handleOpenNew,
        handleOpenEdit,
        handleDelete,
        confirmDelete,
        handleSave,
        executeOfficialUpdate,
        handleImportTraits,
        addTag,
        removeTag,
        addEffect,
        updateEffect,
        removeEffect,
        allSkills,
        allAttributes
    } = useTraitActions(data, onUpdate, filterType === 'all' ? 'avantage' : filterType);

    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    const handleSortChange = (criteria: SortOption) => {
        if (sortBy === criteria) setSortOrder(prev => prev === 'asc' ? 'desc' : 'asc');
        else { setSortBy(criteria); setSortOrder('asc'); }
    };

    const toggleTagFilter = (tag: string) => {
        setSelectedTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    };

    const showFooter = !!onMultiSelect;

    return (
        <div className="flex flex-col h-full bg-[#fdfbf7] rounded-sm shadow-sm border border-[#bfae85]/50 overflow-hidden relative">
            <div className="p-4 bg-stone-100/30 border-b border-[#bfae85]/30 flex flex-col gap-3 shrink-0">
                <div className="flex justify-between items-center">
                    <h3 className="font-bold text-[#4a3b32] flex items-center gap-2">
                        <BookOpen size={20} className="text-[#8b2e2e]" /> Bibliothèque de Traits
                    </h3>
                    {isEditable && (
                        <div className="flex gap-2">
                            <button onClick={() => setShowOfficialUpdateConfirm(true)} className="bg-blue-50 border border-blue-200 text-blue-700 hover:bg-blue-100 px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap" title="Mettre à jour depuis le serveur officiel">
                                <RefreshCw size={14} /> Officiel
                            </button>
                            <button onClick={() => setIsImportModalOpen(true)} className="bg-white/80 border border-[#bfae85]/50 text-[#5c4d41] hover:bg-stone-50 hover:text-[#1c1917] px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap" title="Importer des traits depuis la fiche de personnage">
                                <Download size={14} /> Importer
                            </button>
                            <button onClick={handleOpenNew} className="bg-[#5c4d41] hover:bg-[#4a3b32] text-white px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap">
                                <Plus size={14} /> Créer
                            </button>
                        </div>
                    )}
                </div>

                <div className="flex gap-2 items-center flex-wrap md:flex-nowrap">
                    <div className="relative flex-grow min-w-[150px]">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3b32]/50" />
                        <input className="w-full pl-9 pr-3 py-1.5 text-sm border border-[#bfae85]/50 rounded-sm focus:border-amber-500 outline-none text-[#1c1917] placeholder-[#4a3b32]/40 bg-white/80" placeholder="Rechercher..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                    </div>
                    <div className="flex bg-[#bfae85]/20 rounded-sm p-0.5 shrink-0">
                        {['all', 'avantage', 'desavantage'].map((t) => (
                            <button key={t} onClick={() => setFilterType(t as any)} className={`px-3 py-1 text-xs font-bold rounded-sm transition-colors ${filterType === t ? 'bg-white text-[#5c4d41] shadow-sm' : 'text-[#5c4d41]/70 hover:text-[#5c4d41]'}`}>
                                {t === 'all' ? 'Tout' : t === 'avantage' ? 'Avantages' : 'Désavantages'}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex items-center gap-2 text-xs border-t border-[#bfae85]/20 pt-2">
                    <span className="font-bold text-[#5c4d41]/70 uppercase tracking-wide">Trier par :</span>
                    <button onClick={() => handleSortChange('name')} className={`flex items-center gap-1 px-2 py-1 rounded-sm border transition-colors ${sortBy === 'name' ? 'bg-amber-50/50 border-amber-200/50 text-amber-800' : 'bg-white/50 border-[#bfae85]/30 text-[#5c4d41] hover:bg-stone-50'}`}>
                        {sortBy === 'name' && (sortOrder === 'asc' ? <ArrowDownAZ size={14} /> : <ArrowUpAZ size={14} />)} Nom
                    </button>
                    <button onClick={() => handleSortChange('cost')} className={`flex items-center gap-1 px-2 py-1 rounded-sm border transition-colors ${sortBy === 'cost' ? 'bg-amber-50/50 border-amber-200/50 text-amber-800' : 'bg-white/50 border-[#bfae85]/30 text-[#5c4d41] hover:bg-stone-50'}`}>
                        <Coins size={14} /> Coût {sortBy === 'cost' && (sortOrder === 'asc' ? '↑' : '↓')}
                    </button>
                    <button onClick={() => handleSortChange('type')} className={`flex items-center gap-1 px-2 py-1 rounded-sm border transition-colors ${sortBy === 'type' ? 'bg-amber-50/50 border-amber-200/50 text-amber-800' : 'bg-white/50 border-[#bfae85]/30 text-[#5c4d41] hover:bg-stone-50'}`}>
                        <Layers size={14} /> Type {sortBy === 'type' && (sortOrder === 'asc' ? '↑' : '↓')}
                    </button>
                </div>

                {allAvailableTags.length > 0 && (
                    <div className="flex items-center gap-2 overflow-x-auto pb-1 no-scrollbar">
                        <Filter size={14} className="text-[#4a3b32]/50 shrink-0" />
                        <div className="flex gap-1">
                            {allAvailableTags.map(tag => (
                                <button key={tag} onClick={() => toggleTagFilter(tag)} className={`text-[10px] px-2 py-0.5 rounded-full border transition-colors whitespace-nowrap ${selectedTags.includes(tag) ? 'bg-[#8b2e2e] text-white border-[#8b2e2e]' : 'bg-white/50 text-[#5c4d41] border-[#bfae85]/30 hover:border-[#bfae85]/60'}`}>
                                    {tag}
                                </button>
                            ))}
                        </div>
                        {selectedTags.length > 0 && <button onClick={() => setSelectedTags([])} className="text-[10px] text-red-700/70 hover:text-red-800 whitespace-nowrap px-1">Effacer filtres</button>}
                    </div>
                )}
            </div>

            <div className={`flex-grow overflow-y-auto p-0 min-h-0 ${showFooter ? 'pb-16' : ''}`}>
                {hybridList.length === 0 && (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic px-4 text-sm">
                        {isEditable ? "La bibliothèque est vide. Ajoutez des avantages et désavantages ici pour les réutiliser facilement." : "La bibliothèque est vide."}
                    </div>
                )}
                {hybridList.length > 0 && processedList.length === 0 && (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic px-4">Aucun trait ne correspond à votre recherche.</div>
                )}

                <div className="divide-y divide-[#bfae85]/20">
                    {processedList.map(merged => (
                        <TraitCard
                            key={merged.entry.id}
                            entry={merged.entry}
                            isEditable={isEditable}
                            isSelected={selection.some(s => s.entry.id === merged.entry.id)}
                            onSelect={onSelect ? (entry) => onSelect(entry) : undefined}
                            onMultiSelect={(id) => toggleSelection(id, hybridList)}
                            onEdit={() => handleOpenEdit(merged)}
                            onDelete={(id) => handleDelete(id, merged.source)}
                            showMultiSelect={!!onMultiSelect}
                            source={merged.source}
                        />
                    ))}
                </div>
            </div>

            {showFooter && (
                <div className="absolute bottom-0 left-0 right-0 p-3 bg-[#fdfbf7] border-t border-[#bfae85]/30 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] flex flex-col gap-2 z-20">
                    {selection.length > 0 && (
                        <div className="flex flex-wrap gap-1.5 max-h-20 overflow-y-auto py-1">
                            {selection.map(s => (
                                <div key={s.tempId} className="flex items-center gap-1 bg-amber-100/50 border border-amber-200 rounded-full pl-2 pr-1 py-0.5 text-[10px] text-amber-900 group/item animate-in zoom-in-50 duration-200">
                                    <span className="font-bold">{s.entry.name}</span>
                                    {s.variant && <span className="opacity-60 italic">: {s.variant}</span>}
                                    <button onClick={() => removeInstance(s.tempId)} className="p-0.5 hover:bg-amber-200 rounded-full transition-colors"><X size={10} /></button>
                                </div>
                            ))}
                        </div>
                    )}
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-bold text-[#5c4d41]">{selection.length} trait(s) sélectionné(s)</span>
                        <button onClick={handleConfirmMultiSelect} disabled={selection.length === 0} className="bg-[#5c4d41] hover:bg-[#4a3b32] disabled:item-stone-300 disabled:cursor-not-allowed text-white px-4 py-2 rounded-sm font-bold text-sm flex items-center gap-2 shadow-sm transition-all">
                            <Plus size={16} /> Ajouter la sélection
                        </button>
                    </div>
                </div>
            )}

            {isImportModalOpen && (
                <TraitImportModal
                    data={data}
                    onClose={() => setIsImportModalOpen(false)}
                    onImport={(entries) => { handleImportTraits(entries); setIsImportModalOpen(false); }}
                />
            )}

            {variantPicker && (
                <TraitVariantPicker
                    variantPicker={variantPicker}
                    onClose={() => setVariantPicker(null)}
                    onSelect={addInstanceWithVariant}
                />
            )}

            {isModalOpen && editForm && (
                <TraitForm
                    editForm={editForm}
                    library={[]}
                    allSkills={allSkills}
                    allAttributes={allAttributes}
                    tagInput={tagInput}
                    error={error}
                    setEditForm={setEditForm}
                    setTagInput={setTagInput}
                    onClose={() => setIsModalOpen(false)}
                    onSave={handleSave}
                    addTag={addTag}
                    removeTag={removeTag}
                    addEffect={addEffect}
                    updateEffect={updateEffect}
                    removeEffect={removeEffect}
                />
            )}

            <ConfirmationModal
                isOpen={showOfficialUpdateConfirm}
                onClose={() => setShowOfficialUpdateConfirm(false)}
                onConfirm={executeOfficialUpdate}
                title="Mise à jour officielle"
                message="Voulez-vous télécharger la dernière version de la bibliothèque officielle ? Cela remplacera les traits officiels existants mais ne touchera pas à vos traits personnels."
                confirmLabel="Mettre à jour"
                type="info"
            />

            <ConfirmationModal
                isOpen={!!showDeleteConfirm}
                onClose={() => setShowDeleteConfirm(null)}
                onConfirm={confirmDelete}
                title="Supprimer le trait ?"
                message="Cette action supprimera ce trait de votre bibliothèque locale. Elle ne pourra pas être annulée."
                confirmLabel="Supprimer"
                type="danger"
            />

            <ConfirmationModal
                isOpen={!!updateResult}
                onClose={() => setUpdateResult(null)}
                onConfirm={() => setUpdateResult(null)}
                title={updateResult?.success ? "Succès" : "Erreur"}
                message={updateResult?.message || ""}
                confirmLabel="OK"
                type={updateResult?.success ? "success" : "danger"}
                cancelLabel=""
            />
        </div>
    );
};

export default TraitLibrary;

import React, { useEffect, useState } from 'react';
import { APP_VERSION, REMOTE_MANIFEST_URL } from '../constants/app';
import { Sparkles, RefreshCw, Download, X } from 'lucide-react';
import { logger } from '../utils/logger';

interface VersionManifest {
    version: string;
    downloadUrl?: string;
}

// Compare semantic versions (simple implementation)
const isNewer = (remote: string, local: string) => {
    const rParts = remote.split('.').map(Number);
    const lParts = local.split('.').map(Number);

    for (let i = 0; i < 3; i++) {
        if (rParts[i] > lParts[i]) return true;
        if (rParts[i] < lParts[i]) return false;
    }
    return false;
};

const UpdateNotifier: React.FC = () => {
    const [updateAvailable, setUpdateAvailable] = useState<VersionManifest | null>(null);
    const [isVisible, setIsVisible] = useState(true);
    const [isChecking, setIsChecking] = useState(false);

    useEffect(() => {
        const checkVersion = async () => {
            if (!REMOTE_MANIFEST_URL || REMOTE_MANIFEST_URL.includes("votre-site-web")) return;

            setIsChecking(true);
            try {
                // Add timestamp to prevent caching
                const response = await fetch(`${REMOTE_MANIFEST_URL}?t=${Date.now()}`);
                if (response.ok) {
                    const manifest: VersionManifest = await response.json();
                    if (manifest.version && isNewer(manifest.version, APP_VERSION)) {
                        setUpdateAvailable(manifest);
                    }
                }
            } catch (error) {
                logger.warn("Impossible de vérifier la mise à jour", error);
            } finally {
                setIsChecking(false);
            }
        };

        // Check immediately on load
        checkVersion();

        // Optional: Check every hour if tab stays open
        const interval = setInterval(checkVersion, 3600000);
        return () => clearInterval(interval);
    }, []);

    if (!updateAvailable || !isVisible) return null;

    const isLocalFile = window.location.protocol === 'file:';

    return (
        <div className="fixed bottom-4 right-4 z-[100] animate-in slide-in-from-right-10 duration-500 no-print">
            <div className="bg-[#fdfbf7] border-2 border-stone-800 rounded-lg shadow-2xl p-4 max-w-sm relative overflow-hidden">

                {/* Decorative "Wax Seal" background effect */}
                <div className="absolute -right-4 -top-4 w-16 h-16 bg-red-800/10 rounded-full blur-xl pointer-events-none"></div>

                <button
                    onClick={() => setIsVisible(false)}
                    className="absolute top-2 right-2 text-stone-400 hover:text-stone-800 transition-colors"
                >
                    <X size={16} />
                </button>

                <div className="flex gap-3 items-start">
                    <div className="bg-amber-100 text-amber-700 p-2 rounded-full border border-amber-200 mt-1">
                        <Sparkles size={20} />
                    </div>

                    <div>
                        <h4 className="font-serif font-bold text-lg text-indigo-950 leading-none mb-1">
                            Mise à jour disponible
                        </h4>
                        <p className="text-xs text-stone-600 mb-3 font-medium">
                            Version <span className="font-mono bg-stone-100 px-1 rounded text-stone-800">{updateAvailable.version}</span> détectée.
                            (Actuelle : {APP_VERSION})
                        </p>

                        {isLocalFile ? (
                            <div className="flex flex-col gap-2">
                                <p className="text-[10px] text-stone-500 italic leading-tight mb-1">
                                    Vous utilisez la version fichier (hors ligne). Veuillez télécharger le nouveau fichier.
                                </p>
                                <a
                                    href={updateAvailable.downloadUrl || "#"}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="flex items-center justify-center gap-2 bg-stone-800 hover:bg-stone-900 text-white px-3 py-1.5 rounded text-xs font-bold transition-all shadow-sm"
                                >
                                    <Download size={14} /> Télécharger
                                </a>
                            </div>
                        ) : (
                            <button
                                onClick={() => window.location.reload()}
                                className="flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded text-xs font-bold transition-all shadow-sm w-full"
                            >
                                <RefreshCw size={14} /> Actualiser la page
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default UpdateNotifier;

import React, { useRef, useState, useEffect } from 'react';
import { ImageConfig } from '../../types';
import { X, Move, Scaling, WrapText, BoxSelect, Maximize2, Minimize2, StretchHorizontal } from 'lucide-react';
import { getImage } from '../../imageDB';
import { ImageCompressionService, GZIP_MARKER } from '../../services/ImageCompressionService';
import { ErrorService } from '../../services/ErrorService';

interface NoteImageZoneProps {
    uniqueId: string; // Placement ID
    imageId: string; // Blob ID
    config?: ImageConfig;
    onUpdateConfig: (newConfig: ImageConfig) => void;
    onDelete: () => void;
}

const NoteImageZone: React.FC<NoteImageZoneProps> = ({ uniqueId, imageId, config, onUpdateConfig, onDelete }) => {
    const [imageUrl, setImageUrl] = useState<string | null>(null);

    // Default Config Initialization
    const defaultConfig: ImageConfig = {
        width: 300,
        height: 200,
        marginTop: 0,
        align: 'right',
        x: 0,
        y: 0,
        mode: 'absolute',
        fit: 'cover' // New default
    };

    const [tempConfig, setTempConfig] = useState<ImageConfig>(config || defaultConfig);
    const [isResizing, setIsResizing] = useState(false);
    const [isMoving, setIsMoving] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const startPosRef = useRef<{ x: number, y: number, w: number, h: number, configX: number, configY: number, mt: number } | null>(null);

    // Sync props to internal state only when not interacting
    useEffect(() => {
        if (!isResizing && !isMoving && config) {
            setTempConfig(prev => ({
                ...prev,
                ...config,
                // Ensure defaults for new properties if migrating old data
                mode: config.mode || prev.mode || 'absolute',
                x: config.x ?? prev.x ?? 0,
                y: config.y ?? prev.y ?? 0,
                fit: config.fit || prev.fit || 'cover'
            }));
        }
    }, [config, isResizing, isMoving]);

    useEffect(() => {
        let active = true;
        let cleanupUrl = "";

        const load = async () => {
            try {
                const blob = await getImage(imageId);
                if (blob && active) {
                    // Check if blob is a GZIP string
                    const text = await new Response(blob).text();
                    let finalUrl = "";

                    if (text.startsWith(GZIP_MARKER)) {
                        const decompressed = ImageCompressionService.decompressFull(text);
                        finalUrl = decompressed;
                    } else {
                        finalUrl = URL.createObjectURL(blob);
                    }

                    if (active) {
                        setImageUrl(finalUrl);
                        cleanupUrl = finalUrl;
                    }
                }
            } catch (e) {
                ErrorService.handleError(e, { context: 'NoteImageZone.load', silent: true });
            }
        };

        load();

        return () => {
            active = false;
            if (cleanupUrl.startsWith('blob:')) {
                URL.revokeObjectURL(cleanupUrl);
            }
        };
    }, [imageId]);

    // --- RESIZE HANDLERS ---
    const handleResizeStart = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsResizing(true);
        startPosRef.current = {
            x: e.clientX,
            y: e.clientY,
            w: tempConfig.width,
            h: tempConfig.height,
            configX: 0, configY: 0, mt: 0
        };
    };

    // --- MOVE HANDLERS ---
    const handleMoveStart = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsMoving(true);
        startPosRef.current = {
            x: e.clientX,
            y: e.clientY,
            w: 0, h: 0,
            configX: tempConfig.x || 0,
            configY: tempConfig.y || 0,
            mt: tempConfig.marginTop
        };
    };

    // Global Mouse Listeners for Drag/Resize
    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!startPosRef.current) return;
            const { x, y, w, h, configX, configY, mt } = startPosRef.current;
            const dx = e.clientX - x;
            const dy = e.clientY - y;

            if (isResizing) {
                const newWidth = Math.max(50, w + dx);
                const newHeight = Math.max(50, h + dy);
                setTempConfig(prev => ({ ...prev, width: newWidth, height: newHeight }));
            }

            if (isMoving) {
                if (tempConfig.mode === 'absolute') {
                    // Absolute Mode: Free X/Y movement
                    const newX = Math.max(0, configX + dx);
                    const newY = Math.max(0, configY + dy);
                    setTempConfig(prev => ({ ...prev, x: newX, y: newY }));
                } else {
                    // Flow Mode: Vertical Margin + Align Flip
                    const newMarginTop = Math.max(0, mt + dy);
                    let newAlign = tempConfig.align;
                    if (tempConfig.align === 'left' && dx > 150) newAlign = 'right';
                    if (tempConfig.align === 'right' && dx < -150) newAlign = 'left';
                    setTempConfig(prev => ({ ...prev, marginTop: newMarginTop, align: newAlign }));
                }
            }
        };

        const handleMouseUp = () => {
            if (isResizing || isMoving) {
                onUpdateConfig(tempConfig);
                setIsResizing(false);
                setIsMoving(false);
                startPosRef.current = null;
            }
        };

        if (isResizing || isMoving) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isResizing, isMoving, tempConfig, onUpdateConfig]);

    const toggleMode = (e: React.MouseEvent) => {
        e.stopPropagation();
        const newMode = tempConfig.mode === 'absolute' ? 'flow' : 'absolute';

        // When switching to absolute, sync X/Y from current visual state if possible
        // Ideally we would calculate position, but for now we rely on existing X/Y or marginTop
        const updates: Partial<ImageConfig> = { mode: newMode };

        if (newMode === 'absolute') {
            // Initialize X/Y if they are 0 (first switch)
            if (!tempConfig.x && !tempConfig.y) {
                updates.y = tempConfig.marginTop; // Approximation
                // X approximation based on align
                updates.x = tempConfig.align === 'right' ? 400 : 20; // Generic fallback
            }
        } else {
            // Initialize marginTop if switching to flow
            if (tempConfig.marginTop === 0 && tempConfig.y) {
                updates.marginTop = tempConfig.y;
            }
        }

        const newConfig = { ...tempConfig, ...updates };
        setTempConfig(newConfig);
        onUpdateConfig(newConfig);
    };

    const toggleFit = (e: React.MouseEvent) => {
        e.stopPropagation();
        const modes: ImageConfig['fit'][] = ['cover', 'contain', 'fill'];
        const currentIdx = modes.indexOf(tempConfig.fit || 'cover');
        const nextMode = modes[(currentIdx + 1) % modes.length];

        const newConfig = { ...tempConfig, fit: nextMode };
        setTempConfig(newConfig);
        onUpdateConfig(newConfig);
    };

    if (!imageUrl) return null;

    // Computed Styles based on Mode
    const isAbsolute = tempConfig.mode === 'absolute';

    const containerStyle: React.CSSProperties = isAbsolute ? {
        position: 'absolute',
        top: tempConfig.y || 0,
        left: tempConfig.x || 0,
        width: tempConfig.width,
        height: tempConfig.height,
        zIndex: 20
    } : {
        float: tempConfig.align,
        width: tempConfig.width,
        // Important: In flow mode, we add the margin to the total height but allow text to flow in it via shape-outside
        height: tempConfig.height + tempConfig.marginTop,
        paddingTop: tempConfig.marginTop, // Push the visual image down
        shapeOutside: `inset(${tempConfig.marginTop}px 0 0 0)`, // Tell text it can occupy the top area

        [tempConfig.align === 'left' ? 'marginRight' : 'marginLeft']: '20px',
        marginBottom: '10px',
        zIndex: 10,
        position: 'relative' // Need relative for internal absolute children
    };

    const isInteracting = isMoving || isResizing;
    const currentFit = tempConfig.fit || 'cover';

    return (
        <div
            ref={containerRef}
            className="group/image select-none"
            style={containerStyle}
        >
            <div className={`w-full h-full relative border-4 border-white shadow-md bg-white transition-shadow ${isInteracting ? 'shadow-xl ring-2 ring-indigo-400 opacity-90' : ''}`}>
                <img
                    src={imageUrl}
                    alt="Note Attachment"
                    className={`w-full h-full pointer-events-none transition-all duration-300 object-${currentFit}`}
                />

                {/* Overlay Controls */}
                <div className={`absolute inset-0 bg-black/10 transition-opacity flex flex-col justify-between p-2
                    ${isInteracting ? 'opacity-100 pointer-events-auto' : 'opacity-0 group-hover/image:opacity-100 pointer-events-none group-hover/image:pointer-events-auto'}
                `}>
                    <div className="flex justify-between items-start">
                        <div className="flex gap-1">
                            {/* Mode Toggle Button */}
                            <button
                                onClick={toggleMode}
                                className={`p-1.5 rounded shadow text-xs font-bold flex items-center gap-1 transition-colors ${isAbsolute
                                    ? 'bg-indigo-600 text-white hover:bg-indigo-700'
                                    : 'bg-white text-indigo-700 hover:bg-indigo-50'
                                    }`}
                                title={isAbsolute ? "Mode Libre (Flottant)" : "Mode Habillage (Texte autour)"}
                            >
                                {isAbsolute ? <BoxSelect size={14} /> : <WrapText size={14} />}
                            </button>

                            {/* Fit Toggle Button */}
                            <button
                                onClick={toggleFit}
                                className="p-1.5 rounded shadow text-xs font-bold flex items-center gap-1 transition-colors bg-white text-stone-700 hover:bg-stone-50"
                                title={`Ajustement : ${currentFit === 'cover' ? 'Remplir (Zoom)' : currentFit === 'contain' ? 'Ajuster (Entier)' : 'Étirer'}`}
                            >
                                {currentFit === 'cover' && <Maximize2 size={14} />}
                                {currentFit === 'contain' && <Minimize2 size={14} />}
                                {currentFit === 'fill' && <StretchHorizontal size={14} />}
                            </button>
                        </div>

                        <button
                            onClick={(e) => { e.stopPropagation(); onDelete(); }}
                            className="bg-red-600 text-white p-1 rounded shadow hover:bg-red-700"
                            title="Supprimer"
                        >
                            <X size={14} />
                        </button>
                    </div>

                    {/* Move Handle (Center) */}
                    <div
                        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 cursor-move bg-white/80 p-2 rounded-full hover:bg-white text-stone-700"
                        onMouseDown={handleMoveStart}
                        title="Déplacer"
                    >
                        <Move size={20} />
                    </div>

                    {/* Resize Handle (Bottom Right) */}
                    <div
                        className="absolute bottom-0 right-0 cursor-nwse-resize p-1 text-white bg-indigo-600/80 rounded-tl-lg hover:bg-indigo-600"
                        onMouseDown={handleResizeStart}
                    >
                        <Scaling size={16} />
                    </div>
                </div>

                {/* Tape visual */}
                <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-16 h-6 bg-yellow-100/50 rotate-2 shadow-sm border border-yellow-200/30 pointer-events-none"></div>
            </div>
        </div>
    );
};

export default NoteImageZone;

import React, { useRef, useState, useEffect } from 'react';
import { CharacterSheetData, PartyColumn, PartyMemberEntry } from '../../types';
import { Plus, X, Trash2 } from 'lucide-react';

interface PartyTableProps {
    data: CharacterSheetData;
    onChange: React.Dispatch<React.SetStateAction<CharacterSheetData>>;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info') => void;
}

const PartyTable: React.FC<PartyTableProps> = ({ data, onChange, onAddLog }) => {
    const columns = data.partyNotes?.columns || [];
    const members = data.partyNotes?.members || [];
    const staticWidths = data.partyNotes?.staticColWidths || { character: 200, player: 200 };
    const [newlyAddedColId, setNewlyAddedColId] = useState<string | null>(null);
    const resizingRef = useRef<{ colId: string | 'character' | 'player', startX: number, startWidth: number } | null>(null);

    // Calculate total minimum width required for the table based on column configs
    const totalTableWidth =
        (staticWidths.character || 200) +
        (staticWidths.player || 200) +
        columns.reduce((acc, col) => acc + (col.width || 150), 0) +
        100; // 100px buffer for fixed columns (Add button + Actions)

    useEffect(() => {
        if (newlyAddedColId) {
            const inputEl = document.getElementById(`party-col-header-${newlyAddedColId}`) as HTMLInputElement;
            if (inputEl) {
                inputEl.focus();
                inputEl.select();
                setNewlyAddedColId(null);
            }
        }
    }, [columns, newlyAddedColId]);

    // ... mouse move/up effects for resizing ...
    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!resizingRef.current) return;
            const { colId, startX, startWidth } = resizingRef.current;
            const delta = e.clientX - startX;
            const newWidth = Math.max(50, startWidth + delta);

            if (colId === 'character' || colId === 'player') {
                onChange(prev => ({
                    ...prev,
                    partyNotes: {
                        ...prev.partyNotes,
                        staticColWidths: {
                            ...prev.partyNotes.staticColWidths!,
                            [colId]: newWidth
                        }
                    }
                }));
            } else {
                onChange(prev => ({
                    ...prev,
                    partyNotes: {
                        ...prev.partyNotes,
                        columns: prev.partyNotes.columns.map(c => c.id === colId ? { ...c, width: newWidth } : c)
                    }
                }));
            }
        };

        const handleMouseUp = () => {
            if (resizingRef.current) {
                resizingRef.current = null;
                document.body.style.cursor = 'default';
            }
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [onChange]);

    const startResizing = (e: React.MouseEvent, colId: string | 'character' | 'player', currentWidth: number) => {
        e.preventDefault();
        resizingRef.current = { colId, startX: e.clientX, startWidth: currentWidth };
        document.body.style.cursor = 'col-resize';
    };

    const addColumn = () => {
        const newId = Math.random().toString(36).substr(2, 9);
        const newCol: PartyColumn = {
            id: newId,
            label: "Nouvelle Colonne",
            width: 150
        };
        onChange({
            ...data,
            partyNotes: {
                ...data.partyNotes,
                columns: [...columns, newCol]
            }
        });
        setNewlyAddedColId(newId);
        onAddLog("Colonne ajoutée au groupe", 'info');
    };

    const deleteColumn = (colId: string) => {
        onChange({
            ...data,
            partyNotes: {
                ...data.partyNotes,
                columns: columns.filter(c => c.id !== colId)
            }
        });
    };

    const updateColumnLabel = (colId: string, newVal: string) => {
        onChange({
            ...data,
            partyNotes: {
                ...data.partyNotes,
                columns: columns.map(c => c.id === colId ? { ...c, label: newVal } : c)
            }
        });
    };

    const addMember = () => {
        const newMember: PartyMemberEntry = {
            id: Math.random().toString(36).substr(2, 9),
            name: '',
            player: '',
            data: {}
        };
        onChange({
            ...data,
            partyNotes: {
                ...data.partyNotes,
                members: [...members, newMember]
            }
        });
        onAddLog("Membre ajouté au groupe", 'success');
    };

    const updateMember = (memberId: string, field: 'name' | 'player' | 'data', value: string, key?: string) => {
        const newMembers = members.map(m => {
            if (m.id !== memberId) return m;
            if (field === 'data' && key) {
                return { ...m, data: { ...m.data, [key]: value } };
            }
            return { ...m, [field]: value };
        });

        onChange({
            ...data,
            partyNotes: {
                ...data.partyNotes,
                members: newMembers
            }
        });
    };

    const deleteMember = (memberId: string) => {
        onChange({
            ...data,
            partyNotes: {
                ...data.partyNotes,
                members: members.filter(m => m.id !== memberId)
            }
        });
    };

    return (
        <div className="w-full h-full flex flex-col p-4">
            <style>{`
                .custom-scrollbar::-webkit-scrollbar {
                    height: 10px;
                    width: 10px;
                }
                .custom-scrollbar::-webkit-scrollbar-track {
                    background: #fbf4e9;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: #d6d3d1;
                    border-radius: 5px;
                    border: 2px solid #fbf4e9;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover {
                    background: #a8a29e;
                }
            `}</style>
            <div className="flex-grow overflow-auto custom-scrollbar">
                <table
                    className="border-collapse table-fixed bg-[#fbf4e9] shadow-sm"
                    style={{ minWidth: '100%', width: `${totalTableWidth}px` }}
                >
                    <thead className="sticky top-0 z-10 shadow-sm">
                        <tr>
                            <th className="border-b-2 border-stone-400 bg-[#fbf4e9] text-left p-2 font-serif text-stone-700 relative" style={{ width: staticWidths.character }}>
                                <div className="truncate font-bold w-full" title="Personnage">Personnage</div>
                                <div className="absolute right-0 top-0 bottom-0 w-2 cursor-col-resize hover:bg-stone-300 z-20" onMouseDown={(e) => startResizing(e, 'character', staticWidths.character)} />
                            </th>
                            <th className="border-b-2 border-stone-400 bg-[#fbf4e9] text-left p-2 font-serif text-stone-700 border-l border-stone-300 relative" style={{ width: staticWidths.player }}>
                                <div className="truncate font-bold w-full" title="Joueur">Joueur</div>
                                <div className="absolute right-0 top-0 bottom-0 w-2 cursor-col-resize hover:bg-stone-300 z-20" onMouseDown={(e) => startResizing(e, 'player', staticWidths.player)} />
                            </th>
                            {columns.map(col => (
                                <th key={col.id} className="border-b-2 border-stone-400 bg-[#fbf4e9] text-left p-2 font-serif text-stone-700 border-l border-stone-300 group relative" style={{ width: col.width || 150 }}>
                                    <input
                                        id={`party-col-header-${col.id}`}
                                        className="bg-transparent font-bold w-full outline-none focus:border-b border-indigo-500 pr-6 truncate"
                                        value={col.label}
                                        title={col.label}
                                        onChange={(e) => updateColumnLabel(col.id, e.target.value)}
                                    />
                                    <button onClick={() => deleteColumn(col.id)} className="absolute right-3 top-1/2 -translate-y-1/2 text-stone-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity z-10" title="Supprimer colonne">
                                        <X size={14} />
                                    </button>
                                    <div className="absolute right-0 top-0 bottom-0 w-2 cursor-col-resize hover:bg-stone-300 z-20" onMouseDown={(e) => startResizing(e, col.id, col.width || 150)} />
                                </th>
                            ))}
                            <th className="border-b-2 border-stone-400 bg-[#fbf4e9] p-2 w-12 text-center align-middle">
                                <button onClick={addColumn} className="text-stone-500 hover:text-indigo-600 transition-colors flex justify-center w-full" title="Ajouter une colonne">
                                    <Plus size={20} />
                                </button>
                            </th>
                            <th className="border-b-2 border-stone-400 bg-[#fbf4e9] w-12"></th>
                        </tr>
                    </thead>
                    <tbody>
                        {members.map(member => (
                            <tr key={member.id} className="hover:bg-stone-50 group">
                                <td className="p-0 border-b border-stone-300 h-10 overflow-hidden">
                                    <input className="w-full h-full bg-transparent px-2 font-handwriting text-lg text-ink outline-none" placeholder="Nom du perso..." value={member.name} onChange={(e) => updateMember(member.id, 'name', e.target.value)} />
                                </td>
                                <td className="p-0 border-b border-stone-300 h-10 border-l border-stone-200 overflow-hidden">
                                    <input className="w-full h-full bg-transparent px-2 font-handwriting text-lg text-ink outline-none" placeholder="Nom du joueur..." value={member.player} onChange={(e) => updateMember(member.id, 'player', e.target.value)} />
                                </td>
                                {columns.map(col => (
                                    <td key={col.id} className="p-0 border-b border-stone-300 h-10 border-l border-stone-200 overflow-hidden">
                                        <input className="w-full h-full bg-transparent px-2 font-handwriting text-lg text-stone-600 outline-none" value={member.data[col.id] || ''} onChange={(e) => updateMember(member.id, 'data', e.target.value, col.id)} />
                                    </td>
                                ))}
                                <td colSpan={2} className="border-b border-stone-300 text-center w-24">
                                    <button onClick={() => deleteMember(member.id)} className="text-stone-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 p-2">
                                        <Trash2 size={16} />
                                    </button>
                                </td>
                            </tr>
                        ))}

                        {/* Button Row - Visible directly after entries or as first entry if empty */}
                        <tr
                            onClick={addMember}
                            className="hover:bg-amber-900/5 transition-colors cursor-pointer group/add h-12 border-b border-dashed border-stone-300 bg-[#fbf4e9]"
                        >
                            <td colSpan={columns.length + 4} className="p-0 text-center align-middle">
                                <button className="flex items-center gap-2 text-stone-500 group-hover/add:text-amber-800 font-bold uppercase text-xs tracking-wider mx-auto transition-colors w-full h-full justify-center py-2">
                                    <Plus size={16} /> Ajouter un Membre
                                </button>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default PartyTable;

import React, { useState, useEffect, useRef } from 'react';
import { NodeViewWrapper } from '@tiptap/react';
import { BookImageAttributes } from '../../../extensions/bookImage';
import { Image as ImageIcon, Loader, Type, Maximize2, Minimize2, ChevronUp, ChevronDown, Crop } from 'lucide-react';
import { getImage } from '../../../imageDB';
import { logger } from '../../../utils/logger';

interface BookImageViewProps {
    node: {
        attrs: BookImageAttributes;
    };
    updateAttributes: (attrs: Partial<BookImageAttributes>) => void;
    selected: boolean;
}

type InteractionMode = 'resize-h' | 'resize-v' | 'resize-both' | 'pan' | null;

const BookImageView: React.FC<BookImageViewProps> = ({ node, updateAttributes, selected }) => {
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [isEditingCaption, setIsEditingCaption] = useState(false);
    const [isPanMode, setIsPanMode] = useState(false);
    const [activeInteraction, setActiveInteraction] = useState<InteractionMode>(null);

    const containerRef = useRef<HTMLDivElement>(null);
    const startRef = useRef<{ x: number, y: number, w: number, h: number, px: number, py: number } | null>(null);

    // Magnetic Snapping points
    const SNAP_POINTS = [0.25, 0.333, 0.5, 0.75, 1];
    const SNAP_THRESHOLD = 0.03; // 3%

    useEffect(() => {
        let active = true;
        const load = async () => {
            if (!node.attrs.imageId) return;
            if (node.attrs.imageId.startsWith('temp-')) return;

            setLoading(true);
            try {
                const blob = await getImage(node.attrs.imageId);
                if (blob && active) {
                    const url = URL.createObjectURL(blob);
                    setImageSrc(url);
                }
            } catch (e) {
                logger.error("Failed to load image", e);
            } finally {
                if (active) setLoading(false);
            }
        };
        load();
        return () => { active = false; };
    }, [node.attrs.imageId]);

    const handleMouseDown = (e: React.MouseEvent, mode: InteractionMode) => {
        e.preventDefault();
        e.stopPropagation();
        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) return;

        startRef.current = {
            x: e.clientX,
            y: e.clientY,
            w: rect.width,
            h: rect.height,
            px: node.attrs.posX ?? 50,
            py: node.attrs.posY ?? 50
        };
        setActiveInteraction(mode);
    };

    useEffect(() => {
        if (!activeInteraction) return;

        const handleMouseMove = (e: MouseEvent) => {
            if (!startRef.current || !containerRef.current) return;

            const deltaX = e.clientX - startRef.current.x;
            const deltaY = e.clientY - startRef.current.y;

            if (activeInteraction === 'pan') {
                // Panning logic: move image inside. 
                // We use pixel to % conversion. This is approximate but works for feedback.
                // 1% of movement = 1% shift or something similar.
                const sensitivity = 0.2; // Adjust for smoothness
                const newPosX = Math.max(0, Math.min(100, startRef.current.px - (deltaX * sensitivity)));
                const newPosY = Math.max(0, Math.min(100, startRef.current.py - (deltaY * sensitivity)));

                updateAttributes({ posX: newPosX, posY: newPosY });
                return;
            }

            // Resizing logic
            const parentWidth = containerRef.current.parentElement?.getBoundingClientRect().width || 1;
            let newWidthPx = startRef.current.w + deltaX;
            let newHeightPx = startRef.current.h + deltaY;

            newWidthPx = Math.max(50, newWidthPx);
            newHeightPx = Math.max(50, newHeightPx);

            let widthRatio = newWidthPx / parentWidth;

            if (activeInteraction === 'resize-h' || activeInteraction === 'resize-both') {
                if (node.attrs.align !== 'center') {
                    widthRatio = Math.min(0.55, widthRatio);
                } else {
                    widthRatio = Math.min(1, widthRatio);
                }

                for (const snap of SNAP_POINTS) {
                    if (Math.abs(widthRatio - snap) < SNAP_THRESHOLD) {
                        widthRatio = snap;
                        break;
                    }
                }
            } else {
                widthRatio = startRef.current.w / parentWidth;
            }

            const finalWidth = `${Math.round(widthRatio * 100)}%`;
            const finalHeight = activeInteraction === 'resize-h'
                ? `${Math.round(startRef.current.h)}px`
                : `${Math.round(newHeightPx)}px`;

            const update: Partial<BookImageAttributes> = {};
            if (activeInteraction === 'resize-h' || activeInteraction === 'resize-both') update.width = finalWidth;
            if (activeInteraction === 'resize-v' || activeInteraction === 'resize-both') update.height = finalHeight;

            updateAttributes(update);
        };

        const handleMouseUp = () => {
            setActiveInteraction(null);
            startRef.current = null;
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [activeInteraction, node.attrs.align, updateAttributes]);

    const isLateral = node.attrs.align !== 'center';

    return (
        <NodeViewWrapper
            className={`book-image-view relative group mb-6 transition-all duration-300 ${selected ? 'ring-2 ring-indigo-500 rounded' : ''}`}
            data-align={node.attrs.align}
            style={{
                float: isLateral ? (node.attrs.align as any) : 'none',
                width: isLateral ? node.attrs.width : '100%',
                display: isLateral ? 'inline-block' : 'block',
                margin: isLateral
                    ? (node.attrs.align === 'left' ? '0 1.5rem 0.5rem 0' : '0 0 0.5rem 1.5rem')
                    : '1.5rem auto',
                clear: isLateral ? 'none' : 'both',
                textAlign: 'center'
            }}
        >
            <div
                ref={containerRef}
                className="inline-block bg-transparent flex items-center justify-center text-stone-400 relative transition-shadow duration-300"
                style={{
                    width: isLateral ? '100%' : (node.attrs.width || '100%'),
                    minHeight: '40px',
                    height: node.attrs.height === 'auto' && imageSrc ? 'auto' : (node.attrs.height === 'auto' ? '200px' : node.attrs.height),
                    boxShadow: selected
                        ? '0 20px 25px -5px rgba(0, 0, 0, 0.2), 0 10px 10px -5px rgba(0, 0, 0, 0.1)'
                        : '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)',
                    borderRadius: '1px',
                    border: '5px solid white',
                    cursor: activeInteraction
                        ? (activeInteraction === 'resize-h' ? 'col-resize' : activeInteraction === 'resize-v' ? 'row-resize' : activeInteraction === 'pan' ? 'move' : 'nwse-resize')
                        : (isPanMode ? 'move' : 'default')
                }}
                onMouseDown={isPanMode ? (e) => handleMouseDown(e, 'pan') : undefined}
            >
                {loading ? (
                    <div className="flex flex-col items-center gap-2 animate-pulse">
                        <Loader size={32} className="animate-spin" />
                        <span className="text-xs">Chargement...</span>
                    </div>
                ) : imageSrc ? (
                    <img
                        src={imageSrc}
                        alt={node.attrs.caption || 'Illustration'}
                        className={`w-full ${node.attrs.height === 'auto' ? 'h-auto' : 'h-full'} transition-all duration-300 rounded-[1px]`}
                        style={{
                            objectFit: node.attrs.fit || 'contain',
                            objectPosition: `${node.attrs.posX ?? 50}% ${node.attrs.posY ?? 50}%`,
                            filter: node.attrs.filter === 'grayscale'
                                ? 'grayscale(100%) contrast(1.1)'
                                : 'none',
                            pointerEvents: isPanMode ? 'none' : 'auto'
                        }}
                        data-drag-handle={!isPanMode}
                    />
                ) : (
                    <div className="flex flex-col items-center gap-2">
                        <ImageIcon size={32} />
                        <span className="text-xs">Image {node.attrs.imageId}</span>
                    </div>
                )}



                {selected && !isPanMode && (
                    <>
                        {/* Corner Handle (Diagonal) */}
                        <div
                            className="absolute bottom-[-8px] right-[-8px] w-4 h-4 bg-indigo-600 rounded-full border-2 border-white cursor-nwse-resize z-[160] shadow-md hover:scale-125 transition-transform active:scale-100"
                            onMouseDown={(e) => handleMouseDown(e, 'resize-both')}
                            title="Redimensionner Largeur & Hauteur"
                        />
                        {/* Right Handle (Horizontal) */}
                        <div
                            className="absolute top-1/2 -translate-y-1/2 right-[-6px] w-1.5 h-1/2 bg-indigo-400/50 hover:bg-indigo-600 rounded-full cursor-col-resize z-[160] transition-colors"
                            onMouseDown={(e) => handleMouseDown(e, 'resize-h')}
                            title="Redimensionner Largeur"
                        />
                        {/* Bottom Handle (Vertical) */}
                        <div
                            className="absolute bottom-[-6px] left-1/2 -translate-x-1/2 w-1/2 h-1.5 bg-indigo-400/50 hover:bg-indigo-600 rounded-full cursor-row-resize z-[160] transition-colors"
                            onMouseDown={(e) => handleMouseDown(e, 'resize-v')}
                            title="Redimensionner Hauteur"
                        />
                    </>
                )}

                {isPanMode && selected && (
                    <div className="absolute inset-0 pointer-events-none border-2 border-dashed border-indigo-400/50 flex items-center justify-center">
                        <div className="bg-indigo-600 text-white text-[10px] px-2 py-0.5 rounded-full shadow-lg animate-bounce">
                            Maintenez et glissez pour cadrer
                        </div>
                    </div>
                )}
            </div>

            {selected && (
                <div
                    className="absolute top-2 right-2 flex flex-wrap justify-end gap-1 content-ignore z-[150] max-w-[200%] pointer-events-auto"
                    onMouseDown={(e) => e.stopPropagation()}
                >
                    <div className="bg-white/90 p-1 rounded shadow-sm flex gap-1 border border-stone-100 pb-1">
                        <button className="hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200" onClick={() => updateAttributes({ align: 'left' })}>L</button>
                        <button className="hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200" onClick={() => updateAttributes({ align: 'center' })}>C</button>
                        <button className="hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200" onClick={() => updateAttributes({ align: 'right' })}>R</button>
                    </div>
                    <div className="bg-white/90 p-1 rounded shadow-sm flex gap-1 border border-stone-100 pb-1">
                        <button
                            className={`hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200 ${node.attrs.filter === 'grayscale' ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : ''}`}
                            onClick={() => updateAttributes({ filter: node.attrs.filter === 'grayscale' ? 'none' : 'grayscale' })}
                            title="Noir & Blanc"
                        >
                            <div className="w-3 h-3 rounded-full bg-gradient-to-br from-white to-black border border-stone-300" />
                        </button>
                        <button
                            className={`hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200 ${isPanMode ? 'bg-indigo-600 text-white border-indigo-700' : ''}`}
                            onClick={(e) => {
                                e.stopPropagation();
                                setIsPanMode(!isPanMode);
                            }}
                            title="Mode Recadrage (Faire glisser l'image)"
                            disabled={node.attrs.fit !== 'cover'}
                        >
                            <Crop size={12} />
                        </button>
                    </div>
                    <div className="bg-white/90 p-1 rounded shadow-sm flex gap-1 border border-stone-100 pb-1">
                        <button
                            className="hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200"
                            onClick={() => setIsEditingCaption(!isEditingCaption)}
                            title="Modifier la légende"
                        >
                            <Type size={12} />
                        </button>
                    </div>

                    <div className="bg-white/90 p-1 rounded shadow-sm flex gap-1 border border-stone-100 pb-1">
                        <button
                            className={`hover:bg-indigo-50 p-1 rounded text-xs px-2 border border-stone-200 ${node.attrs.fit === 'cover' ? 'bg-indigo-50 border-indigo-300' : ''}`}
                            onClick={() => updateAttributes({ fit: node.attrs.fit === 'cover' ? 'contain' : 'cover' })}
                            title={node.attrs.fit === 'cover' ? "Passer en mode Ajuster (Contain)" : "Passer en mode Remplir (Cover)"}
                        >
                            {node.attrs.fit === 'cover' ? <Minimize2 size={12} /> : <Maximize2 size={12} />}
                        </button>
                        <div className="flex flex-col border-l border-stone-200 pl-1">
                            <button
                                className="hover:bg-indigo-50 px-1 rounded text-[8px] leading-none h-1/2"
                                onClick={() => {
                                    const h = node.attrs.height === 'auto' ? 200 : parseInt(String(node.attrs.height));
                                    updateAttributes({ height: `${h + 40}px` });
                                }}
                                title="Augmenter la hauteur"
                            >
                                <ChevronUp size={10} />
                            </button>
                            <button
                                className="hover:bg-indigo-50 px-1 rounded text-[8px] leading-none h-1/2"
                                onClick={() => {
                                    const h = node.attrs.height === 'auto' ? 200 : parseInt(String(node.attrs.height));
                                    updateAttributes({ height: `${Math.max(50, h - 40)}px` });
                                }}
                                title="Diminuer la hauteur"
                            >
                                <ChevronDown size={10} />
                            </button>
                        </div>
                        <button
                            className="hover:bg-amber-50 p-1 rounded text-[10px] px-1 border border-stone-200 text-stone-500"
                            onClick={() => updateAttributes({ height: 'auto', posX: 50, posY: 50 })}
                            title="Hauteur automatique (Réinitialise aussi le cadrage)"
                            disabled={node.attrs.height === 'auto'}
                        >
                            Auto
                        </button>
                    </div>
                </div>
            )}

            {isEditingCaption ? (
                <div className="mt-2 w-full max-w-[80%] mx-auto">
                    <input
                        type="text"
                        defaultValue={node.attrs.caption}
                        placeholder="Légende de l'image..."
                        className="w-full text-center text-xs font-serif italic border-b border-stone-300 focus:border-stone-500 outline-none bg-transparent px-2 py-1"
                        onBlur={(e) => {
                            updateAttributes({ caption: e.target.value });
                            setIsEditingCaption(false);
                        }}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                                updateAttributes({ caption: (e.target as HTMLInputElement).value });
                                setIsEditingCaption(false);
                            }
                        }}
                    />
                </div>
            ) : (
                node.attrs.caption && (
                    <div
                        className="text-center text-stone-500 text-xs italic mt-2 font-serif cursor-pointer hover:text-stone-700 transition-colors"
                        onClick={() => selected && setIsEditingCaption(true)}
                        title="Cliquer pour modifier"
                    >
                        {node.attrs.caption}
                    </div>
                )
            )}
        </NodeViewWrapper>
    );
};

export default BookImageView;

import React, { useRef, useEffect } from 'react';
import { NodeViewWrapper, NodeViewContent } from '@tiptap/react';
import { Editor, NodeViewProps } from '@tiptap/core';
import { Calendar } from 'lucide-react';

interface ChapterHeaderViewProps extends Omit<NodeViewProps, 'node' | 'editor'> {
    node: NodeViewProps['node'] & { attrs: { date: string } };
    editor: Editor;
    updateAttributes: (attrs: Partial<{ date: string }>) => void;
}

const ChapterHeaderView: React.FC<ChapterHeaderViewProps> = ({ node, editor, getPos, updateAttributes }) => {
    const dateInputRef = useRef<HTMLInputElement>(null);

    // Surgical Selection: Select the title text natively via Tiptap/ProseMirror
    // if it's a freshly created chapter (with the default text).
    useEffect(() => {
        const isDefault = node.content?.size > 0 &&
            node.content.firstChild?.text === 'Nouveau Chapitre';

        if (isDefault && typeof getPos === 'function') {
            const selectText = () => {
                if (editor.isDestroyed) return;

                try {
                    const pos = (getPos as () => number)();
                    const from = pos + 1;
                    const to = from + node.content.size;

                    // Execute focus and selection in a single transaction for atomicity
                    editor.chain()
                        .focus()
                        .setTextSelection({ from, to })
                        .run();
                } catch (err) {
                    // Silently fail if pos is invalid during a concurrent update
                }
            };

            // Double security: small timeout + requestAnimationFrame to ensure DOM is ready
            const timer = setTimeout(() => {
                requestAnimationFrame(selectText);
            }, 100);

            return () => clearTimeout(timer);
        }
    }, []); // Run only once on mount

    const formatDate = (dateStr: string) => {
        if (!dateStr) return 'Date du récit...';
        try {
            const date = new Date(dateStr);
            if (isNaN(date.getTime())) return dateStr;
            return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
        } catch {
            return dateStr;
        }
    };

    const handleIconClick = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (dateInputRef.current) {
            if ('showPicker' in dateInputRef.current) {
                (dateInputRef.current as any).showPicker();
            } else {
                (dateInputRef.current as HTMLInputElement).click();
            }
        }
    };

    return (
        <NodeViewWrapper className="chapter-header-wrapper mt-8 mb-6 border-b border-stone-800/30 pb-4 relative group w-full">
            <div className="flex flex-col gap-2 w-full text-center">
                <div className="flex items-center justify-center gap-2 text-stone-500 font-serif italic tracking-wider">
                    <button
                        type="button"
                        onClick={handleIconClick}
                        className="p-1 hover:bg-stone-800/5 rounded-full transition-colors cursor-pointer border-none bg-transparent"
                        title="Choisir une date"
                    >
                        <Calendar size={14} className="opacity-50" />
                    </button>

                    <input
                        ref={dateInputRef}
                        type="date"
                        value={node.attrs.date}
                        className="absolute opacity-0 pointer-events-none w-0 h-0"
                        onChange={(e) => updateAttributes({ date: e.target.value })}
                        onClick={(e) => e.stopPropagation()}
                    />

                    <span
                        className="text-xs text-center min-w-[100px] hover:bg-stone-800/5 rounded px-2 transition-colors cursor-pointer"
                        onClick={handleIconClick}
                    >
                        {formatDate(node.attrs.date)}
                    </span>
                </div>

                <div className="font-serif font-bold text-3xl text-stone-900 tracking-tight uppercase">
                    <NodeViewContent />
                </div>

                <div className="w-16 h-px bg-stone-400 mx-auto mt-2" />
            </div>
        </NodeViewWrapper>
    );
};

export default ChapterHeaderView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { useEditor, EditorContent, JSONContent } from '@tiptap/react';
import { getBookExtensions } from './extensions/bookExtensions';
import { PAGE_WIDTH, PAGE_HEIGHT } from '../constants';
import { saveImage } from '../../../imageDB';
import { BookTableOfContents } from './BookTableOfContents';
import { useBookTableOfContents } from './useBookTableOfContents';
import { logger } from '../../../utils/logger';

const INK_COLORS = [
    { name: 'Noir Corbeau', color: '#1c1917' },
    { name: 'Bleu Royal', color: '#1e3a8a' },
    { name: 'Sang Séché', color: '#7f1d1d' },
    { name: 'Vert Forêt', color: '#064e3b' },
    { name: 'Or Ancien', color: '#b45309' },
    { name: 'Violet Sombre', color: '#581c87' },
];

const HIGHLIGHT_COLORS = [
    { name: 'Ambre', color: '#f59e0b40' },
    { name: 'Menthe', color: '#10b98140' },
    { name: 'Azur', color: '#3b82f640' },
    { name: 'Rose', color: '#ef444440' },
    { name: 'Violet', color: '#8b5cf640' },
];

interface ColumnarEditorProps {
    initialContent?: JSONContent | string;
    onUpdate?: (content: JSONContent) => void;
    readOnly?: boolean;
}

export const ColumnarEditor: React.FC<ColumnarEditorProps> = ({
    initialContent,
    onUpdate,
    readOnly = false
}) => {
    const timeoutRef = useRef<NodeJS.Timeout | null>(null);
    const [isDrawingMode, setIsDrawingMode] = useState(false);
    const [showColorPalette, setShowColorPalette] = useState(false);
    const [showHighlightPalette, setShowHighlightPalette] = useState(false);
    const [drawStart, setDrawStart] = useState<{ x: number, y: number } | null>(null);
    const [drawRect, setDrawRect] = useState<{ x: number, y: number, w: number, h: number } | null>(null);

    const onUpdateRef = useRef(onUpdate);
    onUpdateRef.current = onUpdate;

    const editorOptions = useMemo(() => ({
        extensions: getBookExtensions(),
        editable: !readOnly,
        immediatelyRender: false,
        onUpdate: ({ editor }: { editor: any }) => {
            if (onUpdateRef.current) {
                if (timeoutRef.current) clearTimeout(timeoutRef.current);
                timeoutRef.current = setTimeout(() => {
                    onUpdateRef.current?.(editor.getJSON());
                }, 1000);
            }
        },
    }), [readOnly]); // initialContent is only used once, readOnly is dynamic

    const editor = useEditor(editorOptions);

    // Initial Content Injection (Safe from flushSync)
    useEffect(() => {
        if (editor && initialContent && !editor.isDestroyed) {
            // Only set if we have content and it's not already there (to be safe)
            // Using a microtask delay just to be 100% sure we are out of the render cycle
            // although useEffect corresponds to the commit phase.
            queueMicrotask(() => {
                // Prevent resetting if content was somehow restored or if we are in a hot reload
                if (editor.isEmpty) {
                    editor.commands.setContent(initialContent, { emitUpdate: false });
                }
            });
        }
    }, [editor]); // Run once when editor is created


    const containerRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const [pageCount, setPageCount] = React.useState(1);
    const [scrollPos, setScrollPos] = React.useState(0);

    const { entries } = useBookTableOfContents(editor, contentRef);

    // Sync content if initialContent changes (e.g. switching chapters)
    useEffect(() => {
        if (editor && initialContent) {
            // Only update if the content is different and editor is not focused/dirty
            // to avoid cursor jumping during active typing (debounce handles saving)
            const currentJson = JSON.stringify(editor.getJSON());
            const nextJson = typeof initialContent === 'string' ? initialContent : JSON.stringify(initialContent);

            if (currentJson !== nextJson && !editor.isFocused) {
                editor.commands.setContent(initialContent, { emitUpdate: false });
            }
        }
    }, [initialContent, editor]);

    // Calculate how many pages we have based on scrollWidth
    useEffect(() => {
        const checkScroll = () => {
            if (!contentRef.current || !containerRef.current) return;

            // We use a small timeout to allow CSS Column reflow to complete
            // especially after image size changes or Tiptap node view renders.
            requestAnimationFrame(() => {
                if (!contentRef.current || !containerRef.current) return;

                const scrollWidth = contentRef.current.scrollWidth;
                const stride = PAGE_WIDTH + 40;

                // We add 1 for the Table of Contents page
                const contentPages = Math.max(1, Math.ceil(scrollWidth / stride));
                const totalPages = contentPages + 1;

                if (totalPages !== pageCount) {
                    setPageCount(totalPages);
                }
                setScrollPos(containerRef.current.scrollLeft);
            });
        };

        const handleScroll = () => {
            if (containerRef.current) {
                setScrollPos(containerRef.current.scrollLeft);
            }
        };

        checkScroll();

        // Add a ResizeObserver that specifically monitors the content container.
        // Since CSS columns with width: fit-content should resize their box,
        // ResizeObserver on contentRef.current is usually correct.
        const observer = new ResizeObserver(checkScroll);
        if (contentRef.current) {
            observer.observe(contentRef.current);
            // Also observe the first child (ProseMirror) just in case
            const firstChild = contentRef.current.firstElementChild;
            if (firstChild) observer.observe(firstChild);
        }

        const container = containerRef.current;
        if (container) {
            container.addEventListener('scroll', handleScroll);
        }

        if (editor) {
            // Defer editor event handlers to avoid calling setState synchronously
            // during Tiptap's internal flushSync cycle.
            let updateRafId: number | null = null;
            let selectionRafId: number | null = null;

            const deferredUpdate = () => {
                if (updateRafId !== null) cancelAnimationFrame(updateRafId);
                updateRafId = requestAnimationFrame(() => {
                    updateRafId = null;
                    checkScroll();
                });
            };

            const deferredSelection = () => {
                if (selectionRafId !== null) cancelAnimationFrame(selectionRafId);
                selectionRafId = requestAnimationFrame(() => {
                    selectionRafId = null;
                    checkScroll();
                });
            };

            editor.on('update', deferredUpdate);
            editor.on('selectionUpdate', deferredSelection);

            return () => {
                observer.disconnect();
                if (container) {
                    container.removeEventListener('scroll', handleScroll);
                }
                editor.off('update', deferredUpdate);
                editor.off('selectionUpdate', deferredSelection);
                if (updateRafId !== null) cancelAnimationFrame(updateRafId);
                if (selectionRafId !== null) cancelAnimationFrame(selectionRafId);
            };
        }

        return () => {
            observer.disconnect();
            if (container) {
                container.removeEventListener('scroll', handleScroll);
            }
        };
    }, [editor, pageCount]);

    const handleDrawingMouseDown = (e: React.MouseEvent) => {
        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) return;
        const x = e.clientX - rect.left + (containerRef.current?.scrollLeft || 0);
        const y = e.clientY - rect.top;
        setDrawStart({ x, y });
        setDrawRect({ x, y, w: 0, h: 0 });
    };

    const handleDrawingMouseMove = (e: React.MouseEvent) => {
        if (!drawStart || !containerRef.current) return;
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left + (containerRef.current.scrollLeft || 0);
        const y = e.clientY - rect.top;

        setDrawRect({
            x: Math.min(x, drawStart.x),
            y: Math.min(y, drawStart.y),
            w: Math.abs(x - drawStart.x),
            h: Math.abs(y - drawStart.y)
        });
    };

    const handleDrawingMouseUp = (e: React.MouseEvent) => {
        if (!drawRect || drawRect.w < 10 || drawRect.h < 10) {
            setDrawStart(null);
            setDrawRect(null);
            setIsDrawingMode(false);
            return;
        }

        const finalRect = { ...drawRect };
        // Get the position in the editor based on mouse coordinates
        const pos = editor?.view.posAtCoords({ left: e.clientX, top: e.clientY });

        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.onchange = async (ce) => {
            const file = (ce.target as HTMLInputElement).files?.[0];
            if (file) {
                try {
                    const imageId = await saveImage(file);
                    // Standardize width to 25/50/75/100 based on drawing
                    const ratio = finalRect.w / PAGE_WIDTH;
                    let widthVal: string;
                    if (ratio < 0.35) widthVal = '25%';
                    else if (ratio < 0.65) widthVal = '50%';
                    else if (ratio < 0.85) widthVal = '75%';
                    else widthVal = '100%';

                    if (editor) {
                        const chain = editor.chain().focus();
                        if (pos) chain.setTextSelection(pos.pos);
                        chain.setBookImage({
                            imageId,
                            width: widthVal,
                            height: `${finalRect.h}px`,
                            fit: 'cover',
                            align: 'center'
                        }).run();
                    }
                } catch (err) {
                    logger.error("Failed to save image", err);
                }
            }
            setIsDrawingMode(false);
            setDrawStart(null);
            setDrawRect(null);
        };
        input.click();
    };


    const [isMounted, setIsMounted] = useState(false);
    useEffect(() => {
        // Double-tick mount to be absolutely safe with React 18 batching
        const frame = requestAnimationFrame(() => {
            const timer = setTimeout(() => setIsMounted(true), 50);
            return () => clearTimeout(timer);
        });
        return () => cancelAnimationFrame(frame);
    }, []);

    if (!editor || !isMounted) {
        return (
            <div className="mx-auto w-[1484px] h-[1000px] flex items-center justify-center bg-[#fbf4e9] rounded-lg shadow-2xl border border-stone-300/50">
                <div className="flex flex-col items-center gap-4 text-stone-400 font-serif italic">
                    <div className="w-8 h-8 border-2 border-stone-300 border-t-amber-600 rounded-full animate-spin" />
                    Lecture du grimoire...
                </div>
            </div>
        );
    }

    const scrollPrev = () => {
        if (containerRef.current) {
            // Precise stride for 2 pages spread
            const stride = (PAGE_WIDTH + 40) * 2;
            containerRef.current.scrollBy({ left: -stride, behavior: 'smooth' });
        }
    };

    const scrollNext = () => {
        if (containerRef.current) {
            const stride = (PAGE_WIDTH + 40) * 2;
            containerRef.current.scrollBy({ left: stride, behavior: 'smooth' });
        }
    };

    const navigateToPage = (pageNumber: number) => {
        if (containerRef.current) {
            const stride = PAGE_WIDTH + 40;
            // pageNumber 1 is TOC, pageNumber 2 is first content page, etc.
            // We scroll to the spread start.
            const spreadIndex = Math.floor((pageNumber - 1) / 2);
            containerRef.current.scrollTo({
                left: spreadIndex * stride * 2,
                behavior: 'smooth'
            });
        }
    };

    return (
        <div className="w-full animate-in fade-in duration-700 flex flex-col items-center justify-start relative overflow-visible gap-4">

            {/* Editor Toolbar */}
            <div className="flex items-center gap-1 p-1 bg-stone-900/95 border border-stone-700/50 rounded-lg shadow-2xl mb-2 sticky top-0 z-[60] backdrop-blur-md">

                {/* Groupe 1: Texte */}
                <div className="flex items-center">
                    <button
                        onClick={() => editor.chain().focus().toggleBold().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('bold') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Gras (Ctrl+B)"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 4h8a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z" /><path d="M6 12h9a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().toggleItalic().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('italic') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Italique (Ctrl+I)"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="4" x2="10" y2="4" /><line x1="14" y1="20" x2="5" y2="20" /><line x1="15" y1="4" x2="9" y2="20" /></svg>
                    </button>
                    <button
                        onClick={() => (editor.chain().focus() as any).toggleUnderline().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('underline') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Souligner (Ctrl+U)"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 3v7a6 6 0 0 0 6 6 6 6 0 0 0 6-6V3" /><line x1="4" y1="21" x2="20" y2="21" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().toggleStrike().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('strike') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Barré"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M16 4H9a3 3 0 0 0-2.83 4" /><path d="M14 12a4 4 0 0 1 0 8H6" /><line x1="4" y1="12" x2="20" y2="12" /></svg>
                    </button>
                    <div className="relative flex items-center">
                        <button
                            onClick={() => setShowHighlightPalette(!showHighlightPalette)}
                            className={`p-2 rounded hover:bg-stone-700 transition-colors ${showHighlightPalette || editor.isActive('highlight') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                            title="Surligner (Aquarelle)"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="m9 11-6 6v3h9l3-3" /><path d="m22 2-9 9" /><path d="m18 4 4 4" /></svg>
                        </button>

                        {showHighlightPalette && (
                            <div className="absolute top-full left-0 mt-2 p-2 bg-stone-900 border border-stone-700 rounded-lg shadow-2xl flex gap-2 z-[70] animate-in fade-in zoom-in duration-200">
                                {HIGHLIGHT_COLORS.map(({ name, color }) => (
                                    <button
                                        key={color}
                                        onClick={() => {
                                            editor.chain().focus().setHighlight({ color }).run();
                                            setShowHighlightPalette(false);
                                        }}
                                        className="w-6 h-6 rounded-full border border-stone-600 hover:scale-110 transition-transform shadow-inner"
                                        style={{ backgroundColor: color }}
                                        title={name}
                                    />
                                ))}
                                <button
                                    onClick={() => {
                                        editor.chain().focus().unsetHighlight().run();
                                        setShowHighlightPalette(false);
                                    }}
                                    className="p-1 rounded hover:bg-stone-800 text-stone-400 hover:text-white transition-colors"
                                    title="Retirer le surlignage"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18" /><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6" /><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2" /></svg>
                                </button>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={() => editor.chain().focus().unsetAllMarks().clearNodes().run()}
                        className="p-2 rounded hover:bg-red-900/40 text-stone-400 hover:text-red-400 transition-colors"
                        title="Effacer toute la mise en forme"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="m7 21-4.3-4.3c-1-1-1-2.5 0-3.4l9.6-9.6c1-1 2.5-1 3.4 0l5.6 5.6c1 1 1 2.5 0 3.4L13 21" /><path d="M22 21H7" /><path d="m5 11 9 9" /></svg>
                    </button>

                    {/* Palette de couleurs */}
                    <div className="relative flex items-center">
                        <button
                            onClick={() => setShowColorPalette(!showColorPalette)}
                            className={`p-2 rounded hover:bg-stone-700 transition-colors ${showColorPalette ? 'bg-stone-800 text-amber-400' : 'text-stone-300'}`}
                            title="Couleur de l'encre"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <path d="m12 19 7-7 3 3-7 7-3-3z" />
                                <path d="m18 13-1.5-7.5L2 2l3.5 14.5L13 18l5-5z" />
                                <path d="m2 2 5 2" />
                                <path d="m5 2 5 2" />
                                <path d="m2 5 2 5" />
                                <path d="m2 8 2 5" />
                            </svg>
                        </button>

                        {showColorPalette && (
                            <div className="absolute top-full left-0 mt-2 p-2 bg-stone-900 border border-stone-700 rounded-lg shadow-2xl flex gap-2 z-[70] animate-in fade-in zoom-in duration-200">
                                {INK_COLORS.map(({ name, color }) => (
                                    <button
                                        key={color}
                                        onClick={() => {
                                            editor.chain().focus().setColor(color).run();
                                            setShowColorPalette(false);
                                        }}
                                        className="w-6 h-6 rounded-full border border-stone-600 hover:scale-110 transition-transform shadow-inner"
                                        style={{ backgroundColor: color }}
                                        title={name}
                                    />
                                ))}
                                <button
                                    onClick={() => {
                                        editor.chain().focus().unsetColor().run();
                                        setShowColorPalette(false);
                                    }}
                                    className="p-1 rounded hover:bg-stone-800 text-stone-400 hover:text-white transition-colors"
                                    title="Réinitialiser"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18" /><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6" /><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2" /></svg>
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                <div className="w-px h-6 bg-stone-700/50 mx-1" />

                {/* Groupe 2: Mise en forme & Listes */}
                <div className="flex items-center">
                    <button
                        onClick={() => editor.chain().focus().toggleBulletList().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('bulletList') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Liste à puces"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="8" y1="6" x2="21" y2="6" /><line x1="8" y1="12" x2="21" y2="12" /><line x1="8" y1="18" x2="21" y2="18" /><line x1="3" y1="6" x2="3.01" y2="6" /><line x1="3" y1="12" x2="3.01" y2="12" /><line x1="3" y1="18" x2="3.01" y2="18" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().toggleOrderedList().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('orderedList') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Liste numérotée"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="10" y1="6" x2="21" y2="6" /><line x1="10" y1="12" x2="21" y2="12" /><line x1="10" y1="18" x2="21" y2="18" /><path d="M4 6h1v4" /><path d="M4 10h2" /><path d="M6 18H4c0-1 2-2 2-3s-1-1.5-2-1" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().toggleBlockquote().run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive('blockquote') ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Citation (Parchemin)"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z" /><path d="M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().setHorizontalRule().run()}
                        className="p-2 rounded hover:bg-stone-700 transition-colors text-stone-300"
                        title="Ligne de séparation"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /></svg>
                    </button>
                </div>

                <div className="w-px h-6 bg-stone-700/50 mx-1" />

                {/* Groupe 3: Alignement & Image */}
                <div className="flex items-center gap-1">
                    <button
                        onClick={() => editor.chain().focus().setTextAlign('left').run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive({ textAlign: 'left' }) ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Aligner à gauche"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="17" y1="10" x2="3" y2="10" /><line x1="21" y1="6" x2="3" y2="6" /><line x1="21" y1="14" x2="3" y2="14" /><line x1="17" y1="18" x2="3" y2="18" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().setTextAlign('center').run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive({ textAlign: 'center' }) ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Aligner au centre"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="10" x2="6" y2="10" /><line x1="21" y1="6" x2="3" y2="6" /><line x1="21" y1="14" x2="3" y2="14" /><line x1="18" y1="18" x2="6" y2="18" /></svg>
                    </button>
                    <button
                        onClick={() => editor.chain().focus().setTextAlign('justify').run()}
                        className={`p-2 rounded hover:bg-stone-700 transition-colors ${editor.isActive({ textAlign: 'justify' }) ? 'text-amber-400 bg-stone-800' : 'text-stone-300'}`}
                        title="Justifier"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="21" y1="10" x2="3" y2="10" /><line x1="21" y1="6" x2="3" y2="6" /><line x1="21" y1="14" x2="3" y2="14" /><line x1="21" y1="18" x2="3" y2="18" /></svg>
                    </button>

                    <div className="w-px h-6 bg-stone-700/50 mx-1" />

                    <button
                        onClick={() => setIsDrawingMode(true)}
                        className={`flex items-center gap-2 px-3 py-1.5 rounded transition-all border font-serif font-bold text-[10px] uppercase h-8 ${isDrawingMode ? 'bg-amber-600 text-white border-amber-500 shadow-lg scale-105' : 'bg-stone-800 text-stone-300 hover:bg-stone-700 border-stone-600'}`}
                        title="Insérer Image (Tracer une zone)"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2" /><circle cx="8.5" cy="8.5" r="1.5" /><polyline points="21 15 16 10 5 21" /></svg>
                        Espace Image
                    </button>
                </div>
            </div>

            {/* Spread Wrapper: Fixed width for exact button anchoring */}
            <div className="relative" style={{ width: `${PAGE_WIDTH * 2 + 40}px` }}>

                {/* Vertical Structural Sidebar (Chapters) */}
                <div
                    className="absolute z-50 flex flex-col items-center gap-3 p-2 bg-stone-900/90 border border-amber-600/30 rounded-xl shadow-2xl backdrop-blur-md animate-in slide-in-from-right-4 duration-500"
                    style={{ right: '-65px', top: '220px' }}
                >
                    <div className="text-[9px] font-serif font-bold text-amber-500/50 uppercase tracking-widest vertical-text py-2">
                        Chapitres
                    </div>
                    <div className="w-8 h-px bg-stone-700/50" />
                    <button
                        onClick={() => (editor.commands as any).setChapter()}
                        className="p-2.5 rounded-lg bg-stone-800 text-stone-300 hover:bg-stone-700 hover:text-amber-400 transition-all border border-stone-700 hover:border-amber-600/50 shadow-lg group relative"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M5 12h14" /></svg>
                        <div className="absolute right-full mr-3 px-2 py-1 bg-stone-900 border border-stone-700 rounded text-[10px] text-stone-300 opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-50">
                            Insérer Chapitre
                        </div>
                    </button>

                    <button
                        onClick={() => (editor.commands as any).appendChapter()}
                        className="p-2.5 rounded-lg bg-amber-600/20 text-amber-500 hover:bg-amber-600/40 transition-all border border-amber-600/30 hover:border-amber-500 shadow-lg group relative"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" /><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" /></svg>
                        <div className="absolute right-full mr-3 px-2 py-1 bg-stone-900 border border-stone-700 rounded text-[10px] text-stone-300 opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-50">
                            Nouveau Chapitre (Fin)
                        </div>
                    </button>
                </div>

                {/* Navigation Buttons - Only show if there are more than 2 pages and we aren't at the limit */}
                {pageCount > 2 && scrollPos > 10 && (
                    <button
                        onClick={scrollPrev}
                        className="absolute z-50 p-3 bg-stone-800 text-stone-200 rounded-full shadow-lg hover:bg-stone-700 transition-colors border border-stone-600 animate-in fade-in duration-300"
                        style={{ left: '-60px', top: '500px', transform: 'translateY(-50%)' }}
                        title="Page Précédente"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6" /></svg>
                    </button>
                )}

                {pageCount > 2 && scrollPos < ((Math.ceil(pageCount / 2) - 1) * (PAGE_WIDTH + 40) * 2 - 10) && (
                    <button
                        onClick={scrollNext}
                        className="absolute z-50 p-3 bg-stone-800 text-stone-200 rounded-full shadow-lg hover:bg-stone-700 transition-colors border border-stone-600 animate-in fade-in duration-300"
                        style={{ right: '-60px', top: '500px', transform: 'translateY(-50%)' }}
                        title="Page Suivante"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6" /></svg>
                    </button>
                )}


                {/* Viewport Container: Handles the horizontal scroll / snap */}
                <div
                    ref={containerRef}
                    className="overflow-x-auto overflow-y-hidden relative no-scrollbar"
                    style={{
                        scrollSnapType: 'x mandatory',
                        width: '100%',
                        height: `${PAGE_HEIGHT}px`,
                        margin: '0 auto',
                    }}
                >
                    {/* Spacer to force scrollable area */}
                    <div style={{ width: `${(Math.ceil(pageCount / 2) * 2) * (PAGE_WIDTH + 40)}px`, height: '1px' }} />
                    {/* Visual Background/Decoration Track: Individual Page Cards */}
                    {(() => {
                        const visualPageCount = Math.ceil(pageCount / 2) * 2;
                        return (
                            <div className="absolute top-0 left-0 h-full pointer-events-none flex" style={{ width: `${visualPageCount * (PAGE_WIDTH + 40)}px` }}>
                                {Array.from({ length: visualPageCount }).map((_, i) => (
                                    <div
                                        key={i}
                                        className="bg-[#fbf4e9] shadow-xl rounded-sm journal-page"
                                        style={{
                                            width: `${PAGE_WIDTH}px`,
                                            height: `${PAGE_HEIGHT}px`,
                                            marginRight: '40px',
                                            flexShrink: 0,
                                            position: 'relative',
                                            scrollSnapAlign: 'start',
                                        }}
                                    >
                                        {/* Page Number */}
                                        <div className="absolute bottom-2 w-full text-center text-stone-400 text-xs font-serif">
                                            - {i + 1} -
                                        </div>

                                        {/* Binding Shadows */}
                                        <div className="absolute top-0 right-0 h-full w-[20px] bg-gradient-to-l from-black/5 to-transparent pointer-events-none" />
                                        <div className="absolute top-0 left-0 h-full w-[15px] bg-gradient-to-r from-black/5 to-transparent pointer-events-none" />
                                    </div>
                                ))}
                            </div>
                        );
                    })()}

                    {/* Table of Contents Page Overlay (Page 1) */}
                    <div
                        className="absolute top-0 left-0 z-20 pointer-events-auto"
                        style={{
                            width: `${PAGE_WIDTH}px`,
                            height: `${PAGE_HEIGHT}px`,
                            paddingTop: '60px'
                        }}
                    >
                        <BookTableOfContents entries={entries} onNavigate={navigateToPage} />
                    </div>

                    {/* Drawing Overlay */}
                    {isDrawingMode && (
                        <div
                            className="absolute top-0 left-0 z-[100] cursor-crosshair bg-white/10 backdrop-blur-[1px]"
                            style={{ width: `${(Math.ceil(pageCount / 2) * 2) * (PAGE_WIDTH + 40)}px`, height: '100%' }}
                            onMouseDown={handleDrawingMouseDown}
                            onMouseMove={handleDrawingMouseMove}
                            onMouseUp={handleDrawingMouseUp}
                        >
                            <div className="sticky left-1/2 -translate-x-1/2 top-4 w-fit bg-amber-600 text-white px-4 py-2 rounded-full shadow-2xl text-sm font-serif font-bold animate-in slide-in-from-top-4 duration-300 flex items-center gap-2">
                                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3v18M3 12h18" /></svg>
                                Tracez la zone de l'image sur le livre
                            </div>
                            {drawRect && (
                                <div
                                    className="absolute border-2 border-dashed border-amber-500 bg-amber-500/10 pointer-events-none"
                                    style={{
                                        left: `${drawRect.x}px`,
                                        top: `${drawRect.y}px`,
                                        width: `${drawRect.w}px`,
                                        height: `${drawRect.h}px`
                                    }}
                                />
                            )}
                            <button
                                className="sticky left-[90%] top-4 bg-stone-800 text-white px-3 py-1.5 rounded-lg shadow-lg text-[10px] font-bold uppercase transition-all hover:bg-red-700"
                                onClick={(e) => { e.stopPropagation(); setIsDrawingMode(false); setDrawStart(null); setDrawRect(null); }}
                            >
                                Annuler [ESC]
                            </button>
                        </div>
                    )}

                    <div
                        ref={contentRef}
                        className="text-stone-900 box-border relative z-10 no-scrollbar max-w-none"
                        style={{
                            position: 'absolute',
                            top: '60px',
                            left: `${PAGE_WIDTH + 40}px`, // Shift content to Page 2
                            height: `${PAGE_HEIGHT - 60 - 50}px`,
                            columnWidth: `${PAGE_WIDTH}px`,
                            columnGap: '40px',
                            columnFill: 'auto',
                            width: 'fit-content',
                            minWidth: `${PAGE_WIDTH}px`,
                            overflow: 'visible',
                        }}
                    >
                        <style>{`
                        .no-scrollbar::-webkit-scrollbar { display: none; }
                        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

                        /* IMPORTANT: The container width is PAGE_WIDTH (722px). 
                           The ProseMirror editor takes 100% of that WIDTH. 
                           Padding is INSIDE the editor, reducing content width to 602px (722 - 60*2).
                           Because box-sizing is border-box, width: 100% = 722px. 
                           This matches the column width perfectly. */
                        .ProseMirror {
                            box-sizing: border-box;
                            width: 100%;
                            height: 100%;
                            outline: none;
                            padding: 0 60px !important; 
                        }

                        /* 
                         * Removed the aggressive child margin override. 
                         * The padding on .ProseMirror (60px) is sufficient to constrain content.
                         * Allowing natural margins inside is safer.
                         */

                        .ProseMirror > * {
                            margin-left: 0 !important;
                            margin-right: 0 !important;
                            max-width: none !important;
                        }    
                        .ProseMirror p {
                            break-inside: auto !important;
                            page-break-inside: auto !important;
                            widows: 1 !important;
                            orphans: 1 !important;
                            margin-bottom: 1em;
                            line-height: 1.6;
                        }

                        h1, h2, h3, .chapter-header-wrapper {
                            break-before: column;
                            break-after: avoid;
                            break-inside: avoid;
                            margin-top: 0; /* Reset top margin for first line alignment */
                        }
                        
                        /* On retire le break-before systématique sur h1/h2 si on veut juste contrôler le saut manuel, 
                           but for now I keep the "Chapter = New Page" behavior requested in the spec */
                        
                        /* Prevent images from being cut */
                        img, .book-image-view {
                            break-inside: avoid;
                            max-width: 100%;
                        }

                        /* Custom Rich Styles for Grimoire */
                        .journal-highlight {
                            background-color: #f59e0b40;
                            padding: 0 2px;
                            border-radius: 2px;
                            box-shadow: 0 0 5px #f59e0b20;
                        }

                        .ProseMirror blockquote {
                            border-left: 3px solid #b45309;
                            padding-left: 1.5rem;
                            margin: 1.5rem 0;
                            font-style: italic;
                            color: #444;
                            background: rgba(180, 83, 9, 0.03);
                            padding-top: 0.5rem;
                            padding-bottom: 0.5rem;
                            border-radius: 0 4px 4px 0;
                            position: relative;
                        }

                        .ProseMirror blockquote::before {
                            content: '"';
                            position: absolute;
                            left: 0.5rem;
                            top: -0.5rem;
                            font-size: 3rem;
                            color: #b4530920;
                            font-family: serif;
                        }

                        .ProseMirror hr {
                            border: none;
                            border-top: 1px solid #b4530930;
                            margin: 2rem auto;
                            width: 60%;
                            position: relative;
                        }

                        .ProseMirror hr::after {
                            content: '◈';
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            transform: translate(-50%, -50%);
                            background: #fbf4e9;
                            padding: 0 10px;
                            color: #b4530950;
                            font-size: 0.8rem;
                        }

                        .ProseMirror ul, .ProseMirror ol {
                            padding-left: 2rem;
                            margin-bottom: 1rem;
                        }

                        .ProseMirror ul {
                            list-style: none;
                        }

                        .ProseMirror ol {
                            list-style: decimal;
                            color: #b45309;
                        }

                        .ProseMirror ol li::marker {
                            font-weight: bold;
                        }

                        .ProseMirror li p {
                            color: #1c1917; /* Revert to stone-900 for text inside lists */
                        }

                        .ProseMirror ul li {
                            position: relative;
                        }

                        .ProseMirror ul li::before {
                            content: '•';
                            position: absolute;
                            left: -1.2rem;
                            color: #b45309;
                            font-size: 1.2rem;
                        }
                    `}</style>

                        <EditorContent editor={editor} className="w-full h-full" />
                    </div>
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { AlertCircle, GraduationCap, BookOpen, CheckCircle2, Zap, ArrowRight, XCircle, ShieldCheck } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { DataConflict } from '../../utils/importExportUtils';
import ThematicButton from '../ui/ThematicButton';
import { LibraryEntry, LibrarySkillEntry, LibrarySpecializationEntry } from '../../types';

interface CloudConflictResolverProps {
    conflicts: DataConflict[];
    resolutionMap: Record<string, 'keep_current' | 'replace'>;
    onResolutionChoice: (key: string, choice: 'keep_current' | 'replace') => void;
    onResolveAll: (choice: 'keep_current' | 'replace') => void;
    onCancel: () => void;
    onConfirm: () => void;
}

const CloudConflictResolver: React.FC<CloudConflictResolverProps> = ({
    conflicts,
    resolutionMap,
    onResolutionChoice,
    onResolveAll,
    onCancel,
    onConfirm
}) => {
    return (
        <div className="flex flex-col h-full overflow-hidden bg-stone-950 text-stone-200">
            {/* Header Section */}
            <div className="bg-stone-900/80 backdrop-blur-md p-5 border-b border-amber-900/30 flex justify-between items-center">
                <div>
                    <h4 className="font-serif text-xl text-amber-500 flex items-center gap-3">
                        <AlertCircle size={24} className="text-amber-500 animate-pulse" />
                        Conflits de Synchronisation
                    </h4>
                    <p className="text-sm text-stone-400 mt-1">
                        Des éléments divergent entre votre version et la version entrante.
                    </p>
                </div>
                <div className="flex gap-3">
                    <ThematicButton
                        variant="secondary"
                        size="sm"
                        onClick={() => onResolveAll('keep_current')}
                    >
                        Tout garder (Actuel)
                    </ThematicButton>
                    <ThematicButton
                        variant="primary"
                        size="sm"
                        onClick={() => onResolveAll('replace')}
                    >
                        Tout remplacer (Cloud)
                    </ThematicButton>
                </div>
            </div>

            {/* Scrollable Conflict List */}
            <div className="flex-grow overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[url('/img/paper-texture.png')] bg-fixed">
                <AnimatePresence mode="popLayout">
                    {conflicts.map((conflict, idx) => {
                        const choice = resolutionMap[conflict.key] || 'keep_current';

                        // Helper to cast types for safe access
                        const currentAsTrait = conflict.current as LibraryEntry;
                        const incomingAsTrait = conflict.incoming as LibraryEntry;
                        const currentAsSkill = conflict.current as LibrarySkillEntry;
                        const incomingAsSkill = conflict.incoming as LibrarySkillEntry;

                        return (
                            <motion.div
                                key={conflict.key}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: idx * 0.05 }}
                                className="bg-stone-900/60 backdrop-blur-sm border border-stone-800 rounded-xl overflow-hidden shadow-2xl"
                            >
                                {/* Conflict Title Bar */}
                                <div className="bg-stone-900/90 px-5 py-3 border-b border-stone-800 flex justify-between items-center">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${conflict.type === 'skill' ? 'bg-purple-900/30 text-purple-400' : 'bg-blue-900/30 text-blue-400'}`}>
                                            {conflict.type === 'skill' ? <GraduationCap size={20} /> : <BookOpen size={20} />}
                                        </div>
                                        <div>
                                            <span className="font-serif text-lg font-bold text-stone-100">{conflict.name}</span>
                                            <span className="ml-3 text-[10px] uppercase tracking-widest text-stone-500 bg-stone-800 px-2 py-0.5 rounded">
                                                {conflict.type}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-stone-500">
                                        <ShieldCheck size={14} className={choice === 'keep_current' ? 'text-blue-500' : 'text-amber-500'} />
                                        {choice === 'keep_current' ? 'Conservation locale' : 'Remplacement Cloud'}
                                    </div>
                                </div>

                                {/* Comparison Grid */}
                                <div className="grid grid-cols-2 gap-px bg-stone-800">
                                    {/* Option: Current */}
                                    <div
                                        className={`p-5 cursor-pointer transition-all duration-300 relative group ${choice === 'keep_current'
                                                ? 'bg-blue-900/10'
                                                : 'bg-stone-900/40 opacity-60 grayscale hover:opacity-100 hover:grayscale-0'
                                            }`}
                                        onClick={() => onResolutionChoice(conflict.key, 'keep_current')}
                                    >
                                        <div className="flex justify-between items-center mb-4">
                                            <span className={`text-[10px] uppercase font-bold tracking-widest ${choice === 'keep_current' ? 'text-blue-400' : 'text-stone-500'}`}>
                                                Version Actuelle
                                            </span>
                                            {choice === 'keep_current' && (
                                                <motion.div layoutId={`check-${conflict.key}`} className="text-blue-500">
                                                    <CheckCircle2 size={20} />
                                                </motion.div>
                                            )}
                                        </div>

                                        <div className="space-y-3">
                                            {conflict.current.description ? (
                                                <p className="text-sm text-stone-300 italic leading-relaxed">
                                                    "{conflict.current.description}"
                                                </p>
                                            ) : (
                                                <p className="text-sm text-stone-500 italic">Sans description</p>
                                            )}

                                            {conflict.type === 'trait' && (
                                                <div className="flex gap-4">
                                                    <div className="bg-stone-950/50 px-3 py-1 rounded border border-stone-800">
                                                        <span className="text-[10px] text-stone-500 block uppercase">Coût</span>
                                                        <span className="text-amber-500 font-bold">{currentAsTrait.cost}</span>
                                                    </div>
                                                    {currentAsTrait.effects && currentAsTrait.effects.length > 0 && (
                                                        <div className="bg-stone-950/50 px-3 py-1 rounded border border-stone-800">
                                                            <span className="text-[10px] text-stone-500 block uppercase">Effets</span>
                                                            <span className="text-blue-400 font-bold flex items-center gap-1">
                                                                <Zap size={10} /> {currentAsTrait.effects.length}
                                                            </span>
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>

                                        {choice === 'keep_current' && (
                                            <div className="absolute inset-0 border-2 border-blue-500/30 rounded-none pointer-events-none" />
                                        )}
                                    </div>

                                    {/* Option: Incoming */}
                                    <div
                                        className={`p-5 cursor-pointer transition-all duration-300 relative group ${choice === 'replace'
                                                ? 'bg-amber-900/10'
                                                : 'bg-stone-900/40 opacity-60 grayscale hover:opacity-100 hover:grayscale-0'
                                            }`}
                                        onClick={() => onResolutionChoice(conflict.key, 'replace')}
                                    >
                                        <div className="flex justify-between items-center mb-4">
                                            <span className={`text-[10px] uppercase font-bold tracking-widest ${choice === 'replace' ? 'text-amber-400' : 'text-stone-500'}`}>
                                                Version Cloud
                                            </span>
                                            {choice === 'replace' && (
                                                <motion.div layoutId={`check-${conflict.key}`} className="text-amber-500">
                                                    <CheckCircle2 size={20} />
                                                </motion.div>
                                            )}
                                        </div>

                                        <div className="space-y-3">
                                            {conflict.incoming.description ? (
                                                <p className="text-sm text-stone-300 italic leading-relaxed">
                                                    "{conflict.incoming.description}"
                                                </p>
                                            ) : (
                                                <p className="text-sm text-stone-500 italic">Sans description</p>
                                            )}

                                            {conflict.type === 'trait' && (
                                                <div className="flex gap-4">
                                                    <div className="bg-stone-950/50 px-3 py-1 rounded border border-stone-800">
                                                        <span className="text-[10px] text-stone-500 block uppercase">Coût</span>
                                                        <span className="text-amber-500 font-bold">{incomingAsTrait.cost}</span>
                                                    </div>
                                                    {incomingAsTrait.effects && incomingAsTrait.effects.length > 0 && (
                                                        <div className="bg-stone-950/50 px-3 py-1 rounded border border-stone-800">
                                                            <span className="text-[10px] text-stone-500 block uppercase">Effets</span>
                                                            <span className="text-blue-400 font-bold flex items-center gap-1">
                                                                <Zap size={10} /> {incomingAsTrait.effects.length}
                                                            </span>
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>

                                        {choice === 'replace' && (
                                            <div className="absolute inset-0 border-2 border-amber-500/30 rounded-none pointer-events-none" />
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        );
                    })}
                </AnimatePresence>
            </div>

            {/* Footer Actions */}
            <div className="p-6 border-t border-amber-900/30 bg-stone-900/90 flex justify-end gap-4">
                <button
                    onClick={onCancel}
                    className="px-6 py-2 text-stone-400 hover:text-stone-100 hover:bg-stone-800 rounded-lg transition-colors flex items-center gap-2"
                >
                    <XCircle size={18} />
                    Annuler l'opération
                </button>
                <ThematicButton
                    variant="primary"
                    onClick={onConfirm}
                >
                    Valider la Synchronisation <ArrowRight size={18} className="ml-2" />
                </ThematicButton>
            </div>
        </div>
    );
};

