import { useNotification } from '../../context/NotificationContext';
import { useCharacter } from '../../context/CharacterContext';
import { NotificationProvider } from '../../context/NotificationContext';
import { CharacterSheetData } from '../../types';
import { APP_VERSION } from '../../constants/app';
import { migrateData } from '../../utils/migrations';
import { useRules } from '../../context/RulesContext';
import { loadRules } from '../../services/RulesLoader';
import { RulesData } from '../../types/rules';
import { CampaignService } from '../../services/CampaignService';
import { ErrorService } from '../../services/ErrorService';
import { INITIAL_DATA } from '../../data/initialState';

// Static Components
import DiegeticNavigation from './DiegeticNavigation';
import CharacterSheet from '../CharacterSheet';
import CharacterSheetPage2 from '../CharacterSheetPage2';
import CharacterSheetSpecializations from '../CharacterSheetSpecializations';
import CharacterSheetXP from '../CharacterSheetXP';

// Lazy Loaded Components
const SettingsView = lazy(() => import('../SettingsView'));
const CampaignNotes = lazy(() => import('../CampaignNotes'));
const ImportExportModal = lazy(() => import('../ImportExportModal'));
const PrintSelectionModal = lazy(() => import('../PrintSelectionModal'));
const ChangelogModal = lazy(() => import('../ChangelogModal'));
const UserGuideModal = lazy(() => import('../UserGuideModal'));
const CreationHUD = lazy(() => import('../CreationHUD'));
const UpdateNotifier = lazy(() => import('../UpdateNotifier'));
const AppearanceModal = lazy(() => import('../AppearanceModal'));
const RulesSourceSelector = lazy(() => import('../RulesSourceSelector'));
const SyncModal = lazy(() => import('../SyncModal'));
const CampaignConflictModal = lazy(() => import('../ui/CampaignConflictModal'));
const CampaignInfoModal = lazy(() => import('../ui/CampaignInfoModal'));

import { exportCharacterAsJSON } from '../../utils/importExportUtils';
import { useNavigationState } from '../../hooks/layout/useNavigationState';
import { usePrintManager } from '../../hooks/layout/usePrintManager';
import { useRulesSync } from '../../hooks/layout/useRulesSync';

// Icons
import { Settings, Printer, FileText, Layers, FileType, AlertTriangle, List, TrendingUp, History, Clock, X, Trash2, Save, Book, LogOut, Menu, Upload } from 'lucide-react';

const MainLayout: React.FC = () => {
    const { data, updateData: setData, addLog, importData } = useCharacter();
    const { rules, updateRules } = useRules();

    // Custom Hooks
    const [isLandscape, setIsLandscape] = useState(false);
    const {
        mode, setMode,
        sheetTab, setSheetTab,
        showDiscardConfirm, setShowDiscardConfirm,
        isSettingsDirty, setIsSettingsDirty,
        handleSwitchMode,
        confirmDiscard
    } = useNavigationState();

    const {
        showPrintModal, setShowPrintModal,
        pagesToPrint,
        handlePrintConfirm
    } = usePrintManager(isLandscape);

    const {
        isSourceSelected, setIsSourceSelected,
        showConflict, setShowConflict,
        pendingRules,
        handleSourceSelect,
        handleConfirmReset
    } = useRulesSync(data, rules, setData, updateRules, addLog);

    // Other UI States
    const [lastSavedState, setLastSavedState] = useState<string>("");
    const [showImportExport, setShowImportExport] = useState(false);
    const [showChangelog, setShowChangelog] = useState(false);
    const [showUserGuide, setShowUserGuide] = useState(false);
    const [showLogs, setShowLogs] = useState(false);
    const [historyTab, setHistoryTab] = useState<'sheet' | 'settings'>('sheet');
    const [showAppearance, setShowAppearance] = useState(false);
    const [showSync, setShowSync] = useState(false);
    const [showCampaignInfo, setShowCampaignInfo] = useState(false);

    // Initialize Reference State & Error Service
    useEffect(() => {
        if (data) setLastSavedState(JSON.stringify(data));
        ErrorService.init(addLog);

        // Show welcome message if available and not shown in this session
        if (rules?.showMetadataToPlayers && rules?.welcomeMessage) {
            const hasShownWelcome = sessionStorage.getItem(`welcome-shown-${rules.settingId}`);
            if (!hasShownWelcome) {
                setShowCampaignInfo(true);
                sessionStorage.setItem(`welcome-shown-${rules.settingId}`, 'true');
            }
        }
    }, []);

    // Logging helpers
    const clearCurrentLogs = () => {
        setData(prev => ({
            ...prev,
            appLogs: prev.appLogs.filter(log => log.category !== historyTab)
        }));
    };

    const filteredLogs = (data.appLogs || []).filter(log => {
        if (log.category === 'both') return true;
        return log.category === historyTab;
    });

    const handlePrintRequest = () => setShowPrintModal(true);

    const handleImportSuccess = async (newData: CharacterSheetData) => {
        setIsSourceSelected(true);
        sessionStorage.setItem('rpg-source-selected', 'true');
        importData(newData);
        const migrated = migrateData(newData);

        if (migrated.syncInfo?.settingId) {
            const currentSettingId = rules?.settingId;
            try {
                const freshRules = await CampaignService.loadSetting(migrated.syncInfo.settingId);
                if (freshRules) {
                    updateRules({
                        ...freshRules,
                        settingId: migrated.syncInfo.settingId,
                        settingName: migrated.syncInfo.settingName
                    });
                    if (migrated.syncInfo.settingId !== currentSettingId) {
                        addLog(`Règles de la campagne "${migrated.syncInfo.settingName}" chargées.`, 'success', 'settings');
                    }
                }
            } catch (e) {
                ErrorService.handleError(e, { context: 'MainLayout.handleImportSuccess', userMessage: "Echec de la synchro des règles." });
            }
        }

        setMode('sheet');
        setIsSettingsDirty(false);
        setLastSavedState(JSON.stringify(newData));
    };

    const handleConfirmBackup = async () => {
        await exportCharacterAsJSON(data, addLog);
    };



    if (!rules || !isSourceSelected) {
        return (
            <div className="fixed inset-0 bg-[#1c1c1c] text-white flex items-center justify-center z-50 bg-[url('https://www.transparenttextures.com/patterns/aged-paper.png')]">
                <Suspense fallback={<div className="text-white animate-pulse">Chargement des règles...</div>}>
                    <RulesSourceSelector
                        isOpen={true}
                        onSelectSource={handleSourceSelect}
                    />

                    {/* Render conflict modal here too because rules are still null during conflict resolution */}
                    <CampaignConflictModal
                        isOpen={showConflict}
                        onClose={() => setShowConflict(false)}
                        characterName={data.header?.name}
                        currentCampaignName={data.syncInfo?.settingName || 'Indépendante'}
                        newCampaignName={pendingRules?.name || ''}
                        onConfirmReset={handleConfirmReset}
                        onStay={() => setShowConflict(false)}
                        onBackup={handleConfirmBackup}
                    />
                </Suspense>
            </div>
        );
    }

    return (
        <NotificationProvider value={addLog}>
            <div className={`min-h-screen bg-[#1c1c1c] text-stone-200 font-sans selection:bg-red-900 selection:text-white ${isLandscape ? 'landscape-mode' : ''}`}>
                <Suspense fallback={null}>
                    <UpdateNotifier />
                </Suspense>

                {/* Background Texture (Parchemin Global) */}
                <div className="fixed inset-0 pointer-events-none z-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/aged-paper.png')]"></div>

                {/* NEW: Diegetic Navigation (Styled as Classic) */}
                <DiegeticNavigation
                    currentMode={mode}
                    onModeChange={handleSwitchMode}
                    onOpenImportExport={() => setShowImportExport(true)}
                    onPrintRequest={handlePrintRequest}
                    onToggleLandscape={() => setIsLandscape(!isLandscape)}
                    isLandscape={isLandscape}
                    onShowLogs={() => setShowLogs(!showLogs)}
                    showLogs={showLogs}
                    onShowUserGuide={() => setShowUserGuide(true)}
                    onShowChangelog={() => setShowChangelog(true)}
                    onOpenAppearance={() => setShowAppearance(true)}
                    onOpenSync={() => setShowSync(true)}
                    syncStatus={data.syncInfo ? 'synced' : 'none'}
                    appVersion={APP_VERSION}
                    onShowCampaignInfo={() => setShowCampaignInfo(true)}
                />

                <div className="relative z-10 flex flex-col min-h-screen">

                    {/* Logs Panel */}
                    <aside
                        className={`fixed right-0 top-14 bottom-0 w-80 bg-white shadow-2xl border-l border-gray-200 transform transition-transform duration-300 z-[60] flex flex-col no-print ${showLogs ? 'translate-x-0' : 'translate-x-full'}`}
                        aria-label="Historique des actions"
                    >
                        <div className="bg-gray-100 border-b border-gray-200">
                            <div className="p-3 flex justify-between items-center">
                                <h4 className="font-bold text-sm text-gray-700 flex items-center gap-2"><Clock size={16} /> Historique</h4>
                                <div className="flex items-center gap-1">
                                    {filteredLogs.length > 0 && (<button onClick={clearCurrentLogs} className="text-gray-500 hover:text-red-600 hover:bg-red-50 rounded p-1 transition-colors" title="Vider la liste actuelle"><Trash2 size={16} /></button>)}
                                    <button onClick={() => setShowLogs(false)} className="text-gray-500 hover:bg-gray-200 rounded p-1"><X size={16} /></button>
                                </div>
                            </div>
                            <div className="flex text-sm font-medium border-t border-gray-200">
                                <button onClick={() => setHistoryTab('sheet')} className={`flex-1 py-2 text-center transition-colors border-b-2 ${historyTab === 'sheet' ? 'border-blue-500 text-blue-700 bg-white' : 'border-transparent text-gray-500 hover:bg-gray-50 hover:text-gray-700'}`}>Fiche</button>
                                <button onClick={() => setHistoryTab('settings')} className={`flex-1 py-2 text-center transition-colors border-b-2 ${historyTab === 'settings' ? 'border-blue-500 text-blue-700 bg-white' : 'border-transparent text-gray-500 hover:bg-gray-50 hover:text-gray-700'}`}>Configuration</button>
                            </div>
                        </div>
                        <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-gray-50">
                            {filteredLogs.length === 0 && (<div className="text-center text-gray-400 text-xs italic mt-4 flex flex-col items-center gap-2"><Clock size={24} className="opacity-20" /><p>Aucune action enregistrée pour {historyTab === 'sheet' ? 'la fiche' : 'la configuration'}</p></div>)}
                            {filteredLogs.map((log) => (
                                <div key={log.id} className={`p-2 rounded border text-xs shadow-sm flex flex-col gap-1 animate-in slide-in-from-right-2 fade-in duration-300 ${log.type === 'success' ? 'bg-green-50 border-green-200 text-green-800' : log.type === 'danger' ? 'bg-red-50 border-red-200 text-red-800' : 'bg-white border-gray-200 text-gray-700'}`}>
                                    <div className="flex justify-between items-center opacity-70 border-b border-black/5 pb-1 mb-1"><span className="font-mono text-[10px]">{log.timestamp}</span></div>
                                    <p>{log.message}</p>
                                </div>
                            ))}
                        </div>
                    </aside>

                    {/* Main Content */}
                    <main className={`mt-4 flex flex-col items-center gap-4 w-full main-content-area ${data.creationConfig?.active ? 'pb-40' : ''}`}>
                        <Suspense fallback={<div className="p-8 text-center text-stone-400">Chargement...</div>}>
                            {mode === 'sheet' ? (
                                <>
                                    {/* Sub Navigation for Sheets */}
                                    <nav
                                        className="sticky top-14 z-40 mb-2 no-print w-full flex justify-center pointer-events-none"
                                        aria-label="Navigation des onglets de personnage"
                                    >
                                        <div className="pointer-events-auto flex gap-4 bg-white/90 backdrop-blur p-1.5 rounded-full shadow-lg border border-gray-200 flex-wrap justify-center">
                                            <button onClick={() => setSheetTab('p1')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'p1' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><Layers size={16} /> Personnage</button>
                                            <button onClick={() => setSheetTab('specs')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'specs' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><List size={16} /> Spécialisations</button>
                                            <button onClick={() => setSheetTab('p2')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'p2' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><FileType size={16} /> Détails & Equipement</button>
                                            <button onClick={() => setSheetTab('xp')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'xp' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><TrendingUp size={16} /> Gestion XP</button>
                                            <button onClick={() => setSheetTab('notes')} className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${sheetTab === 'notes' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}><Book size={16} /> Notes de Campagne</button>
                                        </div>
                                    </nav>



                                    <div className={`w-full flex px-2 md:px-0 pb-8 ${sheetTab === 'notes' ? 'overflow-visible' : sheetTab === 'prototype' ? 'overflow-hidden' : 'overflow-x-auto'}`}>
                                        <div className={`${sheetTab === 'p1' ? 'block' : 'hidden'} mx-auto`}><CharacterSheet isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'specs' ? 'block' : 'hidden'} mx-auto`}><CharacterSheetSpecializations isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'p2' ? 'block' : 'hidden'} mx-auto`}><CharacterSheetPage2 isLandscape={isLandscape} /></div>
                                        <div className={`${sheetTab === 'xp' ? 'block' : 'hidden'} mx-auto`}><CharacterSheetXP isLandscape={isLandscape} /></div>
                                        {sheetTab === 'notes' && (
                                            <div className="mx-auto block"><CampaignNotes /></div>
                                        )}
                                    </div>

                                    {data.creationConfig?.active && (<CreationHUD />)}
                                </>
                            ) : (
                                <SettingsView
                                    onClose={() => handleSwitchMode('sheet')}
                                    onDirtyChange={setIsSettingsDirty}
                                />
                            )}
                        </Suspense>
                    </main>

                    <div id="printable-area" className="hidden">
                        {pagesToPrint.p1 && (<div className="print-sheet-wrapper"><CharacterSheet isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.specs && (<div className="print-sheet-wrapper"><CharacterSheetSpecializations isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.p2 && (<div className="print-sheet-wrapper"><CharacterSheetPage2 isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.xp && (<div className="print-sheet-wrapper"><CharacterSheetXP isLandscape={isLandscape} /></div>)}
                        {pagesToPrint.notes && (<div className="print-sheet-wrapper"><CampaignNotes /></div>)}
                    </div>

                    <Suspense fallback={null}>
                        <ImportExportModal
                            isOpen={showImportExport}
                            onClose={() => setShowImportExport(false)}
                            onImportSuccess={handleImportSuccess}
                            onExportSuccess={() => { setLastSavedState(JSON.stringify(data)); }}
                            variant={mode === 'settings' ? 'gm' : 'player'}
                        />
                        <PrintSelectionModal isOpen={showPrintModal} onClose={() => setShowPrintModal(false)} onConfirm={(s: Record<string, boolean>) => handlePrintConfirm(s as any)} />

                        <ChangelogModal isOpen={showChangelog} onClose={() => setShowChangelog(false)} />
                        <UserGuideModal isOpen={showUserGuide} onClose={() => setShowUserGuide(false)} />
                        <AppearanceModal
                            isOpen={showAppearance}
                            onClose={() => setShowAppearance(false)}
                            data={data}
                            onUpdate={(newData) => setData(newData)}
                        />
                        <SyncModal
                            isOpen={showSync}
                            onClose={() => setShowSync(false)}
                            characterData={data}
                            onSyncComplete={(syncInfo) => {
                                setData(prev => ({ ...prev, syncInfo }));
                                addLog(`Fiche synchronisée avec ${syncInfo?.settingName}`, 'success', 'sheet');
                            }}
                        />

                        <CampaignConflictModal
                            isOpen={showConflict}
                            onClose={() => setShowConflict(false)}
                            characterName={data.header?.name}
                            currentCampaignName={data.syncInfo?.settingName || 'Indépendante'}
                            newCampaignName={pendingRules?.name || ''}
                            onConfirmReset={handleConfirmReset}
                            onStay={() => setShowConflict(false)}
                            onBackup={handleConfirmBackup}
                        />

                        <CampaignInfoModal
                            isOpen={showCampaignInfo}
                            onClose={() => setShowCampaignInfo(false)}
                            campaignName={rules?.settingName || 'Ma Campagne'}
                            description={rules?.description}
                            welcomeMessage={rules?.welcomeMessage}
                        />
                    </Suspense>
                </div>
            </div>
        </NotificationProvider>
    );
};

export default MainLayout;

import React, { useState } from 'react';
import { GraduationCap, Save, HelpCircle, X, AlertOctagon } from 'lucide-react';
import ThematicModal from '../ui/ThematicModal';
import { CATEGORY_HELP } from '../../data/constants';
import { LibrarySkillEntry } from '../../types';

interface LibrarySkillFormProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    skill: LibrarySkillEntry;
    onSkillChange: (skill: LibrarySkillEntry) => void;
    onSave: () => void;
    error: string | null;
    categories?: { code: string, label: string, loc?: string }[];
}

const LibrarySkillForm: React.FC<LibrarySkillFormProps> = ({
    isOpen,
    onClose,
    title,
    skill,
    onSkillChange,
    onSave,
    error,
    categories = CATEGORY_HELP
}) => {
    const [showCategoryHelp, setShowCategoryHelp] = useState(false);
    const [variantDraft, setVariantDraft] = useState(skill.variants?.join(', ') || '');

    React.useEffect(() => {
        setVariantDraft(skill.variants?.join(', ') || '');
    }, [skill.variants?.join(',')]);

    const handleSave = () => {
        const cleaned = variantDraft.split(',').map(v => v.trim()).filter(Boolean);
        onSkillChange({ ...skill, variants: cleaned });
        // Since setState is async, we can't rely on skill prop being updated yet if onSave uses it.
        // But most of our onSave functions in this project use the latest 'skill' object passed to onSkillChange.
        // Actually, let's look at how LibrarySkillLibrary.tsx handleSave works.
        onSave();
    };

    return (
        <ThematicModal
            isOpen={isOpen}
            onClose={onClose}
            title={title}
            icon={<GraduationCap size={20} />}
            size={showCategoryHelp ? 'lg' : 'md'}
            footer={
                <>
                    <button onClick={onClose} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
                    <button onClick={handleSave} className="px-6 py-2 bg-[#5c4d41] text-white rounded-sm font-bold shadow-md hover:bg-[#4a3b32] flex items-center gap-2">
                        <Save size={16} /> Enregistrer
                    </button>
                </>
            }
        >
            <div className="flex flex-col lg:flex-row gap-8 py-2">
                {/* Editor Form */}
                <div className="flex-grow flex flex-col gap-5">
                    <div>
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Nom de la compétence</label>
                        <input
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 font-serif font-black text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm"
                            value={skill.name}
                            onChange={(e) => onSkillChange({ ...skill, name: e.target.value })}
                        />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Description (Narrative)</label>
                        <textarea
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-3 text-sm text-[#1c1917] bg-white/50 min-h-[120px] focus:border-amber-500 outline-none resize-none shadow-sm italic leading-relaxed"
                            value={skill.description || ''}
                            onChange={(e) => onSkillChange({ ...skill, description: e.target.value })}
                        />
                    </div>
                    <div>
                        <div className="flex justify-between items-center mb-1">
                            <label className="block text-[10px] font-bold text-[#bfae85] uppercase tracking-widest">Catégorie de placement par défaut</label>
                            {!showCategoryHelp && (
                                <button
                                    onClick={() => setShowCategoryHelp(true)}
                                    className="text-[#5c4d41] hover:text-[#8b2e2e] transition-colors flex items-center gap-1 text-[9px] font-bold"
                                    title="Voir l'aide sur les catégories"
                                >
                                    <HelpCircle size={14} /> Aide
                                </button>
                            )}
                        </div>
                        <select
                            className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-sm text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm font-bold"
                            value={skill.defaultCategory || ''}
                            onChange={(e) => onSkillChange({ ...skill, defaultCategory: e.target.value })}
                        >
                            <option value="">-- Placement libre --</option>
                            {categories.map(cat => (
                                <option key={cat.code} value={cat.code}>{cat.label}</option>
                            ))}
                        </select>
                        <p className="text-[10px] text-[#5c4d41] mt-1.5 italic px-1">Définit dans quelle section de la fiche cette compétence sera rangée lors de l'importation.</p>
                    </div>
                    <div className="bg-amber-50/50 border border-amber-200/50 rounded-sm p-3 flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="isVariableSkill"
                            className="w-4 h-4 accent-amber-600 cursor-pointer"
                            checked={skill.isVariable || false}
                            onChange={(e) => onSkillChange({ ...skill, isVariable: e.target.checked })}
                        />
                        <label htmlFor="isVariableSkill" className="cursor-pointer select-none">
                            <span className="block text-xs font-bold text-[#5c4d41] uppercase tracking-wide">Compétence à Spécialité / Variable</span>
                            <span className="block text-[10px] text-[#5c4d41]/70 italic mt-0.5">Cochez si le joueur doit préciser quelque chose (ex: "Artisanat : Forge"). Permet d'avoir plusieurs fois cette compétence.</span>
                        </label>
                    </div>

                    {skill.isVariable && (
                        <div className="animate-in fade-in slide-in-from-top-2 duration-200 -mt-2 px-1">
                            <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Variantes suggérées (Réserve)</label>
                            <input
                                className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-xs text-[#1c1917] bg-[#fdfbf7] focus:border-amber-500 outline-none shadow-sm font-bold placeholder:italic placeholder:font-normal"
                                value={variantDraft}
                                onChange={(e) => setVariantDraft(e.target.value)}
                                onBlur={() => {
                                    const cleaned = variantDraft.split(',').map(v => v.trim()).filter(v => v !== '');
                                    onSkillChange({ ...skill, variants: cleaned });
                                }}
                                placeholder="Forge, Histoire, Épées..."
                            />
                            <p className="text-[9px] text-[#5c4d41]/70 mt-1 italic px-1">Séparez par des virgules. Ces options seront proposées lors du drag-and-drop.</p>
                        </div>
                    )}
                    {error && (
                        <div className="bg-red-50 text-red-800 text-[11px] p-3 rounded-sm border border-red-200 font-bold flex items-center gap-2 animate-shake">
                            <AlertOctagon size={16} /> {error}
                        </div>
                    )}
                </div>

                {/* Side Help Panel */}
                {showCategoryHelp && (
                    <div className="w-full lg:w-72 shrink-0 animate-in slide-in-from-right-4 duration-300">
                        <div className="flex justify-between items-center mb-2 border-b border-[#bfae85]/30 pb-1">
                            <span className="text-[10px] font-serif font-black uppercase text-[#8b2e2e] tracking-widest flex items-center gap-1">
                                <HelpCircle size={12} /> Aide aux catégories
                            </span>
                            <button
                                onClick={() => setShowCategoryHelp(false)}
                                className="text-[#5c4d41] hover:text-[#8b2e2e] p-0.5 rounded"
                            >
                                <X size={14} />
                            </button>
                        </div>
                        <div className="p-0 overflow-hidden bg-white/30 rounded-sm border border-[#bfae85]/30 relative">
                            <table className="w-full text-[10px] text-left border-collapse">
                                <thead className="bg-[#fdfbf7] border-b border-[#bfae85]/50 transition-colors">
                                    <tr>
                                        <th className="px-3 py-2 font-black tracking-widest text-[#8b2e2e]">Code</th>
                                        <th className="px-3 py-2 font-black tracking-widest text-[#8b2e2e]">Emplacement</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-[#bfae85]/20">
                                    {categories.map((cat, i) => (
                                        <tr key={i} className="hover:bg-amber-50/30 transition-colors">
                                            <td className="px-3 py-1.5 font-mono text-[#8b2e2e] font-bold">{cat.code}</td>
                                            <td className="px-3 py-1.5 text-[#4a3b32]">
                                                <div className="font-bold leading-tight">{cat.label}</div>
                                                <div className="text-[8px] text-[#5c4d41]/70 italic leading-tight">{cat.loc}</div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <p className="mt-3 text-[9px] text-[#5c4d41]/70 leading-relaxed italic border-l-2 border-[#bfae85]/30 pl-2">
                            Conseil : Copiez-collez le code technique exact pour un tri automatique parfait.
                        </p>
                    </div>
                )}
            </div>
        </ThematicModal>
    );
};

export default LibrarySkillForm;

import React, { useState } from 'react';
import { Search, Plus, Eye, EyeOff, CheckCircle2, Globe, RefreshCw, Download, Layers, Edit2, Trash2, GraduationCap } from 'lucide-react';
import { LibrarySkillEntry } from '../../types';
import { MergedEntry } from '../../utils/libraryMerger';

interface SkillLibraryTabProps {
    skillsList: MergedEntry<LibrarySkillEntry>[];
    filteredSkills: MergedEntry<LibrarySkillEntry>[];
    usedSkillNames: Set<string>;
    skillSearch: string;
    setSkillSearch: (val: string) => void;
    hideKnownSkills: boolean;
    setHideKnownSkills: (val: boolean) => void;
    handleOfficialUpdateClick: () => void;
    setShowImportConfirm: (val: boolean) => void;
    handleOpenNewSkill: () => void;
    handleOpenEditSkill: (merged: MergedEntry<LibrarySkillEntry>) => void;
    handleDeleteRequest: (merged: MergedEntry<LibrarySkillEntry>) => void;
    getCategoryLabel: (code: string) => string;
}

const SkillLibraryTab: React.FC<SkillLibraryTabProps> = ({
    skillsList,
    filteredSkills,
    usedSkillNames,
    skillSearch,
    setSkillSearch,
    hideKnownSkills,
    setHideKnownSkills,
    handleOfficialUpdateClick,
    setShowImportConfirm,
    handleOpenNewSkill,
    handleOpenEditSkill,
    handleDeleteRequest,
    getCategoryLabel
}) => {
    return (
        <div className="absolute inset-0 flex flex-col bg-[#fdfbf7]">
            {/* Skill Toolbar */}
            <div className="p-3 bg-stone-100/30 border-b border-[#bfae85]/30 grid grid-cols-1 lg:grid-cols-3 items-center gap-4 shrink-0">
                {/* Search Bar - Left */}
                <div className="relative w-full max-w-sm flex gap-2">
                    <div className="relative flex-grow">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3b32]/50" />
                        <input
                            className="w-full pl-9 pr-3 py-1.5 text-sm border border-[#bfae85]/50 rounded-sm focus:border-amber-500 outline-none text-[#1c1917] placeholder-[#4a3b32]/40 bg-white/80"
                            placeholder="Rechercher une compétence..."
                            value={skillSearch}
                            onChange={(e) => setSkillSearch(e.target.value)}
                        />
                    </div>
                    <button
                        onClick={() => setHideKnownSkills(!hideKnownSkills)}
                        className={`px-2 py-1.5 rounded-sm border transition-colors flex items-center justify-center ${hideKnownSkills ? 'bg-amber-100 text-amber-800 border-amber-300' : 'bg-white text-[#5c4d41] border-[#bfae85]/50 hover:bg-stone-50'}`}
                        title={hideKnownSkills ? "Afficher les compétences acquises" : "Masquer les compétences acquises"}
                    >
                        {hideKnownSkills ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                </div>

                {/* Shared Legend - Center */}
                <div className="flex justify-center gap-3">
                    <div className="flex items-center gap-1.5 px-2 py-0.5 bg-green-50/50 border border-green-200/50 rounded-full w-fit">
                        <CheckCircle2 size={10} className="text-green-600" />
                        <span className="text-[9px] font-bold text-green-800/70 uppercase tracking-tight whitespace-nowrap">Présent</span>
                    </div>
                    <div className="flex items-center gap-1.5 px-2 py-0.5 bg-blue-50/50 border border-blue-200/50 rounded-full w-fit">
                        <Globe size={10} className="text-indigo-600" />
                        <span className="text-[9px] font-bold text-indigo-800/70 uppercase tracking-tight whitespace-nowrap">Officiel</span>
                    </div>
                </div>

                {/* Actions - Right */}
                <div className="flex gap-2 justify-end">
                    <button
                        onClick={handleOfficialUpdateClick}
                        className="bg-blue-50 border border-blue-200 text-blue-700 hover:bg-blue-100 px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap"
                        title="Mettre à jour depuis le serveur officiel"
                    >
                        <RefreshCw size={14} /> Officiel
                    </button>
                    <button
                        onClick={() => setShowImportConfirm(true)}
                        className="bg-white/80 border border-[#bfae85]/50 text-[#5c4d41] hover:bg-stone-50 hover:text-[#1c1917] px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap"
                        title="Ajouter toutes les compétences de la fiche à la réserve"
                    >
                        <Download size={14} /> Importer
                    </button>
                    <button
                        onClick={handleOpenNewSkill}
                        className="bg-[#5c4d41] hover:bg-[#4a3b32] text-white px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap"
                    >
                        <Plus size={14} /> Créer
                    </button>
                </div>
            </div>

            {/* Skill List */}
            <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
                {skillsList.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic px-4 text-sm flex flex-col items-center">
                        <GraduationCap size={48} className="opacity-20 mb-2" />
                        <p>La réserve de compétences est vide.</p>
                        <p className="text-xs mt-2 text-[#5c4d41]/80 italic">
                            Utilisez le bouton <strong>"Importer de la fiche"</strong> pour la remplir automatiquement <br />
                            avec vos compétences actuelles.
                        </p>
                    </div>
                ) : filteredSkills.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic">Aucune compétence trouvée.</div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {filteredSkills.map(merged => {
                            const skill = merged.entry;
                            const isUsed = usedSkillNames.has(skill.name.trim().toLowerCase());
                            const isOfficial = merged.source === 'official';

                            return (
                                <div
                                    key={skill.id}
                                    className={`border rounded-sm p-2 group flex flex-col justify-between transition-all bg-white/60 ${isUsed
                                        ? 'border-green-300/40 bg-green-50/10'
                                        : isOfficial ? 'border-blue-300/40 bg-blue-50/5' : 'border-[#bfae85]/30 hover:border-amber-400/50 hover:shadow-sm'
                                        }`}
                                >
                                    <div className="flex flex-col gap-1">
                                        <div className="flex justify-between items-center gap-2">
                                            <div className="flex items-center gap-1.5 min-w-0">
                                                {skill.isVariable && (
                                                    <span title="Compétence à variations">
                                                        <Layers size={10} className="text-blue-600 shrink-0" />
                                                    </span>
                                                )}
                                                {isOfficial && (
                                                    <span title="Compétence Officielle">
                                                        <Globe size={11} className="text-indigo-500 shrink-0" />
                                                    </span>
                                                )}
                                                {isUsed && (
                                                    <span title="Présent dans la fiche">
                                                        <CheckCircle2 size={10} className="text-green-600 shrink-0" />
                                                    </span>
                                                )}
                                                <span className={`font-serif font-black uppercase text-[11px] tracking-wide truncate ${isUsed ? 'text-green-800' : 'text-[#4a3b32]'}`}>
                                                    {skill.name}
                                                </span>
                                            </div>

                                            <div className="flex gap-1 shrink-0 opacity-40 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => handleOpenEditSkill(merged)} className="text-blue-500 hover:bg-blue-50 p-1 rounded" title="Éditer/Voir"><Edit2 size={12} /></button>
                                                {!isUsed && !isOfficial && (
                                                    <button onClick={() => handleDeleteRequest(merged)} className="text-red-500 hover:bg-red-50 p-1 rounded" title="Supprimer"><Trash2 size={12} /></button>
                                                )}
                                            </div>
                                        </div>
                                        {skill.description && (
                                            <p className="text-[10px] text-[#5c4d41] italic line-clamp-1 leading-tight opacity-70" title={skill.description}>{skill.description}</p>
                                        )}
                                    </div>
                                    {skill.defaultCategory && (
                                        <span className="text-[8px] text-amber-800/50 font-mono bg-amber-100/20 px-1 py-0.5 rounded-sm self-start mt-1 border border-amber-200/10">
                                            {getCategoryLabel(skill.defaultCategory)}
                                        </span>
                                    )}

                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export default SkillLibraryTab;

import React from 'react';
import { CharacterSheetData, SuggestionEntry } from '../../types';
import { useRules } from '../../context/RulesContext';
import { Check, X, BookmarkPlus, type LucideIcon, Lightbulb } from 'lucide-react';
import ThematicButton from '../ui/ThematicButton';

interface Props {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (msg: string, type: 'success' | 'info' | 'danger', cat: 'sheet' | 'settings' | 'both') => void;
}

const AdminSuggestions: React.FC<Props> = ({ data, onUpdate, onAddLog }) => {
    const { rules, updateRules } = useRules();
    const suggestions = data.suggestions || [];

    const handleReject = (id: string) => {
        const newSuggestions = suggestions.filter(s => s.id !== id);
        onUpdate({ ...data, suggestions: newSuggestions });
        onAddLog("Suggestion rejetée et supprimée.", 'info', 'settings');
    };

    const handlePromote = (suggestion: SuggestionEntry) => {
        if (!rules) return;

        const newRules = JSON.parse(JSON.stringify(rules)); // Deep clone
        let promoted = false;

        if (suggestion.type === 'variant' && suggestion.parentId) {
            // Logic for Variants: Add to parent skill's variants list
            const skill = newRules.libraries.skills.find((s: any) => s.id === suggestion.parentId);
            if (skill) {
                if (!skill.variants) skill.variants = [];
                if (!skill.variants.includes(suggestion.name)) {
                    skill.variants.push(suggestion.name);
                    skill.variants.sort((a: string, b: string) => a.localeCompare(b)); // Keep sorted
                    promoted = true;
                    onAddLog(`Variante "${suggestion.name}" ajoutée à la compétence "${skill.name}".`, 'success', 'settings');
                } else {
                    onAddLog("Cette variante existe déjà dans la définition.", 'info', 'settings');
                    // Mark as promoted anyway to remove it
                    promoted = true;
                }
            } else {
                onAddLog("Erreur : Compétence parente introuvable.", 'danger', 'settings');
            }
        }
        /* 
        // Future logic for Traits/Skills promotion
        else if (suggestion.type === 'trait') {
             // ... create new trait entry in library ...
        }
        */

        if (promoted) {
            updateRules(newRules);
            handleReject(suggestion.id); // Remove from list after promotion
        }
    };

    if (suggestions.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-8 text-stone-500 italic">
                <Lightbulb size={48} className="mb-4 opacity-20" />
                <p>Aucune suggestion en attente.</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            <div className="bg-amber-50 border border-amber-200 p-4 rounded-sm flex items-start gap-3">
                <Lightbulb className="text-amber-600 shrink-0 mt-1" size={20} />
                <div>
                    <h3 className="font-bold text-amber-800 text-sm uppercase tracking-wide mb-1">Suggestions des Joueurs</h3>
                    <p className="text-xs text-amber-900/80">
                        Ces éléments ont été créés localement par les joueurs. Vous pouvez les valider pour les intégrer officiellement aux règles de la campagne (Bibliothèque).
                    </p>
                </div>
            </div>

            <div className="grid gap-3">
                {suggestions.map(s => (
                    <div key={s.id} className="bg-white border border-stone-200 p-4 rounded-sm shadow-sm flex items-center justify-between hover:border-amber-300 transition-colors">
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-full ${s.type === 'variant' ? 'bg-indigo-100 text-indigo-700' : 'bg-stone-100 text-stone-600'}`}>
                                {s.type === 'variant' ? <BookmarkPlus size={18} /> : <Lightbulb size={18} />}
                            </div>
                            <div>
                                <div className="font-bold text-[#2c241b]">{s.name}</div>
                                <div className="text-xs text-stone-500 uppercase tracking-widest flex items-center gap-2">
                                    <span>{s.type === 'variant' ? 'Nouvelle Variante' : 'Nouvel Élément'}</span>
                                    {s.category && <span className="px-1.5 py-0.5 bg-stone-100 rounded text-[10px]">{s.category}</span>}
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            <ThematicButton onClick={() => handlePromote(s)} variant="primary" className="!px-3 !py-1.5 text-xs">
                                <Check size={14} className="mr-1" /> Intégrer
                            </ThematicButton>
                            <ThematicButton onClick={() => handleReject(s.id)} variant="secondary" className="!px-3 !py-1.5 text-xs !bg-stone-100 hover:!bg-red-50 hover:!text-red-700 hover:!border-red-200">
                                <X size={14} />
                            </ThematicButton>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

