import React, { useState } from 'react';
import { CharacterSheetData } from '../../types';
import { Zap, Play, CheckSquare, Info, LayoutGrid } from 'lucide-react';
import ThematicModal from '../ui/ThematicModal';
import { DEFAULT_ATTRIBUTES, ATTRIBUTE_PRESETS } from '../../data/defaults/attributes';

interface AttributesEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
}


const AttributesEditor: React.FC<AttributesEditorProps> = ({ data, onUpdate, onAddLog }) => {
    const [pendingPreset, setPendingPreset] = useState<any>(null);
    const [showPresetConfirm, setShowPresetConfirm] = useState(false);

    const categories = data.attributeSettings || [];
    const count = categories.length;

    // Find global attribute count from the first category
    const firstCatId = categories[0]?.id;
    const globalAttrCount = firstCatId && data.attributes[firstCatId]
        ? data.attributes[firstCatId].length
        : 4;

    // --- LOGIC ---

    const requestPresetLoad = (preset: typeof ATTRIBUTE_PRESETS[0]) => {
        setPendingPreset(preset);
        setShowPresetConfirm(true);
    };

    const executePresetLoad = () => {
        if (!pendingPreset) return;

        const newSettings: any[] = [];
        const newAttributes: any = {};

        pendingPreset.structure.forEach((cat: any) => {
            newSettings.push({ id: cat.id, label: cat.label });
            newAttributes[cat.id] = cat.attrs.map((name: string) => ({
                id: Math.random().toString(36).substr(2, 9),
                name: name,
                val1: "0", val2: "", val3: "",
                creationVal1: 0, creationVal2: 0, creationVal3: 0
            }));
        });

        onUpdate({
            ...data,
            attributeSettings: newSettings,
            attributes: newAttributes
        });

        onAddLog(`Préréglage attributs appliqué : ${pendingPreset.name}`, 'success', 'settings');
        setShowPresetConfirm(false);
        setPendingPreset(null);
    };

    const handleCategoryCountChange = (newCount: number) => {
        const defaultDefs = [
            { id: 'pave_attributs_1', label: 'Physique' },
            { id: 'pave_attributs_2', label: 'Mental' },
            { id: 'pave_attributs_3', label: 'Social' },
            { id: 'pave_attributs_4', label: 'Mystique' }
        ];

        const currentDefs = [...data.attributeSettings];
        const currentAttributes = { ...data.attributes };

        const firstCat = currentDefs[0]?.id;
        const currentAttrCount = firstCat && currentAttributes[firstCat] ? currentAttributes[firstCat].length : 4;

        if (newCount > currentDefs.length) {
            for (let i = currentDefs.length; i < newCount; i++) {
                let defToAdd = defaultDefs[i];
                if (!defToAdd) {
                    defToAdd = { id: `pave_attributs_${i + 1}`, label: `Pavé ${i + 1}` };
                }

                if (currentDefs.some(d => d.id === defToAdd.id)) {
                    defToAdd = { ...defToAdd, id: `${defToAdd.id}_${Math.random().toString(36).substr(2, 4)}` };
                }
                currentDefs.push(defToAdd);

                currentAttributes[defToAdd.id] = Array(currentAttrCount).fill(null).map((_, idx) => {
                    let attrName = `Attribut ${idx + 1}`;
                    const baseId = defToAdd.id.split('_')[0];
                    if (DEFAULT_ATTRIBUTES[baseId] && DEFAULT_ATTRIBUTES[baseId][idx]) {
                        attrName = DEFAULT_ATTRIBUTES[baseId][idx];
                    }

                    return {
                        id: Math.random().toString(36).substr(2, 9),
                        name: attrName,
                        val1: "0", val2: "", val3: ""
                    };
                });
            }
        } else if (newCount < currentDefs.length) {
            const removed = currentDefs.splice(newCount);
            removed.forEach(def => {
                delete currentAttributes[def.id];
            });
        }

        onUpdate({
            ...data,
            attributeSettings: currentDefs,
            attributes: currentAttributes
        });
    };

    const handleGlobalAttributeCountChange = (newCount: number) => {
        const newAttributes = { ...data.attributes };

        Object.keys(newAttributes).forEach(catId => {
            const attrs = [...(newAttributes[catId] || [])];
            if (newCount > attrs.length) {
                const diff = newCount - attrs.length;
                for (let i = 0; i < diff; i++) {
                    const idx = attrs.length;
                    let attrName = `Attribut ${idx + 1}`;
                    const baseId = catId.split('_')[0];
                    if (DEFAULT_ATTRIBUTES[baseId] && DEFAULT_ATTRIBUTES[baseId][idx]) {
                        attrName = DEFAULT_ATTRIBUTES[baseId][idx];
                    }

                    attrs.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name: attrName,
                        val1: "0", val2: "", val3: ""
                    });
                }
            } else if (newCount < attrs.length) {
                attrs.splice(newCount);
            }
            newAttributes[catId] = attrs;
        });

        onUpdate({
            ...data,
            attributes: newAttributes
        });
    };

    const updateCategoryLabel = (id: string, label: string) => {
        const newSettings = data.attributeSettings.map(def =>
            def.id === id ? { ...def, label } : def
        );
        onUpdate({ ...data, attributeSettings: newSettings });
    };

    const updateAttributeName = (catId: string, attrId: string, name: string) => {
        const catAttrs = data.attributes[catId];
        if (!catAttrs) return;

        const newAttrs = catAttrs.map(attr =>
            attr.id === attrId ? { ...attr, name } : attr
        );
        onUpdate({
            ...data,
            attributes: {
                ...data.attributes,
                [catId]: newAttrs
            }
        });
    };

    const toggleSecondaryAttributes = () => {
        const isActive = !data.secondaryAttributesActive;
        const newSecondary = { ...data.secondaryAttributes };

        if (isActive) {
            data.attributeSettings.forEach(cat => {
                if (!newSecondary[cat.id]) {
                    newSecondary[cat.id] = [
                        { id: Math.random().toString(36).substr(2, 9), name: 'Secondaire 1', val1: "0", val2: "", val3: "" },
                        { id: Math.random().toString(36).substr(2, 9), name: 'Secondaire 2', val1: "0", val2: "", val3: "" }
                    ];
                }
            });
        }

        onUpdate({
            ...data,
            secondaryAttributesActive: isActive,
            secondaryAttributes: newSecondary
        });
    };

    const updateSecondaryAttributeName = (catId: string, index: number, name: string) => {
        const newSecAttrs = [...(data.secondaryAttributes[catId] || [])];
        if (newSecAttrs[index]) {
            newSecAttrs[index] = { ...newSecAttrs[index], name };
            onUpdate({
                ...data,
                secondaryAttributes: {
                    ...data.secondaryAttributes,
                    [catId]: newSecAttrs
                }
            });
        }
    };

    const updateAttributeCost = (cost: number) => {
        onUpdate({
            ...data,
            creationConfig: {
                ...data.creationConfig,
                attributeCost: cost
            }
        });
    };

    // --- RENDER ---

    return (
        <div className="bg-[#fdfbf7]/80 backdrop-blur-sm p-6 rounded-sm shadow-md border border-[#bfae85]/30 animate-in fade-in slide-in-from-bottom-4 duration-300">
            <h3 className="font-serif font-black text-sm mb-6 text-[#5c4d41] border-b border-[#bfae85]/30 pb-4 flex items-center gap-2 uppercase tracking-widest">
                <LayoutGrid className="text-[#8b2e2e]" size={20} />
                Configuration des Attributs
            </h3>

            {/* Quick Slots (Presets) */}
            <div className="mb-8">
                <h4 className="font-bold text-[10px] text-[#bfae85] mb-3 flex items-center gap-2 uppercase tracking-widest">
                    <Zap size={14} className="text-amber-500" /> Emplacements Rapides (Préréglages)
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {ATTRIBUTE_PRESETS.map((preset, idx) => (
                        <button
                            key={idx}
                            onClick={() => requestPresetLoad(preset)}
                            className="bg-[#fdfbf7] border border-[#bfae85]/30 hover:border-amber-400 hover:bg-amber-50/30 hover:shadow-md rounded-sm p-3 text-left transition-all group flex items-start gap-3"
                        >
                            <div className="bg-white p-2 rounded-full border border-[#bfae85]/20 group-hover:border-amber-400 group-hover:text-amber-700 text-[#bfae85]/50">
                                <Play size={14} className="ml-0.5" />
                            </div>
                            <div>
                                <span className="block font-bold text-[#5c4d41] text-xs group-hover:text-amber-900">{preset.name}</span>
                                <span className="block text-[10px] text-[#5c4d41]/60 italic">{preset.description}</span>
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* Option Secondary Attributes */}
            <div className="mb-8 p-4 bg-[#8b2e2e]/5 border border-[#8b2e2e]/20 rounded-sm flex items-center justify-between">
                <div>
                    <h4 className="font-bold text-[#8b2e2e] text-[10px] uppercase tracking-widest flex items-center gap-2">
                        <CheckSquare size={16} /> Attributs Secondaires
                    </h4>
                    <p className="text-[10px] text-[#5c4d41]/70 mt-1 italic leading-tight">
                        Active 2 attributs supplémentaires par pavé pour les calculs dérivés ou jauges spéciales.
                    </p>
                </div>
                <button
                    onClick={toggleSecondaryAttributes}
                    className={`w-12 h-6 rounded-full p-1 transition-colors duration-300 ${data.secondaryAttributesActive ? 'bg-[#8b2e2e]' : 'bg-stone-300'}`}
                >
                    <div className={`bg-white w-4 h-4 rounded-full shadow transform transition-transform duration-300 ${data.secondaryAttributesActive ? 'translate-x-6' : ''}`} />
                </button>
            </div>

            {/* Global Settings (Cats & Attrs Count) */}
            <div className="mb-8 bg-[#bfae85]/5 p-4 rounded-sm border border-[#bfae85]/20 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

                {/* Category Count */}
                <div className="flex flex-col gap-2">
                    <span className="font-bold text-[#5c4d41]/80 uppercase text-[10px] tracking-widest">Nombre de pavés :</span>
                    <div className="flex gap-2">
                        {[1, 2, 3, 4].map(n => (
                            <button
                                key={n}
                                onClick={() => handleCategoryCountChange(n)}
                                className={`w-10 h-10 rounded-full font-black text-base transition-all ${count === n
                                    ? 'bg-[#8b2e2e] text-white shadow-lg ring-2 ring-[#8b2e2e]/20 scale-110'
                                    : 'bg-white border border-[#bfae85]/30 text-[#5c4d41]/50 hover:bg-[#8b2e2e]/5 hover:text-[#8b2e2e]'
                                    }`}
                            >
                                {n}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Attributes Count (Global) */}
                <div className="flex flex-col gap-2">
                    <span className="font-bold text-[#5c4d41]/80 uppercase text-[10px] tracking-widest">Attributs par pavé :</span>
                    <div className="flex gap-2">
                        {[1, 2, 3, 4, 5].map(n => (
                            <button
                                key={n}
                                onClick={() => handleGlobalAttributeCountChange(n)}
                                className={`w-10 h-10 rounded-full font-black text-base transition-all ${globalAttrCount === n
                                    ? 'bg-[#8b2e2e] text-white shadow-lg ring-2 ring-[#8b2e2e]/20 scale-110'
                                    : 'bg-white border border-[#bfae85]/30 text-[#5c4d41]/50 hover:bg-[#8b2e2e]/5 hover:text-[#8b2e2e]'
                                    }`}
                            >
                                {n}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Attribute Cost */}
                <div className="flex flex-col gap-2">
                    <label className="block text-[10px] font-bold text-[#5c4d41]/80 uppercase tracking-widest">Coût XP</label>
                    <div className="flex items-center gap-2">
                        <input
                            type="number"
                            value={data.creationConfig.attributeCost ?? 6}
                            onChange={(e) => updateAttributeCost(parseInt(e.target.value) || 0)}
                            className="w-20 border border-[#bfae85]/40 rounded-sm px-3 py-1.5 focus:border-[#8b2e2e] outline-none font-bold"
                        />
                        <div title="Coût en expérience pour augmenter un attribut de 1 point (Défaut: 6)" className="text-[10px] text-[#5c4d41]/60 italic flex items-center gap-1">
                            <Info size={14} className="text-[#bfae85]" />
                            <span>/ point</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Category Cards Grid */}
            <div className={`grid gap-4 grid-cols-1 md:grid-cols-${count}`}>
                {categories.map((cat, idx) => {
                    const attrs = data.attributes[cat.id] || [];
                    const secondaryAttrs = data.secondaryAttributesActive ? (data.secondaryAttributes[cat.id] || []) : [];

                    return (
                        <div key={cat.id} className="bg-white border border-gray-200 rounded-lg shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col h-full">
                            <div className="bg-slate-100 p-3 border-b border-gray-200">
                                <label className="text-xs font-bold text-gray-500 uppercase tracking-wide block mb-1">
                                    Pavé {idx + 1}
                                </label>
                                <input
                                    value={cat.label}
                                    onChange={(e) => updateCategoryLabel(cat.id, e.target.value)}
                                    onFocus={(e) => e.target.select()}
                                    className="w-full font-bold text-lg bg-white border border-gray-300 rounded px-2 py-1 shadow-inner focus:border-blue-500 focus:ring-2 focus:ring-blue-200 outline-none text-gray-900 transition-all"
                                    placeholder="Nom du pavé"
                                />
                            </div>

                            <div className="p-3 space-y-2 flex-grow bg-slate-50/50">
                                {attrs.map((attr, aIdx) => (
                                    <div key={attr.id} className="flex items-center gap-2">
                                        <span className="text-xs text-gray-400 w-4 font-mono select-none">{aIdx + 1}</span>
                                        <input
                                            value={attr.name}
                                            onChange={(e) => updateAttributeName(cat.id, attr.id, e.target.value)}
                                            onFocus={(e) => e.target.select()}
                                            className="flex-grow text-sm border border-gray-300 rounded px-2 py-1 focus:border-blue-500 outline-none bg-white shadow-sm font-medium text-gray-800"
                                            placeholder={`Attribut ${aIdx + 1}`}
                                        />
                                    </div>
                                ))}

                                {data.secondaryAttributesActive && secondaryAttrs.length > 0 && (
                                    <>
                                        <hr className="my-3 border-dashed border-gray-300" />
                                        <div className="text-[10px] text-gray-400 font-bold uppercase text-center mb-2 tracking-wide">Secondaires</div>
                                        {secondaryAttrs.map((sAttr, sIdx) => (
                                            <div key={sAttr.id} className="flex items-center gap-2">
                                                <span className="text-xs text-purple-400 w-4 font-mono select-none">+{sIdx + 1}</span>
                                                <input
                                                    value={sAttr.name}
                                                    onChange={(e) => updateSecondaryAttributeName(cat.id, sIdx, e.target.value)}
                                                    onFocus={(e) => e.target.select()}
                                                    className="flex-grow text-sm border border-purple-200 rounded px-2 py-1 focus:border-purple-500 outline-none bg-white shadow-sm font-medium text-gray-800"
                                                    placeholder={`Attr. Secondaire ${sIdx + 1}`}
                                                />
                                            </div>
                                        ))}
                                    </>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Preset Confirmation Modal */}
            {showPresetConfirm && pendingPreset && (
                <ThematicModal
                    isOpen={showPresetConfirm}
                    onClose={() => { setShowPresetConfirm(false); setPendingPreset(null); }}
                    title="Charger le préréglage ?"
                    icon={<Zap size={24} className="text-amber-600" />}
                    size="md"
                    footer={
                        <>
                            <button onClick={() => { setShowPresetConfirm(false); setPendingPreset(null); }} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
                            <button onClick={executePresetLoad} className="px-6 py-2 bg-[#8b2e2e] text-white rounded-sm font-bold shadow-md hover:bg-[#6a2424]">
                                Confirmer
                            </button>
                        </>
                    }
                >
                    <div className="flex flex-col items-center text-center space-y-4 py-4">
                        <div className="bg-amber-50/50 p-4 rounded-sm border border-[#bfae85]/30 w-full">
                            <span className="block font-black text-[#8b2e2e] uppercase tracking-widest text-sm mb-1">{pendingPreset.name}</span>
                            <span className="text-[10px] text-[#5c4d41]/70 italic">{pendingPreset.description}</span>
                        </div>
                        <p className="text-xs text-[#5c4d41] leading-relaxed">
                            Cette action remplacera <span className="font-bold underline">toute</span> votre configuration d'attributs actuelle.
                        </p>
                        <div className="bg-red-50/50 border border-red-200/50 p-2 rounded-sm w-full">
                            <p className="text-[10px] text-red-800/80 italic font-bold">Les noms et scores actuels seront perdus.</p>
                        </div>
                    </div>
                </ThematicModal>
            )}
        </div>
    );
};

export default AttributesEditor;

import React from 'react';
import { CharacterSheetData } from '../../types';
import { Sliders, List, PieChart, CreditCard, Info, AlertCircle } from 'lucide-react';

interface CreationConfigEditorProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
}

const CreationConfigEditor: React.FC<CreationConfigEditorProps> = ({ data, onUpdate, onAddLog }) => {
    const config = data.creationConfig;
    if (!config) return null;

    const updateCreationConfig = (field: string, value: any) => {
        onUpdate({
            ...data,
            creationConfig: {
                ...data.creationConfig,
                [field]: value
            }
        });
        onAddLog(`Config Création modifiée : ${field}`, 'info', 'settings');
    };

    const updatePointsBuckets = (bucket: 'attributes' | 'skills' | 'backgrounds', value: number) => {
        onUpdate({
            ...data,
            creationConfig: {
                ...data.creationConfig,
                pointsBuckets: {
                    ...(data.creationConfig.pointsBuckets || { attributes: 0, skills: 0, backgrounds: 0 }),
                    [bucket]: value
                }
            }
        });
    };

    const updateCardConfig = (field: string, value: any) => {
        onUpdate({
            ...data,
            creationConfig: {
                ...data.creationConfig,
                cardConfig: {
                    ...data.creationConfig.cardConfig,
                    [field]: value
                }
            }
        });
    };

    const updateRankSlot = (rank: number, value: number) => {
        onUpdate({
            ...data,
            creationConfig: {
                ...data.creationConfig,
                rankSlots: {
                    ...data.creationConfig.rankSlots,
                    [rank]: value
                }
            }
        });
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">

            {/* Configuration Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">

                {/* General Settings */}
                <div className="bg-[#fdfbf7]/80 backdrop-blur-sm p-6 rounded-sm shadow-md border border-[#bfae85]/30">
                    <h4 className="font-bold text-[#5c4d41] border-b border-[#bfae85]/30 pb-2 mb-4 flex items-center gap-2 uppercase tracking-widest text-sm">
                        <Sliders size={18} className="text-[#8b2e2e]" /> Paramètres de Création
                    </h4>

                    <div className="space-y-4">
                        {/* Extended Skills Toggle */}
                        <div className="flex items-center justify-between bg-[#bfae85]/10 p-2 rounded-sm border border-[#bfae85]/20 mb-4">
                            <label className="text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest">Rangs Étendus (6+)</label>
                            <div className="flex items-center gap-2">
                                <span className="text-[9px] font-bold text-[#5c4d41]/60 tracking-widest">{config.extendedSkills ? 'ACTIF' : 'INACTIF'}</span>
                                <button
                                    onClick={() => updateCreationConfig('extendedSkills', !config.extendedSkills)}
                                    className={`w-8 h-4 rounded-full p-0.5 transition-colors ${config.extendedSkills ? 'bg-[#8b2e2e]' : 'bg-stone-300'}`}
                                >
                                    <div className={`bg-white w-3 h-3 rounded-full shadow-sm transform transition-transform ${config.extendedSkills ? 'translate-x-4' : ''}`} />
                                </button>
                            </div>
                        </div>

                        <div>
                            <label className="block text-[10px] font-bold text-[#8b2e2e] uppercase tracking-widest mb-1.5">Méthode de Création</label>
                            <div className="flex bg-stone-200/50 p-1 rounded-sm border border-stone-300/30">
                                <button
                                    onClick={() => updateCreationConfig('mode', 'rangs')}
                                    className={`flex-1 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-sm transition-all ${config.mode === 'rangs' ? 'bg-[#8b2e2e] text-white shadow-md' : 'text-[#5c4d41]/60 hover:text-[#5c4d41]'}`}
                                >
                                    Par Rangs
                                </button>
                                <button
                                    onClick={() => updateCreationConfig('mode', 'points')}
                                    className={`flex-1 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-sm transition-all ${config.mode === 'points' ? 'bg-[#8b2e2e] text-white shadow-md' : 'text-[#5c4d41]/60 hover:text-[#5c4d41]'}`}
                                >
                                    Par Points (XP)
                                </button>
                            </div>
                        </div>

                        {config.mode === 'points' && (
                            <div className="space-y-4">
                                {/* Sub-mode selector */}
                                <div>
                                    <label className="block text-[9px] font-bold text-[#bfae85] mb-1 uppercase tracking-tighter">Type de Répartition</label>
                                    <div className="flex bg-stone-200/50 p-1 rounded-sm border border-stone-300/30">
                                        <button
                                            onClick={() => updateCreationConfig('pointsDistributionMode', 'global')}
                                            className={`flex-1 py-1 text-[9px] font-bold uppercase rounded-sm transition-all ${(!config.pointsDistributionMode || config.pointsDistributionMode === 'global') ? 'bg-[#5c4d41] text-white shadow-sm' : 'text-[#5c4d41]/60 hover:text-[#5c4d41]'}`}
                                        >
                                            Pot Commun
                                        </button>
                                        <button
                                            onClick={() => updateCreationConfig('pointsDistributionMode', 'buckets')}
                                            className={`flex-1 py-1 text-[9px] font-bold uppercase rounded-sm transition-all ${config.pointsDistributionMode === 'buckets' ? 'bg-[#5c4d41] text-white shadow-sm' : 'text-[#5c4d41]/60 hover:text-[#5c4d41]'}`}
                                        >
                                            Budgets Séparés
                                        </button>
                                    </div>
                                </div>

                                {(!config.pointsDistributionMode || config.pointsDistributionMode === 'global') ? (
                                    <div className="animate-in fade-in slide-in-from-top-2">
                                        <label className="block text-sm font-bold text-gray-700 mb-1">XP de Départ (Global)</label>
                                        <input
                                            type="number"
                                            value={config.startingXP || 0}
                                            onChange={(e) => updateCreationConfig('startingXP', parseInt(e.target.value) || 0)}
                                            className="w-full border border-gray-300 rounded px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none font-mono font-bold text-lg"
                                        />
                                    </div>
                                ) : (
                                    <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">XP Attributs</label>
                                            <input
                                                type="number"
                                                value={config.pointsBuckets?.attributes || 0}
                                                onChange={(e) => updatePointsBuckets('attributes', parseInt(e.target.value) || 0)}
                                                className="w-full border border-gray-300 rounded px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none"
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">XP Compétences</label>
                                            <input
                                                type="number"
                                                value={config.pointsBuckets?.skills || 0}
                                                onChange={(e) => updatePointsBuckets('skills', parseInt(e.target.value) || 0)}
                                                className="w-full border border-gray-300 rounded px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none"
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">XP Arrière-plans</label>
                                            <input
                                                type="number"
                                                value={config.pointsBuckets?.backgrounds || 0}
                                                onChange={(e) => updatePointsBuckets('backgrounds', parseInt(e.target.value) || 0)}
                                                className="w-full border border-gray-300 rounded px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none"
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {config.mode === 'rangs' && (
                            <div className="grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">Pts Attributs</label>
                                    <input
                                        type="number"
                                        value={config.attributePoints || 0}
                                        onChange={(e) => updateCreationConfig('attributePoints', parseInt(e.target.value) || 0)}
                                        className="w-full border border-gray-300 rounded px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">Pts Arr. Plans</label>
                                    <input
                                        type="number"
                                        value={config.backgroundPoints || 0}
                                        onChange={(e) => updateCreationConfig('backgroundPoints', parseInt(e.target.value) || 0)}
                                        className="w-full border border-gray-300 rounded px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    />
                                </div>
                            </div>
                        )}

                        <div className="grid grid-cols-2 gap-4 bg-[#bfae85]/10 p-3 rounded-sm border border-[#bfae85]/30">
                            <div>
                                <label className="block text-[10px] font-bold text-[#5c4d41]/60 mb-1 uppercase tracking-widest">Attr. Min</label>
                                <input
                                    type="number"
                                    value={config.attributeMin ?? -2}
                                    onChange={(e) => updateCreationConfig('attributeMin', parseInt(e.target.value))}
                                    className="w-full border border-[#bfae85]/40 rounded-sm px-2 py-1 text-xs focus:border-[#8b2e2e] outline-none bg-white font-bold text-[#2c241b]"
                                />
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold text-[#5c4d41]/60 mb-1 uppercase tracking-widest">Attr. Max</label>
                                <input
                                    type="number"
                                    value={config.attributeMax ?? 3}
                                    onChange={(e) => updateCreationConfig('attributeMax', parseInt(e.target.value))}
                                    className="w-full border border-[#bfae85]/40 rounded-sm px-2 py-1 text-xs focus:border-[#8b2e2e] outline-none bg-white font-bold text-[#2c241b]"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Right Column: Rank Slots or Colors */}
                <div className="flex flex-col gap-6">

                    {/* Rank Slots Configuration (Only if mode is 'rangs') */}
                    {config.mode === 'rangs' && (
                        <div className="bg-white p-6 rounded-xl shadow border border-gray-200">
                            <h4 className="font-bold text-gray-800 border-b pb-2 mb-4 flex items-center gap-2">
                                <List size={18} /> Répartition des Rangs
                            </h4>
                            <div className="space-y-3">
                                {[5, 4, 3, 2, 1].map(rank => (
                                    <div key={rank} className="flex items-center justify-between p-2 hover:bg-gray-50 rounded">
                                        <span className="font-bold text-gray-600">Rang {rank}</span>
                                        <div className="flex items-center gap-2">
                                            <input
                                                type="number"
                                                // @ts-expect-error -- legacy code
                                                value={config.rankSlots[rank] || 0}
                                                onChange={(e) => updateRankSlot(rank, parseInt(e.target.value) || 0)}
                                                className="w-20 border border-gray-300 rounded px-2 py-1 text-center font-mono focus:border-blue-500 outline-none"
                                            />
                                            <span className="text-sm text-gray-400">rangs</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Distribution Preview for Points Mode (Buckets) */}
                    {config.mode === 'points' && config.pointsDistributionMode === 'buckets' && (
                        <div className="bg-white p-6 rounded-xl shadow border border-gray-200">
                            <h4 className="font-bold text-gray-800 border-b pb-2 mb-4 flex items-center gap-2">
                                <PieChart size={18} /> Répartition Totale
                            </h4>
                            <div className="space-y-4">
                                <div className="flex justify-between items-center">
                                    <span className="text-sm text-gray-600">Attributs</span>
                                    <span className="font-bold">{config.pointsBuckets?.attributes || 0} XP</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-sm text-gray-600">Compétences</span>
                                    <span className="font-bold">{config.pointsBuckets?.skills || 0} XP</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-sm text-gray-600">Arrière-plans</span>
                                    <span className="font-bold">{config.pointsBuckets?.backgrounds || 0} XP</span>
                                </div>
                                <div className="pt-2 border-t border-gray-200 flex justify-between items-center">
                                    <span className="font-bold text-gray-800">Total</span>
                                    <span className="font-bold text-blue-600 text-lg">
                                        {(config.pointsBuckets?.attributes || 0) + (config.pointsBuckets?.skills || 0) + (config.pointsBuckets?.backgrounds || 0)} XP
                                    </span>
                                </div>
                            </div>
                        </div>
                    )}

                </div>

            </div>

            {/* Separator */}
            <hr className="border-[#bfae85]/30 mx-10" />

            {/* Card System Configuration - INDEPENDENT FROM CREATION MODE */}
            <div className="bg-[#fdfbf7]/80 backdrop-blur-sm p-6 rounded-sm shadow-md border border-[#bfae85]/30">
                <div className="flex items-center justify-between border-b border-[#bfae85]/30 pb-2 mb-4">
                    <h4 className="font-bold text-[#5c4d41] flex items-center gap-2 uppercase tracking-widest text-sm">
                        <CreditCard size={18} className="text-[#8b2e2e]" /> Système de Carte
                    </h4>
                    <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-[#5c4d41]/40 tracking-widest">{config.cardConfig?.active ? 'ACTIF' : 'INACTIF'}</span>
                        <button
                            onClick={() => updateCardConfig('active', !config.cardConfig?.active)}
                            className={`w-10 h-5 rounded-full p-0.5 transition-colors ${config.cardConfig?.active ? 'bg-[#166534]' : 'bg-stone-300'}`}
                        >
                            <div className={`bg-white w-4 h-4 rounded-full shadow-sm transform transition-transform ${config.cardConfig?.active ? 'translate-x-5' : ''}`} />
                        </button>
                    </div>
                </div>

                <div className={`grid grid-cols-1 md:grid-cols-3 gap-6 transition-opacity ${config.cardConfig?.active ? 'opacity-100' : 'opacity-40 pointer-events-none grayscale'}`}>
                    <div>
                        <label className="block text-[10px] font-bold text-[#bfae85] mb-1 uppercase tracking-tighter">Compétences retenues</label>
                        <div className="flex items-center gap-2">
                            <input
                                type="number"
                                value={config.cardConfig?.bestSkillsCount ?? 6}
                                onChange={(e) => updateCardConfig('bestSkillsCount', parseInt(e.target.value))}
                                className="w-full border border-[#bfae85]/40 rounded-sm px-3 py-1.5 focus:border-[#8b2e2e] outline-none bg-white font-bold"
                            />
                            <div title="Nombre de meilleures compétences utilisées pour la moyenne">
                                <Info size={16} className="text-[#bfae85]" />
                            </div>
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Incrément par Palier</label>
                        <input
                            type="number"
                            step="0.1"
                            value={config.cardConfig?.increment ?? 0.5}
                            onChange={(e) => updateCardConfig('increment', parseFloat(e.target.value))}
                            className="w-full border border-gray-300 rounded px-3 py-2 focus:border-blue-500 outline-none"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Seuil de Base (Valet)</label>
                        <input
                            type="number"
                            step="0.1"
                            value={config.cardConfig?.baseStart ?? 2}
                            onChange={(e) => updateCardConfig('baseStart', parseFloat(e.target.value))}
                            className="w-full border border-gray-300 rounded px-3 py-2 focus:border-blue-500 outline-none"
                        />
                    </div>
                </div>
            </div>

        </div>
    );
};

export default CreationConfigEditor;

import React from 'react';
import { CharacterSheetData, LibrarySkillEntry, SkillCategoryKey } from '../../types';
import { BookOpen, Archive, GripVertical, ArrowRight, Layers, CheckCircle2 } from 'lucide-react';

interface LibrarySidebarProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings') => void;
    draggedItem: { type: 'sheet_skill' | 'lib_skill', category?: string, index?: number, id?: string, data?: any } | null;
    setDraggedItem: (item: any) => void;
}

const LibrarySidebar: React.FC<LibrarySidebarProps> = ({ data, onUpdate, onAddLog, draggedItem, setDraggedItem }) => {

    const handleDragStart = (e: React.DragEvent, type: 'lib_skill', dataPayload: any) => {
        setDraggedItem({ type, ...dataPayload });
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("application/json", JSON.stringify({ type, ...dataPayload }));
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
    };

    const handleDropOnLibrary = (e: React.DragEvent) => {
        e.preventDefault();
        if (!draggedItem) return;

        // Only accept items from sheet (archiving)
        if (draggedItem.type === 'sheet_skill' && draggedItem.category !== 'counters') {
            const catKey = draggedItem.category as SkillCategoryKey;
            const index = draggedItem.index!;

            const newSkills = { ...data.skills };
            const list = [...(newSkills[catKey] || [])];
            const [removedItem] = list.splice(index, 1);
            newSkills[catKey] = list;

            // Add to Library
            // Check duplicate name first to be safe
            const existingInLib = (data.skillLibrary || []).find(l => l.name === removedItem.name);
            const newLib = [...(data.skillLibrary || [])];

            if (!existingInLib && removedItem.name.trim() !== '') {
                const newLibEntry: LibrarySkillEntry = {
                    id: Math.random().toString(36).substr(2, 9),
                    name: removedItem.name,
                    description: '',
                    defaultCategory: catKey
                };
                newLib.push(newLibEntry);
                onAddLog(`Archivage : "${removedItem.name}" déplacé vers la réserve`, 'info', 'settings');
            } else {
                onAddLog(`Suppression : "${removedItem.name}" retiré de la fiche`, 'info', 'settings');
            }

            // Sort Library Alphabetically
            newLib.sort((a, b) => a.name.localeCompare(b.name));

            onUpdate({
                ...data,
                skills: newSkills,
                skillLibrary: newLib
            });
        }
        setDraggedItem(null);
    };

    // Filter out skills that are already present on the sheet to avoid duplication clutter
    const currentSkillNames = new Set<string>();
    Object.keys(data.skills).forEach(cat => {
        data.skills[cat].forEach(s => {
            if (s.name) currentSkillNames.add(s.name.trim().toLowerCase());
        });
    });

    const visibleLibrary = (data.skillLibrary || []).filter(libItem =>
        libItem.isVariable || !currentSkillNames.has(libItem.name.trim().toLowerCase())
    );

    return (
        <div
            className={`w-80 bg-slate-100 border-l border-gray-300 flex flex-col fixed right-0 top-14 bottom-0 z-30 transition-colors ${draggedItem?.type === 'sheet_skill' ? 'bg-orange-50 border-orange-300' : ''}`}
            onDragOver={handleDragOver}
            onDrop={handleDropOnLibrary}
        >
            <div className="p-4 bg-slate-200 border-b border-gray-300 font-bold text-slate-700 flex items-center gap-2 shadow-sm">
                <BookOpen size={18} />
                Réserve de Compétences
            </div>

            {draggedItem?.type === 'sheet_skill' && draggedItem.category !== 'counters' && (
                <div className="absolute inset-0 bg-orange-100/90 z-50 flex flex-col items-center justify-center border-4 border-dashed border-orange-400 m-2 rounded-xl pointer-events-none">
                    <Archive size={48} className="text-orange-600 mb-2" />
                    <span className="font-bold text-orange-800 text-lg">Archiver ici</span>
                    <span className="text-sm text-orange-700">Retirer de la fiche et garder en réserve</span>
                </div>
            )}

            <div className="p-3 text-xs text-slate-500 border-b border-slate-200 bg-slate-50">
                Glissez des compétences ici vers la fiche pour les ajouter.
                Glissez une compétence de la fiche ici pour la ranger.
            </div>

            <div className="flex-grow overflow-y-auto p-3 space-y-2 custom-scrollbar">
                {visibleLibrary.length === 0 ? (
                    <div className="text-center text-slate-400 italic mt-10 px-4">
                        {(data.skillLibrary || []).length > 0
                            ? "Toutes les compétences de la réserve sont déjà sur la fiche."
                            : "La réserve est vide."}
                    </div>
                ) : (
                    visibleLibrary.map(item => {
                        const isPresent = currentSkillNames.has(item.name.trim().toLowerCase());

                        return (
                            <div
                                key={item.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, 'lib_skill', { data: item })}
                                className={`p-2 rounded border shadow-sm cursor-grab active:cursor-grabbing transition-all flex justify-between items-center group ${isPresent
                                        ? 'bg-green-50/30 border-green-200/60 hover:border-green-400'
                                        : 'bg-white border-gray-300 hover:border-purple-400 hover:shadow-md'
                                    }`}
                            >
                                <div className="flex items-center gap-2 overflow-hidden">
                                    <GripVertical size={14} className="text-gray-300 shrink-0" />
                                    <div className="flex flex-col min-w-0">
                                        <div className="flex items-center gap-1.5">
                                            <span className={`font-bold text-sm truncate ${isPresent ? 'text-green-800' : 'text-slate-700'}`}>
                                                {item.name}
                                            </span>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            {item.isVariable && (
                                                <div className="flex items-center gap-0.5 text-[10px] text-blue-600 bg-blue-50 px-1 rounded-sm border border-blue-100">
                                                    <Layers size={10} />
                                                    <span className="font-semibold" title="Compétence à variations">Variable</span>
                                                </div>
                                            )}
                                            {isPresent && (
                                                <div className="flex items-center gap-0.5 text-[10px] text-green-700 bg-green-50 px-1 rounded-sm border border-green-100">
                                                    <CheckCircle2 size={10} />
                                                    <span className="font-semibold">Présent</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <ArrowRight size={14} className="text-gray-300 opacity-0 group-hover:opacity-100 shrink-0 mx-1" />
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
};

