import React, { useState, useMemo } from 'react';
import { X, Search, Award, Info, GripVertical } from 'lucide-react';
import { useCharacterData } from '../../context/CharacterContext';
import { smartIncludes } from '../../utils/stringUtils';

interface SpecializationLibraryDrawerProps {
    isOpen: boolean;
    onClose: () => void;
    onSelect?: (name: string, minLevel: number) => void;
}

const SpecializationLibraryDrawer: React.FC<SpecializationLibraryDrawerProps> = ({
    isOpen,
    onClose,
    onSelect
}) => {
    const data = useCharacterData();
    const [searchTerm, setSearchTerm] = useState('');

    const library = data.specializationLibrary || [];

    const filteredLibrary = useMemo(() => {
        return library.filter(entry =>
            smartIncludes(entry.name, searchTerm) ||
            (entry.description && smartIncludes(entry.description, searchTerm))
        ).sort((a, b) => a.name.localeCompare(b.name));
    }, [library, searchTerm]);

    const handleDragStart = (e: React.DragEvent, entry: any) => {
        // Store both name and default level in the drag data
        e.dataTransfer.setData('text/plain', entry.name);
        e.dataTransfer.setData('application/json', JSON.stringify({
            name: entry.name,
            minLevel: entry.defaultMinLevel
        }));
        e.dataTransfer.effectAllowed = 'copy';
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-y-0 right-0 w-80 bg-white shadow-2xl z-[200] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300">
            {/* Header */}
            <div className="p-4 bg-amber-700 text-white flex justify-between items-center shrink-0">
                <h3 className="font-bold flex items-center gap-2">
                    <Award size={20} /> Catalogue de Spés
                </h3>
                <button onClick={onClose} className="hover:bg-white/20 p-1 rounded transition-colors">
                    <X size={20} />
                </button>
            </div>

            {/* Search */}
            <div className="p-3 border-b bg-gray-50 shrink-0">
                <div className="relative">
                    <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                        className="w-full pl-8 pr-3 py-1.5 text-xs border border-gray-300 rounded focus:border-amber-500 outline-none"
                        placeholder="Chercher..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>

            {/* List */}
            <div className="flex-grow overflow-y-auto p-2 custom-scrollbar space-y-2">
                {filteredLibrary.length === 0 ? (
                    <div className="text-center text-gray-400 py-10 italic text-xs">
                        {library.length === 0 ? "La bibliothèque est vide." : "Aucun résultat."}
                    </div>
                ) : (
                    filteredLibrary.map(entry => (
                        <div
                            key={entry.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, entry)}
                            onClick={() => onSelect && onSelect(entry.name, entry.defaultMinLevel)}
                            className="bg-white border border-gray-200 rounded-lg p-3 hover:border-amber-400 hover:shadow-sm cursor-grab active:cursor-grabbing transition-all group relative"
                        >
                            <div className="flex justify-between items-start mb-1">
                                <div className="flex items-center gap-2">
                                    <GripVertical size={14} className="text-gray-300 group-hover:text-amber-500" />
                                    <span className="font-bold text-sm text-gray-800">{entry.name}</span>
                                </div>
                                <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-1.5 py-0.5 rounded border border-amber-100">
                                    Lvl {entry.defaultMinLevel}
                                </span>
                            </div>
                            {entry.description && (
                                <p className="text-[10px] text-gray-500 line-clamp-1 group-hover:line-clamp-none transition-all">
                                    {entry.description}
                                </p>
                            )}
                        </div>
                    ))
                )}
            </div>

            {/* Footer / Instructions */}
            <div className="p-3 bg-gray-50 border-t border-gray-200 text-[10px] text-gray-500 flex gap-2">
                <Info size={14} className="shrink-0 text-amber-500" />
                <p>Faites glisser une spécialisation sur la fiche ou cliquez pour l'ajouter (si liste active).</p>
            </div>
        </div>
    );
};

export default SpecializationLibraryDrawer;

import React, { useState, useMemo } from 'react';
import { Search, Plus, Award, CheckCircle2, Edit2, Trash2, Download, HelpCircle, Save, X, AlertTriangle, RefreshCw, Eye, EyeOff, Globe } from 'lucide-react';
import { CharacterSheetData } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { LibrarySpecializationEntry } from '../../types';
import { smartIncludes } from '../../utils/stringUtils';
import { useRules } from '../../context/RulesContext';
import { mergeLibraries, MergedEntry } from '../../utils/libraryMerger';
import ConfirmationModal from '../ui/ConfirmationModal';

interface SpecializationLibraryViewProps {
    data: CharacterSheetData;
    onUpdate: (newData: CharacterSheetData) => void;
}

const SpecializationLibraryView: React.FC<SpecializationLibraryViewProps> = ({ data, onUpdate }) => {
    const addLog = useNotification();

    const [searchTerm, setSearchTerm] = useState('');
    const [hideKnown, setHideKnown] = useState(true); // Default: Hide known
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingEntry, setEditingEntry] = useState<LibrarySpecializationEntry | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [showImportConfirm, setShowImportConfirm] = useState(false);
    const [entryToDelete, setEntryToDelete] = useState<LibrarySpecializationEntry | null>(null);
    const [skillSearch, setSkillSearch] = useState('');

    // OFFICIAL: Get Rules Context
    const { rules, updateRules } = useRules();

    // MERGE: Compute Hybrid Specialization Library
    const hybridSpecializations = useMemo(() => {
        const local = data.specializationLibrary || [];
        const official = rules?.libraries?.specializations || [];

        return mergeLibraries(local, official);
    }, [data.specializationLibrary, rules]);

    const library = hybridSpecializations; // Now MergedEntry[]

    // Liste plate de toutes les compétences pour le mapping
    const allSkills = useMemo(() => {
        const skills: { id: string, name: string }[] = [];
        if (data.skills) {
            Object.values(data.skills).forEach(category => {
                category.forEach(skill => {
                    if (skill.name && skill.name.trim() !== '') {
                        skills.push({ id: skill.id, name: skill.name });
                    }
                });
            });
        }
        return skills.sort((a, b) => a.name.localeCompare(b.name));
    }, [data.skills]);

    // Compétences filtrées pour la modale
    const filteredSkillsForModal = useMemo(() => {
        return allSkills.filter(s =>
            smartIncludes(s.name, skillSearch) || (editingEntry?.skillIds.includes(s.id))
        );
    }, [allSkills, skillSearch, editingEntry?.skillIds]);

    // Déterminer quelles spécialisations sont déjà utilisées sur la fiche
    const usedSpecializations = useMemo(() => {
        const names = new Set<string>();
        Object.values(data.specializations || {}).forEach(spes => {
            spes.forEach(s => names.add(s.trim().toLowerCase()));
        });
        Object.values(data.imposedSpecializations || {}).forEach(spes => {
            spes.forEach(s => names.add(s.name.trim().toLowerCase()));
        });
        return names;
    }, [data.specializations, data.imposedSpecializations]);

    // Filtrer et trier la bibliothèque
    const filteredLibrary = useMemo(() => {
        return library.filter(m => {
            const matchesSearch = smartIncludes(m.entry.name, searchTerm) ||
                (m.entry.description && smartIncludes(m.entry.description, searchTerm));

            const isUsed = usedSpecializations.has(m.entry.name.trim().toLowerCase());
            const matchesFilter = hideKnown ? !isUsed : true;

            return matchesSearch && matchesFilter;
        }).sort((a, b) => a.entry.name.localeCompare(b.entry.name));
    }, [library, searchTerm, hideKnown, usedSpecializations]);

    const handleOpenNew = () => {
        setError(null);
        setEditingEntry({
            id: Math.random().toString(36).substr(2, 9),
            name: '',
            skillIds: [],
            defaultMinLevel: 1,
            description: ''
        });
        setSkillSearch('');
        setIsModalOpen(true);
    };

    const handleOpenEdit = (merged: MergedEntry<LibrarySpecializationEntry>) => {
        setError(null);
        setSkillSearch('');
        // Force keep official ID to allow creating copy
        setEditingEntry({ ...merged.entry });
        setIsModalOpen(true);
    };

    const handleSave = () => {
        if (!editingEntry) return;
        if (!editingEntry.name.trim()) {
            setError("Le nom est requis.");
            return;
        }

        const duplicate = hybridSpecializations.find(m =>
            m.source === 'local' && // Check duplication only against LOCAL items
            m.entry.id !== editingEntry.id &&
            m.entry.name.trim().toLowerCase() === editingEntry.name.trim().toLowerCase()
        );

        if (duplicate) {
            setError("Une spécialisation locale portant ce nom existe déjà.");
            return;
        }

        let newLibrary;
        const localList = data.specializationLibrary || [];
        const exists = localList.some(e => e.id === editingEntry.id);

        if (exists) {
            newLibrary = localList.map(e => e.id === editingEntry.id ? editingEntry : e);
        } else {
            // New or cloned from official
            newLibrary = [...localList, editingEntry];
        }

        onUpdate({ ...data, specializationLibrary: newLibrary });
        addLog(`Spécialisation "${editingEntry.name}" enregistrée.`, 'success', 'settings');
        setIsModalOpen(false);
        setEditingEntry(null);
    };

    const [showOfficialUpdateConfirm, setShowOfficialUpdateConfirm] = useState(false);

    const handleOfficialUpdateClick = () => {
        setShowOfficialUpdateConfirm(true);
    };

    const executeOfficialUpdate = async () => {
        try {
            const res = await fetch('./data/specializations.json?t=' + Date.now());
            if (!res.ok) throw new Error("Fichier introuvable");

            const json = await res.json();
            const newSpecs = json.data as LibrarySpecializationEntry[];

            if (json.meta && json.meta.type !== 'specializations') throw new Error("Format invalide");

            // Update Rules Context
            const updatedRules = {
                ...rules!,
                libraries: {
                    ...rules!.libraries,
                    specializations: newSpecs
                }
            };
            updateRules(updatedRules);
            addLog(`Bibliothèque officielle mise à jour (${newSpecs.length} spécialisations).`, 'success', 'settings');
        } catch (e) {
            addLog("Échec de la mise à jour officielle : " + (e as Error).message, 'danger', 'settings');
        }
    };

    const executeImportFromSheet = () => {
        // Import into LOCAL
        const currentLib = JSON.parse(JSON.stringify(data.specializationLibrary || []));
        const existingNames = new Set(currentLib.map((e: any) => e.name.trim().toLowerCase()));
        let addedCount = 0;

        // Scanner les spécialisations classiques
        Object.entries(data.specializations || {}).forEach(([skillId, spes]) => {
            spes.forEach(name => {
                const norm = name.trim();
                if (norm && !existingNames.has(norm.toLowerCase())) {
                    currentLib.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name: norm,
                        skillIds: [skillId],
                        defaultMinLevel: 1,
                        description: ""
                    });
                    existingNames.add(norm.toLowerCase());
                    addedCount++;
                }
            });
        });

        // Scanner les spécialisations imposées
        Object.entries(data.imposedSpecializations || {}).forEach(([skillId, spes]) => {
            spes.forEach(s => {
                const norm = s.name.trim();
                if (norm && !existingNames.has(norm.toLowerCase())) {
                    currentLib.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name: norm,
                        skillIds: [skillId],
                        defaultMinLevel: s.minLevel,
                        description: ""
                    });
                    existingNames.add(norm.toLowerCase());
                    addedCount++;
                }
            });
        });

        if (addedCount > 0) {
            currentLib.sort((a: any, b: any) => a.name.localeCompare(b.name));
            onUpdate({ ...data, specializationLibrary: currentLib });
            addLog(`${addedCount} spécialisation(s) importée(s) depuis la fiche.`, 'success', 'settings');
        } else {
            addLog("Toutes les spécialisations de la fiche sont déjà dans la bibliothèque.", 'info', 'settings');
        }
        setShowImportConfirm(false);
    };

    const handleDeleteRequest = (merged: MergedEntry<LibrarySpecializationEntry>) => {
        if (merged.source === 'official') {
            addLog("Impossible de supprimer une spécialisation officielle.", 'info', 'settings');
            return;
        }
        setEntryToDelete(merged.entry);
    };

    const executeDelete = () => {
        if (!entryToDelete) return;
        const localList = data.specializationLibrary || [];
        onUpdate({
            ...data,
            specializationLibrary: localList.filter(e => e.id !== entryToDelete.id)
        });
        addLog(`Spécialisation "${entryToDelete.name}" supprimée.`, 'info', 'settings');
        setEntryToDelete(null);
    };

    return (
        <div className="absolute inset-0 flex flex-col bg-[#fdfbf7]">
            {/* Toolbar */}
            <div className="p-4 bg-stone-100/30 border-b border-[#bfae85]/30 flex flex-col sm:flex-row justify-between items-center gap-4 shrink-0">
                <div className="relative flex-grow max-w-md w-full flex gap-2">
                    <div className="relative flex-grow">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3b32]/50" />
                        <input
                            className="w-full pl-9 pr-3 py-1.5 text-sm border border-[#bfae85]/50 rounded-sm focus:border-amber-500 outline-none text-[#1c1917] placeholder-[#4a3b32]/40 bg-white/80"
                            placeholder="Rechercher une spécialisation..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <button
                        onClick={() => setHideKnown(!hideKnown)}
                        className={`px-2 py-1.5 rounded-sm border transition-colors flex items-center justify-center ${hideKnown ? 'bg-amber-100 text-amber-800 border-amber-300' : 'bg-white text-[#5c4d41] border-[#bfae85]/50 hover:bg-stone-50'}`}
                        title={hideKnown ? "Afficher les spécialisations acquises" : "Masquer les spécialisations acquises"}
                    >
                        {hideKnown ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                </div>
                <div className="flex gap-2 w-full sm:w-auto">
                    <button
                        onClick={handleOfficialUpdateClick}
                        className="bg-blue-50 border border-blue-200 text-blue-700 hover:bg-blue-100 px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap flex-1 sm:flex-initial justify-center"
                        title="Mettre à jour depuis le serveur officiel"
                    >
                        <RefreshCw size={14} /> Officiel
                    </button>
                    <button
                        onClick={() => setShowImportConfirm(true)}
                        className="bg-white/80 border border-[#bfae85]/50 text-[#5c4d41] hover:bg-stone-50 hover:text-[#1c1917] px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap flex-1 sm:flex-initial justify-center"
                    >
                        <Download size={14} /> Importer
                    </button>
                    <button
                        onClick={handleOpenNew}
                        className="bg-[#5c4d41] hover:bg-[#4a3b32] text-white px-3 py-1.5 rounded-sm text-xs font-bold flex items-center gap-1 transition-colors shadow-sm whitespace-nowrap flex-1 sm:flex-initial justify-center"
                    >
                        <Plus size={14} /> Créer
                    </button>
                </div>
            </div>

            {/* List */}
            <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
                {library.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic px-4 text-sm flex flex-col items-center">
                        <Award size={48} className="opacity-20 mb-2" />
                        <p>La bibliothèque de spécialisations est vide.</p>
                        <p className="text-xs mt-2 text-[#5c4d41]/80 italic">Peuplez-la manuellement ou importez l'existant.</p>
                    </div>
                ) : filteredLibrary.length === 0 ? (
                    <div className="text-center text-[#5c4d41]/60 py-10 italic">Aucun résultat.</div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {filteredLibrary.map(merged => {
                            const entry = merged.entry;
                            const isUsed = usedSpecializations.has(entry.name.trim().toLowerCase());
                            const isOfficial = merged.source === 'official';

                            return (
                                <div
                                    key={entry.id}
                                    className={`border rounded-sm p-3 transition-all bg-white/60 group flex flex-col justify-between ${isUsed
                                        ? 'border-green-300/40 bg-green-50/10'
                                        : isOfficial ? 'border-blue-300/40 bg-blue-50/5' : 'border-[#bfae85]/30 hover:border-amber-400/50 hover:shadow-sm'
                                        }`}
                                >
                                    <div>
                                        <div className="flex justify-between items-start mb-1">
                                            <div className="flex flex-col">
                                                <span className={`font-serif font-black uppercase text-xs tracking-wide ${isUsed ? 'text-green-800' : 'text-[#4a3b32]'}`}>
                                                    {entry.name}
                                                </span>
                                                {isOfficial && (
                                                    <div title="Spécialisation Officielle" className="w-fit mt-0.5">
                                                        <Globe size={11} className="text-indigo-500" />
                                                    </div>
                                                )}
                                            </div>

                                            {isUsed && (
                                                <span className="text-[9px] bg-green-100/50 text-green-800/80 px-1.5 py-0.5 rounded-sm flex items-center gap-1 font-bold border border-green-200/50 uppercase tracking-tight">
                                                    <CheckCircle2 size={10} /> Utilisée
                                                </span>
                                            )}
                                            {!isUsed && (
                                                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => handleOpenEdit(merged)} className="text-blue-500 hover:bg-blue-50 p-1 rounded"><Edit2 size={14} /></button>
                                                    {!isOfficial && (
                                                        <button onClick={() => handleDeleteRequest(merged)} className="text-red-500 hover:bg-red-50 p-1 rounded"><Trash2 size={14} /></button>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                        {entry.description && (
                                            <p className="text-[10px] text-[#5c4d41] italic line-clamp-2 mb-2 leading-tight opacity-80">{entry.description}</p>
                                        )}
                                        <div className="flex flex-wrap gap-1 mt-1">
                                            {entry.skillIds.map(sid => {
                                                const s = allSkills.find(sk => sk.id === sid);
                                                return (
                                                    <span key={sid} className="text-[9px] bg-stone-100/50 text-[#5c4d41] px-1.5 py-0.5 rounded-sm border border-[#bfae85]/20">
                                                        {s ? s.name : sid}
                                                    </span>
                                                );
                                            })}
                                        </div>
                                    </div>
                                    <div className="mt-2 text-[10px] text-[#5c4d41]/60 flex justify-between items-center border-t border-[#bfae85]/20 pt-1">
                                        <span>Seuil MJ : <span className="font-bold text-amber-700">{entry.defaultMinLevel}</span></span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* Modals */}
            {isModalOpen && editingEntry && (
                <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden flex flex-col animate-in zoom-in duration-200 border-2 border-[#bfae85]/50">
                        <div className="p-4 border-b border-[#bfae85]/50 flex justify-between items-center text-white bg-amber-700/90">
                            <h3 className="font-bold text-lg flex items-center gap-2 font-serif tracking-wide">
                                <Award size={20} />
                                {data.specializationLibrary?.some(e => e.id === editingEntry.id) ? 'Éditer Spécialisation' : 'Nouvelle Spécialisation (Copie)'}
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="hover:bg-white/20 p-1 rounded transition-colors">
                                <X size={24} />
                            </button>
                        </div>

                        <div className="p-6 bg-[#fdfbf7] flex flex-col gap-4 overflow-y-auto max-h-[70vh]">
                            <div>
                                <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Nom</label>
                                <input
                                    className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 font-black font-serif text-[#1c1917] bg-white/50 focus:border-amber-500 outline-none shadow-sm"
                                    value={editingEntry.name}
                                    onChange={(e) => setEditingEntry({ ...editingEntry, name: e.target.value })}
                                />
                            </div>

                            <div>
                                <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Compétences associées</label>
                                <div className="relative mb-2">
                                    <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-[#5c4d41]/60" />
                                    <input
                                        className="w-full pl-7 pr-2 py-1 text-[11px] border border-[#bfae85]/50 rounded-sm focus:border-amber-500 outline-none bg-white/50"
                                        placeholder="Filtrer les compétences..."
                                        value={skillSearch}
                                        onChange={(e) => setSkillSearch(e.target.value)}
                                    />
                                    {skillSearch && (
                                        <button
                                            onClick={() => setSkillSearch('')}
                                            className="absolute right-2 top-1/2 -translate-y-1/2 text-[#5c4d41]/60 hover:text-gray-600"
                                        >
                                            <X size={12} />
                                        </button>
                                    )}
                                </div>
                                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto border border-[#bfae85]/50 rounded-sm p-2 bg-white/30 custom-scrollbar">
                                    {filteredSkillsForModal.length === 0 ? (
                                        <div className="col-span-2 text-center py-2 text-[10px] text-[#5c4d41]/60 italic">Aucun résultat.</div>
                                    ) : filteredSkillsForModal.map(skill => (
                                        <label key={skill.id} className={`flex items-center gap-2 text-xs cursor-pointer hover:bg-stone-100/50 p-1 rounded transition-colors ${editingEntry.skillIds.includes(skill.id) ? 'bg-amber-100/30' : ''}`}>
                                            <input
                                                type="checkbox"
                                                checked={editingEntry.skillIds.includes(skill.id) || editingEntry.skillIds.includes(skill.name)}
                                                onChange={(e) => {
                                                    const ids = e.target.checked
                                                        ? [...editingEntry.skillIds, skill.id]
                                                        : editingEntry.skillIds.filter(id => id !== skill.id && id !== skill.name);
                                                    setEditingEntry({ ...editingEntry, skillIds: ids });
                                                }}
                                                className="rounded border-[#bfae85]/50 text-amber-600 focus:ring-amber-500"
                                            />
                                            <span className={`truncate ${editingEntry.skillIds.includes(skill.id) ? 'font-bold text-amber-900' : 'text-[#4a3b32]'}`}>{skill.name}</span>
                                        </label>
                                    ))}
                                </div>
                                {editingEntry.skillIds.length > 0 && (
                                    <div className="mt-1 text-[9px] text-[#5c4d41]/60 italic">
                                        {editingEntry.skillIds.length} compétence(s) sélectionnée(s)
                                    </div>
                                )}
                            </div>

                            <div>
                                <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Seuil minimum par défaut (MJ)</label>
                                <input
                                    type="number"
                                    min="0"
                                    max="5"
                                    className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-sm bg-white/50 focus:border-amber-500 outline-none shadow-sm"
                                    value={editingEntry.defaultMinLevel}
                                    onChange={(e) => setEditingEntry({ ...editingEntry, defaultMinLevel: parseInt(e.target.value) || 0 })}
                                />
                                <p className="text-[10px] text-[#5c4d41]/60 mt-1 italic">Ce seuil sera appliqué automatiquement lors de l'ajout en mode "Imposée".</p>
                            </div>

                            <div>
                                <label className="block text-[10px] font-bold text-[#bfae85] uppercase mb-1 tracking-widest">Description</label>
                                <textarea
                                    className="w-full border border-[#bfae85]/50 rounded-sm px-3 py-2 text-sm bg-white/50 min-h-[80px] focus:border-amber-500 outline-none resize-none shadow-sm italic text-[#4a3b32]"
                                    value={editingEntry.description || ''}
                                    onChange={(e) => setEditingEntry({ ...editingEntry, description: e.target.value })}
                                />
                            </div>

                            {error && (
                                <div className="bg-red-50 text-red-600 text-xs p-2 rounded border border-red-200 font-bold">
                                    {error}
                                </div>
                            )}
                        </div>

                        <div className="p-4 border-t border-[#bfae85]/30 bg-stone-100/30 flex justify-end gap-3">
                            <button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-[#5c4d41] hover:bg-stone-200/50 rounded-sm font-bold">Annuler</button>
                            <button onClick={handleSave} className="px-6 py-2 bg-[#5c4d41] text-white rounded-sm font-bold shadow-md hover:bg-[#4a3b32] flex items-center gap-2">
                                <Save size={16} /> Enregistrer
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <ConfirmationModal
                isOpen={showImportConfirm}
                onClose={() => setShowImportConfirm(false)}
                onConfirm={executeImportFromSheet}
                title="Importer les spécialisations ?"
                message="Scanne toutes les spécialisations (Joueur & MJ) présentes sur la fiche pour les ajouter à la bibliothèque. Les doublons seront ignorés."
                confirmLabel="Confirmer l'import"
                type="info"
            />

            <ConfirmationModal
                isOpen={!!entryToDelete}
                onClose={() => setEntryToDelete(null)}
                onConfirm={executeDelete}
                title="Supprimer ?"
                message={`Voulez-vous vraiment supprimer "${entryToDelete?.name}" de la bibliothèque ?`}
                confirmLabel="Supprimer"
                type="danger"
            />

            <ConfirmationModal
                isOpen={showOfficialUpdateConfirm}
                onClose={() => setShowOfficialUpdateConfirm(false)}
                onConfirm={executeOfficialUpdate}
                title="Mise à jour officielle"
                message="Voulez-vous vérifier et télécharger les dernières spécialisations officielles ?"
                confirmLabel="Mettre à jour"
                type="info"
            />
        </div>
    );
};

export default SpecializationLibraryView;

import React, { useState, useRef, useEffect } from 'react';
import { Search, Award, Plus } from 'lucide-react';
import { useCharacterData } from '../../context/CharacterContext';
import { LibrarySpecializationEntry } from '../../types';
import { smartIncludes } from '../../utils/stringUtils';

interface SpecializationOmnibarProps {
    value: string;
    onChange: (value: string) => void;
    onSelect?: (entry: LibrarySpecializationEntry) => void;
    onBlur?: (value: string) => void;
    placeholder?: string;
    className?: string;
    skillId?: string; // Si fourni, filtre les suggestions pour cette compétence
    variant?: 'default' | 'sheet';
    showPlaceholder?: boolean;
}

const SpecializationOmnibar: React.FC<SpecializationOmnibarProps> = ({
    value,
    onChange,
    onSelect,
    onBlur,
    placeholder = "Saisir une spécialisation...",
    className = "",
    skillId,
    variant = 'default',
    showPlaceholder = true
}) => {
    const data = useCharacterData();
    const [isOpen, setIsOpen] = useState(false);
    const [highlightedIndex, setHighlightedIndex] = useState(-1);
    const containerRef = useRef<HTMLDivElement>(null);

    const library = data.specializationLibrary || [];

    // Filtrer les suggestions
    const suggestions = library.filter(entry => {
        // Filtrage par texte
        const matchText = smartIncludes(entry.name, value);
        // Filtrage par compétence (optionnel)
        const matchSkill = !skillId || entry.skillIds.includes(skillId);

        return matchText && matchSkill && value.trim() !== "" && entry.name.toLowerCase() !== value.toLowerCase();
    }).slice(0, 5); // Limiter à 5 suggestions

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (!isOpen || suggestions.length === 0) return;

        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setHighlightedIndex(prev => (prev + 1) % suggestions.length);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setHighlightedIndex(prev => (prev - 1 + suggestions.length) % suggestions.length);
        } else if (e.key === 'Enter' && highlightedIndex >= 0) {
            e.preventDefault();
            handleSelect(suggestions[highlightedIndex]);
        } else if (e.key === 'Escape') {
            setIsOpen(false);
        }
    };

    const handleSelect = (entry: LibrarySpecializationEntry) => {
        onChange(entry.name);
        if (onSelect) onSelect(entry);
        setIsOpen(false);
        setHighlightedIndex(-1);
    };

    return (
        <div className={`relative ${className}`} ref={containerRef}>
            <div className="relative">
                <input
                    type="text"
                    value={value}
                    onChange={(e) => {
                        onChange(e.target.value);
                        setIsOpen(true);
                        setHighlightedIndex(-1);
                    }}
                    onFocus={() => setIsOpen(true)}
                    onBlur={() => {
                        if (onBlur) onBlur(value);
                    }}
                    onKeyDown={handleKeyDown}
                    placeholder={showPlaceholder ? placeholder : ""}
                    className={variant === 'sheet'
                        ? "w-full bg-transparent border-none text-[10px] h-4 px-1 focus:outline-none font-handwriting text-amber-900 placeholder-transparent"
                        : "w-full border border-[#bfae85]/50 bg-[#fefaf2] rounded-sm px-2 py-1 text-sm text-[#1c1917] font-bold focus:border-amber-600 outline-none transition-colors shadow-sm placeholder-[#bfae85]/60"
                    }
                />
                {suggestions.length > 0 && isOpen && (
                    <div className="absolute z-[100] left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-xl overflow-hidden animate-in fade-in slide-in-from-top-1 duration-100">
                        <div className="p-1 bg-amber-50 text-[10px] font-bold text-amber-700 border-b flex items-center gap-1 uppercase tracking-wider">
                            <Award size={10} /> Catalogue
                        </div>
                        {suggestions.map((entry, index) => (
                            <button
                                key={entry.id}
                                onClick={() => handleSelect(entry)}
                                onMouseEnter={() => setHighlightedIndex(index)}
                                className={`w-full text-left px-3 py-2 text-sm flex flex-col gap-0.5 transition-colors ${index === highlightedIndex ? 'bg-amber-100' : 'hover:bg-gray-50'
                                    }`}
                            >
                                <span className="font-bold text-gray-800">{entry.name}</span>
                                {entry.description && (
                                    <span className="text-[10px] text-gray-400 truncate">{entry.description}</span>
                                )}
                            </button>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default SpecializationOmnibar;

import React from 'react';
import { LibraryEntry } from '../../types';
import { Zap, Edit2, Trash2, Plus, CheckSquare, Square, Lock, Globe, Layers } from 'lucide-react';

interface TraitCardProps {
    entry: LibraryEntry;
    isEditable: boolean;
    isSelected: boolean;
    onSelect?: (entry: LibraryEntry) => void;
    onMultiSelect?: (id: string) => void;
    onEdit: (entry: LibraryEntry) => void;
    onDelete: (id: string) => void;
    showMultiSelect: boolean;
    source?: 'local' | 'official' | 'modified';
    isLocked?: boolean;
    isActive?: boolean;
}

const TraitCard: React.FC<TraitCardProps> = ({
    entry,
    isEditable,
    isSelected,
    onSelect,
    onMultiSelect,
    onEdit,
    onDelete,
    showMultiSelect,
    source = 'local',
    isLocked = false,
    isActive = true
}) => {
    if (!entry) return null;

    return (
        <div
            className={`p-2 transition-colors group cursor-pointer select-none border-b border-slate-100 last:border-0 flex items-center gap-2 ${isSelected ? 'bg-amber-50/50 hover:bg-amber-100/50' : 'hover:bg-stone-50'} ${!isActive ? 'opacity-60 grayscale' : ''}`}
            onClick={() => {
                if (showMultiSelect && onMultiSelect) {
                    onMultiSelect(entry.id);
                } else if (onSelect) {
                    onSelect(entry);
                }
            }}
        >
            {/* 1. Toggle / Type Indicator (Fixed width) */}
            <div className="w-8 flex flex-col items-center justify-center shrink-0 gap-1">
                {showMultiSelect ? (
                    <div className="text-[#8b2e2e]">
                        {isSelected ? <CheckSquare size={16} /> : <Square size={16} className="text-[#bfae85]" />}
                    </div>
                ) : (
                    <div className={`w-2.5 h-2.5 rounded-full ${entry.type === 'avantage' ? 'bg-green-600' : 'bg-[#8b2e2e]'}`} title={entry.type === 'avantage' ? 'Avantage' : 'Désavantage'} />
                )}
            </div>

            {/* 2. Status Icons (Fixed width) */}
            <div className="w-16 flex items-center gap-1 shrink-0">
                {entry.isVariable && <div title="Trait à variantes"><Layers size={14} className="text-blue-500" /></div>}
                {source === 'official' && <div title="Trait Officiel"><Globe size={14} className="text-indigo-500" /></div>}
                {entry.effects && entry.effects.length > 0 && <div title="Effets mécaniques"><Zap size={14} className="text-amber-500 fill-amber-500" /></div>}
                {isLocked && <div title="Trait utilisé"><Lock size={14} className="text-amber-600" /></div>}
            </div>

            {/* 3. Content (Flexible) */}
            <div className="flex-grow overflow-hidden pr-2">
                <div className="flex justify-between items-baseline gap-2">
                    <span className={`font-bold text-sm truncate ${isSelected ? 'text-amber-900' : 'text-[#4a3b32]'} ${!isActive ? 'line-through text-slate-500' : ''}`} title={entry.name}>
                        {entry.name}
                    </span>
                    <span className="text-[10px] font-mono font-bold text-[#5c4d41] bg-[#bfae85]/20 px-1 rounded-sm border border-[#bfae85]/10 shrink-0">
                        {entry.cost} pts
                    </span>
                </div>
                {entry.description && (
                    <div className="text-[10px] text-[#5c4d41]/70 italic truncate" title={entry.description}>
                        {entry.description}
                    </div>
                )}
                {/* Tags displayed on hover or if space allows? Let's keep them compact */}
                {entry.tags && entry.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-0.5">
                        {entry.tags.slice(0, 3).map(tag => (
                            <span key={tag} className="text-[8px] bg-stone-100 text-[#5c4d41]/60 px-1 rounded-sm border border-stone-200">
                                #{tag}
                            </span>
                        ))}
                    </div>
                )}
            </div>

            {/* 4. Actions (Fixed width) */}
            <div className="w-16 flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                {isEditable && (
                    <>
                        <button
                            onClick={(e) => { e.stopPropagation(); onEdit(entry); }}
                            className="p-1 text-blue-600 hover:bg-blue-50 rounded"
                            title="Éditer"
                        >
                            <Edit2 size={14} />
                        </button>
                        <button
                            onClick={(e) => { e.stopPropagation(); onDelete(entry.id); }}
                            disabled={isLocked}
                            className={`p-1 rounded ${isLocked ? 'text-stone-300' : 'text-red-600 hover:bg-red-50'}`}
                            title={isLocked ? "Action impossible : trait utilisé" : "Supprimer"}
                        >
                            <Trash2 size={14} />
                        </button>
                    </>
                )}
                {onSelect && !showMultiSelect && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onSelect(entry); }}
                        className="p-1 text-green-700 hover:bg-green-50 rounded border border-green-200 shadow-sm bg-white"
                        title="Ajouter à la fiche"
                    >
                        <Plus size={14} />
                    </button>
                )}
            </div>
        </div>
    );
};

export default TraitCard;

import React from 'react';
import { TraitEffect } from '../../types';
import { Zap, X, Star, GraduationCap, Dumbbell, ChevronDown } from 'lucide-react';

interface TraitEffectEditorProps {
    effects: TraitEffect[];
    allSkills: { id: string, name: string }[];
    allAttributes: { id: string, name: string }[];
    onAdd: () => void;
    onUpdate: <K extends keyof TraitEffect>(id: string, field: K, value: TraitEffect[K]) => void;
    onRemove: (id: string) => void;
}

const TraitEffectEditor: React.FC<TraitEffectEditorProps> = ({
    effects,
    allSkills,
    allAttributes,
    onAdd,
    onUpdate,
    onRemove
}) => {
    return (
        <div className="p-4 bg-stone-100/5 backdrop-blur-sm">
            <div className="flex justify-between items-center mb-4">
                <h5 className="font-serif font-black uppercase text-[10px] text-[#bfae85] tracking-widest flex items-center gap-2">
                    <Zap size={14} className="text-amber-600/60" />
                    Effets Mécaniques
                </h5>
                <button
                    onClick={onAdd}
                    className="text-[10px] bg-white/50 border border-[#bfae85]/30 hover:bg-amber-50 text-[#5c4d41] px-3 py-1 rounded-sm font-bold transition-colors shadow-sm"
                >
                    + Ajouter
                </button>
            </div>

            <div className="space-y-3">
                {(!effects || effects.length === 0) && (
                    <div className="text-center text-amber-800/40 text-xs italic py-2">
                        Aucun effet configuré. Ce trait sera purement narratif.
                    </div>
                )}
                {(effects || []).map(effect => {
                    // Configuration visuelle par type
                    let typeIcon = <Star size={16} />;
                    let themeColor = 'text-amber-700';
                    let borderColor = 'border-amber-200';
                    let bgColor = 'bg-white';

                    if (effect.type === 'xp_bonus') {
                        typeIcon = <Star size={14} />;
                        themeColor = 'text-amber-800';
                        borderColor = 'border-amber-400/30';
                        bgColor = 'bg-amber-50/40';
                    } else if (effect.type === 'free_skill_rank') {
                        typeIcon = <GraduationCap size={14} />;
                        themeColor = 'text-blue-800';
                        borderColor = 'border-blue-400/30';
                        bgColor = 'bg-blue-50/40';
                    } else if (effect.type === 'attribute_bonus') {
                        typeIcon = <Dumbbell size={14} />;
                        themeColor = 'text-[#8b2e2e]';
                        borderColor = 'border-[#8b2e2e]/30';
                        bgColor = 'bg-[#8b2e2e]/5';
                    }

                    return (
                        <div key={effect.id} className={`rounded-lg border ${borderColor} ${bgColor} shadow-sm overflow-hidden group`}>

                            {/* Header Row: Type Selector & Delete */}
                            <div className="flex items-center justify-between p-2 border-b border-black/5 bg-white/60">
                                <div className="flex items-center gap-2 flex-grow relative">
                                    <div className={themeColor}>{typeIcon}</div>

                                    {/* Styled Dropdown Container */}
                                    <div className="relative flex-grow">
                                        <select
                                            className={`appearance-none bg-white border border-gray-300 font-bold text-xs text-gray-900 w-full focus:outline-none focus:ring-1 focus:ring-blue-300 cursor-pointer pr-4 py-1 pl-2 rounded shadow-sm`}
                                            value={effect.type}
                                            onChange={(e) => onUpdate(effect.id, 'type', e.target.value as any)}
                                        >
                                            <option value="attribute_bonus" className="text-gray-900 bg-white">Bonus Attribut</option>
                                            <option value="xp_bonus" className="text-gray-900 bg-white">Bonus XP</option>
                                            <option value="free_skill_rank" className="text-gray-900 bg-white">Rang de Compétence Gratuit</option>
                                        </select>
                                        <ChevronDown size={12} className={`absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none ${themeColor} opacity-50`} />
                                    </div>
                                </div>
                                <button onClick={() => onRemove(effect.id)} className="text-gray-400 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-colors ml-2">
                                    <X size={14} />
                                </button>
                            </div>

                            {/* Content Row: Specific Inputs */}
                            <div className="p-3">
                                {effect.type === 'xp_bonus' ? (
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-bold text-[#5c4d41] uppercase tracking-wide">Montant XP :</span>
                                        <input
                                            type="number"
