import { Node, mergeAttributes } from '@tiptap/core';
import type { CommandProps, RawCommands } from '@tiptap/core';
import { ReactNodeViewRenderer } from '@tiptap/react';
import { TextSelection } from 'prosemirror-state';
import ChapterHeaderView from '../components/campaign/book/ChapterHeaderView';

declare module '@tiptap/core' {
    interface Commands<ReturnType> {
        chapterHeading: {
            setChapter: () => ReturnType;
            appendChapter: () => ReturnType;
        };
    }
}

export const ChapterHeading = Node.create({
    name: 'chapterHeading',

    group: 'block',

    content: 'inline*',

    defining: true,

    addAttributes() {
        return {
            date: {
                default: '',
            },
            level: {
                default: 1,
            },
        };
    },

    parseHTML() {
        return [
            {
                tag: 'div[data-type="chapter-heading"]',
            },
        ];
    },

    renderHTML({ HTMLAttributes }) {
        return ['div', mergeAttributes(HTMLAttributes, { 'data-type': 'chapter-heading' }), 0];
    },

    addCommands() {
        return {
            setChapter:
                () =>
                    ({ chain, state }: CommandProps) => {
                        const { selection } = state;
                        const { empty } = selection;

                        if (empty) {
                            // If cursor is in the middle of a paragraph, split it first!
                            return chain()
                                .splitBlock()
                                .insertContent({
                                    type: this.name,
                                    attrs: { date: new Date().toISOString().split('T')[0] },
                                    content: [{ type: 'text', text: 'Nouveau Chapitre' }],
                                })
                                .focus()
                                .run();
                        }

                        // If text is selected, convert it to a chapter
                        return chain()
                            .insertContent({
                                type: this.name,
                                attrs: { date: new Date().toISOString().split('T')[0] },
                            })
                            .focus()
                            .run();
                    },

            appendChapter:
                () =>
                    ({ chain, state }: CommandProps) => {
                        const endPos = state.doc.content.size;
                        return chain()
                            .focus() // Focus first to ensure editor is active
                            .insertContentAt(endPos, [
                                {
                                    type: this.name,
                                    attrs: { date: new Date().toISOString().split('T')[0] },
                                    content: [{ type: 'text', text: 'Nouveau Chapitre' }],
                                },
                                {
                                    type: 'paragraph',
                                }
                            ])
                            .focus(endPos + 1) // Hard focus on the new node
                            .run();
                    },
        } as RawCommands;
    },

    addNodeView() {
        return ReactNodeViewRenderer(ChapterHeaderView as any);
    },
});

import { useState, useMemo } from 'react';
import { RulesData } from '../../types/rules';
import { LibrarySkillEntry } from '../../types';
import { smartIncludes } from '../../utils/stringUtils';
import { disambiguateCategories } from '../../utils/categoryUtils';
import { CATEGORY_HELP } from '../../data/constants';
import { publishFileToGitHub } from '../../services/githubService';

/**
 * Hook to manage the state and logic for AdminSkillLibrary.
 * Extracts CRUD, filtering, and publishing logic from the component.
 */
export const useAdminSkillLibrary = (rules: RulesData, onUpdate: (newRules: RulesData) => void, globalUsage: Record<string, number> = {}) => {
    const list = rules.libraries?.skills || [];

    const [searchTerm, setSearchTerm] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingSkill, setEditingSkill] = useState<LibrarySkillEntry | null>(null);
    const [variantDraft, setVariantDraft] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [showCategoryHelp, setShowCategoryHelp] = useState(false);

    // Advanced Filters
    const [activeFilter, setActiveFilter] = useState<boolean | null>(null);
    const [sourceFilter, setSourceFilter] = useState<boolean | null>(null);
    const [typeFilter, setTypeFilter] = useState<boolean | null>(null);
    const [usageFilter, setUsageFilter] = useState<boolean | null>(null);

    const [showPublishConfirm, setShowPublishConfirm] = useState(false);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);
    const [publishResult, setPublishResult] = useState<{ success: boolean; message: string } | null>(null);
    const [showConfigAlert, setShowConfigAlert] = useState(false);

    const placedSkillNames = useMemo(() => {
        const names = new Set<string>();
        if (rules.definitions.skills) {
            Object.values(rules.definitions.skills).forEach((skillsArray) => {
                (skillsArray as string[]).forEach(name => {
                    if (name.trim()) names.add(name.trim().toLowerCase());
                });
            });
        }
        return names;
    }, [rules.definitions.skills]);

    const filteredList = useMemo(() => {
        return list
            .filter(s => {
                const matchesSearch = smartIncludes(s.name, searchTerm) || (s.description && smartIncludes(s.description, searchTerm));
                if (!matchesSearch) return false;

                if (activeFilter !== null) {
                    const isActive = s.isActive !== false;
                    if (activeFilter !== isActive) return false;
                }

                if (sourceFilter !== null) {
                    const isGlobal = s.isGlobal === true;
                    if (sourceFilter !== isGlobal) return false;
                }

                if (typeFilter !== null) {
                    const isVariable = s.isVariable === true;
                    if (typeFilter !== isVariable) return false;
                }

                if (usageFilter !== null) {
                    const isPlaced = placedSkillNames.has(s.name.trim().toLowerCase());
                    if (usageFilter !== isPlaced) return false;
                }

                return true;
            })
            .sort((a, b) => a.name.localeCompare(b.name));
    }, [list, searchTerm, activeFilter, sourceFilter, typeFilter, usageFilter, placedSkillNames]);

    const availableCategories = useMemo(() => {
        let rawCategories = [...CATEGORY_HELP];
        if (rules.definitions.skillCategories && rules.definitions.skillCategories.length > 0) {
            rawCategories = rules.definitions.skillCategories.map(cat => ({
                code: cat.id,
                label: cat.label,
                loc: cat.description || ""
            }));
        }
        return disambiguateCategories(rawCategories);
    }, [rules.definitions.skillCategories]);

    const getCategoryLabel = (code: string) => {
        return availableCategories.find(c => c.code === code)?.label || code;
    };

    const handleOpenNew = () => {
        setError(null);
        setEditingSkill({
            id: crypto.randomUUID(),
            name: '',
            description: '',
            isVariable: false
        });
        setVariantDraft('');
        setIsModalOpen(true);
    };

    const handleOpenEdit = (skill: LibrarySkillEntry) => {
        setError(null);
        setEditingSkill({ ...skill });
        setVariantDraft(skill.variants?.join(', ') || '');
        setIsModalOpen(true);
    };

    const handleDelete = (id: string) => {
        setShowDeleteConfirm(id);
    };

    const confirmDelete = () => {
        if (!showDeleteConfirm) return;
        onUpdate({
            ...rules,
            libraries: { ...rules.libraries, skills: list.filter(s => s.id !== showDeleteConfirm) }
        });
        setShowDeleteConfirm(null);
    };

    const handleSave = () => {
        if (!editingSkill) return;
        if (!editingSkill.name.trim()) { setError("Le nom est requis."); return; }

        const duplicate = list.find(s => s.id !== editingSkill.id && s.name.trim().toLowerCase() === editingSkill.name.trim().toLowerCase());
        if (duplicate) { setError("Une compétence portant ce nom existe déjà."); return; }

        const cleanedVariants = variantDraft
            .split(',')
            .map(v => v.trim())
            .filter(v => v !== '');

        const skillToSave = { ...editingSkill, variants: cleanedVariants };

        const newList = list.some(s => s.id === skillToSave.id)
            ? list.map(s => s.id === skillToSave.id ? skillToSave : s)
            : [...list, skillToSave];

        newList.sort((a, b) => a.name.localeCompare(b.name));

        onUpdate({
            ...rules,
            libraries: { ...rules.libraries, skills: newList }
        });
        setIsModalOpen(false);
        setEditingSkill(null);
    };

    const toggleSkillActive = (skill: LibrarySkillEntry) => {
        const newList = list.map(s => s.id === skill.id ? { ...s, isActive: !s.isActive } : s);
        onUpdate({ ...rules, libraries: { ...rules.libraries, skills: newList } });
    };

    const handleBulkSelect = (active: boolean) => {
        const visibleIds = new Set(filteredList.map(s => s.id));
        const newList = list.map(skill =>
            visibleIds.has(skill.id) ? { ...skill, isActive: active } : skill
        );
        onUpdate({
            ...rules,
            libraries: { ...rules.libraries, skills: newList }
        });
    };

    const handlePublishClick = () => {
        const token = localStorage.getItem('GITHUB_TOKEN');
        const owner = localStorage.getItem('GITHUB_OWNER');
        const repo = localStorage.getItem('GITHUB_REPO');

        if (!token || !owner || !repo) {
            setShowConfigAlert(true);
            return;
        }

        setShowPublishConfirm(true);
    };

    const executePublish = async () => {
        const token = localStorage.getItem('GITHUB_TOKEN') || '';
        const owner = localStorage.getItem('GITHUB_OWNER') || '';
        const repo = localStorage.getItem('GITHUB_REPO') || '';

        try {
            const content = JSON.stringify({
                meta: {
                    version: rules.version,
                    date: new Date().toISOString(),
                    type: 'skills'
                },
                data: list
            }, null, 2);

            const result = await publishFileToGitHub(
                'public/data/skills.json',
                content,
                `update(skills): Mise à jour bibliothèque compétences v${rules.version}`,
                { token, owner, repo, branch: 'main' }
            );

            if (result.success) {
                setPublishResult({ success: true, message: "Bibliothèque de compétences publiée avec succès !" });
            } else {
                setPublishResult({ success: false, message: "Erreur lors de la publication : " + result.message });
            }
        } catch (e) {
            setPublishResult({ success: false, message: "Erreur inattendue : " + (e as Error).message });
        }
    };

    return {
        list,
        searchTerm, setSearchTerm,
        isModalOpen, setIsModalOpen,
        editingSkill, setEditingSkill,
        variantDraft, setVariantDraft,
        error, setError,
        showCategoryHelp, setShowCategoryHelp,
        activeFilter, setActiveFilter,
        sourceFilter, setSourceFilter,
        typeFilter, setTypeFilter,
        usageFilter, setUsageFilter,
        showPublishConfirm, setShowPublishConfirm,
        showDeleteConfirm, setShowDeleteConfirm,
        publishResult, setPublishResult,
        showConfigAlert, setShowConfigAlert,
        placedSkillNames,
        filteredList,
        availableCategories,
        getCategoryLabel,
        handleOpenNew,
        handleOpenEdit,
        handleDelete,
        toggleSkillActive,
        confirmDelete,
        handleSave,
        handleBulkSelect,
        handlePublishClick,
        executePublish
    };
};

import { useState, useEffect, useCallback } from 'react';
import { CharacterSheetData } from '../../types';
import { RulesData } from '../../types/rules';
import { CampaignService } from '../../services/CampaignService';
import { ErrorService } from '../../services/ErrorService';
import { loadRules } from '../../services/RulesLoader';
import { logger } from '../../utils/logger';
import { INITIAL_DATA } from '../../data/initialState';

export const useRulesSync = (
    data: CharacterSheetData,
    rules: RulesData | null,
    setData: (newData: CharacterSheetData | ((prev: CharacterSheetData) => CharacterSheetData)) => void,
    updateRules: (rules: RulesData) => void,
    addLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void
) => {
    const [isSourceSelected, setIsSourceSelected] = useState<boolean>(() => {
        return sessionStorage.getItem('rpg-source-selected') === 'true';
    });
    const [showConflict, setShowConflict] = useState(false);
    const [pendingRules, setPendingRules] = useState<{ rules: RulesData, id: string, name: string } | null>(null);

    // Initial Source Selection Helper
    const handleSourceSelect = useCallback(async (sourceType: 'online' | 'offline', selectedRules?: RulesData, settingId?: string, settingName?: string) => {
        setIsSourceSelected(true);
        sessionStorage.setItem('rpg-source-selected', 'true');

        if (sourceType === 'online' && selectedRules && settingId) {
            const hasCharacter = data.header?.name?.trim() !== '';
            const isDifferentCampaign = data.syncInfo?.settingId !== settingId;

            if (hasCharacter && isDifferentCampaign) {
                setPendingRules({ rules: selectedRules, id: settingId, name: settingName || 'Nouvelle Campagne' });
                setShowConflict(true);
            } else {
                updateRules({
                    ...selectedRules,
                    settingId,
                    settingName: settingName || (selectedRules.settingName as string)
                });
            }
        } else {
            const fallback = await loadRules();
            if (fallback) updateRules(fallback);
            else alert("Impossible de charger les règles locales.");
        }
    }, [data, updateRules]);

    // Restore Rules on Refresh if linked to campaign
    useEffect(() => {
        const syncInfo = data?.syncInfo;
        if (!syncInfo?.settingId || !rules || isSourceSelected === false) return;

        if (rules?.settingId !== syncInfo.settingId) {
            logger.log(`[useRulesSync] Rules Mismatch Detected. Restoring ${syncInfo.settingId}...`);
            CampaignService.loadSetting(syncInfo.settingId).then(restoredRules => {
                if (restoredRules) {
                    updateRules({
                        ...restoredRules,
                        settingId: syncInfo.settingId as string,
                        settingName: syncInfo.settingName || 'Inconnue'
                    });
                    addLog(`Règles de la campagne "${syncInfo.settingName}" restaurées.`, 'info', 'settings');
                }
            }).catch(err => logger.error("[useRulesSync] Failed to restore rules", err));
        }
    }, [data.syncInfo, rules?.settingId, isSourceSelected, updateRules, addLog]);

    const handleConfirmReset = useCallback(() => {
        if (!pendingRules) return;
        setData(JSON.parse(JSON.stringify(INITIAL_DATA)));
        updateRules({ ...pendingRules.rules, settingId: pendingRules.id, settingName: pendingRules.name });
        setShowConflict(false);
        setPendingRules(null);
        addLog(`Nouvelle campagne chargée : ${pendingRules.name}. Fiche réinitialisée.`, 'info', 'settings');
    }, [pendingRules, setData, updateRules, addLog]);

    return {
        isSourceSelected, setIsSourceSelected,
        showConflict, setShowConflict,
        pendingRules, setPendingRules,
        handleSourceSelect,
        handleConfirmReset
    };
};

import { useState, useMemo } from 'react';
import { LibrarySkillEntry, CharacterSheetData } from '../../types';
import { RulesData } from '../../types/rules';
import { mergeLibraries, MergedEntry } from '../../utils/libraryMerger';
import { smartIncludes } from '../../utils/stringUtils';

export const useSkillLibrary = (
    data: CharacterSheetData,
    rules: RulesData | null,
    onUpdate: (newData: CharacterSheetData) => void,
    addLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void
) => {
    const [skillSearch, setSkillSearch] = useState('');
    const [hideKnownSkills, setHideKnownSkills] = useState(true);
    const [isSkillModalOpen, setIsSkillModalOpen] = useState(false);
    const [editingSkill, setEditingSkill] = useState<LibrarySkillEntry | null>(null);
    const [skillError, setSkillError] = useState<string | null>(null);
    const [showRenameConfirm, setShowRenameConfirm] = useState<{ oldName: string, newSkill: LibrarySkillEntry } | null>(null);
    const [showImportConfirm, setShowImportConfirm] = useState(false);
    const [skillToDelete, setSkillToDelete] = useState<LibrarySkillEntry | null>(null);

    const hybridSkills = useMemo(() => {
        const local = data.skillLibrary || [];
        const official = rules?.libraries?.skills || [];
        return mergeLibraries(local, official);
    }, [data.skillLibrary, rules]);

    const usedSkillNames = useMemo(() => {
        const names = new Set<string>();
        if (data.skills) {
            Object.keys(data.skills).forEach(key => {
                const list = data.skills[key] || [];
                list.forEach((s: any) => {
                    if (s.name && s.name.trim() !== '') {
                        names.add(s.name.trim().toLowerCase());
                    }
                });
            });
        }
        return names;
    }, [data.skills]);

    const filteredSkills = useMemo(() => {
        return hybridSkills.filter(m => {
            const matchesSearch = smartIncludes(m.entry.name, skillSearch) ||
                smartIncludes(m.entry.description || '', skillSearch);
            const isKnown = usedSkillNames.has(m.entry.name.trim().toLowerCase());
            const matchesFilter = hideKnownSkills ? !isKnown : true;
            return matchesSearch && matchesFilter;
        }).sort((a, b) => a.entry.name.localeCompare(b.entry.name));
    }, [hybridSkills, skillSearch, hideKnownSkills, usedSkillNames]);

    const handleOpenNewSkill = () => {
        setSkillError(null);
        setEditingSkill({
            id: Math.random().toString(36).substr(2, 9),
            name: '',
            description: ''
        });
        setIsSkillModalOpen(true);
    };

    const handleOpenEditSkill = (merged: MergedEntry<LibrarySkillEntry>) => {
        setSkillError(null);
        setEditingSkill({ ...merged.entry });
        setIsSkillModalOpen(true);
    };

    const finalizeSaveSkill = (skillToSave: LibrarySkillEntry, renameOnSheet: boolean = false) => {
        const localList = data.skillLibrary || [];
        const exists = localList.some(s => s.id === skillToSave.id);

        let newLibrary;
        if (exists) {
            newLibrary = localList.map(s => s.id === skillToSave.id ? skillToSave : s);
        } else {
            newLibrary = [...localList, skillToSave];
        }

        const newData = { ...data, skillLibrary: newLibrary };

        if (renameOnSheet && showRenameConfirm) {
            const oldName = showRenameConfirm.oldName.trim().toLowerCase();
            const newName = skillToSave.name.trim();

            const updatedSkills = { ...data.skills };
            Object.keys(updatedSkills).forEach(cat => {
                if (Array.isArray(updatedSkills[cat])) {
                    updatedSkills[cat] = updatedSkills[cat].map((s: any) =>
                        (s.name && s.name.trim().toLowerCase() === oldName)
                            ? { ...s, name: newName }
                            : s
                    );
                }
            });
            newData.skills = updatedSkills;
        }

        onUpdate(newData);
        addLog(`Compétence "${skillToSave.name}" enregistrée dans la réserve.`, 'success', 'settings');
        setIsSkillModalOpen(false);
        setEditingSkill(null);
        setShowRenameConfirm(null);
    };

    const handleSaveSkill = (skillToSave: LibrarySkillEntry) => {
        if (!skillToSave.name.trim()) {
            setSkillError("Le nom de la compétence est requis.");
            return;
        }

        const duplicate = hybridSkills.find(m =>
            m.source === 'local' &&
            m.entry.id !== skillToSave.id &&
            m.entry.name.trim().toLowerCase() === skillToSave.name.trim().toLowerCase()
        );

        if (duplicate) {
            setSkillError("Une compétence portant ce nom existe déjà.");
            return;
        }

        const existingMerged = hybridSkills.find(m => m.entry.id === skillToSave.id);
        const existing = existingMerged ? existingMerged.entry : null;
        const nameChanged = existing && existing.name.trim().toLowerCase() !== skillToSave.name.trim().toLowerCase();
        const isUsed = existing && usedSkillNames.has(existing.name.trim().toLowerCase());

        if (nameChanged && isUsed) {
            setShowRenameConfirm({ oldName: existing.name, newSkill: skillToSave });
            setIsSkillModalOpen(false);
            return;
        }

        const cleanedSkill = {
            ...skillToSave,
            variants: skillToSave.variants ? skillToSave.variants.map(v => v.trim()).filter(v => v !== '') : []
        };

        finalizeSaveSkill(cleanedSkill);
    };

    const handleDeleteRequest = (merged: MergedEntry<LibrarySkillEntry>) => {
        if (merged.source === 'official') {
            addLog("Impossible de supprimer une compétence officielle.", "info", "settings");
            return;
        }
        setSkillToDelete(merged.entry);
    };

    const executeDeleteSkill = () => {
        if (!skillToDelete) return;
        const localList = data.skillLibrary || [];
        onUpdate({ ...data, skillLibrary: localList.filter(s => s.id !== skillToDelete.id) });
        addLog(`Compétence "${skillToDelete.name}" supprimée de la réserve.`, 'info', 'settings');
        setSkillToDelete(null);
    };

    const executeImportFromSheet = () => {
        const currentLib = JSON.parse(JSON.stringify(data.skillLibrary || []));
        const existingNames = new Set(currentLib.map((s: any) => s.name.trim().toLowerCase()));
        let addedCount = 0;

        Object.keys(data.skills).forEach(key => {
            if (key === 'arrieres_plans') return;
            const sheetSkills = data.skills[key] || [];
            sheetSkills.forEach((skill: any) => {
                const normalized = skill.name ? skill.name.trim() : "";
                if (normalized && !existingNames.has(normalized.toLowerCase())) {
                    currentLib.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name: skill.name,
                        description: "",
                        defaultCategory: key
                    });
                    existingNames.add(normalized.toLowerCase());
                    addedCount++;
                }
            });
        });

        if (addedCount > 0) {
            currentLib.sort((a: any, b: any) => a.name.localeCompare(b.name));
            onUpdate({ ...data, skillLibrary: currentLib });
            addLog(`${addedCount} compétence(s) importée(s) depuis la fiche.`, 'success', 'settings');
        } else {
            addLog("Toutes les compétences de la fiche sont déjà dans la réserve.", 'info', 'settings');
        }
        setShowImportConfirm(false);
    };

    return {
        skillSearch, setSkillSearch,
        hideKnownSkills, setHideKnownSkills,
        isSkillModalOpen, setIsSkillModalOpen,
        editingSkill, setEditingSkill,
        skillError, setSkillError,
        showRenameConfirm, setShowRenameConfirm,
        showImportConfirm, setShowImportConfirm,
        skillToDelete, setSkillToDelete,
        hybridSkills,
        usedSkillNames,
        filteredSkills,
        handleOpenNewSkill,
        handleOpenEditSkill,
        handleSaveSkill,
        finalizeSaveSkill,
        handleDeleteRequest,
        executeDeleteSkill,
        executeImportFromSheet
    };
};

import { useState, useEffect, useCallback } from 'react';
import { CharacterSheetData } from '../../types';
import { INITIAL_DATA } from '../../data/initialState';
import { applyRulesToState } from '../../utils/rulesAdapter';
import { RulesData } from '../../types/rules';

export const useSettingsManager = (
    initialData: CharacterSheetData,
    rules: RulesData | null,
    isOnlineMode: boolean,
    expertMode: boolean,
    onUpdate: (newData: CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void,
    onDirtyChange?: (isDirty: boolean) => void
) => {
    const [localData, setLocalData] = useState<CharacterSheetData>(initialData);
    const [activeTab, setActiveTab] = useState<'general' | 'attributes' | 'skills' | 'specializations' | 'creation' | 'library' | 'cloud' | 'suggestions'>('library');
    const [isDirty, setIsDirty] = useState(false);
    const [showResetConfirm, setShowResetConfirm] = useState(false);
    const [showExpertWarning, setShowExpertWarning] = useState(false);

    // Helper to compare data excluding volatile/computed fields
    const getComparableData = useCallback((d: CharacterSheetData) => {
        const { appLogs, xpLogs, experience, ...rest } = d;
        return rest;
    }, []);

    // Effect to detect unsaved changes
    useEffect(() => {
        const dirty = JSON.stringify(getComparableData(localData)) !== JSON.stringify(getComparableData(initialData));
        setIsDirty(dirty);
        if (onDirtyChange) {
            onDirtyChange(dirty);
        }
    }, [localData, initialData, onDirtyChange, getComparableData]);

    // Force Tab to Library if entering Online Mode without Expert Mode
    useEffect(() => {
        const advancedTabs = ['attributes', 'skills', 'specializations', 'creation'];
        if (isOnlineMode && !expertMode && advancedTabs.includes(activeTab)) {
            setActiveTab('library');
        }
    }, [isOnlineMode, expertMode, activeTab]);

    const handleSave = useCallback(() => {
        onUpdate(localData);
        onAddLog('Modifications de la structure sauvegardées', 'success', 'settings');
    }, [localData, onUpdate, onAddLog]);

    const handleLocalUpdate = useCallback((newData: CharacterSheetData) => {
        setLocalData(newData);
    }, []);

    const performReset = useCallback(() => {
        const base = JSON.parse(JSON.stringify(INITIAL_DATA));
        const newState = rules ? applyRulesToState(base, rules) : base;

        setLocalData(newState);
        onUpdate(newState);
        setShowResetConfirm(false);

        const logMsg = rules
            ? `Réinitialisation complète (Règles chargées : v${rules.version})`
            : "Réinitialisation complète des données (Règles par défaut)";
        onAddLog(logMsg, 'danger', 'settings');
    }, [rules, onUpdate, onAddLog]);

    const toggleAutoSync = useCallback((enabled: boolean) => {
        if (!localData.syncInfo) return;
        handleLocalUpdate({
            ...localData,
            syncInfo: {
                ...localData.syncInfo,
                isAutoSyncEnabled: enabled
            }
        });
    }, [localData, handleLocalUpdate]);

    return {
        localData,
        activeTab,
        setActiveTab,
        isDirty,
        showResetConfirm,
        setShowResetConfirm,
        showExpertWarning,
        setShowExpertWarning,
        handleSave,
        handleLocalUpdate,
        performReset,
        toggleAutoSync
    };
};

import { useState, useEffect, useCallback } from 'react';
import { CharacterSheetData, LibraryEntry } from '../../types';
import { RulesData } from '../../types/rules';
import { normalizeString } from '../../utils/stringUtils';

export const useTraitEditor = (
    data: CharacterSheetData,
    rules: RulesData | null,
    onChange: (newData: CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both', detail?: string) => void
) => {
    const [editingSlot, setEditingSlot] = useState<{ type: 'avantages' | 'desavantages', index: number } | null>(null);
    const [showLibraryInEditor, setShowLibraryInEditor] = useState(false);
    const [multiSelectTarget, setMultiSelectTarget] = useState<'avantages' | 'desavantages' | null>(null);

    const [editorName, setEditorName] = useState('');
    const [editorValue, setEditorValue] = useState('');
    const [editorTag, setEditorTag] = useState('');
    const [editorVariant, setEditorVariant] = useState('');
    const [editorVariants, setEditorVariants] = useState<string[]>([]);
    const [editorDescription, setEditorDescription] = useState('');
    const [editorDefinitionId, setEditorDefinitionId] = useState<string | undefined>(undefined);
    const [editorIsVariable, setEditorIsVariable] = useState(false);

    useEffect(() => {
        if (editingSlot) {
            const item = data.page2[editingSlot.type][editingSlot.index];
            setEditorName(item.name);
            setEditorValue(item.value);
            setEditorDescription(item.description || '');
            setEditorTag(item.tag || '');
            setEditorVariant(item.variant || '');

            let defId = item.definitionId;
            let variants: string[] = [];

            const libEntry = rules?.libraries?.traits?.find(t =>
                (defId && t.id === defId) ||
                normalizeString(t.name) === normalizeString(item.name)
            );

            if (libEntry) {
                defId = libEntry.id;
                variants = libEntry.variants || [];
                setEditorIsVariable(libEntry.isVariable || false);
            } else {
                setEditorIsVariable(false);
            }

            setEditorDefinitionId(defId);
            setEditorVariants(variants);
        }
    }, [editingSlot, data.page2, rules?.libraries?.traits]);

    const openEditor = (type: 'avantages' | 'desavantages', index: number) => {
        setEditingSlot({ type, index });
    };

    const closeEditor = () => {
        setEditingSlot(null);
        setShowLibraryInEditor(false);
    };

    const saveTraitFromEditor = () => {
        if (!editingSlot) return;
        const newList = [...data.page2[editingSlot.type]];
        newList[editingSlot.index] = {
            name: editorName,
            value: editorValue,
            description: editorDescription,
            tag: editorTag,
            variant: editorVariant,
            definitionId: editorDefinitionId
        };
        onChange({ ...data, page2: { ...data.page2, [editingSlot.type]: newList } });
        onAddLog(`Modification ${editingSlot.type === 'avantages' ? 'Avantage' : 'Désavantage'}`, 'info', 'sheet');
        closeEditor();
    };

    const removeTrait = (type: 'avantages' | 'desavantages', index: number) => {
        const list = [...data.page2[type]];
        list[index] = { name: '', value: '', variant: '', description: '', tag: '', definitionId: undefined };
        onChange({ ...data, page2: { ...data.page2, [type]: list } });
        onAddLog(`Suppression ${type === 'avantages' ? 'Avantage' : 'Désavantage'}`, 'info', 'sheet');
    };

    const handleMultiAdd = (instances: { entry: LibraryEntry; variant?: string }[]) => {
        if (!multiSelectTarget) return;
        const currentList = [...data.page2[multiSelectTarget]];
        let addedCount = 0;
        let listIndex = 0;
        instances.forEach(instance => {
            const entry = instance.entry;
            while (listIndex < currentList.length && currentList[listIndex].name.trim() !== '') { listIndex++; }
            if (listIndex < currentList.length) {
                currentList[listIndex] = {
                    name: entry.name,
                    value: entry.cost,
                    description: entry.description,
                    tag: entry.tags?.[0] || '',
                    variant: instance.variant || '',
                    definitionId: entry.id
                };
                addedCount++;
            }
        });
        if (addedCount > 0) {
            onChange({ ...data, page2: { ...data.page2, [multiSelectTarget]: currentList } });
            onAddLog(`Ajout de ${addedCount} traits.`, 'success', 'sheet');
        }
        setMultiSelectTarget(null);
    };

    const clearEditor = () => {
        setEditorName('');
        setEditorValue('');
        setEditorDescription('');
        setEditorTag('');
        setEditorVariant('');
        setEditorVariants([]);
        setEditorIsVariable(false);
    };

    return {
        editingSlot, setEditingSlot,
        showLibraryInEditor, setShowLibraryInEditor,
        multiSelectTarget, setMultiSelectTarget,
        editorName, setEditorName,
        editorValue, setEditorValue,
        editorTag, setEditorTag,
        editorVariant, setEditorVariant,
        editorVariants, setEditorVariants,
        editorDescription, setEditorDescription,
        editorIsVariable, setEditorIsVariable,
        editorDefinitionId, setEditorDefinitionId,
        openEditor,
        closeEditor,
        saveTraitFromEditor,
        removeTrait,
        handleMultiAdd,
        clearEditor
    };
};

import { useCallback } from 'react';
import { DotEntry, SuggestionEntry } from '../../types';
import { normalizeString } from '../../utils/stringUtils';
import { generateId } from '../../utils/factories';
import { CharacterSheetData } from '../../types/character';
import { RulesData } from '../../types/rules';

export const useVariableSkills = (
    data: CharacterSheetData,
    onChange: (update: (prev: CharacterSheetData) => CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void,
    rules: RulesData | null,
    setVariantModalState: (state: any) => void,
    variantModalState: any
) => {
    const handleDefineVariant = useCallback((category: string, id: string, name: string) => {
        const existingEntry = data.skills[category]?.find(s => s.id === id);
        let definitionId = existingEntry?.definitionId;
        let variants: string[] = [];

        const libSkill = rules?.libraries?.skills?.find(s =>
            (definitionId && s.id === definitionId) ||
            normalizeString(s.name) === normalizeString(name)
        );

        if (libSkill) {
            definitionId = libSkill.id;
            variants = libSkill.variants || [];
        }

        setVariantModalState({
            isOpen: true,
            category,
            id,
            skillName: name,
            definitionId,
            variants
        });
    }, [data.skills, rules?.libraries?.skills, setVariantModalState]);

    const finalizeVariantDefinition = (variantName: string) => {
        const { category, id, definitionId } = variantModalState;
        if (!variantName.trim()) return;

        onChange(prev => {
            const list = prev.skills[category];
            if (!list) return prev;

            const index = list.findIndex(s => s.id === id);
            if (index === -1) return prev;

            const newList = [...list];

            newList[index] = {
                ...newList[index],
                variant: variantName.trim(),
                definitionId: definitionId || newList[index].definitionId
            };

            const newItem: DotEntry = {
                id: generateId(),
                name: newList[index].name,
                value: 0,
                creationValue: 0,
                max: 5,
                variant: "",
                definitionId: definitionId
            };

            newList.splice(index + 1, 0, newItem);

            onAddLog(`Définition variante : ${newList[index].name} : ${newList[index].variant}`, 'success', 'sheet');

            const newState = {
                ...prev,
                skills: {
                    ...prev.skills,
                    [category]: newList
                }
            };

            if (definitionId && variantName.trim()) {
                const libSkill = rules?.libraries?.skills?.find(s => s.id === definitionId);
                const normalizedVariant = normalizeString(variantName);

                const isKnown = libSkill?.variants?.some(v => normalizeString(v) === normalizedVariant);

                if (libSkill && !isKnown) {
                    const alreadySuggested = prev.suggestions?.some(s =>
                        s.type === 'variant' &&
                        s.parentId === definitionId &&
                        normalizeString(s.name) === normalizedVariant
                    );

                    if (!alreadySuggested) {
                        const suggestion: SuggestionEntry = {
                            id: generateId(),
                            type: 'variant',
                            name: variantName.trim(),
                            category: category,
                            parentId: definitionId,
                            timestamp: Date.now()
                        };
                        newState.suggestions = [...(prev.suggestions || []), suggestion];
                        onAddLog(`Suggestion de variante envoyée : ${variantName}`, 'info', 'sheet');
                    }
                }
            }

            return newState;
        });

        setVariantModalState((prev: any) => ({ ...prev, isOpen: false }));
    };

    return {
        handleDefineVariant,
        finalizeVariantDefinition
    };
};

import { useCallback } from 'react';
import { DotEntry, SuggestionEntry } from '../types';
import { normalizeString } from '../utils/stringUtils';
import { generateId } from '../utils/factories';
import { RulesData } from '../types/rules';
import { CharacterSheetData } from '../types/character';
import { getSkillCategory, getCounter, setCounter } from '../utils/stateAccessors';

interface DropPayload {
    type: string;
    data: {
        id?: string;
        name: string;
        description?: string;
        isVariable?: boolean;
        categoryType?: string;
        [key: string]: any;
    };
    categoryType?: string;
}

export const useCharacterSheetActions = (
    data: CharacterSheetData,
    onChange: (update: (prev: CharacterSheetData) => CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both', deduplicationId?: string) => void,
    rules: RulesData | null
) => {

    const updateHeader = useCallback((field: keyof typeof data.header, value: string) => {
        onChange(prev => ({ ...prev, header: { ...prev.header, [field]: value } }));
        onAddLog(`En-tête modifiée : ${String(field)} = "${value}"`, 'info', 'sheet', `header_${String(field)}`);
    }, [onChange, onAddLog]);

    const updateDot = useCallback((section: 'skills', category: string, id: string, value: number) => {
        onChange(prev => {
            const list = getSkillCategory(prev, category);
            if (!list) return prev;

            const isCreationMode = prev.creationConfig && prev.creationConfig.active;
            const catDef = rules?.definitions?.skillCategories?.find(c => c.id === category);
            const behavior = catDef?.behavior;
            const isBaseSkill = !behavior || behavior === 'Compétence' || behavior === 'Secondaire';

            const newList = list.map(item => {
                if (item.id !== id) return item;
                if (isCreationMode && isBaseSkill) {
                    return { ...item, value, creationValue: value };
                }
                return { ...item, value };
            });

            const itemName = list.find(item => item.id === id)?.name || 'Compétence';
            onAddLog(`Modification ${String(itemName)} : ${value}`, 'info', 'sheet', `dot_${String(id)}`);

            const updatedState = {
                ...prev,
                [section]: {
                    ...prev[section],
                    [String(category)]: newList
                }
            };

            if (section === 'skills' && prev.counters) {
                const counterKey = Object.keys(prev.counters).find(k => k === id);
                if (counterKey) {
                    const currentCounter = getCounter(prev, counterKey);
                    if (currentCounter && !Array.isArray(currentCounter)) {
                        const newCounter = { ...currentCounter, value, creationValue: isCreationMode ? value : currentCounter.creationValue };
                        const updatedCounters = { ...prev.counters };
                        setCounter({ ...prev, counters: updatedCounters } as CharacterSheetData, counterKey, newCounter);
                        updatedState.counters = updatedCounters;
                    }
                }
            }

            return updatedState;
        });
    }, [onChange, onAddLog, rules]);

    const handleDropItem = useCallback((category: string, payload: DropPayload, targetIndex?: number) => {
        const { type, data: itemData, categoryType } = payload;
        const catDef = rules?.definitions?.skillCategories?.find(c => c.id === category);
        const behavior = catDef?.behavior || 'Compétence';

        if (categoryType === 'skill' && (behavior !== 'Compétence' && behavior !== 'Secondaire')) {
            onAddLog("Action bloquée : Cette catégorie n'accepte pas les compétences.", 'danger', 'sheet');
            return;
        }
        if (categoryType === 'background' && behavior !== 'Arrière-plan') {
            onAddLog("Action bloquée : Cette catégorie n'accepte pas les historiques.", 'danger', 'sheet');
            return;
        }

        const newEntry: DotEntry = type === 'sheet_item'
            ? (itemData as DotEntry)
            : {
                id: generateId(),
                name: itemData.name,
                value: 0,
                creationValue: 0,
                max: 5,
                description: itemData.description,
                definitionId: itemData.id
            };

        onChange(prev => {
            const updatedSkills = { ...prev.skills };
            if (type === 'sheet_item') {
                Object.keys(updatedSkills).forEach(cat => {
                    updatedSkills[cat] = (updatedSkills[cat] || []).filter(s => s.id !== newEntry.id);
                });
            }

            const currentList = [...(updatedSkills[category] || [])];
            if (newEntry.name && !itemData.isVariable && currentList.some(s => s.name?.toLowerCase() === itemData.name.toLowerCase() && s.id !== newEntry.id)) {
                return prev;
            }

            if (targetIndex !== undefined && targetIndex >= 0 && targetIndex <= currentList.length) {
                currentList.splice(targetIndex, 0, newEntry);
            } else {
                currentList.push(newEntry);
            }

            updatedSkills[category] = currentList;
            const newState = { ...prev, skills: updatedSkills };

            if (type === 'custom_lib_item' || type === 'lib_skill') {
                const suggestionType = categoryType || (category.toLowerCase().includes('background') || category.toLowerCase().includes('arrière-plan') ? 'background' : 'skill');
                const suggestion: SuggestionEntry = {
                    id: generateId(),
                    type: suggestionType as 'skill' | 'background',
                    name: itemData.name,
                    category: category,
                    timestamp: Date.now()
                };
                newState.suggestions = [...(prev.suggestions || []), suggestion];
                onAddLog(`Suggestion créée pour le MJ : ${itemData.name}`, 'info', 'sheet');
            }

            return newState;
        });

        onAddLog(type === 'sheet_item' ? `Déplacement : ${itemData.name || 'Espaceur'}` : `Ajout réussi : ${itemData.name || 'Espaceur'}`, 'success', 'sheet');
    }, [onChange, onAddLog, rules]);

    const handleRemoveItem = useCallback((category: string, id: string) => {
        onChange(prev => {
            const currentList = prev.skills[category] || [];
            const itemToRemove = currentList.find(s => s.id === id);

            if (itemToRemove && itemToRemove.name && (itemToRemove.value || 0) > 0) {
                onAddLog(`Action bloquée : Impossible de supprimer une compétence avec des points investis.`, 'danger', 'sheet');
                return prev;
            }

            const updatedList = currentList.filter(s => s.id !== id);
            return { ...prev, skills: { ...prev.skills, [category]: updatedList } };
        });
        onAddLog("Élément supprimé de la fiche", 'info', 'sheet');
    }, [onChange, onAddLog]);

    const updateAttribute = useCallback((category: string, id: string, field: 'val1' | 'val2' | 'val3', value: string) => {
        onChange(prev => {
            const numValue = parseInt(value) || 0;
            const isCreationMode = prev.creationConfig && prev.creationConfig.active;

            const updateInList = <T extends { id: string; name?: string;[key: string]: any }>(list: T[]) => {
                const idx = list.findIndex(item => item.id === id);
                if (idx === -1) return null;
                const newList = [...list];
                const item = newList[idx];
                const creationKey = `creation${field.charAt(0).toUpperCase() + field.slice(1)}`;
                newList[idx] = isCreationMode
                    ? { ...item, [field]: value, [creationKey]: numValue }
                    : { ...item, [field]: value };
                return { newList, name: item.name };
            };

            const attrResult = updateInList(prev.attributes?.[category] || []);
            if (attrResult) {
                onAddLog(`Attribut ${attrResult.name} modifié`, 'info', 'sheet', `attr_${id}_${field}`);
                return { ...prev, attributes: { ...prev.attributes, [category]: attrResult.newList } };
            }

            const secResult = updateInList(prev.secondaryAttributes?.[category] || []);
            if (secResult) {
                onAddLog(`Attribut ${secResult.name} modifié`, 'info', 'sheet', `attr_sec_${id}_${field}`);
                return { ...prev, secondaryAttributes: { ...prev.secondaryAttributes, [category]: secResult.newList } };
            }

            return prev;
        });
    }, [onChange, onAddLog]);

    const updateCombatWeapon = useCallback((id: string, field: string, value: string) => {
        onChange(prev => {
            const newWeapons = (prev.combat.weapons || []).map(w => w.id === id ? { ...w, [field]: value } : w);
            return { ...prev, combat: { ...prev.combat, weapons: newWeapons } };
        });
        onAddLog(`Arme modifiée (${field})`, 'info', 'sheet');
    }, [onChange, onAddLog]);

    const updateArmor = useCallback((index: number, field: string, value: string) => {
        onChange(prev => {
            const newArmor = [...(prev.combat.armor || [])];
            if (newArmor[index]) {
                newArmor[index] = { ...newArmor[index], [field]: value };
                return { ...prev, combat: { ...prev.combat, armor: newArmor } };
            }
            return prev;
        });
        onAddLog(`Armure modifiée (${field})`, 'info', 'sheet');
    }, [onChange, onAddLog]);

    const updateCounter = useCallback((id: string, value: number, isCustom = false, field: 'value' | 'current' = 'value') => {
        onChange(prev => {
            const isCreationMode = prev.creationConfig && prev.creationConfig.active;
            if (isCustom) {
                const newCustom = (prev.counters.custom || []).map(c => {
                    if (c.id !== id) return c;
                    const newItem = { ...c };
                    if (field === 'value') {
                        newItem.value = value;
                        if (isCreationMode) newItem.creationValue = value;
                        if ((newItem.current || 0) > value) newItem.current = value;
                    } else {
                        newItem.current = Math.min(value, newItem.value);
                    }
                    return newItem;
                });
                return { ...prev, counters: { ...prev.counters, custom: newCustom } };
            } else {
                const counterKey = Object.keys(prev.counters).find(k => {
                    const c = getCounter(prev, k);
                    return !Array.isArray(c) && c?.id === id;
                }) || id;
                const current = getCounter(prev, counterKey);
                if (!current || Array.isArray(current)) return prev;

                const sysDef = rules?.definitions?.counters?.[id] || (rules?.definitions?.counters && rules.definitions.counters[counterKey]);
                const displayName = current.name || sysDef?.name || id;
                const libDef = rules?.libraries?.counters?.find(c => c.id === id || normalizeString(c.name) === normalizeString(displayName));

                const xpCost = libDef?.xpCost !== undefined ? libDef.xpCost : (sysDef?.xpCost ?? 0);
                const defaultValue = libDef?.defaultValue !== undefined ? libDef.defaultValue : (sysDef?.defaultValue ?? 0);

                if (field === 'value' && (libDef || sysDef)) {
                    if (xpCost <= 0 && value > current.value) return prev;
                    if (value < defaultValue) return prev;
                }

                const newItem = { ...current };
                if (field === 'value') {
                    newItem.value = value;
                    if ((newItem.current || 0) > value) newItem.current = value;
                } else {
                    newItem.current = Math.min(value, newItem.value);
                }

                const updatedCounters = { ...prev.counters };
                setCounter({ ...prev, counters: updatedCounters } as CharacterSheetData, counterKey, newItem);
                const updatedState = { ...prev, counters: updatedCounters };

                // Sync with skills if applicable
                if (field === 'value' && prev.skills) {
                    const newSkills = { ...prev.skills };
                    let skillFound = false;
                    Object.keys(newSkills).forEach(catId => {
                        const list = newSkills[catId];
                        const idx = list.findIndex(s => s.id === id);
                        if (idx !== -1) {
                            const catDef = rules?.definitions?.skillCategories?.find(c => c.id === catId);
                            const isCounterCat = catDef?.behavior === 'Compteur';
                            const newList = [...list];
                            newList[idx] = { ...newList[idx], value, creationValue: (isCreationMode && !isCounterCat) ? value : newList[idx].creationValue };
                            newSkills[catId] = newList;
                            skillFound = true;
                        }
                    });
                    if (skillFound) updatedState.skills = newSkills;
                }
                return updatedState;
            }
        });
    }, [onChange, onAddLog, rules]);

    return {
        updateHeader,
        updateDot,
        handleDropItem,
        handleRemoveItem,
        updateAttribute,
        updateCombatWeapon,
        updateArmor,
        updateCounter
    };
};

import { useCallback, useMemo } from 'react';
import { CharacterSheetData, DotEntry } from '../types';
import { RulesData, SkillBehavior } from '../types/rules';

export interface SkillBlock {
    title: string;
    items: DotEntry[];
    cat: string;
    description?: string;
}

export interface SheetColumn {
    id: number;
    topBlocks: SkillBlock[];
    bottomBlocks: SkillBlock[];
    readonly blocks: SkillBlock[];
}

export interface SheetLayout {
    columns: SheetColumn[];
    columnCount: number;
    backgrounds: SkillBlock[];
    counters: { title: string; id: string; description?: string }[];
}

type ColumnRow = 'top' | 'bottom';
interface Mapping {
    col: number;
    row: ColumnRow;
}

const LANDSCAPE_MAP: Record<string, Mapping> = {
    'Col_Comp_1': { col: 0, row: 'top' },
    'Col_Comp_2': { col: 1, row: 'top' },
    'Col_Comp_3': { col: 2, row: 'top' },
    'Col_Comp_4': { col: 3, row: 'top' },
    'Col_Comp_5': { col: 4, row: 'top' },
    'Col_Comp_6': { col: 0, row: 'bottom' },
    'Col_Comp_7': { col: 1, row: 'bottom' },
    'Col_Comp_8': { col: 2, row: 'bottom' },
    'Col_Comp_9': { col: 3, row: 'bottom' },
    'Col_Comp_10': { col: 4, row: 'bottom' },
};

const PORTRAIT_MAP: Record<string, Mapping> = {
    'Col_Comp_1': { col: 0, row: 'top' },
    'Col_Comp_2': { col: 1, row: 'top' },
    'Col_Comp_3': { col: 2, row: 'top' },
    'Col_Comp_4': { col: 3, row: 'top' },
    'Col_Comp_5': { col: 0, row: 'bottom' },
    'Col_Comp_6': { col: 1, row: 'bottom' },
    'Col_Comp_7': { col: 2, row: 'bottom' },
    'Col_Comp_8': { col: 3, row: 'bottom' },
    'Col_Comp_9': { col: 0, row: 'bottom' }, // Overflow
};

export const useSheetLayout = (data: CharacterSheetData, rules: RulesData | null) => {

    const attributeCategories = useMemo(() => data.attributeSettings || [
        { id: 'pave_attributs_1', label: 'Physique' },
        { id: 'pave_attributs_2', label: 'Mental' },
        { id: 'pave_attributs_3', label: 'Social' }
    ], [data.attributeSettings]);

    const getAttributesGridClass = useCallback(() => {
        const count = attributeCategories.length;
        if (count === 1) return 'grid-cols-1';
        if (count === 2) return 'grid-cols-2';
        if (count === 3) return 'grid-cols-3';
        if (count === 4) return 'grid-cols-4';
        return 'grid-cols-3'; // fallback
    }, [attributeCategories]);

    const getDynamicColumns = useCallback((isLandscape: boolean = false): SheetLayout => {
        const skillCats = rules?.definitions?.skillCategories || [];
        const fallback: SheetLayout = { columns: [], columnCount: isLandscape ? 5 : 4, backgrounds: [], counters: [] };

        if (skillCats.length === 0) return fallback;

        // 1. Separate by behavior
        const skillsSet = skillCats.filter(c => c.behavior === 'Compétence' || c.behavior === 'Secondaire');
        const backgroundsSet = skillCats.filter(c => c.behavior === 'Arrière-plan');
        const countersSet = skillCats.filter(c => c.behavior === 'Compteur');

        // 2. Base columns
        const columnCount = isLandscape ? 5 : 4;
        const columns: SheetColumn[] = Array.from({ length: columnCount }, (_, id) => ({
            id,
            topBlocks: [],
            bottomBlocks: [],
            get blocks() { return [...this.topBlocks, ...this.bottomBlocks]; }
        }));

        const mapping = isLandscape ? LANDSCAPE_MAP : PORTRAIT_MAP;

        skillsSet.forEach(cat => {
            const items = data.skills[cat.id] || [];
            const map = mapping[cat.id] || { col: 0, row: 'top' };
            const block: SkillBlock = {
                title: cat.label,
                items,
                cat: cat.id,
                description: cat.description
            };

            // Safety check for col index
            if (map.col < columns.length) {
                if (map.row === 'top') {
                    columns[map.col].topBlocks.push(block);
                } else {
                    columns[map.col].bottomBlocks.push(block);
                }
            }
        });

        return {
            columns,
            columnCount,
            backgrounds: backgroundsSet.map(cat => ({
                title: cat.label,
                items: data.skills[cat.id] || [],
                cat: cat.id,
                description: cat.description
            })),
            counters: countersSet.map(cat => ({
                title: cat.label,
                id: cat.id,
                description: cat.description
            }))
        };
    }, [data.skills, rules?.definitions?.skillCategories]);

    return {
        attributeCategories,
        getAttributesGridClass,
        getDynamicColumns
    };
};

import { useState, useMemo, useCallback } from 'react';
import { CharacterSheetData, LibraryEntry, TraitEffect } from '../types';
import { MergedEntry } from '../utils/libraryMerger';
import { useRules } from '../context/RulesContext';

export const useTraitActions = (
    data: CharacterSheetData,
    onUpdate: (newData: CharacterSheetData) => void,
    defaultType: 'avantage' | 'desavantage'
) => {
    const { rules, updateRules } = useRules();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editForm, setEditForm] = useState<LibraryEntry | null>(null);
    const [tagInput, setTagInput] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);
    const [showOfficialUpdateConfirm, setShowOfficialUpdateConfirm] = useState(false);
    const [updateResult, setUpdateResult] = useState<{ success: boolean; message: string } | null>(null);

    const handleOpenNew = useCallback(() => {
        setError(null);
        setTagInput('');
        setEditForm({
            id: Math.random().toString(36).substr(2, 9),
            name: '',
            type: defaultType,
            cost: '1',
            description: '',
            tags: [],
            effects: []
        });
        setIsModalOpen(true);
    }, [defaultType]);

    const handleOpenEdit = useCallback((merged: MergedEntry<LibraryEntry> | LibraryEntry) => {
        const entry = 'entry' in merged ? merged.entry : merged;
        const source = 'source' in merged ? merged.source : 'local';

        setError(null);
        setTagInput('');
        setEditForm({
            ...entry,
            id: entry.id,
            tags: [...(entry.tags || [])],
            effects: (entry.effects || []).map(e => ({ ...e }))
        });
        setIsModalOpen(true);
    }, []);

    const handleDelete = useCallback((id: string, source: string) => {
        if (source === 'official') return;
        setShowDeleteConfirm(id);
    }, []);

    const confirmDelete = useCallback(() => {
        if (!showDeleteConfirm) return;
        const local = (data && Array.isArray(data.library)) ? data.library : [];
        onUpdate({ ...data, library: local.filter(l => l.id !== showDeleteConfirm) });
        setShowDeleteConfirm(null);
    }, [data, onUpdate, showDeleteConfirm]);

    const handleSave = useCallback(() => {
        if (!editForm) return;
        if (!editForm.name.trim()) { setError("Le nom du trait ne peut pas être vide."); return; }

        const local = (data && Array.isArray(data.library)) ? data.library : [];
        const duplicate = local.find(l => l.id !== editForm.id && l.name.trim().toLowerCase() === editForm.name.trim().toLowerCase());

        if (duplicate) { setError("Un trait personnel portant ce nom existe déjà."); return; }

        const formToSave = {
            ...editForm,
            variants: editForm.variants ? editForm.variants.map(v => v.trim()).filter(v => v !== '') : []
        };

        const existsLocally = local.some(l => l.id === formToSave.id);
        const newLibrary = existsLocally
            ? local.map(l => l.id === formToSave.id ? formToSave : l)
            : [formToSave, ...local];

        onUpdate({ ...data, library: newLibrary });
        setIsModalOpen(false);
        setEditForm(null);
    }, [data, editForm, onUpdate]);

    const executeOfficialUpdate = async () => {
        try {
            const res = await fetch('./data/traits.json?t=' + Date.now());
            if (!res.ok) throw new Error("Fichier introuvable");

            const json = await res.json();
            const newTraits = json.data as LibraryEntry[];

            if (json.meta && json.meta.type !== 'traits') throw new Error("Format invalide");

            const updatedRules = {
                ...rules!,
                libraries: {
                    ...rules!.libraries,
                    traits: newTraits
                }
            };
            updateRules(updatedRules);
            setUpdateResult({ success: true, message: `Bibliothèque officielle mise à jour (${newTraits.length} traits).` });
        } catch (e) {
            setUpdateResult({ success: false, message: "Échec de la mise à jour officielle : " + (e as Error).message });
        } finally {
            setShowOfficialUpdateConfirm(false);
        }
    };

    const handleImportTraits = useCallback((importedEntries: LibraryEntry[]) => {
        const local = (data && Array.isArray(data.library)) ? data.library : [];
        const newLibrary = [...local];

        importedEntries.forEach(entry => {
            const index = newLibrary.findIndex(l => l.id === entry.id);
            if (index >= 0) {
                newLibrary[index] = entry;
            } else {
                newLibrary.unshift(entry);
            }
        });

        onUpdate({ ...data, library: newLibrary });
    }, [data, onUpdate]);

    const addTag = useCallback(() => {
        if (!editForm || !tagInput.trim()) return;
        const newTag = tagInput.trim();
        if (!(editForm.tags || []).includes(newTag)) {
            setEditForm({ ...editForm, tags: [...(editForm.tags || []), newTag] });
        }
        setTagInput('');
    }, [editForm, tagInput]);

    const removeTag = useCallback((tagToRemove: string) => {
        if (!editForm) return;
        setEditForm({ ...editForm, tags: (editForm.tags || []).filter(t => t !== tagToRemove) });
    }, [editForm]);

    const addEffect = useCallback(() => {
        if (!editForm) return;
        const newEffect: TraitEffect = { id: Math.random().toString(36).substr(2, 9), type: 'xp_bonus', value: 0 };
        setEditForm({ ...editForm, effects: [...(editForm.effects || []), newEffect] });
    }, [editForm]);

    const updateEffect = useCallback((id: string, field: keyof TraitEffect, value: any) => {
        if (!editForm) return;
        setEditForm({
            ...editForm,
            effects: (editForm.effects || []).map(e => e.id === id ? { ...e, [field]: value } : e)
        });
    }, [editForm]);

    const removeEffect = useCallback((id: string) => {
        if (!editForm) return;
        setEditForm({ ...editForm, effects: (editForm.effects || []).filter(e => e.id !== id) });
    }, [editForm]);

    const allSkills = useMemo(() => {
        if (!data || !data.skills) return [];
        const skills: { id: string, name: string }[] = [];
        Object.values(data.skills).forEach(skillList => {
            skillList.forEach(s => {
                if (s.name && s.name.trim() !== '') {
                    skills.push({ id: s.id, name: s.name });
                }
            });
        });
        return skills.sort((a, b) => a.name.localeCompare(b.name));
    }, [data.skills]);

    const allAttributes = useMemo(() => {
        if (!data || !data.attributes) return [];
        const attrs: { id: string, name: string }[] = [];
        if (data.attributes) {
            Object.keys(data.attributes).forEach(key => {
                data.attributes[key].forEach(a => {
                    if (a.name && a.name.trim() !== '') {
                        attrs.push({ id: a.id, name: a.name });
                    }
                });
            });
        }
        return attrs.sort((a, b) => a.name.localeCompare(b.name));
    }, [data.attributes]);

    return {
        isModalOpen,
        setIsModalOpen,
        editForm,
        setEditForm,
        tagInput,
        setTagInput,
        error,
        showDeleteConfirm,
        setShowDeleteConfirm,
        showOfficialUpdateConfirm,
        setShowOfficialUpdateConfirm,
        updateResult,
        setUpdateResult,
        handleOpenNew,
        handleOpenEdit,
        handleDelete,
        confirmDelete,
        handleSave,
        executeOfficialUpdate,
        handleImportTraits,
        addTag,
        removeTag,
        addEffect,
        updateEffect,
        removeEffect,
        allSkills,
        allAttributes
    };
};

import { useMemo, useState } from 'react';
import { CharacterSheetData, LibraryEntry } from '../types';
import { useRules } from '../context/RulesContext';
import { mergeLibraries, MergedEntry } from '../utils/libraryMerger';
import { smartIncludes } from '../utils/stringUtils';

export type SortOption = 'name' | 'cost' | 'type';
export type SortOrder = 'asc' | 'desc';

export const useTraitLibrary = (
    data: CharacterSheetData,
    searchTerm: string,
    filterType: 'all' | 'avantage' | 'desavantage',
    selectedTags: string[],
    sortBy: SortOption,
    sortOrder: SortOrder
) => {
    const { rules } = useRules();

    const hybridList = useMemo(() => {
        const local = (data && Array.isArray(data.library)) ? data.library.filter(entry => entry && typeof entry === 'object') : [];
        const official = rules?.libraries?.traits || [];
        return mergeLibraries(local, official);
    }, [data.library, rules]);

    const allAvailableTags = useMemo(() => {
        const tags = new Set<string>();
        hybridList.forEach(m => (m.entry.tags || []).forEach(t => tags.add(t)));
        return Array.from(tags).sort();
    }, [hybridList]);

    const processedList = useMemo(() => {
        const list = hybridList.filter(m => {
            const entry = m.entry;
            const entryTags = entry.tags || [];
            const matchesSearch = smartIncludes(entry.name, searchTerm) ||
                smartIncludes(entry.description, searchTerm) ||
                entryTags.some(t => smartIncludes(t, searchTerm));
            const matchesType = filterType === 'all' || entry.type === filterType;
            const matchesTags = selectedTags.length === 0 || selectedTags.every(sel =>
                entryTags.some(t => t.toLowerCase() === sel.toLowerCase())
            );
            return matchesSearch && matchesType && matchesTags;
        });

        list.sort((a, b) => {
            const ea = a.entry;
            const eb = b.entry;

            let comparison = 0;
            if (sortBy === 'name') comparison = ea.name.localeCompare(eb.name);
            else if (sortBy === 'cost') comparison = (parseInt(ea.cost) || 0) - (parseInt(eb.cost) || 0);
            else if (sortBy === 'type') comparison = ea.type.localeCompare(eb.type);

            if (comparison === 0) return ea.name.localeCompare(eb.name);
            return sortOrder === 'asc' ? comparison : -comparison;
        });

        return list;
    }, [hybridList, searchTerm, filterType, selectedTags, sortBy, sortOrder]);

    return {
        hybridList,
        processedList,
        allAvailableTags
    };
};

import { supabase } from './supabase';
import { AttributePreset } from '../types/system';
import { ErrorService } from './ErrorService';
import { TABLE_ATTRIBUTE_PRESETS } from '../constants/db';

export const AttributeService = {
    /**
     * List all available attribute presets
     */
    async listAttributePresets(): Promise<AttributePreset[] | null> {
        const { data, error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .select('*')
            .order('is_official', { ascending: false })
            .order('name', { ascending: true });

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.listAttributePresets' });
            return null;
        }

        // Map DB snake_case to TS camelCase if needed (though here it seems we use it directly or it was already mapped)
        // Let's ensure mapping for consistency
        return (data || []).map(p => ({
            id: p.id,
            name: p.name,
            description: p.description,
            hasSecondary: p.has_secondary,
            structure: p.structure,
            isOfficial: p.is_official
        }));
    },

    /**
     * Save a new attribute preset
     */
    async saveAttributePreset(name: string, description: string, structure: any, hasSecondary: boolean): Promise<boolean> {
        const { error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .insert([{
                name,
                description,
                structure,
                has_secondary: hasSecondary,
                is_official: false
            }]);

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.saveAttributePreset', userMessage: "Impossible de sauvegarder le preset." });
            return false;
        }
        return true;
    },

    /**
     * Delete an attribute preset (only if not official)
     */
    async deleteAttributePreset(id: string): Promise<boolean> {
        const { error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .delete()
            .eq('id', id)
            .eq('is_official', false); // Safety check

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.deleteAttributePreset', userMessage: "Impossible de supprimer le preset." });
            return false;
        }
        return true;
    },

    /**
     * Update an attribute preset metadata
     */
    async updateAttributePreset(id: string, updates: { name?: string; description?: string }): Promise<boolean> {
        // Map camelCase to snake_case if needed (none here as name/description are same)
        const { error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .update(updates)
            .eq('id', id);

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.updateAttributePreset', userMessage: "Impossible de mettre à jour le preset." });
            return false;
        }
        return true;
    }
};

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { CampaignService } from './CampaignService';
import { OfflineStorageService } from './OfflineStorageService';
import { DatabaseService } from './DatabaseService';
import { LibraryService } from './LibraryService';
import { defaultRules } from '../data/defaultRules';
import { RulesData } from '../types/rules';

// Mock dependencies
vi.mock('./DatabaseService', () => ({
    DatabaseService: {
        fetchOne: vi.fn(),
        fetchAll: vi.fn(),
        insert: vi.fn(),
        update: vi.fn(),
        delete: vi.fn(),
        deleteBy: vi.fn()
    }
}));

vi.mock('./LibraryService', () => ({
    LibraryService: {
        loadLibraries: vi.fn(),
        persistInitialLibraries: vi.fn(),
        syncLibraries: vi.fn()
    }
}));

// We will use a "fake" IndexedDB implementation for OfflineStorageService logic
// since idb-keyval uses browser APIs not available in Node easily without setup.
// We'll mock the module 'idb-keyval' itself.
const mockStore = new Map<string, any>();

vi.mock('idb-keyval', () => ({
    get: vi.fn((key) => Promise.resolve(mockStore.get(key as string))),
    set: vi.fn((key, val) => {
        mockStore.set(key as string, val);
        return Promise.resolve();
    }),
    entries: vi.fn(() => Promise.resolve(Array.from(mockStore.entries()))),
    del: vi.fn((key) => {
        mockStore.delete(key as string);
        return Promise.resolve();
    })
}));

describe('Integration: CampaignService & OfflineStorage', () => {

    beforeEach(() => {
        vi.clearAllMocks();
        mockStore.clear();
    });

    it('should save loaded campaign to offline cache', async () => {
        const campaignId = 'camp-123';
        const mockDbSetting = {
            id: campaignId,
            name: 'Test Campaign',
            version: '1.0.0',
            last_updated: new Date().toISOString(),
            configurations: { ...defaultRules.configurations },
            definitions: { ...defaultRules.definitions },
            is_public: false,
            is_archived: false,
            show_metadata_to_players: true
        };

        const mockLibraries = {
            traits: [],
            skills: [],
            specializations: [],
            backgrounds: [],
            counters: []
        };

        // 1. Mock Database Response
        (DatabaseService.fetchOne as any).mockResolvedValue(mockDbSetting);
        (LibraryService.loadLibraries as any).mockResolvedValue(mockLibraries);

        // 2. Load Setting via CampaignService
        const setting = await CampaignService.loadSetting(campaignId);
        expect(setting).not.toBeNull();
        expect(setting?.settingId).toBe(campaignId);

        // 3. Manually trigger save to cache (usually done in RulesLoader or UI, but we test the Service interop here)
        // In the real app, RulesLoader calls CampaignService.loadSetting check then OfflineStorageService.saveRules.
        // Let's simulate that flow.

        if (setting) {
            await OfflineStorageService.saveRules(setting);
        }

        // 4. Verify Cache Content
        // Check "active" cache
        const activeRules = await OfflineStorageService.getActiveRules();
        expect(activeRules).toEqual(setting);
        expect(mockStore.get('rpg-rules-cache')).toBeDefined();

        // Check "specific" cache
        const specificRules = await OfflineStorageService.getRulesBySettingId(campaignId);
        expect(specificRules).toEqual(setting);
        expect(mockStore.get(`rpg-rules-${campaignId}`)).toBeDefined();
    });

    it('should retrieve campaign from offline cache when explicitly requested', async () => {
        const campaignId = 'offline-camp-456';
        const cachedRules: RulesData = {
            ...defaultRules,
            settingId: campaignId,
            settingName: 'Offline Campaign',
            version: '2.0.0'
        };

        // 1. Seed Cache
        await OfflineStorageService.saveRules(cachedRules);

        // 2. Retrieve from Cache
        const retrieved = await OfflineStorageService.getRulesBySettingId(campaignId);

        expect(retrieved).not.toBeNull();
        expect(retrieved?.settingName).toBe('Offline Campaign');
    });

    it('should list cached campaigns for offline switching', async () => {
        const c1: RulesData = { ...defaultRules, settingId: 'c1', settingName: 'Campaign One', version: '1.0' };
        const c2: RulesData = { ...defaultRules, settingId: 'c2', settingName: 'Campaign Two', version: '1.1' };

        await OfflineStorageService.saveRules(c1);
        await OfflineStorageService.saveRules(c2);

        const list = await OfflineStorageService.listCachedCampaigns();

        expect(list).toHaveLength(2);
        expect(list).toContainEqual({ id: 'c1', name: 'Campaign One', version: '1.0' });
        expect(list).toContainEqual({ id: 'c2', name: 'Campaign Two', version: '1.1' });
    });

    it('should handle updates: new fetch should overwrite cache', async () => {
        const campaignId = 'update-test';

        // 1. Initial State (Old Version in Cache)
        const oldRules: RulesData = { ...defaultRules, settingId: campaignId, version: '1.0' };
        await OfflineStorageService.saveRules(oldRules);

        // 2. New Version from DB
        const newDbSetting = {
            id: campaignId,
            name: 'Updated Campaign',
            version: '2.0',
            last_updated: new Date().toISOString(),
            configurations: { ...defaultRules.configurations },
            definitions: { ...defaultRules.definitions },
            is_public: true
        };
        (DatabaseService.fetchOne as any).mockResolvedValue(newDbSetting);
        (LibraryService.loadLibraries as any).mockResolvedValue({ traits: [], skills: [], specializations: [], backgrounds: [], counters: [] });

        // 3. Load & Save
        const newRules = await CampaignService.loadSetting(campaignId);
        expect(newRules).not.toBeNull();
        if (newRules) await OfflineStorageService.saveRules(newRules);

        // 4. Verify Cache Updated
        const cached = await OfflineStorageService.getRulesBySettingId(campaignId);
        expect(cached?.version).toBe('2.0');
    });
});

import { supabase } from './supabase';
import { DatabaseService } from './DatabaseService';
import { GameSetting, RulesData, GameSettingSummary } from '../types/rules';
export type { GameSetting, RulesData, GameSettingSummary };
import { LibraryService } from './LibraryService';
import { logger } from '../utils/logger';
import { ErrorService } from './ErrorService';
import { migrateRulesToV2 } from '../utils/migrations';
import { RulesDataSchema } from '../utils/validation/rulesSchema';
import { TABLE_GAME_SETTINGS, TABLE_LIBRARIES_TRAITS, TABLE_LIBRARIES_SKILLS, TABLE_LIBRARIES_SPECIALIZATIONS, TABLE_LIBRARIES_BACKGROUNDS, TABLE_LIBRARIES_COUNTERS } from '../constants/db';
import { SKILL_COLUMNS } from '../constants/app';

// Interface de la base de données (table game_settings)
interface DBGameSetting {
    id: string;
    name: string;
    version: string;
    last_updated: string;
    configurations: RulesData['configurations']; // JSONB
    definitions: RulesData['definitions']; // JSONB
    is_public: boolean;
    is_archived: boolean;
    description: string | null;
    welcome_message: string | null;
    show_metadata_to_players: boolean;
}

export const CampaignService = {

    /**
     * List all available settings (campagnes)
     */
    async listSettings(): Promise<GameSettingSummary[] | null> {
        return await DatabaseService.fetchAll<GameSettingSummary>(TABLE_GAME_SETTINGS, {
            select: 'id, name, version, last_updated, is_public, is_archived',
            order: { column: 'last_updated', ascending: false }
        }, 'CampaignService.listSettings');
    },

    /**
     * List public settings available for players
     */
    async listPublicSettings(): Promise<GameSettingSummary[]> {
        return await DatabaseService.fetchAll<GameSettingSummary>(
            TABLE_GAME_SETTINGS,
            {
                select: 'id, name, version, last_updated, is_public',
                eq: { is_public: true },
                order: { column: 'last_updated', ascending: false }
            },
            'CampaignService.listPublicSettings'
        ) || [];
    },

    /**
     * Duplicate an existing setting
     */
    async duplicateSetting(id: string, newName: string): Promise<string | null> {
        const originalSetting = await CampaignService.loadSetting(id);

        if (!originalSetting) {
            ErrorService.handleError(new Error(`Setting with ID ${id} not found for duplication.`), {
                context: 'CampaignService.duplicateSetting',
                userMessage: "La campagne originale n'a pas été trouvée."
            });
            return null;
        }

        // Prepare rules for the new setting
        const newRules: Partial<RulesData> = {
            version: originalSetting.version,
            configurations: originalSetting.configurations,
            definitions: originalSetting.definitions,
            libraries: originalSetting.libraries,
            // Do not copy settingId, settingName, lastUpdated, is_public as they are specific to the original
        };

        // Create the new setting
        const newSettingId = await CampaignService.createSetting(newName, newRules);

        if (!newSettingId) {
            ErrorService.handleError(new Error(`Failed to create new setting for duplication of ${id}.`), {
                context: 'CampaignService.duplicateSetting',
                userMessage: "Échec de la création de la nouvelle campagne."
            });
            return null;
        }

        return newSettingId;
    },

    /**
     * Create a new empty setting
     */
    async createSetting(name: string, initialRules: Partial<RulesData>): Promise<string | null> {
        // Prepare JSONBs
        const configurations = initialRules.configurations || {};
        const definitions = initialRules.definitions || {};

        const inserted = await DatabaseService.insert<{ id: string }>(TABLE_GAME_SETTINGS, {
            name,
            version: initialRules.version || '1.0.0',
            configurations,
            definitions,
            is_public: false
        }, 'CampaignService.createSetting');

        if (!inserted) return null;

        const result = Array.isArray(inserted) ? inserted[0] : inserted;
        const settingId = result.id;

        // Persist Libraries if present
        if (initialRules.libraries) {
            await LibraryService.persistInitialLibraries(settingId, initialRules);
        }

        return settingId;
    },

    /**
     * Load a full setting by ID
     */
    async loadSetting(id: string): Promise<RulesData | null> {
        if (!id || id === 'orphan') {
            return null;
        }

        try {
            // 1. Fetch Main Config
            const settingData = await DatabaseService.fetchOne<DBGameSetting>(TABLE_GAME_SETTINGS, id, 'CampaignService.loadSetting');

            if (!settingData) {
                return null;
            }

            // 2. Load Libraries
            const libraries = await LibraryService.loadLibraries(id);

            const rulesRaw = migrateRulesToV2({
                version: settingData.version,
                lastUpdated: new Date(settingData.last_updated).getTime(),
                configurations: settingData.configurations,
                definitions: settingData.definitions,
                theme: (settingData.configurations as Record<string, unknown>)?.theme as { creationColor: string; xpColor: string } || { creationColor: "#000", xpColor: "#000" },
                libraries: libraries
            });

            // Validate with Zod
            const validationResult = RulesDataSchema.safeParse(rulesRaw);

            if (!validationResult.success) {
                logger.warn("[CampaignService] Validation Details:", JSON.stringify(validationResult.error.flatten(), null, 2));
                ErrorService.handleError(new Error("Données de campagne non conformes"), {
                    context: 'CampaignService.loadSetting',
                    userMessage: "Certaines données de la campagne ne respectent pas le schéma attendu (voir console)."
                });
                return null; // Don't proceed with invalid data
            }

            const rules = validationResult.data as RulesData;

            // Inject setting metadata
            rules.settingId = id;
            rules.settingName = settingData.name;
            rules.description = settingData.description || undefined;
            rules.welcomeMessage = settingData.welcome_message || undefined;
            rules.showMetadataToPlayers = settingData.show_metadata_to_players;
            rules.isArchived = settingData.is_archived;
            rules.source = 'database';

            // 3. REBUILD definitions.skills layout from libraries if needed
            // Only rebuild if the current layout is empty or significantly different
            const currentLayoutKeys = Object.keys(rules.definitions.skills || {});
            const hasExistingLayout = currentLayoutKeys.length > 0 && currentLayoutKeys.some(k => rules.definitions.skills?.[k] && (rules.definitions.skills[k] as string[]).length > 0);

            if (!hasExistingLayout && libraries.skills.length > 0) {
                logger.log("[CampaignService] Rebuilding skill layout from library (empty layout detected)");
                if (!rules.definitions.skills) rules.definitions.skills = {};

                libraries.skills.forEach(s => {
                    if (s.isActive !== false) {
                        const cat = s.defaultCategory || SKILL_COLUMNS.COL_2;
                        if (!rules.definitions.skills[cat]) rules.definitions.skills[cat] = [];
                        if (!rules.definitions.skills[cat].includes(s.name)) {
                            rules.definitions.skills[cat].push(s.name);
                        }
                    }
                });
            }

            // Ensure categories from libraries exist in skillCategories if migrateRules didn't find them
            // Backgrounds
            const bgCatDef = rules.definitions.skillCategories?.find((c) => c.behavior === 'Arrière-plan');
            const bgCat = bgCatDef?.id || SKILL_COLUMNS.COL_8;

            if (!rules.definitions.skills[bgCat]) rules.definitions.skills[bgCat] = [];
            libraries.backgrounds.forEach(b => {
                if (b.isActive !== false && !rules.definitions.skills[bgCat].includes(b.name)) {
                    rules.definitions.skills[bgCat].push(b.name);
                }
            });

            // Counters
            const counterCatDef = rules.definitions.skillCategories?.find((c) => c.behavior === 'Compteur');
            const counterCat = counterCatDef?.id || SKILL_COLUMNS.COL_9;
            if (!rules.definitions.skills[counterCat]) rules.definitions.skills[counterCat] = [];
            libraries.counters.forEach(c => {
                if (c.isActive !== false && !rules.definitions.skills[counterCat].includes(c.name)) {
                    rules.definitions.skills[counterCat].push(c.name);
                }
            });

            // Sync definitions.counters map (for specific counter definitions like max/xpCost)
            if (libraries.counters && libraries.counters.length > 0) {
                const activeCounters = libraries.counters.filter(c => c.isActive !== false);

                if (!rules.definitions.counters) {
                    rules.definitions.counters = {};
                }

                activeCounters.forEach(libCounter => {
                    // Determine stable key: ID preferred for global, slug for local
                    const key = libCounter.id || libCounter.name
                        .normalize('NFD')
                        .replace(/[\u0300-\u036f]/g, '')
                        .toLowerCase()
                        .replace(/[^a-z0-9]/g, '_')
                        .replace(/_+/g, '_')
                        .replace(/^_|_$/g, '');

                    // Always synchronize definition with library data to prevent stale values (from legacy JSON)
                    rules.definitions.counters[key] = {
                        id: libCounter.id,
                        name: libCounter.name,
                        description: libCounter.description || rules.definitions.counters[key]?.description || '',
                        max: libCounter.maxValue ?? rules.definitions.counters[key]?.max ?? 10,
                        value: libCounter.defaultValue ?? rules.definitions.counters[key]?.value,
                        defaultValue: libCounter.defaultValue ?? rules.definitions.counters[key]?.defaultValue,
                        xpCost: libCounter.xpCost ?? rules.definitions.counters[key]?.xpCost ?? 0
                    };
                });
            }

            return rules;
        } catch (e) {
            ErrorService.handleError(e, { context: 'CampaignService.loadSetting', userMessage: "Erreur critique lors du chargement de la campagne." });
            return null;
        }
    },

    /**
     * Save/Update a setting
     * This is complex because we must save the root AND the libraries
     */
    async saveSetting(id: string, rules: RulesData, name?: string): Promise<{ success: boolean; message?: string }> {

        // 1. Update Root
        const rootUpdate: Partial<DBGameSetting> = {
            version: rules.version,
            last_updated: new Date().toISOString(),
            configurations: rules.configurations,
            definitions: rules.definitions,
            description: rules.description || null,
            welcome_message: rules.welcomeMessage || null,
            show_metadata_to_players: !!rules.showMetadataToPlayers,
            is_archived: !!rules.isArchived
        };
        if (name) rootUpdate.name = name;

        const success = await DatabaseService.update(TABLE_GAME_SETTINGS, id, rootUpdate, 'CampaignService.saveSetting');

        if (!success) {
            return { success: false, message: "Erreur MAJ Root" };
        }

        // 2. Synchronize Libraries
        try {
            await LibraryService.syncLibraries(id, rules);
        } catch (libError) {
            ErrorService.handleError(libError, { context: 'CampaignService.saveSetting', userMessage: "Erreur sauvegarde bibliothèques." });
            return { success: false, message: `Erreur Bibliothèques: ${(libError as Error).message}` };
        }

        return { success: true };
    },

    /**
     * Delete a setting and all its related data
     */
    async deleteSetting(id: string): Promise<boolean> {
        // Delete libraries first (manual cascade just in case DB cascade isn't set)
        const results = await Promise.allSettled([
            DatabaseService.deleteBy(TABLE_LIBRARIES_TRAITS, 'setting_id', id, 'CampaignService.deleteSetting.traits'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_SKILLS, 'setting_id', id, 'CampaignService.deleteSetting.skills'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_SPECIALIZATIONS, 'setting_id', id, 'CampaignService.deleteSetting.specs'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_BACKGROUNDS, 'setting_id', id, 'CampaignService.deleteSetting.bgs'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_COUNTERS, 'setting_id', id, 'CampaignService.deleteSetting.counters')
        ]);

        const failures = results.filter(r => r.status === 'rejected');
        if (failures.length > 0) {
            ErrorService.handleError(new Error(`${failures.length} suppressions de bibliothèques échouées`), {
                context: 'CampaignService.deleteSetting'
            });
            return false;
        }

        // Delete the setting itself
        return await DatabaseService.delete('game_settings', id, 'CampaignService.deleteSetting');
    },

    /**
     * Toggle public/private visibility
     */
    async togglePublic(id: string, isPublic: boolean): Promise<boolean> {
        return await DatabaseService.update(TABLE_GAME_SETTINGS, id, { is_public: isPublic }, 'CampaignService.togglePublic');
    },

    /**
     * Set archived status
     */
    async setArchived(id: string, isArchived: boolean): Promise<boolean> {
        return await DatabaseService.update(TABLE_GAME_SETTINGS, id, { is_archived: isArchived }, 'CampaignService.setArchived');
    },

    /**
     * Manual schema check for a setting
     */
    async checkSchema(id: string): Promise<boolean> {
        try {
            const rules = await CampaignService.loadSetting(id);
            if (!rules) return false;
            // loadSetting already performs Zod validation
            return true;
        } catch (e) {
            return false;
        }
    }

}

/**
 * CharacterSyncService
 * 
 * Handles synchronization of player character sheets to Supabase.
 * Players can sync their sheets manually; Admin can read them.
 */

import { DatabaseService } from './DatabaseService';
import { CharacterSheetData } from '../types/character';

import { ImageSyncResolver } from './ImageSyncResolver';
import { ErrorService } from './ErrorService';

// Types for sync operations
export interface SyncedCharacter {
    id: string;
    setting_id: string;
    character_name: string;
    player_name: string;
    data: CharacterSheetData;
    last_synced: string;
    created_at: string;
}

export interface SyncedCharacterSummary {
    id: string;
    setting_id: string;
    character_name: string;
    player_name: string;
    last_synced: string;
    data_size?: number; // Real size in bytes from view_characters_summary
}

export interface SyncResult {
    success: boolean;
    syncId?: string;
    error?: string;
}

export const CharacterSyncService = {

    /**
     * Sync a character sheet to the database.
     * Uses upsert: creates if new, updates if exists (same setting/player/character combo).
     */
    async syncCharacter(
        settingId: string,
        playerName: string,
        characterName: string,
        data: CharacterSheetData
    ): Promise<SyncResult> {
        try {
            // Remove syncInfo from the data being stored to avoid circular reference
            const { syncInfo, ...cleanData } = data;

            // Step 1: Resolve and compress images for portable sync
            const dataToStore = await ImageSyncResolver.resolveImagesForSync(cleanData);

            const result = await DatabaseService.upsert<{ id: string }>(
                'characters',
                {
                    setting_id: (settingId === 'orphan' || !settingId) ? null : settingId,
                    player_name: playerName.trim(),
                    character_name: characterName.trim(),
                    data: dataToStore,
                    last_synced: new Date().toISOString()
                },
                {
                    onConflict: 'setting_id,character_name,player_name',
                    ignoreDuplicates: false
                },
                'CharacterSyncService.syncCharacter'
            );

            if (!result) {
                return { success: false, error: "Erreur de synchronisation (DatabaseService)." };
            }

            return { success: true, syncId: result.id };
        } catch (e) {
            ErrorService.handleError(e, { context: 'CharacterSyncService.syncCharacter' });
            return { success: false, error: (e as Error).message };
        }
    },

    /**
     * Get all characters synced by a specific player (for cloud loading).
     */
    async getCharactersByPlayerName(playerName: string): Promise<SyncedCharacterSummary[]> {
        return await DatabaseService.fetchAll<SyncedCharacterSummary>(
            'view_characters_summary',
            {
                select: 'id, character_name, player_name, last_synced, setting_id, data_size',
                eq: { player_name: playerName.trim() },
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getCharactersByPlayerName'
        );
    },

    /**
     * Get ALL characters across all campaigns (for Admin Master List).
     */
    async getAllCharacters(): Promise<SyncedCharacterSummary[]> {
        return await DatabaseService.fetchAll<SyncedCharacterSummary>(
            'view_characters_summary',
            {
                select: 'id, character_name, player_name, last_synced, setting_id, data_size',
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getAllCharacters'
        );
    },

    /**
     * Get all characters synced to a specific campaign (for Admin view).
     */
    async getCharactersBySettingId(settingId: string): Promise<SyncedCharacterSummary[]> {
        return await DatabaseService.fetchAll<SyncedCharacterSummary>(
            'view_characters_summary',
            {
                select: 'id, setting_id, character_name, player_name, last_synced, data_size',
                eq: { setting_id: settingId },
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getCharactersBySettingId'
        );
    },

    /**
     * Get a single character by ID (for Admin or Player detail view).
     */
    async getCharacterById(id: string): Promise<SyncedCharacter | null> {
        return await DatabaseService.fetchOne<SyncedCharacter>(
            'characters',
            id,
            'CharacterSyncService.getCharacterById'
        );
    },

    /**
     * Delete a synced character (Admin only, if needed later).
     */
    async deleteCharacter(id: string): Promise<boolean> {
        return await DatabaseService.delete(
            'characters',
            id,
            'CharacterSyncService.deleteCharacter'
        );
    },

    /**
     * Check if character sync table exists and is accessible.
     */
    async checkSyncAvailable(): Promise<boolean> {
        return await DatabaseService.checkAvailable('characters');
    },

    async processImages(obj: any, action: 'compress' | 'decompress'): Promise<any> {
        return action === 'compress'
            ? ImageSyncResolver.resolveImagesForSync(obj)
            : ImageSyncResolver.injectImagesAfterSync(obj);
    }
};

import { supabase } from './supabase';
import { ErrorService } from './ErrorService';

/**
 * Generic Database Service to abstract Supabase calls.
 * Provides consistent error handling and typing.
 */
export const DatabaseService = {

    /**
     * Execute a Supabase query builder and handle errors automatically.
     * Useful for complex queries constructed outside.
     */
    async execute<T>(
        queryPromise: PromiseLike<{ data: T | null; error: any }>,
        context: string,
        userMessage: string
    ): Promise<T | null> {
        // Supabase client does not throw, it returns error object.
        // However, if the promise rejects (network failure etc), we catch it.
        try {
            const { data, error } = await queryPromise;

            if (error) {
                // Determine if it's a "No rows found" error which might not be critical depending on context
                // But generally, if the caller expected data, it's an error.
                // The caller can check for null data.
                ErrorService.handleError(error, { context, userMessage });
                return null;
            }

            return data;
        } catch (e) {
            ErrorService.handleError(e, { context, userMessage });
            return null;
        }
    },

    /**
     * Fetch a single record by ID.
     */
    async fetchOne<T>(
        table: string,
        id: string,
        context: string = `DatabaseService.fetchOne(${table})`
    ): Promise<T | null> {
        const { data, error } = await supabase
            .from(table)
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            // PGRST116 means no rows returned for .single(), which is valid "null" result mostly
            if (error.code === 'PGRST116') return null;

            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la récupération de la donnée." });
            return null;
        }
        return data;
    },

    /**
     * Fetch all records matching a simple equality filter.
     */
    async fetchAll<T>(
        table: string,
        query: {
            eq?: Record<string, any>,
            or?: string,
            select?: string,
            order?: { column: string, ascending?: boolean },
            limit?: number
        } = {},
        context: string = `DatabaseService.fetchAll(${table})`
    ): Promise<T[]> {
        let builder = supabase.from(table).select(query.select || '*');

        if (query.or) {
            builder = builder.or(query.or);
        }

        if (query.eq) {
            Object.entries(query.eq).forEach(([key, value]) => {
                if (value !== undefined && value !== null) {
                    builder = builder.eq(key, value);
                } else if (value === null) {
                    builder = builder.is(key, null);
                }
            });
        }

        if (query.order) {
            builder = builder.order(query.order.column, { ascending: query.order.ascending ?? true });
        }

        if (query.limit) {
            builder = builder.limit(query.limit);
        }

        const { data, error } = await builder;

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la liste des données." });
            return [];
        }

        return data as T[];
    },

    /**
     * Insert a record (or multiple).
     * @returns The inserted data (single object or array depending on input).
     */
    async insert<T>(
        table: string,
        data: any | any[],
        context: string = `DatabaseService.insert(${table})`
    ): Promise<T | T[] | null> {
        const isArray = Array.isArray(data);

        let resultPromise;
        if (isArray) {
            resultPromise = supabase.from(table).insert(data).select();
        } else {
            resultPromise = supabase.from(table).insert(data).select().single();
        }

        const { data: inserted, error } = await resultPromise;

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la création." });
            return null;
        }
        return inserted as T | T[];
    },

    /**
     * Update a record by ID.
     */
    async update<T>(
        table: string,
        id: string,
        data: Partial<T>,
        context: string = `DatabaseService.update(${table})`
    ): Promise<boolean> {
        const { error } = await supabase
            .from(table)
            .update(data)
            .eq('id', id);

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la mise à jour." });
            return false;
        }
        return true;
    },

    /**
     * Delete a record by ID.
     */
    async delete(
        table: string,
        id: string,
        context: string = `DatabaseService.delete(${table})`
    ): Promise<boolean> {
        const { error } = await supabase
            .from(table)
            .delete()
            .eq('id', id);

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la suppression." });
            return false;
        }
        return true;
    },

    /**
     * Delete multiple records by a specific column filter (e.g. setting_id)
     */
    async deleteBy(
        table: string,
        column: string,
        value: string,
        context: string = `DatabaseService.deleteBy(${table})`
    ): Promise<boolean> {
        const { error } = await supabase
            .from(table)
            .delete()
            .eq(column, value);

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors du nettoyage des données." });
            return false;
        }
        return true;
    },

    /**
     * Upsert a record.
     */
    async upsert<T>(
        table: string,
        data: Partial<T> | any, // Use any for raw data if T is complex, but Partial<T> is preferred
        options: { onConflict?: string, ignoreDuplicates?: boolean } = {},
        context: string = `DatabaseService.upsert(${table})`
    ): Promise<T | null> {
        // Automatically add owner if missing and user is logged in
        if (table === 'characters' && !data.created_by) {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                data.created_by = user.id;
            }
        }

        const { data: result, error } = await supabase
            .from(table)
            .upsert(data, options)
            .select()
            .single();

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la synchronisation (upsert)." });
            return null;
        }
        return result as T;
    },

    /**
     * Check if a table is accessible (HEAD request).
     */
    async checkAvailable(table: string): Promise<boolean> {
        try {
            const { error } = await supabase
                .from(table)
                .select('id', { count: 'exact', head: true });
            return !error;
        } catch {
            return false;
        }
    }
};

export type ErrorSeverity = 'info' | 'warning' | 'error' | 'critical';

export interface ErrorLogOptions {
    context?: string;      // Ex: "CharacterSync", "LibraryLoader"
    userMessage?: string;  // Message friendly pour l'utilisateur
    silent?: boolean;      // Si true, log seulement en console, pas de notification
    error?: unknown;       // L'erreur originale
}

type NotifyFn = (
    message: string,
    type?: 'success' | 'danger' | 'info',
    category?: 'sheet' | 'settings' | 'both',
    deduplicationId?: string
) => void;

export class ErrorService {
    private static notifier: NotifyFn | null = null;

    /**
     * Injecte la fonction de notification (depuis NotificationContext ou CharacterContext)
     */
    static init(notifyFn: NotifyFn) {
        this.notifier = notifyFn;
    }

    /**
     * Log une erreur et notifie l'utilisateur si nécessaire
     */
    static handleError(error: unknown, options: ErrorLogOptions = {}) {
        const { context = 'General', userMessage, silent = false } = options;

        // Extraction du message d'erreur
        const technicalMessage = error instanceof Error
            ? error.message
            : typeof error === 'string'
                ? error
                : JSON.stringify(error);

        // 1. Console Log enrichi
        const isForbidden = technicalMessage.includes('403') || (error as any)?.status === 403 || (error as any)?.code === '42501';

        const timestamp = new Date().toLocaleTimeString();
        console.groupCollapsed(`%c[${timestamp}] [${context}] Error`, 'color: red; font-weight: bold;');
        console.error('Original Error:', error);
        if (userMessage) console.log('User Message:', userMessage);
        if (isForbidden) {
            console.warn('💡 Tip: This 403 error might be due to missing "admin" role in your Supabase app_metadata.');
        }
        console.groupEnd();

        // 2. Notification Utilisateur
        if (!silent && this.notifier) {
            let displayMsg = userMessage || `Erreur (${context}): ${technicalMessage}`;
            if (isForbidden && !userMessage) {
                displayMsg = `Accès refusé (${context}). Vérifiez vos droits administrateur.`;
            } else if (isForbidden) {
                displayMsg += " (Vérifiez vos droits administrateur)";
            }
            // On utilise 'danger' pour les erreurs
            // On log dans 'both' pour être sûr que ce soit visible dans l'historique global
            this.notifier(displayMsg, 'danger', 'both');
        }
    }

    /**
     * Wrapper pour les blocs try/catch
     */
    static async tryCatch<T>(
        promise: Promise<T>,
        options: ErrorLogOptions
    ): Promise<T | null> {
        try {
            return await promise;
        } catch (error) {
            this.handleError(error, options);
            return null;
        }
    }
}

/**
 * ImageCompressionService
 * 
 * Compresses images for efficient storage in database.
 * - Step 1: JPEG compression + resize (preserving aspect ratio)
 * - Step 2: gzip compression of base64 string
 * Total gain: 70-85% size reduction
 */

import pako from 'pako';
import { ErrorService } from './ErrorService';

export const GZIP_MARKER = 'GZIP:';

/**
 * Image compression constants
 * Quality range: 0-1 (0 = worst, 1 = best)
 * 0.8 = good balance between quality and size
 */
const IMAGE_COMPRESSION_CONFIG = {
    // Standard compression for avatars/thumbnails
    STANDARD: {
        quality: 0.5,
        maxWidth: 1200,
        format: 'webp' as const
    },

    // Full resolution for documents/detailed images
    FULL: {
        quality: 0.5,
        maxWidth: 1920,
        format: 'webp' as const
    }
};

export interface CompressionResult {
    compressed: string;
    originalSize: number;
    compressedSize: number;
    compressionRatio: number;
}

export const ImageCompressionService = {

    /**
     * Compress an image (base64) with WebP quality reduction and resize.
     * Preserves aspect ratio - only resizes if width > maxWidth.
     * 
     * @param base64 - Image in base64 format (data:image/...)
     * @param quality - WebP quality (0-1)
     * @param maxWidth - Maximum width in pixels
     * @returns Compressed base64 image
     */
    async compressImage(
        base64: string,
        quality: number = IMAGE_COMPRESSION_CONFIG.STANDARD.quality,
        maxWidth: number = IMAGE_COMPRESSION_CONFIG.STANDARD.maxWidth
    ): Promise<string> {
        return new Promise((resolve, reject) => {
            // Create image element
            const img = new Image();

            img.onload = () => {
                try {
                    // Calculate new dimensions preserving aspect ratio
                    let width = img.width;
                    let height = img.height;

                    if (width > maxWidth) {
                        const ratio = maxWidth / width;
                        width = maxWidth;
                        height = Math.round(height * ratio);
                    }

                    // Create canvas
                    const canvas = document.createElement('canvas');
                    canvas.width = width;
                    canvas.height = height;

                    // Draw and compress
                    const ctx = canvas.getContext('2d');
                    if (!ctx) {
                        reject(new Error('Failed to get canvas context'));
                        return;
                    }

                    ctx.drawImage(img, 0, 0, width, height);

                    // Convert to WebP with quality setting
                    // Fallback to JPEG if WebP is not supported (older browsers)
                    const compressedBase64 = canvas.toDataURL('image/webp', quality);

                    // Basic check: if it turned into png (default fallback), force jpeg
                    if (compressedBase64.startsWith('data:image/png')) {
                        const jpegFallback = canvas.toDataURL('image/jpeg', quality);
                        resolve(jpegFallback);
                    } else {
                        resolve(compressedBase64);
                    }

                } catch (e) {
                    reject(e);
                }
            };

            img.onerror = () => {
                reject(new Error('Failed to load image'));
            };

            img.src = base64;
        });
    },

    /**
     * Compress a base64 string using gzip (lossless).
     * 
     * @param base64 - Base64 string to compress
     * @returns Compressed base64 string with marker
     */
    compressBase64(base64: string): string {
        try {
            // WebP is already highly compressed. GZIP might add overhead or gain little.
            // But we keep it for now as "double safety" especially for the Base64 string overhead.

            // Remove data URL prefix if present
            const base64Data = base64.includes(',')
                ? base64.split(',')[1]
                : base64;

            // Convert base64 to binary
            const binaryString = atob(base64Data);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }

            // Compress with pako (gzip)
            const compressed = pako.gzip(bytes);

            // Convert back to base64
            const compressedBase64 = btoa(
                String.fromCharCode.apply(null, Array.from(compressed))
            );

            // Add marker to identify compressed data
            return `${GZIP_MARKER}${compressedBase64}`;
        } catch (e) {
            ErrorService.handleError(e, { context: 'ImageCompressionService.compressBase64', silent: true });
            return base64; // Return original on error
        }
    },

    /**
     * Decompress a gzip-compressed base64 string.
     * 
     * @param compressed - Compressed string with GZIP: marker
     * @returns Original base64 string
     */
    decompressBase64(compressed: string): string {
        try {
            // Check if data is compressed
            if (!compressed.startsWith(GZIP_MARKER)) {
                return compressed; // Not compressed, return as-is
            }

            // Remove marker
            const compressedData = compressed.substring(GZIP_MARKER.length);

            // Convert base64 to binary
            const binaryString = atob(compressedData);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }

            // Decompress with pako
            const decompressed = pako.ungzip(bytes);

            // Convert back to base64
            return btoa(
                String.fromCharCode.apply(null, Array.from(decompressed))
            );
        } catch (e) {
            ErrorService.handleError(e, { context: 'ImageCompressionService.decompressBase64', silent: true });
            return compressed; // Return original on error
        }
    },

    /**
     * Full compression pipeline: Image compression + gzip.
     * 
     * @param base64 - Original image base64
     * @param quality - JPEG quality (0-1)
     * @param maxWidth - Maximum width
     * @returns Compression result with stats
     */
    async compressFull(
        base64: string,
        quality: number = IMAGE_COMPRESSION_CONFIG.FULL.quality,
        maxWidth: number = IMAGE_COMPRESSION_CONFIG.FULL.maxWidth
    ): Promise<CompressionResult> {
        const originalSize = base64.length;

        // Step 1: Image compression
        const imageCompressed = await this.compressImage(base64, quality, maxWidth);

        // Step 2: gzip compression
        const fullyCompressed = this.compressBase64(imageCompressed);

        const compressedSize = fullyCompressed.length;
        const compressionRatio = ((originalSize - compressedSize) / originalSize) * 100;

        return {
            compressed: fullyCompressed,
            originalSize,
            compressedSize,
            compressionRatio
        };
    },

    /**
     * Decompress data from full compression pipeline.
     * 
     * @param compressed - Fully compressed data
     * @returns Decompressed base64 image
     */
    decompressFull(compressed: string): string {
        // Only need to decompress gzip layer
        // Image compression is lossy and permanent
        return this.decompressBase64(compressed);
    },

    /**
     * Recursively process an object to compress/decompress image strings.
     * Moves this logic from CharacterSyncService to be reusable.
     */
    async processImages(obj: any, action: 'compress' | 'decompress'): Promise<any> {
        if (!obj || typeof obj !== 'object') return obj;

        if (Array.isArray(obj)) {
            return Promise.all(obj.map(item => this.processImages(item, action)));
        }

        const processed: any = {};
        for (const [key, value] of Object.entries(obj)) {
            if (typeof value === 'string') {
                if (action === 'compress' && value.startsWith('data:image/')) {
                    const result = await this.compressFull(value);
                    processed[key] = result.compressed;
                } else if (action === 'compress' && value.startsWith(GZIP_MARKER)) {
                    // ALREADY COMPRESSED - SKIP to avoid generation loss
                    processed[key] = value;
                } else if (action === 'decompress' && value.startsWith(GZIP_MARKER)) {
                    processed[key] = this.decompressFull(value);
                } else {
                    processed[key] = value;
                }
            } else if (typeof value === 'object') {
                processed[key] = await this.processImages(value, action);
            } else {
                processed[key] = value;
            }
        }
        return processed;
    }
};

import { getImage, saveImage, blobToBase64, base64ToBlob } from '../imageDB';
import { GZIP_MARKER, ImageCompressionService } from './ImageCompressionService';
import { logger } from '../utils/logger';

/**
 * ImageSyncResolver
 * 
 * Orchestrates the conversion between local IndexedDB image references (imageId)
 * and compressed data strings used for cloud synchronization.
 */
export const ImageSyncResolver = {

    /**
     * Finds all imageId references in the data and replaces them with compressed WebP+GZIP strings.
     * This makes the character data "portable" for cloud sync.
     */
    async resolveImagesForSync(data: unknown): Promise<unknown> {
        if (!data || typeof data !== 'object' || data === null) return data;

        if (Array.isArray(data)) {
            return Promise.all(data.map(item => this.resolveImagesForSync(item)));
        }

        const obj = data as Record<string, unknown>;
        const processed: Record<string, unknown> = {};

        for (const [key, value] of Object.entries(obj)) {
            // Case 1: Portrait Image ID
            if (key === 'characterImageId' && typeof value === 'string' && value.startsWith('img_')) {
                try {
                    const blob = await getImage(value);
                    if (blob) {
                        const base64 = await blobToBase64(blob);
                        const result = await ImageCompressionService.compressFull(base64);
                        processed[key] = result.compressed;
                        // Clear legacy carrier image if it exists in the same object
                        if (obj.characterImage !== undefined) processed.characterImage = '';
                    } else {
                        processed[key] = value;
                    }
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to resolve portrait image:", e);
                    processed[key] = value;
                }
            }
            // Case 2: Grimoire Image Node (Tiptap bookImage)
            else if (key === 'type' && value === 'bookImage' && (obj.attrs as Record<string, any> | undefined)?.imageId) {
                try {
                    const attrs = obj.attrs as Record<string, any>;
                    const imageId = attrs.imageId;
                    if (typeof imageId === 'string' && imageId.startsWith('img_')) {
                        const blob = await getImage(imageId);
                        if (blob) {
                            const base64 = await blobToBase64(blob);
                            const result = await ImageCompressionService.compressFull(base64);

                            processed.type = 'bookImage';
                            processed.attrs = {
                                ...attrs,
                                imageId: result.compressed // Replace ID with compressed data for sync
                            };

                            // Copy any other node properties (content, marks, etc)
                            for (const k of Object.keys(obj)) {
                                if (k !== 'type' && k !== 'attrs') processed[k] = obj[k];
                            }
                            return processed;
                        }
                    }
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to resolve book image:", e);
                }
                processed[key] = value;
            }
            // Case 3: Generic Base64 Image (any other field)
            else if (typeof value === 'string' && value.startsWith('data:image/')) {
                try {
                    const result = await ImageCompressionService.compressFull(value);
                    processed[key] = result.compressed;
                } catch (e) {
                    processed[key] = value;
                }
            }
            // Standard recursion
            else if (typeof value === 'object' && value !== null) {
                processed[key] = await this.resolveImagesForSync(value);
            } else {
                processed[key] = value;
            }
        }
        return processed;
    },

    /**
     * Finds all compressed image strings (GZIP:...) in the data, saves them to IndexedDB,
     * and replaces them with local imageIds.
     */
    async injectImagesAfterSync(data: unknown): Promise<unknown> {
        if (!data || typeof data !== 'object' || data === null) return data;

        if (Array.isArray(data)) {
            return Promise.all(data.map(item => this.injectImagesAfterSync(item)));
        }

        const obj = data as Record<string, unknown>;
        const processed: Record<string, unknown> = {};

        for (const [key, value] of Object.entries(obj)) {
            // Case 1: Portrait (compressed string in characterImageId field)
            if (key === 'characterImageId' && typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    const blob = await base64ToBlob(value);
                    const newId = await saveImage(blob);
                    processed[key] = newId;
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject portrait image:", e);
                    processed[key] = '';
                }
            }
            // Case 2: Grimoire Image Node (compressed string in imageId attr)
            else if (key === 'type' && value === 'bookImage' && (obj.attrs as Record<string, any> | undefined)?.imageId?.startsWith?.(GZIP_MARKER)) {
                try {
                    const attrs = obj.attrs as Record<string, any>;
                    const compressed = attrs.imageId;
                    const blob = await base64ToBlob(compressed);
                    const newId = await saveImage(blob);

                    processed.type = 'bookImage';
                    processed.attrs = {
                        ...attrs,
                        imageId: newId // Replace compressed data with local ID
                    };

                    for (const k of Object.keys(obj)) {
                        if (k !== 'type' && k !== 'attrs') processed[k] = obj[k];
                    }
                    return processed;
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject book image:", e);
                }
                processed[key] = value;
            }
            // Case 3: Generic Compressed Image
            else if (typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    processed[key] = ImageCompressionService.decompressFull(value);
                } catch (e) {
                    processed[key] = value;
                }
            }
            // Standard recursion
            else if (typeof value === 'object' && value !== null) {
                processed[key] = await this.injectImagesAfterSync(value);
            } else {
                processed[key] = value;
            }
        }
        return processed;
    }
};

import { CharacterSheetData, ExperienceData, TraitEffect, SkillCategoryKey, DotEntry, RulesData } from '../types';
import { normalizeString } from '../utils/stringUtils';

/**
 * Service centralisant les formules de calcul des règles du jeu.
 * Utilisé par la feuille de personnage (Joueur) et l'éditeur de règles (Admin).
 */
export const RuleCalculationsService = {

    /**
     * Calcule la somme triangulaire : n + (n-1) + ... + 1
     */
    triangular(n: number): number {
        return (n * (n + 1)) / 2;
    },

    /**
     * Calcule le coût en XP pour passer d'un niveau de création à un niveau actuel
     */
    getXPCost(currentValue: number, creationValue: number = 0, factor: number = 1.0, useTriangular: boolean = true): number {
        if (currentValue === 0 || currentValue <= creationValue) return 0;

        if (useTriangular) {
            const baseCost = this.triangular(currentValue) - this.triangular(creationValue);
            return baseCost * factor;
        } else {
            // Coût linéaire
            const diff = Math.max(0, currentValue - creationValue);
            return diff * factor;
        }
    },

    /**
     * Calcule le bilan d'XP complet pour un personnage
     */
    calculateExperienceResults(data: CharacterSheetData, rules?: RulesData): ExperienceData {
        // 0. Extraction des effets actifs des traits
        const activeEffects: TraitEffect[] = [];
        const findEffects = (traitName: string) => {
            if (!traitName) return;
            const entry = data.library?.find(l => l.name.trim().toLowerCase() === traitName.trim().toLowerCase());
            if (entry && entry.effects) {
                entry.effects.forEach(e => activeEffects.push(e));
            }
        };

        data.page2?.avantages?.forEach(t => findEffects(t.name));
        data.page2?.desavantages?.forEach(t => findEffects(t.name));

        const traitXPBonus = activeEffects
            .filter(e => e.type === 'xp_bonus')
            .reduce((sum, e) => sum + e.value, 0);

        // 1. Calcul de l'XP dépensée
        let totalSpent = 0;
        const skillFactor = data.xpCosts?.skillFactor ?? 1.0;
        const specFactor = data.xpCosts?.specializationFactor ?? 0.5;

        // Helpers pour les bonus
        const getFreeRankLimit = (skillName: string) => {
            const effect = activeEffects.find(e =>
                e.type === 'free_skill_rank' &&
                e.target &&
                skillName.trim().toLowerCase() === e.target.trim().toLowerCase()
            );
            return effect ? effect.value : 0;
        };

        const getAttributeBonus = (attrName: string) => {
            const effect = activeEffects.find(e =>
                e.type === 'attribute_bonus' &&
                e.target &&
                attrName.trim().toLowerCase() === e.target.trim().toLowerCase()
            );
            return effect ? effect.value : 0;
        };

        // Set of handled counter IDs to avoid double-counting
        const handledCounters = new Set<string>();

        // Calcul des Compétences basé sur skillCategories (Dynamique)
        const categories = rules?.definitions?.skillCategories;

        if (categories && categories.length > 0) {
            categories.forEach(cat => {
                const skillList = data.skills[cat.id];
                if (!Array.isArray(skillList)) return;

                const multiplier = cat.costConfig?.factor ?? 1.0;
                const isTriangular = cat.costConfig?.type === 'triangular';
                const behavior = cat.behavior;

                skillList.forEach(skill => {
                    const freeLimit = getFreeRankLimit(skill.name);
                    const effectiveCreationValue = Math.max(skill.creationValue || 0, freeLimit);

                    let baseFactor = multiplier;

                    // Apply Base * Multiplier logic based on behavior
                    if (behavior === 'Arrière-plan') {
                        // Base for backgrounds is backgroundCost from config
                        const baseCost = data.creationConfig?.backgroundCost ?? 2;
                        baseFactor = baseCost * multiplier;
                    }

                    if (behavior === 'Compteur') {
                        // Base for counters is defined in counter definition (System or Library)
                        // Prioritize Library Definition
                        const rulesCounters = rules?.definitions?.counters || {};
                        const libCounters = rules?.libraries?.counters || [];

                        const sysDef = rulesCounters[skill.id];
                        const displayName = skill.name || sysDef?.name || skill.id;

                        const libDef = libCounters.find(c => c.id === skill.id)
                            || libCounters.find(c => normalizeString(c.name) === normalizeString(displayName));

                        const baseCost = libDef?.xpCost !== undefined ? libDef.xpCost : (sysDef?.xpCost ?? 5);


                        const freeBase = libDef?.defaultValue !== undefined ? libDef.defaultValue : (sysDef?.defaultValue ?? 0);

                        // Effective creation value is MAX(creationValue, defaultValue)
                        // If user created at 0 but default is 3, they get 3 for free.
                        const effectiveBase = Math.max(skill.creationValue || 0, freeBase);

                        baseFactor = baseCost * multiplier;
                        handledCounters.add(skill.id);

                        const valCost = this.getXPCost(skill.value, effectiveBase, baseFactor, false);
                        totalSpent += valCost;
                    } else {
                        // Standard calculation (Normal Skills, Backgrounds, etc.)
                        totalSpent += this.getXPCost(skill.value, effectiveCreationValue, baseFactor, isTriangular);
                    }
                });
            });
        } else {
            // Fallback Legacy (Anciens persos ou règles sans skillCategories)
            const standardCategories = ['talents', 'competences', 'competences_col_2', 'connaissances', 'autres_competences', 'autres', 'Col_Comp_1', 'Col_Comp_2', 'Col_Comp_3', 'Col_Comp_4', 'Col_Comp_5', 'Col_Comp_7'];
            standardCategories.forEach(key => {
                const list = data.skills[key];
                if (Array.isArray(list)) {
                    list.forEach(skill => {
                        const freeLimit = getFreeRankLimit(skill.name);
                        const effectiveCreationValue = Math.max(skill.creationValue || 0, freeLimit);
                        totalSpent += this.getXPCost(skill.value, effectiveCreationValue, skillFactor, true);
                    });
                }
            });

            const secondSkills = data.skills.competences2 || data.skills.Col_Comp_6;
            if (Array.isArray(secondSkills)) {
                secondSkills.forEach(skill => {
                    const freeLimit = getFreeRankLimit(skill.name);
                    const effectiveCreationValue = Math.max(skill.creationValue || 0, freeLimit);
                    totalSpent += this.getXPCost(skill.value, effectiveCreationValue, specFactor, true);
                });
            }

            const bgCostBase = data.creationConfig?.backgroundCost ?? 2;
            const backgroundSkills = data.skills.arrieres_plans || data.skills.Col_Comp_8;
            if (Array.isArray(backgroundSkills)) {
                backgroundSkills.forEach(skill => {
                    // Legacy fallback: assume multiplier 1 if not in categories
                    totalSpent += this.getXPCost(skill.value, skill.creationValue || 0, bgCostBase, false);
                });
            }
        }

        // Compteurs (traitement des compteurs restant non gérés dans les catégories)
        // Priorité : Bibliothèque (Custom) > Définitions (System)
        const rulesCounters = rules?.definitions?.counters || {};
        const libCounters = rules?.libraries?.counters || [];

        if (data.counters) {
            Object.keys(data.counters).forEach(key => {
                if (key === 'custom' || handledCounters.has(key)) return;

                const counterEntry = data.counters[key];

                // Guard against Array (should not happen for non-custom ID but types say DotEntry | DotEntry[])
                if (Array.isArray(counterEntry)) return;

                // Find definition: definitions first, then library fallback? 
                // OR Library override? usually Library overrides system defaults in this app design.
                // Lookup strict ID first, then fuzzy name match using normalization (accent insensitive)
                const sysDef = rulesCounters[key];
                const displayName = counterEntry.name || sysDef?.name || key;

                const libDef = libCounters.find(c => c.id === key)
                    || libCounters.find(c => normalizeString(c.name) === normalizeString(displayName));


                const xpCost = libDef?.xpCost !== undefined ? libDef.xpCost : (sysDef?.xpCost ?? 0);


                if (counterEntry && !Array.isArray(counterEntry) && xpCost > 0) {
                    // Check if this counter is assigned to a category to get its multiplier
                    let multiplier = 1.0;
                    const catId = Object.keys(data.skills).find(cid => {
                        const list = data.skills[cid];
                        return Array.isArray(list) && list.some(s => s.id === key);
                    });

                    if (catId && categories) {
                        const cat = categories.find(c => c.id === catId);
                        if (cat) multiplier = cat.costConfig?.factor ?? 1.0;
                    }

                    totalSpent += this.getXPCost(counterEntry.value, counterEntry.creationValue || 0, xpCost * multiplier, false);
                }
            });

            // Traitement des compteurs "Custom" (Legacy / Ad-hoc)
            if (data.counters.custom && Array.isArray(data.counters.custom)) {
                data.counters.custom.forEach(counter => {
                    // Ignorer si déjà traité (peu probable car custom n'est pas une clé racine, mais sécurité)
                    if (handledCounters.has(counter.id)) return;


                    // Recherche de définition (Bibliothèque)
                    const libDef = libCounters.find(c => c.id === counter.id)
                        || libCounters.find(c => normalizeString(c.name) === normalizeString(counter.name));


                    // Fallback vers définition système (via nom)
                    const sysDef = Object.values(rulesCounters).find(c => c.name === counter.name);

                    // Coût XP effectif
                    const xpCost = libDef?.xpCost !== undefined ? libDef.xpCost : (sysDef?.xpCost ?? 0);


                    if (xpCost > 0) {
                        // Compteur Custom = Toujours facteur 1.0 (sauf si un jour on les lie aux catégories, mais c'est le cas désactivé plus haut)
                        // On ne vérifie pas l'appartenance à une catégorie pour les "custom array" car ils ne devraient pas y être (c'est les IDs système qui y sont).

                        // Base de calcul : Max(creationValue, defaultValue du modèle)
                        // Souvent pour custom, creationValue est 0 ou correct.
                        const modelDefault = libDef?.defaultValue ?? (sysDef?.defaultValue ?? 0);
                        const creationValue = Math.max(counter.creationValue || 0, modelDefault);

                        const cost = this.getXPCost(counter.value, creationValue, xpCost, false);

                        totalSpent += cost;
                    }
                });
            }
        }

        // Spécialisations (Coût 0 par défaut)
        const specs = data.specializations || {};
        Object.values(specs).forEach(list => {
            // Les spécialisations ne coûtent plus d'XP
            totalSpent += 0;
        });

        // Attributs (Coût Linéaire)
        if (data.attributeSettings) {
            data.attributeSettings.forEach(cat => {
                const attrs = data.attributes[cat.id];
                const secAttrs = data.secondaryAttributesActive ? data.secondaryAttributes[cat.id] : [];
                const allAttrs = [...(attrs || []), ...(secAttrs || [])];

                if (allAttrs) {
                    allAttrs.forEach(attr => {
                        const val = parseInt(attr.val1) || 0;
                        const bonus = getAttributeBonus(attr.name);
                        const effectiveCreation = (attr.creationVal1 || 0) + bonus;
                        const costPerPoint = data.xpCosts?.attributeFactor ?? 6;
                        totalSpent += this.getXPCost(val, effectiveCreation, costPerPoint, false);
                    });
                }
            });
        }

        const gainFromLogs = (data.xpLogs || []).reduce((sum, entry) => sum + (entry.amount || 0), 0);
        const totalGain = gainFromLogs + traitXPBonus;

        return {
            gain: traitXPBonus > 0 ? `${gainFromLogs} (+${traitXPBonus})` : gainFromLogs.toString(),
            spent: totalSpent.toString(),
            rest: (totalGain - totalSpent).toString()
        };
    },

    /**
     * Calcule la valeur de la carte de tarot basée sur les meilleures compétences
     */
    calculateCardValue(data: CharacterSheetData, rules: RulesData | null): string | null {
        const cardConfig = data.creationConfig?.cardConfig;
        if (!cardConfig || !cardConfig.active) return null;

        const cardSkills: number[] = [];
        const rulesCategories = data.skills;

        Object.keys(rulesCategories).forEach(key => {
            // On ignore les arrière-plans et compteurs pour le tarot (Logique métier)
            const catConfig = data.creationConfig?.rankSlots ? rules?.definitions?.skillCategories?.find(c => c.id === key) : null;
            if (catConfig && (catConfig.behavior === 'Arrière-plan' || catConfig.behavior === 'Compteur')) return;

            // Fallback pour anciens IDs
            if (key === 'arrieres_plans' || key === 'counters' || key === 'Col_Comp_8' || key === 'Col_Comp_9') return;

            const list = rulesCategories[key] || [];
            list.forEach((skill: DotEntry) => {
                if (skill.name && skill.value > 0) {
                    cardSkills.push(skill.value);
                }
            });
        });

        cardSkills.sort((a, b) => b - a);
        const n = cardConfig.bestSkillsCount || 3;
        const topSkills = cardSkills.slice(0, n);
        while (topSkills.length < n) topSkills.push(0);

        const average = topSkills.reduce((a, b) => a + b, 0) / n;
        const delta = average - cardConfig.baseStart;
        const steps = Math.floor((delta + 0.0001) / cardConfig.increment);

        if (steps < 1) return "Aucune";

        const globalIndex = steps - 1;
        const rankIndex = Math.floor(globalIndex / 4);
        const countIndex = globalIndex % 4;

        const counts = ["Un", "Deux", "Trois", "Quatre"];
        const ranksSingular = ["Valet", "Dame", "Roi"];
        const ranksPlural = ["Valets", "Dames", "Rois"];

        if (rankIndex < 3) {
            const countStr = counts[countIndex];
            const rankStr = countIndex === 0 ? ranksSingular[rankIndex] : ranksPlural[rankIndex];
            return `${countStr} ${rankStr}`;
        }
        return "Quatre Rois (Max)";
    }
};

