            expect(result).toEqual({ ...mockCachedRules, source: 'cache' });
        });

        it('should load specific setting from cache when offline and settingId provided', async () => {
            const settingId = 'test-setting-id';
            const mockCachedRules = { ...defaultRules, settingId, version: '1.0.0' };
            (OfflineStorageService.getRulesBySettingId as Mock).mockResolvedValue(mockCachedRules);

            const result = await loadRules(settingId);

            expect(OfflineStorageService.getRulesBySettingId).toHaveBeenCalledWith(settingId);
            expect(result).toEqual({ ...mockCachedRules, source: 'cache' });
        });

        it('should fallback to default rules when offline and no cache', async () => {
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(null);

            const result = await loadRules();

            expect(result).toEqual(defaultRules);
        });
    });

    describe('Online Mode - GitHub API Strategy', () => {
        it('should fetch from GitHub API if not rate limited', async () => {
            const mockApiRules = { ...defaultRules, version: '2.0.0' };
            mockFetch.mockResolvedValueOnce({
                ok: true,
                json: async () => mockApiRules
            });

            const result = await loadRules();

            expect(mockFetch).toHaveBeenCalledWith(expect.stringContaining('api.github.com'), expect.anything());
            expect(result).toEqual({ ...mockApiRules, source: 'api' });
        });

        it('should handle API rate limit (403) and fallback to Raw CDN', async () => {
            // API Fails with 403
            mockFetch.mockResolvedValueOnce({
                ok: false,
                status: 403
            });

            // Raw CDN Success
            const mockRawRules = { ...defaultRules, version: '3.0.0' };
            mockFetch.mockResolvedValueOnce({
                ok: true,
                json: async () => mockRawRules
            });

            const result = await loadRules();

            expect(GithubRateLimiter.setLimited).toHaveBeenCalled();
            expect(result).toEqual({ ...mockRawRules, source: 'api' });
        });

        it('should skip API if already rate limited', async () => {
            (GithubRateLimiter.isLimited as Mock).mockReturnValue(true);

            // Raw CDN Success
            const mockRawRules = { ...defaultRules, version: '4.0.0' };
            mockFetch.mockResolvedValueOnce({
                ok: true,
                json: async () => mockRawRules
            });

            const result = await loadRules();

            // Verify call URL instead of strict count
            const callUrls = mockFetch.mock.calls.map((c: any) => c[0]);
            const hasApi = callUrls.some((url: string) => url.includes('api.github.com'));
            const hasRaw = callUrls.some((url: string) => url.includes('raw.githubusercontent.com'));

            expect(hasApi).toBe(false);
            expect(hasRaw).toBe(true);
            expect(result).toEqual({ ...mockRawRules, source: 'api' });
        });
    });

    describe('Last Resort', () => {
        it('should fallback to general cache if online fetch fails', async () => {
            // API Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));
            // Raw Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));

            const mockCachedRules = { ...defaultRules, version: 'cache-v1' };
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(mockCachedRules);

            const result = await loadRules();

            expect(OfflineStorageService.getActiveRules).toHaveBeenCalled();
            expect(result).toEqual(mockCachedRules);
        });

        it('should return defaultRules if absolutely all else fails', async () => {
            // API Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));
            // Raw Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));

            // Cache Fails
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(null);

            const result = await loadRules();

            expect(result).toEqual(defaultRules);
        });
    });
});

import { DatabaseService } from '../DatabaseService';
import { LibraryEntry as LibraryTraitEntry, LibrarySkillEntry, LibrarySpecializationEntry, LibraryBackgroundEntry, LibraryCounterEntry } from '../../types/system';
import { ErrorService } from '../ErrorService';

import { normalizeString } from '../../utils/stringUtils';
import { logger } from '../../utils/logger';

const ensureUUID = (id: string | undefined): string => {
    if (!id) return crypto.randomUUID();
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (uuidRegex.test(id)) return id;
    logger.warn(`[LibraryImporter] Legacy ID detected (${id}), replacing with UUID`);
    return crypto.randomUUID();
};

// Helper to check duplicates against DB
const filterDuplicates = async <T extends { name: string }>(table: string, targetId: string | null, newItems: T[]): Promise<T[]> => {
    if (newItems.length === 0) return [];

    // Check both ID and Name to be safe
    const query = targetId ? { eq: { setting_id: targetId } } : { eq: { setting_id: null } };

    // We fetch existing names.
    // Note: This isn't perfect if names are very similar but not identical, but `normalizeString` helps.
    const existing = await DatabaseService.fetchAll<{ name: string }>(table, { ...query, select: 'name' }, 'LibraryImporter.checkDupes');
    const existingNames = new Set(existing.map(e => normalizeString(e.name)));

    return newItems.filter(item => !existingNames.has(normalizeString(item.name)));
};

export const LibraryImporter = {
    /**
     * Partial Imports: Add items to libraries without overwriting existing ones.
     */
    async importTraits(targetId: string | null, traits: LibraryTraitEntry[], linkToSettingId?: string): Promise<boolean> {
        if (traits.length === 0) return true;
        const payload = traits.map(t => ({
            setting_id: targetId,
            id: ensureUUID(t.id),
            type: t.type,
            name: t.name,
            cost: t.cost,
            description: t.description || '',
            tags: t.tags || [],
            is_variable: t.isVariable || false,
            effects: t.effects || []
        }));

        const uniquePayload = await filterDuplicates('libraries_traits', targetId, payload);

        // If nothing new to insert, we can still proceed to check links if needed, 
        // but typically we only link what we just inserted or if we know it exists.
        // However, if it was a duplicate, it implies it's already there. 
        // For simplicity and safety (avoiding duplicate primary key errors if we tried to re-insert), we only insert unique.

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_traits', uniquePayload, 'LibraryImporter.importTraits'));
        }

        if (!result) return false;

        // Auto-link if global import but triggered from a campaign
        // Only link the ones we intended to import (even if they were duplicates, we might want to link them? 
        // The original logic only linked what was *inserted*). 
        // The prompt implies we want to prevent adding *duplicates* to the library.
        // If it's already in the library, rel-linking it might be redundant or handled elsewhere?
        // Let's stick to linking only what we successfully processed (or verified as existing?).
        // Actually, if it's a duplicate, it means it exists. We might still want to link it if `linkToSettingId` is provided.
        // But `uniquePayload` only contains NEW items.
        // If we want to link EXISTING items too, we'd need their IDs.
        // For now, let's stick to the pattern: Only insert and link validation for NEW items.
        // (If the user wants to link an existing global item, that's a different operation usually).

        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, trait_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_traits', relPayload, 'LibraryImporter.importTraits.link');
        }

        return true;
    },

    async importSkills(targetId: string | null, skills: LibrarySkillEntry[], linkToSettingId?: string): Promise<boolean> {
        if (skills.length === 0) return true;

        const payload = skills.map(s => ({
            setting_id: targetId,
            id: ensureUUID(s.id),
            name: s.name,
            description: s.description,
            default_category: s.defaultCategory,
            is_variable: s.isVariable
        }));

        const uniquePayload = await filterDuplicates('libraries_skills', targetId, payload);

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_skills', uniquePayload, 'LibraryImporter.importSkills'));
        }
        if (!result) return false;

        // Auto-link if global
        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, skill_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_skills', relPayload, 'LibraryImporter.importSkills.link');
        }

        return true;
    },

    async importSpecializations(targetId: string | null, specs: LibrarySpecializationEntry[], linkToSettingId?: string): Promise<boolean> {
        if (specs.length === 0) return true;
        const payload = specs.map(s => ({
            setting_id: targetId,
            id: ensureUUID(s.id),
            name: s.name,
            description: s.description,
            skill_ids: s.skillIds || [],
            default_min_level: s.defaultMinLevel || 1
        }));

        const uniquePayload = await filterDuplicates('libraries_specializations', targetId, payload);

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_specializations', uniquePayload, 'LibraryImporter.importSpecializations'));
        }
        if (!result) return false;

        // Auto-link if global
        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, specialization_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_specializations', relPayload, 'LibraryImporter.importSpecializations.link');
        }

        return true;
    },

    async importBackgrounds(targetId: string | null, backgrounds: LibraryBackgroundEntry[], linkToSettingId?: string): Promise<boolean> {
        if (backgrounds.length === 0) return true;
        const payload = backgrounds.map(b => ({
            setting_id: targetId,
            id: ensureUUID(b.id),
            name: b.name,
            description: b.description,
            is_variable: b.isVariable || false
        }));

        const uniquePayload = await filterDuplicates('libraries_backgrounds', targetId, payload);

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_backgrounds', uniquePayload, 'LibraryImporter.importBackgrounds'));
        }
        if (!result) return false;

        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, background_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_backgrounds', relPayload, 'LibraryImporter.importBackgrounds.link');
        }

        return true;
    },

    async importCounters(targetId: string | null, counters: LibraryCounterEntry[], linkToSettingId?: string): Promise<boolean> {
        if (counters.length === 0) return true;
        const payload = counters.map(c => ({
            setting_id: targetId,
            id: ensureUUID(c.id),
            name: c.name,
            description: c.description,
            max_value: c.maxValue || 10,
            default_value: c.defaultValue || 0,
            xp_cost: c.xpCost || 0
        }));

        const uniquePayload = await filterDuplicates('libraries_counters', targetId, payload);

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_counters', uniquePayload, 'LibraryImporter.importCounters'));
        }
        if (!result) return false;

        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, counter_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_counters', relPayload, 'LibraryImporter.importCounters.link');
        }

        return true;
    }
};

import { supabase } from '../supabase';
import { DatabaseService } from '../DatabaseService';
import { RulesData } from '../../types/rules';
import { LibraryMapper } from './LibraryMapper';
import { ErrorService } from '../ErrorService';
import {
    DBTrait, DBSkill, DBSpecialization, DBBackground, DBCounter,
    RelSettingTrait, RelSettingSkill, RelSettingSpecialization,
    RelSettingBackground, RelSettingCounter,
    DBTraitVariant, DBSkillVariant, DBBackgroundVariant
} from '../../types/database';
import {
    TABLE_LIBRARIES_TRAITS, TABLE_LIBRARIES_SKILLS, TABLE_LIBRARIES_SPECIALIZATIONS, TABLE_LIBRARIES_BACKGROUNDS, TABLE_LIBRARIES_COUNTERS,
    TABLE_REL_SETTING_TRAITS, TABLE_REL_SETTING_SKILLS, TABLE_REL_SETTING_SPECIALIZATIONS, TABLE_REL_SETTING_BACKGROUNDS, TABLE_REL_SETTING_COUNTERS,
    TABLE_LIBRARIES_TRAITS_VARIANTS, TABLE_LIBRARIES_SKILLS_VARIANTS, TABLE_LIBRARIES_BACKGROUNDS_VARIANTS
} from '../../constants/db';

export const LibraryLoader = {
    /**
     * Load libraries for a specific setting and map them to RulesData format
     */
    async loadLibraries(settingId: string): Promise<RulesData['libraries']> {
        const orFilter = `setting_id.eq.${settingId},setting_id.is.null`;

        try {
            const [
                traits, skills, specs,
                relTraits, relSkills, relSpecs,
                backgrounds, relBackgrounds, counters, relCounters,
                traitVariants, skillVariants, bgVariants
            ] = await Promise.all([
                DatabaseService.fetchAll<DBTrait>(TABLE_LIBRARIES_TRAITS, { or: orFilter }, 'LibraryLoader.loadTraits'),
                DatabaseService.fetchAll<DBSkill>(TABLE_LIBRARIES_SKILLS, { or: orFilter }, 'LibraryLoader.loadSkills'),
                DatabaseService.fetchAll<DBSpecialization>(TABLE_LIBRARIES_SPECIALIZATIONS, { or: orFilter }, 'LibraryLoader.loadSpecs'),
                DatabaseService.fetchAll<RelSettingTrait>(TABLE_REL_SETTING_TRAITS, { eq: { setting_id: settingId } }, 'LibraryLoader.relTraits'),
                DatabaseService.fetchAll<RelSettingSkill>(TABLE_REL_SETTING_SKILLS, { eq: { setting_id: settingId } }, 'LibraryLoader.relSkills'),
                DatabaseService.fetchAll<RelSettingSpecialization>(TABLE_REL_SETTING_SPECIALIZATIONS, { eq: { setting_id: settingId } }, 'LibraryLoader.relSpecs'),
                DatabaseService.fetchAll<DBBackground>(TABLE_LIBRARIES_BACKGROUNDS, { or: orFilter }, 'LibraryLoader.loadBackgrounds'),
                DatabaseService.fetchAll<RelSettingBackground>(TABLE_REL_SETTING_BACKGROUNDS, { eq: { setting_id: settingId } }, 'LibraryLoader.relBackgrounds'),
                DatabaseService.fetchAll<DBCounter>(TABLE_LIBRARIES_COUNTERS, { or: orFilter }, 'LibraryLoader.loadCounters'),
                DatabaseService.fetchAll<RelSettingCounter>(TABLE_REL_SETTING_COUNTERS, { eq: { setting_id: settingId } }, 'LibraryLoader.relCounters'),
                DatabaseService.fetchAll<DBTraitVariant>(TABLE_LIBRARIES_TRAITS_VARIANTS, { or: orFilter, select: 'trait_id, name' }, 'LibraryLoader.loadTraitsVariants'),
                DatabaseService.fetchAll<DBSkillVariant>(TABLE_LIBRARIES_SKILLS_VARIANTS, { or: orFilter, select: 'skill_id, name' }, 'LibraryLoader.loadSkillsVariants'),
                DatabaseService.fetchAll<DBBackgroundVariant>(TABLE_LIBRARIES_BACKGROUNDS_VARIANTS, { or: orFilter, select: 'background_id, name' }, 'LibraryLoader.loadBgVariants')
            ]);

            const traitVarMap = new Map<string, string[]>();
            traitVariants.forEach((v: DBTraitVariant) => {
                const list = traitVarMap.get(v.trait_id) || [];
                if (!list.includes(v.name)) {
                    list.push(v.name);
                    traitVarMap.set(v.trait_id, list);
                }
            });

            const skillVarMap = new Map<string, string[]>();
            skillVariants.forEach((v: DBSkillVariant) => {
                const list = skillVarMap.get(v.skill_id) || [];
                if (!list.includes(v.name)) {
                    list.push(v.name);
                    skillVarMap.set(v.skill_id, list);
                }
            });

            const bgVarMap = new Map<string, string[]>();
            bgVariants.forEach((v: DBBackgroundVariant) => {
                const list = bgVarMap.get(v.background_id) || [];
                if (!list.includes(v.name)) {
                    list.push(v.name);
                    bgVarMap.set(v.background_id, list);
                }
            });

            const activeTraitIds = new Set<string>(relTraits.map((r: RelSettingTrait) => r.trait_id));
            const activeSkillIds = new Set<string>(relSkills.map((r: RelSettingSkill) => r.skill_id));
            const activeSpecIds = new Set<string>(relSpecs.map((r: RelSettingSpecialization) => r.specialization_id));
            const activeBgIds = new Set<string>(relBackgrounds.map((r: RelSettingBackground) => r.background_id));
            const activeCounterIds = new Set<string>(relCounters.map((r: RelSettingCounter) => r.counter_id));

            const skillDefaultMap = new Map<string, string>(relSkills.map((r: RelSettingSkill) => [r.skill_id, r.default_category]));
            const bgDefaultMap = new Map<string, string>(relBackgrounds.map((r: RelSettingBackground) => [r.background_id, r.default_category]));
            const counterDefaultMap = new Map<string, string>(relCounters.map((r: RelSettingCounter) => [r.counter_id, r.default_category]));

            return {
                traits: traits.map((t: DBTrait) => LibraryMapper.mapTrait(t, activeTraitIds, settingId, traitVarMap.get(t.id))).sort((a, b) => a.name.localeCompare(b.name)),
                skills: skills.map((s: DBSkill) => LibraryMapper.mapSkill(s, activeSkillIds, settingId, skillVarMap.get(s.id), skillDefaultMap.get(s.id))).sort((a, b) => a.name.localeCompare(b.name)),
                specializations: specs.map((s: DBSpecialization) => LibraryMapper.mapSpec(s, activeSpecIds, settingId)).sort((a, b) => a.name.localeCompare(b.name)),
                backgrounds: backgrounds.map((b: DBBackground) => LibraryMapper.mapBackground(b, activeBgIds, settingId, bgVarMap.get(b.id), bgDefaultMap.get(b.id))).sort((a, b) => a.name.localeCompare(b.name)),
                counters: counters.map((c: DBCounter) => LibraryMapper.mapCounter(c, activeCounterIds, settingId, counterDefaultMap.get(c.id))).sort((a, b) => a.name.localeCompare(b.name))
            };
        } catch (error) {
            ErrorService.handleError(error, {
                context: 'LibraryLoader.loadLibraries',
                userMessage: 'Erreur de chargement des bibliothèques'
            });
            return { traits: [], skills: [], specializations: [], backgrounds: [], counters: [] };
        }
    },

    /**
     * Get usage statistics from all settings except the current one
     */
    async loadGlobalUsage(currentSettingId: string): Promise<Record<string, number>> {
        try {
            const tables = [
                { table: TABLE_REL_SETTING_TRAITS, id: 'trait_id', cat: false },
                { table: TABLE_REL_SETTING_SKILLS, id: 'skill_id', cat: true },
                { table: TABLE_REL_SETTING_BACKGROUNDS, id: 'background_id', cat: true },
                { table: TABLE_REL_SETTING_COUNTERS, id: 'counter_id', cat: true },
                { table: TABLE_REL_SETTING_SPECIALIZATIONS, id: 'specialization_id', cat: false }
            ];

            const results = await Promise.all(tables.map(async t => {
                let query = supabase.from(t.table).select(`${t.id}, setting_id`);

                // Filter out current setting
                query = query.neq('setting_id', currentSettingId);

                // For tables with categories, only count "placed" items
                if (t.cat) {
                    query = query.not('default_category', 'is', null);
                }

                const { data } = await query;
                return { idKey: t.id, data: data || [] };
            }));

            const usageMap: Record<string, number> = {};
            results.forEach(res => {
                res.data.forEach((row: any) => {
                    const id = row[res.idKey];
                    usageMap[id] = (usageMap[id] || 0) + 1;
                });
            });

            return usageMap;
        } catch (error) {
            ErrorService.handleError(error, { context: 'LibraryLoader.loadGlobalUsage', silent: true });
            return {};
        }
    }
};

import { supabase } from '../../services/supabase'; // Keep for selects until fully abstracted or use execute
import { DatabaseService } from '../../services/DatabaseService';
import { RulesData } from '../../types/rules';
import { LibraryEntry as LibraryTraitEntry } from '../../types/system';
import { LIBRARY_TYPE_CONFIG, LibraryTypeKey } from '../../constants/db';

export const LibraryPersistence = {
    /**
     * Persist initial libraries for a new setting
     */
    async persistInitialLibraries(settingId: string, initialRules: Partial<RulesData>) {
        if (!initialRules.libraries) return;

        for (const typeCfg of LIBRARY_TYPE_CONFIG) {
            const items = (initialRules.libraries as any)[typeCfg.key] || [];
            if (items.length === 0) continue;

            // Fetch existing globals to avoid duplicates
            const globals = await DatabaseService.fetchAll<{ id: string, name: string }>(typeCfg.table, {
                select: 'id, name',
                eq: { setting_id: null }
            }, `LibraryPersistence.persistInitial.${typeCfg.key}.globals`);

            const globalMap = new Map((globals || []).map(g => [g.name.trim().toLowerCase(), g.id]));
            const toCreate: any[] = [];
            const toLink: any[] = [];

            items.forEach((item: any) => {
                const normalized = item.name.trim().toLowerCase();
                const existingId = globalMap.get(normalized);

                if (existingId) {
                    const link: any = { setting_id: settingId, [typeCfg.idKey]: existingId, is_active: true };
                    // Default categories for skills/backgrounds/counters
                    if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds' || typeCfg.key === 'counters') {
                        link.default_category = item.defaultCategory;
                    }
                    toLink.push(link);
                } else {
                    // Create as global
                    const payload: any = {
                        id: item.id,
                        name: item.name,
                        description: item.description,
                        setting_id: null
                    };

                    // Add type-specific fields
                    if (typeCfg.key === 'traits') {
                        payload.type = item.type;
                        payload.cost = item.cost;
                        payload.tags = item.tags || [];
                        payload.is_variable = item.isVariable;
                        payload.effects = item.effects || [];
                    } else if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds') {
                        payload.is_variable = item.isVariable;
                    } else if (typeCfg.key === 'counters') {
                        payload.max_value = item.maxValue;
                        payload.default_value = item.defaultValue;
                        payload.xp_cost = item.xpCost;
                    } else if (typeCfg.key === 'specializations') {
                        payload.skill_ids = item.skillIds;
                        payload.default_min_level = item.defaultMinLevel;
                    }

                    toCreate.push(payload);
                    const link: any = { setting_id: settingId, [typeCfg.idKey]: item.id, is_active: true };
                    if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds' || typeCfg.key === 'counters') {
                        link.default_category = item.defaultCategory;
                    }
                    toLink.push(link);
                }
            });

            if (toCreate.length > 0) await DatabaseService.insert(typeCfg.table, toCreate, `LibraryPersistence.persistInitial.${typeCfg.key}.create`);
            if (toLink.length > 0) await DatabaseService.insert(typeCfg.rel, toLink, `LibraryPersistence.persistInitial.${typeCfg.key}.links`);
        }
    },

    /**
     * Delete and Re-insert libraries (Standard Sync Strategy)
     */
    async syncLibraries(settingId: string, rules: RulesData) {
        for (const typeCfg of LIBRARY_TYPE_CONFIG) {
            const currentItems = (rules.libraries as any)[typeCfg.key] || [];

            // 1. UPSERT Global Repository items
            for (const item of currentItems) {
                const payload: any = {
                    id: item.id, // Mandatory for upsert
                    name: item.name,
                    description: item.description,
                    setting_id: null // Ensure it's marked as Global in the repository
                };

                if (typeCfg.key === 'traits') {
                    payload.type = item.type;
                    payload.cost = item.cost;
                    payload.tags = item.tags;
                    payload.is_variable = item.isVariable;
                    payload.effects = item.effects;
                } else if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds') {
                    payload.is_variable = item.isVariable;
                } else if (typeCfg.key === 'counters') {
                    payload.max_value = item.maxValue;
                    payload.default_value = item.defaultValue;
                    payload.xp_cost = item.xpCost;
                } else if (typeCfg.key === 'specializations') {
                    payload.skill_ids = item.skillIds;
                    payload.default_min_level = item.defaultMinLevel;
                }

                // Use UPSERT instead of update to handle newly created items from the UI
                await DatabaseService.upsert(typeCfg.table, payload, {}, `LibraryPersistence.sync.${typeCfg.key}.upsertGlobal`);
            }

            // 2. Refresh RELATIONSHIPS (Active/Local Preference)
            await DatabaseService.deleteBy(typeCfg.rel, 'setting_id', settingId, `LibraryPersistence.sync.${typeCfg.key}.deleteLinks`);
            const activeItems = currentItems.filter((i: any) => i.isActive !== false);
            if (activeItems.length > 0) {
                const relPayload = activeItems.map((item: any) => {
                    const link: any = {
                        setting_id: settingId,
                        [typeCfg.idKey]: item.id,
                        is_active: true
                    };
                    // Skills, backgrounds and counters have default categories
                    if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds' || typeCfg.key === 'counters') {
                        link.default_category = item.defaultCategory;
                    }
                    return link;
                });
                await DatabaseService.insert(typeCfg.rel, relPayload, `LibraryPersistence.sync.${typeCfg.key}.insertLinks`);
            }

            // 3. Refresh VARIANTS (if applicable)
            if ('variants' in typeCfg && typeCfg.variants) {
                const variantsTable = typeCfg.variants as string;
                await DatabaseService.deleteBy(variantsTable, 'setting_id', settingId, `LibraryPersistence.sync.${typeCfg.key}.deleteVariants`);
                const variantsPayload: any[] = [];
                currentItems.forEach((item: any) => {
                    if (item.variants && item.variants.length > 0) {
                        item.variants.forEach((v: string) => {
                            variantsPayload.push({
                                [typeCfg.idKey]: item.id,
                                setting_id: settingId,
                                name: v
                            });
                        });
                    }
                });
                if (variantsPayload.length > 0) {
                    await DatabaseService.insert(variantsTable, variantsPayload, `LibraryPersistence.sync.${typeCfg.key}.insertVariants`);
                }
            }
        }
    }
};

