import { INITIAL_DATA } from '../../data/initialState';
import { LibrarySkillEntry } from '../../types';

/**
 * Migration: Libraries (skills, traits)
 * - Fix typo skilllibrary → skillLibrary
 * - Pre-fill skillLibrary from INITIAL_DATA
 * - Harvest skills from existing sheet data
 * - Migrate library type names (vertu → avantage)
 * - Ensure isVariable flag is set correctly
 */
export const migrateLibrary = (parsed: any): void => {
    // Fix key casing typo
    if (parsed.skilllibrary && !parsed.skillLibrary) {
        parsed.skillLibrary = parsed.skilllibrary;
        delete parsed.skilllibrary;
    }

    // Pre-fill skillLibrary
    if (!parsed.skillLibrary || parsed.skillLibrary.length === 0) {
        const initialSkillList: LibrarySkillEntry[] = [...INITIAL_DATA.skillLibrary];
        const seenNames = new Set<string>(initialSkillList.map(s => s.name.trim().toLowerCase()));

        // Harvest skills from sheet data
        if (parsed.skills) {
            Object.keys(parsed.skills).forEach(cat => {
                if (cat === 'arrieres_plans') return;
                const skills = parsed.skills[cat] || [];
                skills.forEach((skill: any) => {
                    if (skill.name && skill.name.trim() !== '') {
                        const normalized = skill.name.trim().toLowerCase();
                        if (!seenNames.has(normalized)) {
                            seenNames.add(normalized);
                            initialSkillList.push({
                                id: Math.random().toString(36).substr(2, 9),
                                name: skill.name,
                                defaultCategory: cat,
                                description: "",
                                isVariable: false
                            });
                        }
                    }
                });
            });
        }
        initialSkillList.sort((a, b) => a.name.localeCompare(b.name));
        parsed.skillLibrary = initialSkillList;
    }

    // Update isVariable flag from INITIAL_DATA
    if (parsed.skillLibrary) {
        const defaultVariableStatus = new Map<string, boolean>();
        INITIAL_DATA.skillLibrary.forEach(s => {
            if (s.isVariable) {
                defaultVariableStatus.set(s.name.trim().toLowerCase(), true);
            }
        });

        parsed.skillLibrary.forEach((s: any) => {
            const normalized = s.name.trim().toLowerCase();
            if (defaultVariableStatus.has(normalized) && typeof s.isVariable === 'undefined') {
                s.isVariable = true;
            }
        });
    }

    // Initialize traits library
    if (!parsed.library) {
        parsed.library = [];
    }

    // Migrate library type names
    if (parsed.library) {
        parsed.library = parsed.library.map((l: any) => ({
            ...l,
            type: l.type === 'vertu' ? 'avantage' : (l.type === 'defaut' ? 'desavantage' : l.type),
            tags: Array.isArray(l.tags) ? l.tags : [],
            effects: Array.isArray(l.effects) ? l.effects : []
        }));
    }
};

/**
 * Migration: Notebook fields
 * - Convert array fields to newline-separated strings
 * - Pad reputation to 7 entries
 * - Initialize characterImage, notes, equipement, armes_list
 */
export const migrateNotebook = (parsed: any): void => {
    if (!parsed.page2) return;

    // Convert array fields to newline-separated strings
    const notebookFields = ['lieux_importants', 'contacts', 'connaissances', 'valeurs_monetaires'];
    notebookFields.forEach(field => {
        if (Array.isArray(parsed.page2[field])) {
            parsed.page2[field] = parsed.page2[field].filter((x: any) => x && x.trim() !== '').join('\n');
        }
        else if (typeof parsed.page2[field] !== 'string') {
            parsed.page2[field] = '';
        }
    });

    // Remove deprecated personalite field
    if (parsed.page2.personalite) {
        delete parsed.page2.personalite;
    }

    // Pad reputation to 7 entries
    if (parsed.page2.reputation) {
        if (parsed.page2.reputation.length < 7) {
            const diff = 7 - parsed.page2.reputation.length;
            parsed.page2.reputation = [
                ...parsed.page2.reputation,
                ...Array(diff).fill({ reputation: '', lieu: '', valeur: '' })
            ];
        }
    } else {
        parsed.page2.reputation = Array(7).fill({ reputation: '', lieu: '', valeur: '' });
    }

    // Convert notes array to string
    if (Array.isArray(parsed.page2.notes)) {
        parsed.page2.notes = parsed.page2.notes.filter((n: string) => n && n.trim() !== '').join('\n');
    } else if (typeof parsed.page2.notes !== 'string') {
        parsed.page2.notes = '';
    }

    // Convert equipement array to string
    if (Array.isArray(parsed.page2.equipement)) {
        parsed.page2.equipement = parsed.page2.equipement.filter((n: string) => n && n.trim() !== '').join('\n');
    } else if (typeof parsed.page2.equipement !== 'string') {
        parsed.page2.equipement = '';
    }

    // Initialize characterImage
    if (typeof parsed.page2.characterImage === 'undefined') {
        parsed.page2.characterImage = '';
    }

    // Convert armes_list array to string
    if (Array.isArray(parsed.page2.armes_list)) {
        parsed.page2.armes_list = parsed.page2.armes_list.filter((n: string) => n && n.trim() !== '').join('\n');
    } else if (typeof parsed.page2.armes_list !== 'string') {
        parsed.page2.armes_list = '';
    }
};

