/**
 * Map of legacy skill category IDs to generic IDs
 */
export const LEGACY_SKILL_MAP: Record<string, string> = {
    'talents': 'Col_Comp_1',
    'competences': 'Col_Comp_2',
    'competences_col_2': 'Col_Comp_3',
    'connaissances': 'Col_Comp_4',
    'autres_competences': 'Col_Comp_5',
    'competences2': 'Col_Comp_6',
    'autres': 'Col_Comp_7',
    'arrieres_plans': 'Col_Comp_8',
    'counters': 'Col_Comp_9'
};

/**
 * Required skill category IDs
 */
export const REQUIRED_SKILL_CATS = [
    'Col_Comp_1', 'Col_Comp_2', 'Col_Comp_3', 'Col_Comp_4',
    'Col_Comp_5', 'Col_Comp_6', 'Col_Comp_7', 'Col_Comp_8', 'Col_Comp_9'
];

/**
 * Migration: Skills
 * - Migrate legacy category IDs to generic IDs (Col_Comp_x) FIRST
 * - Initialize missing skill categories from INITIAL_DATA
 * - Add creationValue property to skills
 * - Fix variable skills using skillLibrary
 */
export const migrateSkills = (parsed: any): void => {
    // Initialize skills object
    if (!parsed.skills) {
        parsed.skills = {};
    }

    // STEP 1: Migrate legacy skill category keys FIRST (before adding defaults)
    // This renames the keys without merging
    Object.keys(LEGACY_SKILL_MAP).forEach(oldKey => {
        if (parsed.skills[oldKey]) {
            const newKey = LEGACY_SKILL_MAP[oldKey];
            // Only move if the new key doesn't exist - don't merge!
            if (!parsed.skills[newKey]) {
                parsed.skills[newKey] = parsed.skills[oldKey];
            }
            delete parsed.skills[oldKey];
        }
    });

    // STEP 2: Inject from INITIAL_DATA only for truly missing categories
    Object.keys(INITIAL_DATA.skills).forEach(key => {
        if (!parsed.skills[key]) {
            parsed.skills[key] = INITIAL_DATA.skills[key];
        }
    });

    // STEP 3: Ensure all required categories exist
    REQUIRED_SKILL_CATS.forEach(cat => {
        if (!parsed.skills[cat]) {
            parsed.skills[cat] = INITIAL_DATA.skills[cat] || [];
        }
    });

    // STEP 4: Ensure all skills have creationValue
    const ensureCreationValue = (list: any[]) => {
        return list.map(item => {
            if (typeof item.creationValue === 'undefined') {
                return { ...item, creationValue: 0 };
            }
            return item;
        });
    };

    Object.keys(parsed.skills).forEach(key => {
        if (Array.isArray(parsed.skills[key])) {
            parsed.skills[key] = ensureCreationValue(parsed.skills[key]);
        }
    });

    // STEP 5: Fix variable skills using skillLibrary as Source of Truth
    if (parsed.skills && parsed.skillLibrary) {
        const variableSkillNames = new Set<string>();
        parsed.skillLibrary.forEach((s: LibrarySkillEntry) => {
            if (s.isVariable) {
                variableSkillNames.add(s.name.trim().toLowerCase());
            }
        });

        Object.keys(parsed.skills).forEach(key => {
            if (Array.isArray(parsed.skills[key])) {
                parsed.skills[key] = parsed.skills[key].map((skill: any) => {
                    if (!skill || !skill.name) return skill;
                    const normalized = skill.name.trim().toLowerCase();
                    if (variableSkillNames.has(normalized) && typeof skill.variant === 'undefined') {
                        return { ...skill, variant: "" };
                    }
                    return skill;
                });
            }
        });
    }
};

/**
 * Migration: Specializations
 * - Initialize specializations object
 * - Convert string specializations to objects with minLevel
 * - Build specializationLibrary from existing data
 */
export const migrateSpecializations = (parsed: any): void => {
    // Initialize specializations
    if (!parsed.specializations) {
        parsed.specializations = {};
    }

    // Convert string array to object array in imposedSpecializations
    if (parsed.imposedSpecializations) {
        Object.keys(parsed.imposedSpecializations).forEach(skillId => {
            const list = parsed.imposedSpecializations[skillId];
            if (Array.isArray(list) && list.length > 0 && typeof list[0] === 'string') {
                parsed.imposedSpecializations[skillId] = list.map((s: string) => ({
                    name: s,
                    minLevel: 0
                }));
            }
        });
    }

    // Build specializationLibrary from existing data
    if (!parsed.specializationLibrary) {
        parsed.specializationLibrary = [];
        const initialSpecList: any[] = [];
        const seenSpecNames = new Set<string>();

        // 1. Harvest from specializations Record
        if (parsed.specializations) {
            Object.keys(parsed.specializations).forEach(skillId => {
                const specs = parsed.specializations[skillId];
                if (Array.isArray(specs)) {
                    specs.forEach(s => {
                        if (s && s.trim() !== '') {
                            const normalized = s.trim().toLowerCase();
                            if (!seenSpecNames.has(normalized)) {
                                seenSpecNames.add(normalized);
                                initialSpecList.push({
                                    id: Math.random().toString(36).substr(2, 9),
                                    name: s.trim(),
                                    skillIds: [skillId],
                                    defaultMinLevel: 0,
                                    description: ""
                                });
                            } else {
                                const existing = initialSpecList.find(e => e.name.trim().toLowerCase() === normalized);
                                if (existing && !existing.skillIds.includes(skillId)) {
                                    existing.skillIds.push(skillId);
                                }
                            }
                        }
                    });
                }
            });
        }

        // 2. Harvest from imposedSpecializations
        if (parsed.imposedSpecializations) {
            Object.keys(parsed.imposedSpecializations).forEach(skillId => {
                const specs = parsed.imposedSpecializations[skillId];
                if (Array.isArray(specs)) {
                    specs.forEach(s => {
                        const name = typeof s === 'string' ? s : s.name;
                        if (name && name.trim() !== '') {
                            const normalized = name.trim().toLowerCase();
                            if (!seenSpecNames.has(normalized)) {
                                seenSpecNames.add(normalized);
                                initialSpecList.push({
                                    id: Math.random().toString(36).substr(2, 9),
                                    name: name.trim(),
                                    skillIds: [skillId],
                                    defaultMinLevel: typeof s === 'object' ? (s.minLevel || 0) : 0,
                                    description: ""
                                });
                            } else {
                                const existing = initialSpecList.find(e => e.name.trim().toLowerCase() === normalized);
                                if (existing && !existing.skillIds.includes(skillId)) {
                                    existing.skillIds.push(skillId);
                                }
                            }
                        }
                    });
                }
            });
        }

        initialSpecList.sort((a, b) => a.name.localeCompare(b.name));
        parsed.specializationLibrary = initialSpecList;
    }
};

/**
 * Migration: Terminology renaming
 * - vertus → avantages
 * - defauts → desavantages
 */
export const migrateTerminology = (parsed: any): void => {
    if (!parsed.page2) return;

    if (parsed.page2.vertus && !parsed.page2.avantages) {
        parsed.page2.avantages = parsed.page2.vertus;
        delete parsed.page2.vertus;
    }
    if (parsed.page2.defauts && !parsed.page2.desavantages) {
        parsed.page2.desavantages = parsed.page2.defauts;
        delete parsed.page2.defauts;
    }
};

/**
 * Migration: Traits structure
 * - string[] → object[] for avantages/desavantages
 * - Padding to 28 elements
 */
export const migrateTraits = (parsed: any): void => {
    if (!parsed.page2) return;

    // Convert string[] to object[]
    if (parsed.page2.avantages && parsed.page2.avantages.length > 0 && typeof parsed.page2.avantages[0] === 'string') {
        parsed.page2.avantages = parsed.page2.avantages.map((s: string) => ({ name: s || '', value: '' }));
    }
    if (parsed.page2.desavantages && parsed.page2.desavantages.length > 0 && typeof parsed.page2.desavantages[0] === 'string') {
        parsed.page2.desavantages = parsed.page2.desavantages.map((s: string) => ({ name: s || '', value: '' }));
    }

    // Padding to 28 elements
    if (parsed.page2.avantages && parsed.page2.avantages.length < 28) {
        const diff = 28 - parsed.page2.avantages.length;
        parsed.page2.avantages = [...parsed.page2.avantages, ...Array(diff).fill(null).map(() => ({ name: '', value: '' }))];
    } else if (!parsed.page2.avantages) {
        parsed.page2.avantages = Array(28).fill(null).map(() => ({ name: '', value: '' }));
    }

    if (parsed.page2.desavantages && parsed.page2.desavantages.length < 28) {
        const diff = 28 - parsed.page2.desavantages.length;
        parsed.page2.desavantages = [...parsed.page2.desavantages, ...Array(diff).fill(null).map(() => ({ name: '', value: '' }))];
    } else if (!parsed.page2.desavantages) {
        parsed.page2.desavantages = Array(28).fill(null).map(() => ({ name: '', value: '' }));
    }
};

import { CharacterSheetData } from '../../types';

// Import migration functions
import { migrateTerminology } from './migrateTerminology';
import { migrateTraits } from './migrateTraits';
import { migrateCounters } from './migrateCounters';
import { migrateAttributes } from './migrateAttributes';
import { migrateNotebook } from './migrateNotebook';
import { migrateLibrary } from './migrateLibrary';
import { migrateSpecializations } from './migrateSpecializations';
import { migrateSkills } from './migrateSkills';
import { migrateDefaults } from './migrateDefaults';
import { migrateCampaignNotes } from './migrateCampaignNotes';

// Type for a migration function
type MigrationFunction = (data: any) => void;

// Registry of migrations by version
// Version 1 corresponds to "Legacy to Current" massive migration
export const MIGRATIONS: Record<number, MigrationFunction[]> = {
    1: [
        migrateTerminology,
        migrateTraits,
        migrateCounters,
        migrateAttributes,
        migrateNotebook,
        migrateLibrary,
        migrateSpecializations,
        migrateSkills,
        migrateDefaults
    ],
    2: [
        migrateCampaignNotes
    ]
};

export const CURRENT_SCHEMA_VERSION = 2;

import { CharacterSheetData, DotEntry, AttributeEntry, TraitEntry } from '../types';
import { RulesData } from '../types/rules';
import { generateId } from './factories';
import { normalizeString } from './stringUtils';
import { getSkillCategory, getCounter, setCounter } from './stateAccessors';
import { reconcileSkillsAndBackgrounds } from './reconcilers/skillsReconciler';

// --- Sub-functions ---

/**
 * Synchronizes metadata and global configurations from rules.
 * Updates character info, XP costs, and creation rules.
 * 
 * @param newState - The current draft state being updated
 * @param rules - The new rules to apply
 */
const reconcileConfigurations = (newState: CharacterSheetData, rules: RulesData) => {
    // 1. Sync Info
    const ruleSettingId = rules.settingId;
    if (ruleSettingId) {
        newState.syncInfo = {
            ...newState.syncInfo,
            settingId: ruleSettingId,
            settingName: rules.settingName || newState.syncInfo?.settingName || 'Inconnue',
            syncId: newState.syncInfo?.syncId || '',
            lastSynced: Date.now()
        };
    }

    // 2. XP Costs
    if (rules.configurations?.xpCosts) {
        newState.xpCosts = {
            attributeFactor: rules.configurations.xpCosts.attributeFactor || 6,
            skillFactor: rules.configurations.xpCosts.skillFactor || 1,
            specializationFactor: rules.configurations.xpCosts.specializationFactor || 0
        };
    }

    // 3. Creation Config
    if (rules.configurations?.creation) {
        newState.creationConfig = {
            ...newState.creationConfig,
            ...rules.configurations.creation,
            cardConfig: rules.configurations.cards ? {
                ...newState.creationConfig.cardConfig,
                ...rules.configurations.cards
            } : newState.creationConfig.cardConfig,
            rankSlots: rules.configurations.creation.rankSlots
        };
    }

    // 4. Secondary Attributes Toggle
    if (rules.configurations?.global?.secondaryAttributes !== undefined) {
        newState.secondaryAttributesActive = rules.configurations.global.secondaryAttributes;
    }
};

/**
 * Reconstructs main attributes based on rules definitions.
 * Preserves dots and values while attaching correct rules-based properties.
 * 
 * @param newState - The current draft state
 * @param rules - The rules containing attribute definitions
 */
const reconcileAttributes = (newState: CharacterSheetData, rules: RulesData) => {
    const ruleAttributes = rules.definitions.attributes;
    if (!ruleAttributes) return;

    // A. Main Attributes
    const newAttributes: Record<string, AttributeEntry[]> = {};
    Object.keys(ruleAttributes).forEach(category => {
        const definedNames = ruleAttributes[category];
        const existingEntries = newState.attributes[category] || [];
        const processedNames = new Set<string>();
        const consumedIds = new Set<string>();

        const syncedAttributes = definedNames.map(name => {
            processedNames.add(name);
            const existing = existingEntries.find(e => e.name === name && !consumedIds.has(e.id));

            if (existing) {
                consumedIds.add(existing.id);
                return { ...existing, name: name };
            } else {
                return {
                    id: generateId(), name, val1: "0", val2: "", val3: "",
                    creationVal1: 0, creationVal2: 0, creationVal3: 0
                };
            }
        });

        const remainingAttributes = existingEntries.filter(e => e && e.name && !consumedIds.has(e.id) && !processedNames.has(e.name));
        newAttributes[category] = [...syncedAttributes, ...remainingAttributes];
    });

    Object.keys(newState.attributes).forEach(cat => {
        if (!newAttributes[cat]) newAttributes[cat] = newState.attributes[cat];
    });
    newState.attributes = newAttributes;

    // B. Attribute Settings (Labels)
    const labels = rules.definitions.labels || {};
    newState.attributeSettings = Object.keys(ruleAttributes).map(key => ({
        id: key,
        label: labels[key] || key.charAt(0).toUpperCase() + key.slice(1)
    }));
};

/**
 * Reconstructs secondary attributes categorized by their type.
 * 
 * @param newState - The current draft state
 * @param rules - The rules containing secondary attribute definitions
 */
const reconcileSecondaryAttributes = (newState: CharacterSheetData, rules: RulesData) => {
    const ruleSecondary = rules.definitions.secondaryAttributes || {};
    const newSecondary: Record<string, AttributeEntry[]> = {};

    const allCategories = new Set([
        ...Object.keys(rules.definitions.attributes || {}),
        ...Object.keys(newState.secondaryAttributes || {})
    ]);

    allCategories.forEach(category => {
        const definedNames = ruleSecondary[category] || [];
        const existingEntries = newState.secondaryAttributes?.[category] || [];
        const processedNames = new Set<string>();
        const consumedIds = new Set<string>();

        const syncedSecondary = definedNames.map(name => {
            processedNames.add(name);
            const existing = existingEntries.find(e => e.name === name && !consumedIds.has(e.id));
            if (existing) {
                consumedIds.add(existing.id);
                return { ...existing, name };
            } else {
                return { id: generateId(), name, val1: "0", val2: "", val3: "", creationVal1: 0, creationVal2: 0, creationVal3: 0 };
            }
        });

        const remainingSecondary = existingEntries.filter(e => e && e.name && !consumedIds.has(e.id) && !processedNames.has(e.name));
        newSecondary[category] = [...syncedSecondary, ...remainingSecondary];
    });
    newState.secondaryAttributes = newSecondary;
};

// --- Sub-functions --- (Note: reconcileSkillsAndBackgrounds is now in reconcilers/skillsReconciler.ts)

/**
 * Synchronizes custom counters with their library definitions.
 * 
 * @param newState - The current draft state
 * @param currentState - The source state
 * @param rules - The campaign rules
 */
const reconcileCounters = (newState: CharacterSheetData, currentState: CharacterSheetData, rules: RulesData) => {
    if (!rules.definitions.counters) return;

    const newCounters: CharacterSheetData['counters'] = {
        custom: currentState.counters.custom || []
    };

    Object.keys(rules.definitions.counters).forEach(key => {
        const def = rules.definitions.counters[key];
        const existingRaw = currentState.counters[key];
        const existing = Array.isArray(existingRaw) ? existingRaw[0] : (existingRaw as DotEntry | undefined);

        const libCounter = rules.libraries?.counters?.find(c => normalizeString(c.name) === normalizeString(def.name) || c.id === key);
        const description = def.description || libCounter?.description || '';

        const defaultValue = def.defaultValue !== undefined ? def.defaultValue : (def.value || 3);
        const max = def.max || 10;

        const value = existing?.value !== undefined ? existing.value : defaultValue;
        const creationValue = existing?.creationValue !== undefined ? existing.creationValue : defaultValue;

        if (existing) {
            newCounters[key] = {
                ...existing,
                name: def.name,
                max,
                description: description || existing.description || '',
                value,
                creationValue
            };
        } else {
            newCounters[key] = {
                id: key,
                name: def.name,
                description,
                value,
                creationValue,
                max,
                current: 0
            };
        }
    });
    newState.counters = newCounters;
};

/**
 * Links traits (advantages/disadvantages) to their latest library definitions.
 * 
 * @param newState - The current draft state
 * @param currentState - The source state
 * @param rules - The campaign rules
 */
const reconcileTraits = (newState: CharacterSheetData, currentState: CharacterSheetData, rules: RulesData) => {
    // Migrer les Avantages (avantages) et Désavantages (desavantages)
    // Le but est de lier les entrées existantes aux définitions de la bibliothèque via definitionId

    const processTraitList = (list: TraitEntry[], type: 'avantage' | 'desavantage'): TraitEntry[] => {
        if (!list) return [];
        return list.map(existing => {
            // Si déjà lié, on garde (on pourrait update le nom ici si besoin, mais attention aux customs)
            if (existing.definitionId) return existing;

            // Tentative de liaison par nom (Migration)
            const libMatch = rules.libraries?.traits?.find(t =>
                t.type === type &&
                normalizeString(t.name) === normalizeString(existing.name)
            );

            if (libMatch) {
                return {
                    ...existing,
                    definitionId: libMatch.id,
                };
            }

            return existing;
        });
    };

    if (newState.page2) {
        newState.page2.avantages = processTraitList(currentState.page2.avantages || [], 'avantage');
        newState.page2.desavantages = processTraitList(currentState.page2.desavantages || [], 'desavantage');
    }
}

// --- Main Function ---

/**
 * Main function to reconcile a character state with a set of rules.
 * Creates a deep clone of the current state and sequentially applies all sub-reconcilers.
 * 
 * @param currentState - Current character sheet data
 * @param rules - New ruleset to apply
 * @returns A new reconciled character sheet state
 */
export const reconcileRulesWithState = (currentState: CharacterSheetData, rules: RulesData): CharacterSheetData => {
    const newState: CharacterSheetData = JSON.parse(JSON.stringify(currentState));

    if (rules.version) {
        newState._rulesVersion = rules.version;
    }

    reconcileConfigurations(newState, rules);
    reconcileAttributes(newState, rules);
    reconcileSecondaryAttributes(newState, rules);
    reconcileSkillsAndBackgrounds(newState, currentState, rules);
    reconcileCounters(newState, currentState, rules);
    reconcileTraits(newState, currentState, rules);

    return newState;
};
